import type { CitaBook } from "@/lib/gospel/types";

/** Libro del Pueblo de Dios — NT (Santa Sede, ESL0506). */
export const NT_GOSPELS: Record<CitaBook, string[][]> = {"mt":[["Genealogía de Jesucristo, hijo de David, hijo de Abraham:","Abraham fue padre de Isaac; Isaac, padre de Jacob; Jacob, padre de Judá y de sus hermanos.","Judá fue padre de Fares y de Zará, y la madre de estos fue Tamar. Fares fue padre de Aram;","Aram, padre de Aminadab; Aminadab, padre de Naasón; Naasón, padre de Salmón.","Salmón fue padre de Booz, y la madre de este fue Rahab. Booz fue padre de Obed, y la madre de este fue Rut. Obed fue padre de Jesé;","Jesé, padre del rey David. David fue padre de Salomón, y la madre de este fue la que había sido mujer de Urías.","Salomón fue padre de Roboam; Roboam, padre de Abías; Abías, padre de Asá;","Asá, padre de Josafat; Josafat, padre de Joram; Joram, padre de Ozías.","Ozías fue padre de Joatam; Joatam, padre de Acaz; Acaz, padre de Ezequías;","Ezequías, padre de Manasés. Manasés fue padre de Josías;","Josías, padre de Jeconías y de sus hermanos, durante el destierro en Babilonia.","Después del destierro en Babilonia: Jeconías fue padre de Salatiel; Salatiel, padre de Zorobabel;","Zorobabel, padre de Abiud; Abiud, padre de Eliacim; Eliacim, padre de Azor.","Azor fue padre de Sadoc; Sadoc, padre de Aquim; Aquim, padre de Eliud;","Eliud, padre de Eleazar; Eleazar, padre de Matán; Matán, padre de Jacob.","Jacob fue padre de José, el esposo de María, de la cual nació Jesús, que es llamado Cristo.","El total de las generaciones es, por lo tanto: desde Abraham hasta David, catorce generaciones; desde David hasta el destierro en Babilonia, catorce generaciones; desde el destierro en Babilonia hasta Cristo, catorce generaciones.","Este fue el origen de Jesucristo: María, su madre, estaba comprometida con José y, cuando todavía no han vivido juntos, concibió un hijo por obra del Espíritu Santo.","José, su esposo, que era un hombre justo y no quería denunciarla públicamente, resolvió abandonarla en secreto.","Mientras pensaba en esto, el Angel del Señor se le apareció en sueños y le dijo: «José, hijo de David, no temas recibir a María, tu esposa, porque lo que ha sido engendrado en ella proviene del Espíritu Santo.","Ella dará a luz un hijo, a quien pondrás el nombre de Jesús, porque él salvará a su Pueblo de todos sus pecados».","Todo esto sucedió para que se cumpliera lo que el Señor había anunciado por el Profeta:","\"La Virgen concebirá y dará a luz un hijo a quien pondrán el nombre de Emanuel\", que traducido significa: «Dios con nosotros».","Al despertar, José hizo lo que el Angel del Señor le había ordenado: llevó a María a su casa,","y sin que hubieran hecho vida en común, ella dio a luz un hijo, y él le puso el nombre de Jesús."],["Cuando nació Jesús, en Belén de Judea, bajo el reinado de Herodes, unos magos de Oriente se presentaron en Jerusalén","y preguntaron: «¿Dónde está el rey de los judíos que acaba de nacer? Porque vimos su estrella en Oriente y hemos venido a adorarlo».","Al enterarse, el rey Herodes quedó desconcertado y con él toda Jerusalén.","Entonces reunió a todos los sumos sacerdotes y a los escribas del pueblo, para preguntarles en qué lugar debía nacer el Mesías.","«En Belén de Judea, –le respondieron–, porque así está escrito por el Profeta:","\"Y tú, Belén, tierra de Judá, ciertamente no eres la menor entre las principales ciudades de Judá, porque de ti surgirá un jefe que será el Pastor de mi pueblo, Israel\"».","Herodes mandó llamar secretamente a los magos y después de averiguar con precisión la fecha en que había aparecido la estrella,","los envió a Belén, diciéndoles: «Vayan e infórmense cuidadosamente acerca del niño, y cuando lo hayan encontrado, avísenme para que yo también vaya a rendirle homenaje».","Después de oír al rey, ellos partieron. La estrella que habían visto en Oriente los precedía, hasta que se detuvo en el lugar donde estaba el niño.","Cuando vieron la estrella se llenaron de alegría,","y al entrar en la casa, encontraron al niño con María, su madre, y postrándose, le rindieron homenaje. Luego, abriendo sus cofres, le ofrecieron dones, oro, incienso y mirra.","Y como recibieron en sueños la advertencia de no regresar al palacio de Herodes, volvieron a su tierra por otro camino.","Después de la partida de los magos, el Angel del Señor se apareció en sueños a José y le dijo: «Levántate, toma al niño y a su madre, huye a Egipto y permanece allí hasta que yo te avise, porque Herodes va a buscar al niño para matarlo».","José se levantó, tomó de noche al niño y a su madre, y se fue a Egipto.","Allí permaneció hasta la muerte de Herodes, para que se cumpliera lo que el Señor había anunciado por medio del Profeta: \"Desde Egipto llamé a mi hijo\".","Al verse engañado por los magos, Herodes se enfureció y mandó matar, en Belén y sus alrededores, a todos los niños menores de dos años, de acuerdo con la fecha que los magos le habían indicado.","Así se cumplió lo que había sido anunciado por el profeta Jeremías:","\"En Ramá se oyó una voz, hubo lágrimas y gemidos: es Raquel, que llora a sus hijos y no quiere que la consuelen, porque ya no existen\".","Cuando murió Herodes, el Angel del Señor se apareció en sueños a José, que estaba en Egipto,","y le dijo: «Levántate, toma al niño y a su madre, y regresa a la tierra de Israel, porque han muerto los que atentaban contra la vida del niño».","José se levantó, tomó al niño y a su madre, y entró en la tierra de Israel.","Pero al saber que Arquelao reinaba en Judea, en lugar de su padre Herodes, tuvo miedo de ir allí y, advertido en sueños, se retiró a la región de Galilea,","donde se estableció en una ciudad llamada Nazaret. Así se cumplió lo que había sido anunciado por los profetas: \"Será llamado Nazareno\"."],["En aquel tiempo se presentó Juan el Bautista, proclamando en el desierto de Judea:","«Conviértanse, porque el Reino de los Cielos está cerca».","A él se refería el profeta Isaías cuando dijo: \"Una voz grita en el desierto: Preparen el camino del Señor, allanen sus senderos\".","Juan tenía una túnica de pelos de camello y un cinturón de cuero, y se alimentaba con langostas y miel silvestre.","La gente de Jerusalén, de toda la Judea y de toda la región del Jordán iba a su encuentro,","y se hacía bautizar por él en las aguas del Jordán, confesando sus pecados.","Al ver que muchos fariseos y saduceos se acercaban a recibir su bautismo, Juan les dijo: «Raza de víboras, ¿quién les enseñó a escapar de la ira de Dios que se acerca?","Produzcan el fruto de una sincera conversión,","y no se contenten con decir: «Tenemos por padre a Abraham». Porque yo les digo que de estas piedras Dios puede hacer surgir hijos de Abraham.","El hacha ya está puesta a la raíz de los árboles: el árbol que no produce buen fruto será cortado y arrojado al fuego.","Yo los bautizo con agua para que se conviertan; pero aquel que viene detrás de mí es más poderoso que yo, y yo ni siquiera soy digno de quitarle las sandalias. El los bautizará en el Espíritu Santo y en el fuego.","Tiene en su mano la horquilla y limpiará su era: recogerá su trigo en el granero y quemará la paja en un fuego inextinguible».","Entonces Jesús fue desde Galilea hasta el Jordán y se presentó a Juan para ser bautizado por él.","Juan se resistía, diciéndole: «Soy yo el que tiene necesidad de ser bautizado por ti, ¡y eres tú el que viene a mi encuentro!».","Pero Jesús le respondió: «Ahora déjame hacer esto, porque conviene que así cumplamos todo lo que es justo». Y Juan se lo permitió.","Apenas fue bautizado, Jesús salió del agua. En ese momento se abrieron los cielos, y vio al Espíritu de Dios descender como una paloma y dirigirse hacia él.","Y se oyó una voz del cielo que decía: «Este es mi Hijo muy querido, en quien tengo puesta toda mi predilección»."],["Entonces Jesús fue llevado por el Espíritu al desierto, para ser tentado por el demonio.","Después de ayunar cuarenta días con sus cuarenta noches, sintió hambre.","Y el tentador, acercándose, le dijo: «Si tú eres Hijo de Dios, manda que estas piedras se conviertan en panes».","Jesús le respondió: «Está escrito: \"El hombre no vive solamente de pan, sino de toda palabra que sale de la boca de Dios\"».","Luego el demonio llevó a Jesús a la Ciudad santa y lo puso en la parte más alta del Templo,","diciéndole: «Si tú eres Hijo de Dios, tírate abajo, porque está escrito: \"Dios dará órdenes a sus ángeles, y ellos te llevarán en sus manos para que tu pie no tropiece con ninguna piedra\"».","Jesús le respondió: «También está escrito: \"No tentarás al Señor, tu Dios\"».","El demonio lo llevó luego a una montaña muy alta; desde allí le hizo ver todos los reinos del mundo con todo su esplendor,","y le dijo: «Te daré todo esto, si te postras para adorarme».","Jesús le respondió: «Retírate, Satanás, porque está escrito: \"Adorarás al Señor, tu Dios, y a él solo rendirás culto\"».","Entonces el demonio lo dejó, y unos ángeles se acercaron para servirlo.","Cuando Jesús se enteró de que Juan había sido arrestado, se retiró a Galilea.","Y, dejando Nazaret, se estableció en Cafarnaúm, a orillas del lago, en los confines de Zabulón y Neftalí,","para que se cumpliera lo que había sido anunciado por el profeta Isaías:","\"¡Tierra de Zabulón, tierra de Neftalí, camino del mar, país de la Transjordania, Galilea de las naciones!","El pueblo que se hallaba en tinieblas vio una gran luz; sobre los que vivían en las oscuras regiones de la muerte, se levantó una luz.\"","A partir de ese momento, Jesús comenzó a proclamar: «Conviértanse, porque el Reino de los Cielos está cerca».","Mientras caminaba a orillas del mar de Galilea, Jesús vio a dos hermanos: a Simón, llamado Pedro, y a su hermano Andrés, que echaban las redes al mar porque eran pescadores.","Entonces les dijo: «Síganme, y yo los haré pescadores de hombres».","Inmediatamente, ellos dejaron las redes y lo siguieron.","Continuando su camino, vio a otros dos hermanos: a Santiago, hijo de Zebedeo, y a su hermano Juan, que estaban en la barca de Zebedeo, su padre, arreglando las redes; y Jesús los llamó.","Inmediatamente, ellos dejaron la barca y a su padre, y lo siguieron.","Jesús recorría toda la Galilea, enseñando en las sinagogas, proclamando la Buena Noticia del reino y curando todas las enfermedades y dolencias de la gente.","Su fama se extendió por toda la Siria, y le llevaban a todos los enfermos, afligidos por diversas enfermedades y sufrimientos: endemoniados, epilépticos y paralíticos, y él los curaba.","Lo seguían grandes multitudes que llegaban a Galilea, de la Decápolis, de Jerusalén, de Judea y de la Transjordania."],["Al ver a la multitud, Jesús subió a la montaña, se sentó, y sus discípulos se acercaron a él.","Entonces tomó la palabra y comenzó a enseñarles, diciendo:","«Felices los que tienen alma de pobres, porque a ellos les pertenece el Reino de los Cielos.","Felices los pacientes, porque recibirán la tierra en herencia.","Felices los afligidos, porque serán consolados.","Felices los que tienen hambre y sed de justicia, porque serán saciados.","Felices los misericordiosos, porque obtendrán misericordia.","Felices los que tienen el corazón puro, porque verán a Dios.","Felices los que trabajan por la paz, porque serán llamados hijos de Dios.","Felices los que son perseguidos por practicar la justicia, porque a ellos les pertenece el Reino de los Cielos.","Felices ustedes, cuando sean insultados y perseguidos, y cuando se los calumnie en toda forma a causa de mí.","Alégrense y regocíjense entonces, porque ustedes tendrán una gran recompensa en el cielo; de la misma manera persiguieron a los profetas que los precedieron.","Ustedes son la sal de la tierra. Pero si la sal pierde su sabor, ¿con qué se la volverá a salar? Ya no sirve para nada, sino para ser tirada y pisada por los hombres.","Ustedes son la luz del mundo. No se puede ocultar una ciudad situada en la cima de una montaña.","Y no se enciende una lámpara para meterla debajo de un cajón, sino que se la pone sobre el candelero para que ilumine a todos los que están en la casa.","Así debe brillar ante los ojos de los hombres la luz que hay en ustedes, a fin de que ellos vean sus buenas obras y glorifiquen al Padre que está en el cielo.","No piensen que vine para abolir la Ley o los Profetas: yo no he venido a abolir, sino a dar cumplimiento.","Les aseguro que no desaparecerá ni una i ni una coma de la Ley, antes que desaparezcan el cielo y la tierra, hasta que todo se realice.","El que no cumpla el más pequeño de estos mandamientos, y enseñe a los otros a hacer lo mismo, será considerado el menor en el Reino de los Cielos. En cambio, el que los cumpla y enseñe, será considerado grande en el Reino de los Cielos.","Les aseguro que si la justicia de ustedes no es superior a la de los escribas y fariseos, no entrarán en el Reino de los Cielos.","Ustedes han oído que se dijo a los antepasados: \"No matarás\", y el que mata, debe ser llevado ante el tribunal.","Pero yo les digo que todo aquel que se irrita contra su hermano, merece ser condenado por un tribunal. Y todo aquel que lo insulta, merece ser castigado por el Sanedrín. Y el que lo maldice, merece la Gehena de fuego.","Por lo tanto, si al presentar tu ofrenda en el altar, te acuerdas de que tu hermano tiene alguna queja contra ti,","deja tu ofrenda ante el altar, ve a reconciliarte con tu hermano, y sólo entonces vuelve a presentar tu ofrenda.","Trata de llegar en seguida a un acuerdo con tu adversario, mientras vas caminando con él, no sea que el adversario te entregue al juez, y el juez al guardia, y te pongan preso.","Te aseguro que no saldrás de allí hasta que hayas pagado el último centavo.","Ustedes han oído que se dijo: \"No cometerás adulterio\".","Pero yo les digo: El que mira a una mujer deseándola, ya cometió adulterio con ella en su corazón.","Si tu ojo derecho es para ti una ocasión de pecado, arráncalo y arrójalo lejos de ti: es preferible que se pierda uno solo de tus miembros, y no que todo tu cuerpo sea arrojado a la Gehena.","Y si tu mano derecha es para ti una ocasión de pecado, córtala y arrójala lejos de ti; es preferible que se pierda uno solo de tus miembros, y no que todo tu cuerpo sea arrojado a la Gehena.","También se dijo: \"El que se divorcia de su mujer, debe darle una declaración de divorcio\".","Pero yo les digo: El que se divorcia de su mujer, excepto en caso de unión ilegal, la expone a cometer adulterio; y el que se casa con una mujer abandonada por su marido, comete adulterio.","Ustedes han oído también que se dijo a los antepasados: \"No jurarás falsamente, y cumplirás los juramentos hechos al Señor\".","Pero yo les digo que no juren de ningún modo: ni por el cielo, porque es el trono de Dios,","ni por la tierra, porque es el estrado de sus pies; ni por Jerusalén, porque es la Ciudad del gran Rey.","No jures tampoco por tu cabeza, porque no puedes convertir en blanco o negro uno solo de tus cabellos.","Cuando ustedes digan «sí», que sea sí, y cuando digan «no», que sea no. Todo lo que se dice de más, viene del Maligno.","Ustedes han oído que se dijo: \"Ojo por ojo y diente por diente\".","Pero yo les digo que no hagan frente al que les hace mal: al contrario, si alguien te da una bofetada en la mejilla derecha, preséntale también la otra.","Al que quiere hacerte un juicio para quitarte la túnica, déjale también el manto;","y si te exige que lo acompañes un kilómetro, camina dos con él.","Da al que te pide, y no le vuelvas la espalda al que quiere pedirte algo prestado.","Ustedes han oído que se dijo: \"Amarás a tu prójimo\" y odiarás a tu enemigo.","Pero yo les digo: Amen a sus enemigos, rueguen por sus perseguidores;","así serán hijos del Padre que está en el cielo, porque él hace salir el sol sobre malos y buenos y hace caer la lluvia sobre justos e injustos.","Si ustedes aman solamente a quienes los aman, ¿qué recompensa merecen? ¿No hacen lo mismo los publicanos?","Y si saludan solamente a sus hermanos, ¿qué hacen de extraordinario? ¿No hacen lo mismo los paganos?","Por lo tanto, sean perfectos como es perfecto el Padre que está en el cielo."],["Tengan cuidado de no practicar su justicia delante de los hombres para ser vistos por ellos: de lo contrario, no recibirán ninguna recompensa del Padre que está en el cielo.","Por lo tanto, cuando des limosna, no lo vayas pregonando delante de ti, como hacen los hipócritas en las sinagogas y en las calles, para ser honrados por los hombres. Les aseguro que ellos ya tienen su recompensa.","Cuando tú des limosna, que tu mano izquierda ignore lo que hace la derecha,","para que tu limosna quede en secreto; y tu Padre, que ve en lo secreto, te recompensará.","Cuando ustedes oren, no hagan como los hipócritas: a ellos les gusta orar de pie en las sinagogas y en las esquinas de las calles, para ser vistos. Les aseguro que ellos ya tienen su recompensa.","Tú, en cambio, cuando ores, retírate a tu habitación, cierra la puerta y ora a tu Padre que está en lo secreto; y tu Padre, que ve en lo secreto, te recompensará.","Cuando oren, no hablen mucho, como hacen los paganos: ellos creen que por mucho hablar serán escuchados.","No hagan como ellos, porque el Padre que está en el cielo sabe bien qué es lo que les hace falta, antes de que se lo pidan.","Ustedes oren de esta manera: Padre nuestro, que estás en el cielo, santificado sea tu Nombre,","que venga tu Reino, que se haga tu voluntad en la tierra como en el cielo.","Danos hoy nuestro pan de cada día.","Perdona nuestras ofensas, como nosotros perdonamos a los que nos han ofendido.","No nos dejes caer en la tentación, sino líbranos del mal.","Si perdonan sus faltas a los demás, el Padre que está en el cielo también los perdonará a ustedes.","Pero si no perdonan a los demás, tampoco el Padre los perdonará a ustedes.","Cuando ustedes ayunen, no pongan cara triste, como hacen los hipócritas, que desfiguran su rostro para que se note que ayunan. Les aseguro que con eso, ya han recibido su recompensa.","Tú, en cambio, cuando ayunes, perfuma tu cabeza y lava tu rostro,","para que tu ayuno no sea conocido por los hombres, sino por tu Padre que está en lo secreto; y tu Padre, que ve en lo secreto, te recompensará.","No acumulen tesoros en la tierra, donde la polilla y la herrumbre los consumen, y los ladrones perforan las paredes y los roban.","Acumulen, en cambio, tesoros en el cielo, donde no hay polilla ni herrumbre que los consuma, ni ladrones que perforen y roben.","Allí donde esté tu tesoro, estará también tu corazón.","La lámpara del cuerpo es el ojo. Si el ojo está sano, todo el cuerpo estará iluminado.","Pero si el ojo está enfermo, todo el cuerpo estará en tinieblas. Si la luz que hay en ti se oscurece, ¡cuánta oscuridad habrá!","Nadie puede servir a dos señores, porque aborrecerá a uno y amará al otro, o bien, se interesará por el primero y menospreciará al segundo. No se puede servir a Dios y al Dinero.","Por eso les digo: No se inquieten por su vida, pensando qué van a comer, ni por su cuerpo, pensando con qué se van a vestir. ¿No vale acaso más la vida que la comida y el cuerpo más que el vestido?","Miren los pájaros del cielo: ellos no siembran ni cosechan, ni acumulan en graneros, y sin embargo, el Padre que está en el cielo los alimenta. ¿No valen ustedes acaso más que ellos?","¿Quién de ustedes, por mucho que se inquiete, puede añadir un solo instante al tiempo de su vida?","¿Y por qué se inquietan por el vestido? Miren los lirios del campo, cómo van creciendo sin fatigarse ni tejer.","Yo les aseguro que ni Salomón, en el esplendor de su gloria, se vistió como uno de ellos.","Si Dios viste así la hierba de los campos, que hoy existe y mañana será echada al fuego, ¡cuánto más hará por ustedes, hombres de poca fe!","No se inquieten entonces, diciendo: «¿Qué comeremos, qué beberemos, o con qué nos vestiremos?».","Son los paganos los que van detrás de estas cosas. El Padre que está en el cielo sabe bien que ustedes las necesitan.","Busquen primero el Reino y su justicia, y todo lo demás se les dará por añadidura.","No se inquieten por el día de mañana; el mañana se inquietará por sí mismo. A cada día le basta su aflicción."],["No juzguen, para no ser juzgados.","Porque con el criterio con que ustedes juzguen se los juzgará, y la medida con que midan se usará para ustedes.","¿Por qué te fijas en la paja que está en el ojo de tu hermano y no adviertes la viga que está en el tuyo?","¿Cómo puedes decirle a tu hermano: «Deja que te saque la paja de tu ojo», si hay una viga en el tuyo?","Hipócrita, saca primero la viga de tu ojo, y entonces verás claro para sacar la paja del ojo de tu hermano.","No den las cosas sagradas a los perros, ni arrojen sus perlas a los cerdos, no sea que las pisoteen y después se vuelvan contra ustedes para destrozarlos.","Pidan y se les dará; busquen y encontrarán; llamen y se les abrirá.","Porque todo el que pide, recibe; el que busca, encuentra; y al que llama, se le abrirá.","¿Quién de ustedes, cuando su hijo le pide pan, le da una piedra?","¿O si le pide un pez, le da una serpiente?","Si ustedes, que son malos, saben dar cosas buenas a sus hijos, ¡cuánto más el Padre celestial dará cosas buenas a aquellos que se las pidan!","Todos los que deseen que los demás hagan por ustedes, háganlo por ellos: en esto consiste la Ley y los Profetas.","Entren por la puerta estrecha, porque es ancha la puerta y espacioso el camino que lleva a la perdición, y son muchos los que van por allí.","Pero es angosta la puerta y estrecho el camino que lleva a la Vida, y son pocos los que lo encuentran.","Tengan cuidado de los falsos profetas, que se presentan cubiertos con pieles de ovejas, pero por dentro son lobos rapaces.","Por sus frutos los reconocerán. ¿Acaso se recogen uvas de los espinos o higos de los cardos?","Así, todo árbol bueno produce frutos buenos y todo árbol malo produce frutos malos.","Un árbol bueno no puede producir frutos malos, ni un árbol malo, producir frutos buenos.","Al árbol que no produce frutos buenos se lo corta y se lo arroja al fuego.","Por sus frutos, entonces, ustedes los reconocerán.","No son los que me dicen: «Señor, Señor», los que entrarán en el Reino de los Cielos, sino los que cumplen la voluntad de mi Padre que está en el cielo.","Muchos me dirán en aquel día: «Señor, Señor, ¿acaso no profetizamos en tu Nombre? ¿No expulsamos a los demonios e hicimos muchos milagros en tu Nombre?».","Entonces yo les manifestaré: «Jamás los conocí; apártense de mí, ustedes, los que hacen el mal».","Así, todo el que escucha las palabras que acabo de decir y las pone en práctica, puede compararse a un hombre sensato que edificó su casa sobre roca.","Cayeron las lluvias, se precipitaron los torrentes, soplaron los vientos y sacudieron la casa; pero esta no se derrumbó porque estaba construida sobre roca.","Al contrario, el que escucha mis palabras y no las practica, puede compararse a un hombre insensato, que edificó su casa sobre arena».","Cayeron las lluvias, se precipitaron los torrentes, soplaron los vientos y sacudieron la casa: esta se derrumbó, y su ruina fue grande».","Cuando Jesús terminó de decir estas palabras, la multitud estaba asombrada de su enseñanza,","porque él les enseñaba como quien tiene autoridad y no como sus escribas."],["Cuando Jesús bajó de la montaña, lo siguió una gran multitud.","Entonces un leproso fue a postrarse ante él y le dijo: «Señor, si quieres, puedes purificarme».","Jesús extendió la mano y lo tocó, diciendo: «Lo quiero, queda purificado». Y al instante quedó purificado de su lepra.","Jesús le dijo: «No se lo digas a nadie, pero ve a presentarse al sacerdote y entrega la ofrenda que ordenó Moisés para que les sirva de testimonio».","Al entrar en Cafarnaúm, se le acercó un centurión, rogándole»","«Señor, mi sirviente está en casa enfermo de parálisis y sufre terriblemente».","Jesús le dijo: «Yo mismo iré a curarlo».","Pero el centurión respondió: «Señor, no soy digno de que entres en mi casa; basta que digas una palabra y mi sirviente se sanará.","Porque cuando yo, que no soy más que un oficial subalterno, digo a uno de los soldados que están a mis órdenes: «Ve», él va, y a otro: «Ven», él viene; y cuando digo a mi sirviente: «Tienes que hacer esto», él lo hace».","Al oírlo, Jesús quedó admirado y dijo a los que lo seguían: «Les aseguro que no he encontrado a nadie en Israel que tenga tanta fe.","Por eso les digo que muchos vendrán de Oriente y de Occidente, y se sentarán a la mesa con Abraham, Isaac y Jacob, en el Reino de los Cielos;","en cambio, los herederos del reino serán arrojados afuera, a las tinieblas, donde habrá llantos y rechinar los dientes».","Y Jesús dijo al centurión: «Ve, y que suceda como has creído». Y el sirviente se curó en ese mismo momento.","Cuando Jesús llegó a la casa de Pedro, encontró a la suegra de este en cama con fiebre.","Le tocó la mano y se le pasó la fiebre. Ella se levantó y se puso a servirlo.","Al atardecer, le llevaron muchos endemoniados, y él, con su palabra, expulsó a los espíritus y curó a todos los que estaban enfermos,","para que se cumpliera lo que había sido anunciado por el profeta Isaías: \"El tomó nuestras debilidades y cargó sobre sí nuestras enfermedades\".","Al verse rodeado de tanta gente, Jesús mandó a sus discípulos que cruzaran a la otra orilla.","Entonces se aproximó un escriba y le dijo: «Maestro, te seguiré adonde vayas».","Jesús le respondió: «Los zorros tienen sus cuevas y las aves del cielo sus nidos; pero el Hijo del hombre no tiene dónde reclinar la cabeza».","Otro de sus discípulos le dijo: «Señor, permíteme que vaya antes a enterrar a mi padre».","Pero Jesús le respondió: «Sígueme, y deja que los muertos entierren a sus muertos».","Después Jesús subió a la barca y sus discípulos lo siguieron.","De pronto se desató en el mar una tormenta tan grande, que las olas cubrían la barca. Mientras tanto, Jesús dormía.","Acercándose a él, sus discípulos lo despertaron, diciéndole: «¡Sálvanos, Señor, nos hundimos!».","El les respondió: «¿Por qué tienen miedo, hombres de poca fe?». Y levantándose, increpó al viento y al mar, y sobrevino una gran calma.","Los hombres se decían entonces, llenos de admiración: «¿Quién es este, que hasta el viento y el mar le obedecen?».","Cuando Jesús llegó a la otra orilla, a la región de los gadarenos, fueron a su encuentro dos endemoniados que salían de los sepulcros. Eran tan feroces, que nadie podía pasar por ese camino.","Y comenzaron a gritar: «¿Que quieres de nosotros, Hijo de Dios? ¿Has venido aquí para atormentarnos antes de tiempo?»","A cierta distancia había una gran piara de cerdos paciendo.","Los demonios suplicaron a Jesús: «Si vas a expulsarnos, envíanos a esa piara».","El les dijo: «Vayan». Ellos salieron y entraron en los cerdos: estos se precipitaron al mar desde lo alto del acantilado, y se ahogaron.","Los cuidadores huyeron y fueron a la ciudad para llevar la noticia de todo lo que había sucedido con los endemoniados.","Toda la ciudad salió al encuentro de Jesús y, al verlo, le rogaron que se fuera de su territorio."],["Jesús subió a la barca, atravesó el lago y regresó a su ciudad.","Entonces le presentaron a un paralítico tendido en una camilla. Al ver la fe de esos hombres, Jesús dijo al paralítico: «Ten confianza, hijo, tus pecados te son perdonados».","Algunos escribas pensaron: «Este hombre blasfema:.","Jesús, leyendo sus pensamientos, les dijo: «¿Por qué piensan mal?","¿Qué es más fácil decir: \"Tus pecados te son perdonados\", o \"Levántate y camina\"?","Para que ustedes sepan que el Hijo del hombre tiene sobre la tierra el poder de perdonar los pecados –dijo al paralítico– levántate, toma tu camilla y vete a tu casa».","El se levantó y se fue a su casa.","Al ver esto, la multitud quedó atemorizada y glorificaba a Dios por haber dado semejante poder a los hombres.","Al irse de allí, Jesús vio a un hombre llamado Mateo, que estaba sentado a la mesa de recaudación de impuestos, y le dijo: «Sígueme». El se levantó y lo siguió.","Mientras Jesús estaba comiendo en la casa, acudieron muchos publicanos y pecadores, y se sentaron a comer con él y sus discípulos.","Al ver esto, los fariseos dijeron a los discípulos: «¿Por qué su Maestro come con publicanos y pecadores?».","Jesús, que había oído, respondió: «No son los sanos los que tienen necesidad del médico, sino los enfermos.","Vayan y aprendan qué significa: Yo quiero misericordia y no sacrificios. Porque yo no he venido a llamar a los justos, sino a los pecadores».","Entonces se acercaron los discípulos de Juan y le dijeron: «¿Por qué tus discípulos no ayunan, como lo hacemos nosotros y los fariseos?».","Jesús les respondió: «¿Acaso los amigos del esposo pueden estar tristes mientras el esposo está con ellos? Llegará el momento en que el esposo les será quitado, y entonces ayunarán.","Nadie usa un pedazo de género nuevo para remendar un vestido viejo, porque el pedazo añadido tira del vestido y la rotura se hace más grande.","Tampoco se pone vino nuevo en odres viejos, porque los odres revientan, el vino se derrama y los odres se pierden. ¡No, el vino nuevo se pone en odres nuevos, y así ambos se conservan!».","Mientras Jesús les estaba diciendo estas cosas, se presentó un alto jefe y, postrándose ante él, le dijo: «Señor, mi hija acaba de morir, pero ven a imponerle tu mano y vivirá».","Jesús se levantó y lo siguió con sus discípulos.","Entonces se le acercó por detrás una mujer que padecía de hemorragias desde hacía doce años, y le tocó los flecos de su manto,","pensando: «Con sólo tocar su manto, quedaré curada».","Jesús se dio vuelta, y al verla, le dijo: «Ten confianza, hija, tu fe te ha salvado». Y desde ese instante la mujer quedó curada.","Al llegar a la casa del jefe, Jesús vio a los que tocaban música fúnebre y a la gente que gritaba, y dijo:","«Retírense, la niña no está muerta, sino que duerme». Y se reían de él.","Cuando hicieron salir a la gente, él entró, la tomó de la mano, y ella se levantó.","Y esta noticia se divulgó por aquella región.","Cuando Jesús se fue, lo siguieron dos ciegos, gritando: «Ten piedad de nosotros, Hijo de David».","Al llegar a la casa, los ciegos se le acercaron y él les preguntó: «¿Creen que yo puedo hacer lo que me piden?». Ellos le respondieron: «Sí, Señor».","Jesús les tocó los ojos, diciendo: «Que suceda como ustedes han creído».","Y se les abrieron sus ojos. Entonces Jesús los conminó: «¡Cuidado! Que nadie lo sepa».","Pero ellos, apenas salieron, difundieron su fama por toda aquella región.","En cuanto se fueron los ciegos, le presentaron a un mudo que estaba endemoniado.","El demonio fue expulsado y el mudo comenzó a hablar. La multitud, admirada, comentaba: «Jamás se vio nada igual en Israel».","Pero los fariseos decían: «El expulsa a los demonios por obra del Príncipe de los demonios».","Jesús recorría todas las ciudades y los pueblos, enseñando en las sinagogas, proclamando la Buena Noticia del Reino y curando todas las enfermedades y dolencias.","Al ver a la multitud, tuvo compasión, porque estaban fatigados y abatidos, como ovejas que no tienen pastor.","Entonces dijo a sus discípulos: «La cosecha es abundante, pero los trabajadores son pocos.","Rueguen al dueño de los sembrados que envíe trabajadores para la cosecha."],["Jesús convocó a sus doce discípulos y les dio el poder de expulsar a los espíritus impuros y de curar cualquier enfermedad o dolencia.","Los nombres de los doce Apóstoles son: en primer lugar, Simón, de sobrenombre Pedro, y su hermano Andrés; luego, Santiago, hijo de Zebedeo, y su hermano Juan;","Felipe y Bartolomé; Tomás y Mateo, el publicano; Santiago, hijo de Alfeo, y Tadeo;","Simón, el Cananeo, y Judas Iscariote, el mismo que lo entregó.","A estos Doce, Jesús los envió con las siguientes instrucciones: «No vayan a regiones paganas, ni entren en ninguna ciudad de los samaritanos.","Vayan, en cambio, a las ovejas perdidas del pueblo de Israel.","Por el camino, proclamen que el Reino de los Cielos está cerca.","Curen a los enfermos, resuciten a los muertos, purifiquen a los leprosos, expulsen a los demonios. Ustedes han recibido gratuitamente, den también gratuitamente.","No lleven encima oro ni plata, ni monedas,","ni provisiones para el camino, ni dos túnicas, ni calzado, ni bastón; porque el que trabaja merece su sustento.","Cuando entren en una ciudad o en un pueblo, busquen a alguna persona respetable y permanezcan en su casa hasta el momento de partir.","Al entrar en la casa, salúdenla invocando la paz sobre ella.","Si esa casa lo merece, que la paz descienda sobre ella; pero si es indigna, que esa paz vuelva a ustedes.","Y si no los reciben ni quieren escuchar sus palabras, al irse de esa casa o de esa ciudad, sacudan hasta el polvo de sus pies.","Les aseguro que, en el día del Juicio, Sodoma y Gomorra serán tratadas menos rigurosamente que esa ciudad.","Yo los envío como a ovejas en medio de lobos: sean entonces astutos como serpientes y sencillos como palomas.","Cuídense de los hombres, porque los entregarán a los tribunales y los azotarán en las sinagogas.","A causa de mí, serán llevados ante gobernadores y reyes, para dar testimonio delante de ellos y de los paganos.","Cuando los entreguen, no se preocupen de cómo van a hablar o qué van a decir: lo que deban decir se les dará a conocer en ese momento,","porque no serán ustedes los que hablarán, sino que el Espíritu de su Padre hablará en ustedes.","El hermano entregará a su hermano para que sea condenado a muerte, y el padre a su hijo; los hijos se rebelarán contra sus padres y los harán morir.","Ustedes serán odiados por todos a causa de mi Nombre, pero aquel que persevere hasta el fin se salvará.","Cuando los persigan en una ciudad, huyan a otra, y si los persiguen en esta, huyan a una tercera. Les aseguro que no acabarán de recorrer las ciudades de Israel, antes que llegue el Hijo del hombre.","El discípulo no es más que el maestro ni el servidor más que su dueño.","Al discípulo le basta ser como su maestro y al servidor como su dueño. Si al dueño de casa lo llamaron Belzebul, ¡cuánto más a los de su casa!","No les teman. No hay nada oculto que no deba ser revelado, y nada secreto que no deba ser conocido.","Lo que yo les digo en la oscuridad, repítanlo en pleno día; y lo que escuchen al oído, proclámenlo desde lo alto de las casas.","No teman a los que matan el cuerpo, pero no pueden matar el alma. Teman más bien a aquel que puede arrojar el alma y el cuerpo a la Gehena.","¿Acaso no se vende un par de pájaros por unas monedas? Sin embargo, ni uno solo de ellos cae en tierra, sin el consentimiento del Padre que está en el cielo.","Ustedes tienen contados todos sus cabellos.","No teman entonces, porque valen más que muchos pájaros.","Al que me reconozca abiertamente ante los hombres, yo los reconoceré ante mi Padre que está en el cielo.","Pero yo renegaré ante mi Padre que está en el cielo de aquel que reniegue de mí ante los hombres.","No piensen que he venido a traer la paz sobre la tierra. No vine a traer la paz, sino la espada.","Porque he venido a enfrentar al hijo con su padre, a la hija con su madre y a la nuera con su suegra;","y así, el hombre tendrá como enemigos a los de su propia casa.","El que ama a su padre o a su madre más que a mí, no es digno de mí; y el que ama a su hijo o a su hija más que a mí, no es digno de mí.","El que no toma su cruz y me sigue, no es digno de mí.","El que encuentre su vida, la perderá; y el que pierda su vida por mí, la encontrará.","El que los recibe a ustedes, me recibe a mí; y el que me recibe, recibe a aquel que me envió.","El que recibe a un profeta por ser profeta, tendrá la recompensa de un profeta; y el que recibe a un justo, tendrá la recompensa de un justo.","Les aseguro que cualquiera que dé a beber, aunque sólo sea un vaso de agua fresca, a uno de estos pequeños por ser mi discípulo, no quedará sin recompensa»."],["Cuando Jesús terminó de dar estas instrucciones a sus doce discípulos, partió de allí, para enseñar y predicar en las ciudades de la región.","Juan el Bautista oyó hablar en la cárcel de las obras de Cristo, y mandó a dos de sus discípulos para preguntarle:","«¿Eres tú el que ha de venir o debemos esperar a otro?».","Jesús les respondió: «Vayan a contar a Juan lo que ustedes oyen y ven:","los ciegos ven y los paralíticos caminan; los leprosos son purificados y los sordos oyen; los muertos resucitan y la Buena Noticia es anunciada a los pobres.","¡Y feliz aquel para quien yo no sea motivo de escándalo!».","Mientras los enviados de Juan se retiraban, Jesús empezó a hablar de él a la multitud, diciendo: «¿Qué fueron a ver al desierto? ¿Una caña agitada por el viento?","¿Qué fueron a ver? ¿Un hombre vestido con refinamiento? Los que se visten de esa manera viven en los palacios de los reyes.","¿Qué fueron a ver entonces? ¿Un profeta? Les aseguro que sí, y más que un profeta.","El es aquel de quien está escrito: \"Yo envío a mi mensajero delante de ti, para prepararte el camino\".","Les aseguro que no ha nacido ningún hombre más grande que Juan el Bautista; y sin embargo, el más pequeño en el Reino de los Cielos es más grande que él.","Desde la época de Juan el Bautista hasta ahora, el Reino de los Cielos es combatido violentamente, y los violentos intentan arrebatarlo.","Porque todos los Profetas, lo mismo que la Ley, han profetizado hasta Juan.","Y si ustedes quieren crearme, él es aquel Elías que debe volver.","¡El que tenga oídos, que oiga!","¿Con quién puedo comparar a esta generación? Se parece a esos muchachos que, sentados en la plaza, gritan a los otros:","«¡Les tocamos la flauta, y ustedes no bailaron! ¡Entonamos cantos fúnebres, y no lloraron!»","Porque llegó Juan, que no come ni bebe, y ustedes dicen: «¡Ha perdido la cabeza!».","Llegó el Hijo del hombre, que come y bebe, y dicen: «Es un glotón y un borracho, amigo de publicanos y pecadores». Pero la Sabiduría ha quedado justificada por sus obras».","Entonces Jesús comenzó a recriminar a aquellas ciudades donde había realizado más milagros, porque no se habían convertido.","«¡Ay de ti, Corozaín! ¡Ay de ti, Betsaida! Porque si los milagros realizados entre ustedes se hubieran hecho en Tiro y en Sidón, hace tiempo que se habrían convertido, poniéndose cilicio y cubriéndose con ceniza.","Yo les aseguro que, en el día del Juicio, Tiro y Sidón serán tratadas menos rigurosamente que ustedes.","Y tú, Cafarnaúm, ¿acaso crees que serás elevada hasta el cielo? No, serás precipitada hasta el infierno. Porque si los milagros realizados en ti se hubieran hecho en Sodoma, esa ciudad aún existiría.","Yo les aseguro que, en el día del Juicio, la tierra de Sodoma será tratada menos rigurosamente que tú».","En esa oportunidad, Jesús dijo: «Te alabo, Padre, Señor del cielo y de la tierra, por haber ocultado estas cosas a los sabios y a los prudentes y haberlas revelado a los pequeños.","Sí, Padre, porque así lo has querido.","Todo me ha sido dado por mi Padre, y nadie conoce al Hijo sino el Padre, así como nadie conoce al Padre sino el Hijo y aquel a quien el Hijo se lo quiera revelar.","Vengan a mí todos los que están afligidos y agobiados, y yo los aliviaré.","Carguen sobre ustedes mi yugo y aprendan de mí, porque soy paciente y humilde de corazón, y así encontrarán alivio.","Porque mi yugo es suave y mi carga liviana."],["En aquel tiempo, Jesús atravesaba unos sembrados y era un día sábado. Como sus discípulos sintieron hambre, comenzaron a arrancar y a comer las espigas.","Al ver esto, los fariseos le dijeron: «Mira que tus discípulos hacen lo que no está permitido en sábado».","Pero él les respondió: «¿No han leído lo que hizo David, cuando él y sus compañeros tuvieron hambre,","cómo entró en la Casa de Dios y comieron los panes de la ofrenda, que no les estaba permitido comer ni a él ni a sus compañeros, sino solamente a los sacerdotes?","¿Y no han leído también en la Ley, que los sacerdotes, en el Templo, violan el descanso del sábado, sin incurrir en falta?","Ahora bien, yo les digo que aquí hay alguien más grande que el Templo.","Si hubieran comprendido lo que significa: Yo quiero misericordia y no sacrificios, no condenarían a los inocentes.","Porque el Hijo del hombre es dueño del sábado.","De allí, Jesús fue a la sinagoga de los fariseos,","donde se encontraba un hombre que tenía una mano paralizada. Para poder acusarlo, ellos le preguntaron: «¿Está permitido curar en sábado?».","El les dijo: «¿Quién de ustedes, si tiene una sola oveja y esta cae a un pozo en sábado, no la va a sacar?","¡Cuánto más vale un hombre que una oveja! Por lo tanto, está permitido hacer una buena acción en sábado».","Entonces dijo al hombre: «Extiende tu mano». El la extendió, y la mano enferma quedó tan sana como la otra.","En seguida los fariseos salieron y se confabularon para buscar la forma de acabar con él.","Al enterarse de esto, Jesús se alejó de allí. Muchos lo siguieron, y los curó a todos.","Pero él les ordenó severamente que no lo dieran a conocer,","para que se cumpliera lo anunciado por el profeta Isaías:","\"Este es mi servidor, a quien elegí, mi muy querido, en quien tengo puesta mi predilección. Derramaré mi Espíritu sobre él y anunciará la justicia a las naciones.","No discutirá ni gritará, y nadie oirá su voz en las plazas.","No quebrará la caña doblada y no apagará la mecha humeante, hasta que haga triunfar la justicia;","y las naciones pondrán la esperanza en su Nombre\".","Entonces, le llevaron a un endemoniado ciego y mudo, y Jesús lo curó, devolviéndole el habla y la vista.","La multitud, asombrada, decía: «¿No será este el Hijo de David?».","Los fariseos, oyendo esto, dijeron: «Este expulsa a los demonios por el poder de Belzebul, el Príncipe de los demonios».","Jesús, conociendo sus pensamientos, les dijo: «Un reino donde hay luchas internas va a la ruina; y una ciudad o una familia dividida no puede subsistir.","Ahora bien, si Satanás expulsa a Satanás, lucha contra sí mismo; entonces, ¿cómo podrá subsistir su reino?","Y si yo expulso a los demonios con el poder de Belzebul, ¿con qué poder los expulsan los discípulos de ustedes? Por eso, ustedes los tendrán a ellos como jueces.","Pero si expulso a los demonios con el poder del Espíritu de Dios, quiere decir que el Reino de Dios ha llegado a ustedes.","¿Acaso alguien puede entrar en la casa de un hombre fuerte y robar sus cosas, si primero no lo ata? Sólo así podrá saquear la casa.","El que no está conmigo, está contra mí; y el que no recoge conmigo, desparrama.","Por eso les digo que todo pecado o blasfemia se les perdonará a los hombres, pero la blasfemia contra el Espíritu no será perdonada.","Al que diga una palabra contra el Hijo del hombre, se le perdonará; pero al que hable contra el Espíritu Santo, no se le perdonará ni en este mundo ni en el futuro.","Supongan que el árbol es bueno: el fruto también será bueno. Supongan que el árbol es malo: el fruto también será malo. Porque el árbol se conoce por su fruto.","Raza de víboras, ¿cómo pueden ustedes decir cosas buenas, siendo malos? Porque la boca habla de la abundancia del corazón.","El hombre bueno saca cosas buenas de su tesoro de bondad; y el hombre malo saca cosas malas de su tesoro de maldad.","Pero les aseguro que en el día del Juicio, los hombres rendirán cuenta de toda palabra vana que hayan pronunciado.","Porque por tus palabras serás justificado, y por tus palabras serás condenado».","Entonces algunos escribas y fariseos le dijeron: «Maestro, queremos que nos hagas ver un signo».","El les respondió: «Esta generación malvada y adúltera reclama un signo, pero no se le dará otro que el del profeta Jonás.","Porque así como Jonás estuvo tres días y tres noches en el vientre del pez, así estará el Hijo del hombre en el seno de la tierra tres días y tres noches.","El día de Juicio, los hombres de Nínive se levantarán contra esta generación y la condenarán, porque ellos se convirtieron por la predicación de Jonás, y aquí hay alguien que es más que Jonás.","El día del Juicio, la Reina del Sur se levantará contra esta generación y la condenará, porque ella vino de los confines de la tierra para escuchar la sabiduría de Salomón, y aquí hay alguien que es más que Salomón.","Cuando el espíritu impuro sale de un hombre, vaga por lugares desiertos en busca de reposo, y al no encontrarlo,","piensa: «Volveré a mi casa, de donde salí». Cuando llega, la encuentra vacía, barrida y ordenada.","Entonces va a buscar a otros siete espíritus peores que él; vienen y se instalan allí. Y al final, ese hombre se encuentra peor que al principio. Así sucederá con esta generación malvada».","Todavía estaba hablando a la multitud, cuando su madre y sus hermanos, que estaban afuera, trataban de hablar con él.","Alguien le dijo: «Tu madre y tus hermanos están ahí afuera y quieren hablarte».","Jesús le respondió: «¿Quién es mí madre y quiénes son mis hermanos?».","Y señalando con la mano a sus discípulos, agregó: «Estos son mi madre y mis hermanos.","Porque todo el que hace la voluntad de mi Padre que está en el cielo, ese es mi hermano, mi hermana y mi madre»."],["Aquel día, Jesús salió de la casa y se sentó a orillas del mar.","Una gran multitud se reunió junto a él, de manera que debió subir a una barca y sentarse en ella, mientras la multitud permanecía en la costa.","Entonces él les habló extensamente por medio de parábolas. Les decía: «El sembrador salió a sembrar.","Al esparcir las semillas, algunas cayeron al borde del camino y los pájaros las comieron.","Otras cayeron en terreno pedregoso, donde no había mucha tierra, y brotaron en seguida, porque la tierra era poco profunda;","pero cuando salió el sol, se quemaron y, por falta de raíz, se secaron.","Otras cayeron entre espinas, y estas, al crecer, las ahogaron.","Otras cayeron en tierra buena y dieron fruto: unas cien, otras sesenta, otras treinta.","¡El que tenga oídos, que oiga!».","Los discípulos se acercaron y le dijeron: «¿Por qué les hablas por medio de parábolas?».","El les respondió: «A ustedes se les ha concedido conocer los misterios del Reino de los Cielos, pero a ellos no.","Porque a quien tiene, se le dará más todavía y tendrá en abundancia, pero al que no tiene, se le quitará aun lo que tiene.","Por eso les hablo por medio de parábolas: porque miran y no ven, oyen y no escuchan ni entienden.","Y así se cumple en ellos la profecía de Isaías, que dice: \"Por más que oigan, no comprenderán, por más que vean, no conocerán,","Porque el corazón de este pueblo se ha endurecido, tienen tapados sus oídos y han cerrado sus ojos, para que sus ojos no vean, y sus oídos no oigan, y su corazón no comprenda, y no se conviertan, y yo no los cure\".","Felices, en cambio, los ojos de ustedes, porque ven; felices sus oídos, porque oyen.","Les aseguro que muchos profetas y justos desearon ver lo que ustedes ven y no lo vieron, oír lo que ustedes oyen, y no lo oyeron.","Escuchen, entonces, lo que significa la parábola del sembrador.","Cuando alguien oye la Palabra del Reino y no la comprende, viene el Maligno y arrebata lo que había sido sembrado en su corazón: este es el que recibió la semilla al borde del camino.","El que la recibe en terreno pedregoso es el hombre que, al escuchar la Palabra, la acepta en seguida con alegría,","pero no la deja echar raíces, porque es inconstante: en cuanto sobreviene una tribulación o una persecución a causa de la Palabra, inmediatamente sucumbe.","El que recibe la semilla entre espinas es el hombre que escucha la Palabra, pero las preocupaciones del mundo y la seducción de las riquezas la ahogan, y no puede dar fruto.","Y el que la recibe en tierra fértil es el hombre que escucha la Palabra y la comprende. Este produce fruto, ya sea cien, ya sesenta, ya treinta por uno».","Y les propuso otra parábola: «El Reino de los Cielos se parece a un hombre que sembró buena semilla en su campo;","pero mientras todos dormían vino su enemigo, sembró cizaña en medio del trigo y se fue.","Cuando creció el trigo y aparecieron las espigas, también apareció la cizaña.","Los peones fueron a ver entonces al propietario y le dijeron: «Señor, ¿no habías sembrado buena semilla en tu campo? ¿Cómo es que ahora hay cizaña en él?.","El les respondió: «Esto lo ha hecho algún enemigo». Los peones replicaron: «¿Quieres que vayamos a arrancarla?».","«No, les dijo el dueño, porque al arrancar la cizaña, corren el peligro de arrancar también el trigo.","Dejen que crezcan juntos hasta la cosecha, y entonces diré a los cosechadores: Arranquen primero la cizaña y átenla en manojos para quemarla, y luego recojan el trigo en mi granero».","También les propuso otra parábola: «El Reino de los Cielos se parece a un grano de mostaza que un hombre sembró en su campo.","En realidad, esta es la más pequeña de las semillas, pero cuando crece es la más grande de las hortalizas y se convierte en un arbusto, de tal manera que los pájaros del cielo van a cobijarse en sus ramas».","Después les dijo esta otra parábola: «El Reino de los Cielos se parece a un poco de levadura que una mujer mezcla con gran cantidad de harina, hasta que fermenta toda la masa».","Todo esto lo decía Jesús a la muchedumbre por medio de parábolas, y no les hablaba sin parábolas,","para que se cumpliera lo anunciado por el Profeta: \"Hablaré en parábolas anunciaré cosas que estaban ocultas desde la creación del mundo\".","Entonces, dejando a la multitud, Jesús regresó a la casa; sus discípulos se acercaron y le dijeron: «Explícanos la parábola de la cizaña en el campo».","El les respondió: «El que siembra la buena semilla es el Hijo del hombre;","el campo es el mundo; la buena semilla son los que pertenecen al Reino; la cizaña son los que pertenecen al Maligno,","y el enemigo que la siembra es el demonio; la cosecha es el fin del mundo y los cosechadores son los ángeles.","Así como se arranca la cizaña y se la quema en el fuego, de la misma manera sucederá al fin del mundo.","El Hijo del hombre enviará a sus ángeles, y estos quitarán de su Reino todos los escándalos y a los que hicieron el mal,","y los arrojarán en el horno ardiente: allí habrá llanto y rechinar de dientes.","Entonces los justos resplandecerán como el sol en el Reino de su Padre. ¡El que tenga oídos, que oiga!","El Reino de los Cielos se parece a un tesoro escondido en un campo; un hombre lo encuentra, lo vuelve a esconder, y lleno de alegría, vende todo lo que posee y compra el campo.","El Reino de los Cielos se parece también a un negociante que se dedicaba a buscar perlas finas;","y al encontrar una de gran valor, fue a vender todo lo que tenía y la compró.","El Reino de los Cielos se parece también a una red que se echa al mar y recoge toda clase de peces.","Cuando está llena, los pescadores la sacan a la orilla y, sentándose, recogen lo bueno en canastas y tiran lo que no sirve.","Así sucederá al fin del mundo: vendrán los ángeles y separarán a los malos de entre los justos,","para arrojarlos en el horno ardiente. Allí habrá llanto y rechinar de dientes.","¿Comprendieron todo esto?». «Sí», le respondieron.","Entonces agregó: «Todo escriba convertido en discípulo del Reino de los Cielos se parece a un dueño de casa que saca de sus reservas lo nuevo y lo viejo».","Cuando Jesús terminó estas parábolas se alejó de allí","y, al llegar a su pueblo, se puso a enseñar a la gente en la sinagoga, de tal manera que todos estaban maravillados. «¿De dónde le viene, decían, esta sabiduría y ese poder de hacer milagros?","¿No es este el hijo del carpintero? ¿Su madre no es la que llaman María? ¿Y no son hermanos suyos Santiago, José, Simón y Judas?","¿Y acaso no viven entre nosotros todas sus hermanas? ¿De dónde le vendrá todo esto?».","Y Jesús era para ellos un motivo de escándalo. Entonces les dijo: «Un profeta es despreciado solamente en su pueblo y en su familia».","Y no hizo allí muchos milagros, a causa de la falta de fe de esa gente."],["En aquel tiempo, la fama de Jesús llegó a oídos del tetrarca Herodes,","y él dijo a sus allegados: «Este es Juan el Bautista; ha resucitado de entre los muertos, y por eso se manifiestan en él poderes milagrosos».","Herodes, en efecto, había hecho arrestar, encadenar y encarcelar a Juan, a causa de Herodías, la mujer de su hermano Felipe,","porque Juan le decía: «No te es lícito tenerla».","Herodes quería matarlo, pero tenía miedo del pueblo, que consideraba a Juan un profeta.","El día en que Herodes festejaba su cumpleaños, la hija de Herodías bailó en público, y le agradó tanto a Herodes","que prometió bajo juramento darle lo que pidiera.","Instigada por su madre, ella dijo: «Tráeme aquí sobre una bandeja la cabeza de Juan el Bautista».","El rey se entristeció, pero a causa de su juramento y por los convidados, ordenó que se la dieran","y mandó decapitar a Juan en la cárcel.","Su cabeza fue llevada sobre una bandeja y entregada a la joven, y esta la presentó a su madre.","Los discípulos de Juan recogieron el cadáver, lo sepultaron y después fueron a informar a Jesús.","Al enterarse de eso, Jesús se alejó en una barca a un lugar desierto para esta a solas. Apenas lo supo la gente, dejó las ciudades y lo siguió a pie.","Cuando desembarcó, Jesús vio una gran muchedumbre y, compadeciéndose de ella, curó a los enfermos.","Al atardecer, los discípulos se acercaron y le dijeron: «Este es un lugar desierto y ya se hace tarde; despide a la multitud para que vaya a las ciudades a comprarse alimentos».","Pero Jesús les dijo: «No es necesario que se vayan, denles de comer ustedes mismos».","Ellos respondieron: «Aquí no tenemos más que cinco panes y dos pescados».","«Tráiganmelos aquí», les dijo.","Y después de ordenar a la multitud que se sentara sobre el pasto, tomó los cinco panes y los dos pescados, y levantando los ojos al cielo, pronunció la bendición, partió los panes, los dio a sus discípulos, y ellos los distribuyeron entre la multitud.","Todos comieron hasta saciarse y con los pedazos que sobraron se llenaron doce canastas.","Los que comieron fueron unos cinco mil hombres, sin contar las mujeres y los niños.","En seguida, obligó a los discípulos que subieran a la barca y pasaran antes que él a la otra orilla, mientras él despedía a la multitud.","Después, subió a la montaña para orar a solas. Y al atardecer, todavía estaba allí, solo.","La barca ya estaba muy lejos de la costa, sacudida por las olas, porque tenían viento en contra.","A la madrugada, Jesús fue hacia ellos, caminando sobre el mar.","Los discípulos, al verlo caminar sobre el mar, se asustaron. «Es un fantasma», dijeron, y llenos de temor se pusieron a gritar.","Pero Jesús les dijo: «Tranquilícense, soy yo; no teman.","Entonces Pedro le respondió: «Señor, si eres tú, mándame ir a tu encuentro sobre el agua».","«Ven», le dijo Jesús. Y Pedro, bajando de la barca, comenzó a caminar sobre el agua en dirección a él.","Pero, al ver la violencia del viento, tuvo miedo, y como empezaba a hundirse, gritó: «Señor, sálvame».","En seguida, Jesús le tendió la mano y lo sostuvo, mientras le decía: «Hombre de poca fe, ¿por qué dudaste?».","En cuanto subieron a la barca, el viento se calmó.","Los que estaban en ella se postraron ante él, diciendo: «Verdaderamente, tú eres el Hijo de Dios».","Al llegar a la otra orilla, fueron a Genesaret.","Cuando la gente del lugar lo reconoció, difundió la noticia por los alrededores, y le llevaban a todos los enfermos,","rogándole que los dejara tocar tan sólo los flecos de su manto, y todos los que lo tocaron quedaron curados."],["Entonces, unos fariseos y escribas de Jerusalén se acercaron a Jesús y le dijeron:","«¿Por qué tus discípulos quebrantan la tradición de nuestros antepasados y no se lavan las manos antes de comer?».","El les respondió: «¿Y por qué ustedes, por seguir su tradición, no cumplen el mandamiento de Dios?","En efecto, Dios dijo: \"Honra a tu padre y a tu madre\" y: \"El que maldice a su padre o a su madre, será condenado a muerte\".","Pero ustedes afirman: El que diga a su padre o a su madre: «He ofrecido al Templo los bienes que tenía para ayudarte»,","está libre de los deberes hacia ellos. Así ustedes, en nombre de su tradición, han anulado la Palabra de Dios.","¡Hipócritas! Bien profetizó de ustedes Isaías, cuando dijo:","\"Este pueblo me honra con los labios, pero su corazón está lejos de mí.","En vano me rinden culto: las doctrinas que enseñan no son sino preceptos humanos\"».","Jesús llamó a la multitud y le dijo: «Escuchen y comprendan.","Lo que mancha al hombre no es lo que entra por la boca, sino lo que sale de ella».","Entonces se acercaron los discípulos y le dijeron: «¿Sabes que los fariseos se escandalizaron al oírte hablar así?».","El les respondió: «Toda planta que no haya plantado mi Padre celestial, será arrancada de raíz.","Déjenlos: son ciegos que guían a otros ciegos. Pero si un ciego guía a otro, los dos caerán en un pozo».","Pedro, tomando la palabra, le dijo: «Explícanos esta parábola».","Jesús le respondió: «¿Ni siquiera ustedes son capaces de comprender?","¿No saben que lo que entra por la boca pasa al vientre y se elimina en lugares retirados?","En cambio, lo que sale de la boca procede del corazón, y eso es lo que mancha al hombre.","Del corazón proceden las malas intenciones, los homicidios, los adulterios, las fornicaciones, los robos, los falsos testimonios, las difamaciones.","Estas son las cosas que hacen impuro al hombre, no el comer sin haberse lavado las manos».","Jesús partió de allí y se retiró al país de Tiro y de Sidón.","Entonces una mujer cananea, que procedía de esa región, comenzó a gritar: «¡Señor, Hijo de David, ten piedad de mí! Mi hija está terriblemente atormentada por un demonio».","Pero él no le respondió nada. Sus discípulos se acercaron y le pidieron: «Señor, atiéndela, porque nos persigue con sus gritos».","Jesús respondió: «Yo he sido enviado solamente a las ovejas perdidas del pueblo de Israel».","Pero la mujer fue a postrarse ante él y le dijo: «¡Señor, socórreme!».","Jesús le dijo: «No está bien tomar el pan de los hijos, para tirárselo a los cachorros».","Ella respondió: «¡Y sin embargo, Señor, los cachorros comen las migas que caen de la mesa de sus dueños!».","Entonces Jesús le dijo: «Mujer, ¡qué grande es tu fe! ¡Que se cumpla tu deseo!». Y en ese momento su hija quedó curada.","Desde allí, Jesús llegó a orillas del mar de Galilea y, subiendo a la montaña, se sentó.","Una gran multitud acudió a él, llevando paralíticos, lisiados, ciegos, mudos y muchos otros enfermos. Los pusieron a sus pies y él los curó.","La multitud se admiraba al ver que los mudos hablaban, los inválidos quedaban curados, los paralíticos caminaban y los ciegos recobraban la vista. Y todos glorificaban al Dios de Israel.","Entonces Jesús llamó a sus discípulos y les dijo: «Me da pena esta multitud, porque hace tres días que están conmigo y no tienen qué comer. No quiero despedirlos en ayunas, porque podrían desfallecer en el camino».","Los discípulos le dijeron: «¿Y dónde podríamos conseguir en este lugar despoblado bastante cantidad de pan para saciar a tanta gente?».","Jesús les dijo: «¿Cuántos panes tienen?». Ellos respondieron: «Siete y unos pocos pescados».","El ordenó a la multitud que se sentara en el suelo;","después, tomó los panes y los pescados, dio gracias, los partió y los dio a los discípulos. Y ellos los distribuyeron entre la multitud.","Todos comieron hasta saciarse, y con los pedazos que sobraron se llenaron siete canastas.","Los que comieron eran cuatro mil hombres, sin contar las mujeres y los niños.","Después que despidió a la multitud, Jesús subió a la barca y se dirigió al país de Magadán."],["Los fariseos y los saduceos se acercaron a él y, para ponerlo a prueba, le pidieron que les hiciera ver un signo del cielo.","El les respondió: «Al atardecer, ustedes dicen: «Va a hacer buen tiempo, porque el cielo está rojo como el fuego».","Y de madrugada, dicen: «Hoy habrá tormenta, porque el cielo está rojo oscuro». ¡De manera que saben interpretar el aspecto del cielo, pero no los signos de los tiempos!","Esta generación malvada y adúltera reclama un signo, pero no se le dará otro signo que el de Jonás». Y en seguida los dejó y se fue.","Al pasar a la orilla, los discípulos se olvidaron de llevar pan.","Jesús les dijo: «Estén atentos y cuídense de la levadura de los fariseos y de los saduceos».","Ellos pensaban: «Lo dice porque no hemos traído pan».","Jesús se dio cuenta y les dijo: «Hombres de poca fe, ¿cómo están pensando que no tienen pan?","¿Todavía no comprenden? ¿No se acuerdan de los cinco panes para cinco mil personas y del número de canastas que juntaron?","¿Y tampoco recuerdan lo siete panes para cuatro mil personas, y cuántas canastas recogieron?","¿Cómo no comprenden que no me refería al pan? ¡Cuídense de la levadura de los fariseos y de los saduceos!».","Entonces entendieron que les había dicho que se cuidaran, no de la levadura del pan, sino de la doctrina de los fariseos y de los saduceos.","Al llegar a la región de Cesarea de Filipo, Jesús preguntó a sus discípulos: «¿Qué dice la gente sobre el Hijo del hombre? ¿Quién dicen que es?».","Ellos le respondieron: «Unos dicen que es Juan el Bautista; otros Elías; y otros, Jeremías o alguno de los profetas».","«Y ustedes, les preguntó, ¿quién dicen que soy?».","Tomando la palabra, Simón Pedro respondió: «Tú eres el Mesías, el Hijo de Dios vivo».","Y Jesús le dijo: «Feliz de ti, Simón, hijo de Jonás, porque esto no te lo ha revelado ni la carne ni la sangre, sino mi Padre que está en el cielo.","Y yo te digo: «Tú eres Pedro, y sobre esta piedra edificaré mi iglesia, y el poder de la Muerte no prevalecerá contra ella.","Yo te dará las llaves del Reino de los Cielos. Todo lo que ates en la tierra, quedará atado en el cielo, y todo lo que desates en la tierra, quedará desatado en el cielo».","Entonces ordenó severamente a sus discípulos que no dijeran a nadie que él era el Mesías.","Desde aquel día, Jesús comenzó a anunciar a sus discípulos que debía ir a Jerusalén, y sufrir mucho de parte de los ancianos, de los sumos sacerdotes y de los escribas; que debía ser condenado a muerte y resucitar al tercer día.","Pedro lo llevó aparte y comenzó a reprenderlo, diciendo: «Dios no lo permita, Señor, eso no sucederá».","Pero él, dándose vuelta, dijo a Pedro: «¡Retírate, ve detrás de mí, Satanás! Tú eres para mí un obstáculo, porque tus pensamientos no son los de Dios, sino los de los hombres».","Entonces Jesús dijo a sus discípulos: «El que quiera venir detrás de mí, que renuncie a sí mismo, que cargue con su cruz y me siga.","Porque él que quiera salvar su vida, la perderá; y el que pierda su vida a causa de mí, la encontrará.","¿De qué le servirá al hombre ganar el mundo entero si pierde su vida? ¿Y qué podrá dar el hombre a cambio de su vida?","Porque el Hijo del hombre vendrá en la gloria de su Padre, rodeado de sus ángeles, y entonces pagará a cada uno de acuerdo con sus obras.","Les aseguro que algunos de los que están aquí presentes no morirán antes de ver al Hijo del hombre, cuando venga en su Reino»."],["Seis días después, Jesús tomó a Pedro, a Santiago y a su hermano Juan, y los llevó aparte a un monte elevado.","Allí se transfiguró en presencia de ellos: su rostro resplandecía como el sol y sus vestiduras se volvieron blancas como la luz.","De pronto se les aparecieron Moisés y Elías, hablando con Jesús.","Pedro dijo a Jesús: «Señor, ¡qué bien estamos aquí! Si quieres, levantará aquí mismo tres carpas, una para ti, otra para Moisés y otra para Elías».","Todavía estaba hablando, cuando una nube luminosa los cubrió con su sombra y se oyó una voz que decía desde la nube: «Este es mi Hijo muy querido, en quien tengo puesta mi predilección: escúchenlo».","Al oír esto, los discípulos cayeron con el rostro en tierra, llenos de temor.","Jesús se acercó a ellos, y tocándolos, les dijo: «Levántense, no tengan miedo».","Cuando alzaron los ojos, no vieron a nadie más que a Jesús solo.","Mientras bajaban del monte, Jesús les ordenó: «No hablen a nadie de esta visión, hasta que el Hijo del hombre resucite de entre los muertos».","Entonces los discípulos le preguntaron: «¿Por qué dicen los escribas que primero debe venir Elías?».","El respondió: «Sí, Elías debe venir a poner en orden todas las cosas;","pero les aseguro que Elías ya ha venido, y no lo han reconocido, sino que hicieron con él lo que quisieron. Y también harán padecer al Hijo del hombre».","Los discípulos comprendieron entonces que Jesús se refería a Juan el Bautista.","Cuando se reunieron con la multitud se le acercó un hombre y, cayendo de rodillas,","le dijo: «Señor, ten piedad de mí hijo, que es epiléptico y está muy mal: frecuentemente cae en el fuego y también en el agua.","Yo lo llevé a tus discípulos, pero no lo pudieron curar».","Jesús respondió: «¡Generación incrédula y perversa! ¿Hasta cuándo estaré con ustedes? ¿Hasta cuándo tendré que soportarlos? Tráiganmelo aquí».","Jesús increpó al demonio, y este salió del niño, que desde aquel momento, quedó curado.","Los discípulos se acercaron entonces a Jesús y le preguntaron en privado: «¿Por qué nosotros no pudimos expulsarlo?».","«Porque ustedes tienen poca fe, les dijo. Les aseguro que si tuvieran fe del tamaño de un grano de mostaza, dirían a esta montaña: «Trasládate de aquí a allá», y la montaña se trasladaría; y nada sería imposible para ustedes».","[«En cuanto a esta clase de demonios, no se los puede expulsar sino por medio de la oración y del ayuno»].","Mientras estaban reunidos en Galilea, Jesús les dijo: «El Hijo del hombre va a ser entregado en manos de los hombres:","lo matarán y al tercer día resucitará». Y ellos quedaron muy apenados.","Al llegar a Cafarnaúm, los cobradores del impuesto del Templo se acercaron a Pedro y le preguntaron: «¿El Maestro de ustedes no paga el impuesto?».","«Sí, lo paga», respondió. Cuando Pedro llegó a la casa, Jesús se adelantó a preguntarle: «¿Qué te parece, Simón? ¿De quiénes perciben los impuestos y las tasas los reyes de la tierra, de sus hijos o de los extraños?».","Y como Pedro respondió: «De los extraños», Jesús le dijo: «Eso quiere decir que los hijos están exentos.","Sin embargo, para no escandalizar a esta gente, ve al lago, echa el anzuelo, toma el primer pez que salga y ábrele la boca. Encontrarás en ella una moneda de plata: tómala, y paga por mí y por ti»."],["En aquel momento los discípulos se acercaron a Jesús para preguntarle: «¿Quién es el más grande en el Reino de los Cielos?».","Jesús llamó a un niño, lo puso en medio de ellos","y dijo: «Les aseguro que si ustedes no cambian o no se hacen como niños, no entrarán en el Reino de los Cielos.","Por lo tanto, el que se haga pequeño como este niño, será el más grande en el Reino de los Cielos.","El que recibe a uno de estos pequeños en mi Nombre, me recibe a mí mismo.","Pero si alguien escandaliza a uno de estos pequeños que creen en mí, sería preferible para él que le ataran al cuello una piedra de moler y lo hundieran en el fondo del mar.","¡Ay del mundo a causa de los escándalos! Es inevitable que existan pero ¡ay de aquel que los causa!","Si tu mano o tu pie son para ti ocasión de pecado, córtalos y arrójalos lejos de ti, porque más te vale entrar en la Vida manco o lisiado, que ser arrojado con tus dos manos o tus pies en el fuego eterno.","Y si tu ojo es para ti ocasión de pecado, arráncalo y tíralo lejos, porque más te vale entrar con un solo ojo en la Vida, que ser arrojado con tus dos ojos en la Gehena del fuego.","Cuídense de despreciar a cualquiera de estos pequeños, porque les aseguro que sus ángeles en el cielo están constantemente en presencia de mi Padre celestial.","[Porque el Hijo del Hombre ha venido a salvar lo que estaba perdido].","¿Qué les parece? Si un hombre tiene cien ovejas, y una de ellas se pierde, ¿no deja las noventa y nueve restantes en la montaña, para ir a buscar la que se extravió?","Y si llega a encontrarla, les aseguro que se alegrará más por ella que por las noventa y nueve que no se extraviaron.","De la misma manera, el Padre que está en el cielo no quiere que se pierda ni uno solo de estos pequeños.","Si tu hermano peca, ve y corrígelo en privado. Si te escucha, habrás ganado a tu hermano.","Si no te escucha, busca una o dos personas más, para que el asunto se decida por la declaración de dos o tres testigos.","Si se niega a hacerles caso, dilo a la comunidad. Y si tampoco quiere escuchar a la comunidad, considéralo como pagano o republicano.","Les aseguro que todo lo que ustedes aten en la tierra, quedará atado en el cielo, y lo que desaten en la tierra, quedará desatado en el cielo.","También les aseguro que si dos de ustedes se unen en la tierra para pedir algo, mi Padre que está en el cielo se lo concederá.","Porque donde hay dos o tres reunidos en mi Nombre, yo estoy presente en medio de ellos».","Entonces se adelantó Pedro y le dijo: «Señor, ¿cuántas veces tendré que perdonar a mi hermano las ofensas que me haga? ¿Hasta siete veces?».","Jesús le respondió: «No te digo hasta siete veces, sino hasta setenta veces siete.","Por eso, el Reino de los Cielos se parece a un rey que quiso arreglar las cuentas con sus servidores.","Comenzada la tarea, le presentaron a uno que debía diez mil talentos.","Como no podía pagar, el rey mandó que fuera vendido junto con su mujer, sus hijos y todo lo que tenía, para saldar la deuda.","El servidor se arrojó a sus pies, diciéndole: \"Señor, dame un plazo y te pagaré todo\".","El rey se compadeció, lo dejó ir y, además, le perdonó la deuda.","Al salir, este servidor encontró a uno de sus compañeros que le debía cien denarios y, tomándolo del cuello hasta ahogarlo, le dijo: \"Págame lo que me debes\".","El otro se arrojó a sus pies y le suplicó: \"Dame un plazo y te pagaré la deuda\".","Pero él no quiso, sino que lo hizo poner en la cárcel hasta que pagara lo que debía.","Los demás servidores, al ver lo que había sucedido, se apenaron mucho y fueron a contarlo a su señor.","Este lo mandó llamar y le dijo: \"¡Miserable! Me suplicaste, y te perdoné la deuda.","¿No debías también tú tener compasión de tu compañero, como yo me compadecí de ti?\".","E indignado, el rey lo entregó en manos de los verdugos hasta que pagara todo lo que debía.","Lo mismo hará también mi Padre celestial con ustedes, si no perdonan de corazón a sus hermanos»."],["Cuando Jesús terminó de decir estas palabras, dejó la Galilea y fue al territorio de Judea, más allá del Jordán.","Lo siguió una gran multitud y allí curó a los enfermos.","Se acercaron a él algunos fariseos y, para ponerlo a prueba, le dijeron: «¿Es lícito al hombre divorciarse de su mujer por cualquier motivo?».","El respondió: «¿No han leído ustedes que el Creador, desde el principio, los hizo varón y mujer;","y que dijo: \"Por eso, el hombre dejará a su padre y a su madre para unirse a su mujer, y los dos no serán sino una sola carne\"?","De manera que ya no son dos, sino una sola carne. Que el hombre no separe lo que Dios ha unido».","Le replicaron: «Entonces, ¿por qué Moisés prescribió entregar una declaración de divorcio cuando uno se separa?».","El les dijo: «Moisés les permitió divorciarse de su mujer, debido a la dureza del corazón de ustedes, pero al principio no era sí.","Por lo tanto, yo les digo: El que se divorcia de su mujer, a no ser en caso de unión ilegal, y se casa con otra, comete adulterio».","Los discípulos le dijeron: «Si esta es la situación del hombre con respecto a su mujer, no conviene casarse».","Y él les respondió: «No todos entienden este lenguaje, sino sólo aquellos a quienes se les ha concedido.","En efecto, algunos no se casan, porque nacieron impotentes del seno de su madre; otros, porque fueron castrados por los hombres; y hay otros que decidieron no casarse a causa del Reino de los Cielos. ¡El que pueda entender, que entienda!».","Le trajeron entonces a unos niños para que les impusiera las manos y orara sobre ellos. Los discípulos los reprendieron,","pero Jesús les dijo: «Dejen a los niños, y no les impidan que vengan a mí, porque el Reino de los Cielos pertenece a los que son como ellos».","Y después de haberles impuesto las manos, se fue de allí.","Luego se le acercó un hombre y le preguntó: «Maestro, ¿qué obras buenas debo hacer para conseguir la Vida eterna?».","Jesús le dijo: «¿Cómo me preguntas acerca de lo que es bueno? Uno solo es el Bueno. Si quieres entrar en la Vida eterna, cumple los Mandamientos».","«¿Cuáles?», preguntó el hombre. Jesús le respondió: «No matarás, no cometerás adulterio, no robarás, no darás falso testimonio,","honrarás a tu padre y a tu madre, y amarás a tu prójimo como a ti mismo».","El joven dijo: «Todo esto lo he cumplido: ¿qué me queda por hacer?».","«Si quieres ser perfecto, le dijo Jesús ve, vende todo lo que tienes y dalo a los pobres: así tendrás un tesoro en el cielo. Después, ven y sígueme».","Al oír estas palabras, el joven se retiró entristecido, porque poseía muchos bienes.","Jesús dijo entonces a sus discípulos: «Les aseguro que difícilmente un rico entrará en el Reino de los Cielos.","Sí, les repito, es más fácil que un camello pase por el ojo de una aguja, que un rico entre en el Reino de los Cielos».","Los discípulos quedaron muy sorprendidos al oír esto y dijeron: «Entonces, ¿quién podrá salvarse?».","Jesús, fijando en ellos su mirada, les dijo: «Para los hombres esto es imposible, pero para dios todo es posible».","Pedro, tomando la palabra, dijo: «Tú sabes que nosotros lo hemos dejado todo y te hemos seguido. ¿Qué nos tocará a nosotros?».","Jesús les respondió: «Les aseguro que en la regeneración del mundo, cuando el Hijo del hombre se siente en su trono de gloria, ustedes, que me han seguido, también se sentarán en doce tronos, para juzgar a las doce tribus de Israel.","Y el que a causa de mi Nombre deje casa, hermanos o hermanas, padre, madre, hijos o campos, recibirá cien veces más y obtendrá como herencia la Vida eterna.","Muchos de los primeros serán los últimos, y muchos de los últimos serán los primeros."],["Porque el Reino de los Cielos se parece a un propietario que salió muy de madrugada a contratar obreros para trabajar en su viña.","Trató con ellos un denario por día y los envío a su viña.","Volvió a salir a media mañana y, al ver a otros desocupados en la plaza,","les dijo: \"Vayan ustedes también a mi viña y les pagaré lo que sea justo\".","Y ellos fueron. Volvió a salir al mediodía y a media tarde, e hizo lo mismo.","Al caer la tarde salió de nuevo y, encontrando todavía a otros, les dijo: \"¿Cómo se han quedado todo el día aquí, sin hacer nada?\".","Ellos les respondieron: \"Nadie nos ha contratado\". Entonces les dijo: \"Vayan también ustedes a mi viña\".","Al terminar el día, el propietario llamó a su mayordomo y le dijo: \"Llama a los obreros y págales el jornal, comenzando por los últimos y terminando por los primeros\".","Fueron entonces los que habían llegado al caer la tarde y recibieron cada uno un denario.","Llegaron después los primeros, creyendo que iban a recibir algo más, pero recibieron igualmente un denario.","Y al recibirlo, protestaban contra el propietario,","diciendo: \"Estos últimos trabajaron nada más que una hora, y tú les das lo mismo que a nosotros, que hemos soportado el peso del trabajo y el calor durante toda la jornada\".","El propietario respondió a uno de ellos: \"Amigo, no soy injusto contigo, ¿acaso no habíamos tratado en un denario?","Toma lo que es tuyo y vete. Quiero dar a este que llega último lo mismo que a ti.","¿No tengo derecho a disponer de mis bienes como me parece? ¿Por qué tomas a mal que yo sea bueno?\".","Así, los últimos serán los primeros y los primeros serán los últimos».","Cuando Jesús se dispuso a subir a Jerusalén, llevó consigo sólo a los Doce, y en el camino les dijo:","«Ahora subimos a Jerusalén, donde el Hijo del hombre va a ser entregado a los sumos sacerdotes y a los escribas. Ellos lo condenarán a muerte","y lo entregarán a los paganos para que sea maltratado, azotado y crucificado, pero al tercer día resucitará».","Entonces la madre de los hijos de Zebedeo se acercó a Jesús, junto con sus hijos, y se postró ante él para pedirle algo.","«¿Qué quieres?», le preguntó Jesús. Ella le dijo: «Manda que mis dos hijos se sienten en tu Reino, uno a tu derecha y el otro a tu izquierda».","«No saben lo que piden», respondió Jesús. «¿Pueden beber el cáliz que yo beberé?». «Podemos», le respondieron.","«Está bien, les dijo Jesús, ustedes beberán mi cáliz. En cuanto a sentarse a mi derecha o a mi izquierda, no me toca a mí concederlo, sino que esos puestos son para quienes se los ha destinado mi Padre».","Al oír esto, los otros diez se indignaron contra los dos hermanos.","Pero Jesús los llamó y les dijo: «Ustedes saben que los jefes de las naciones dominan sobre ellas y los poderosos les hacen sentir su autoridad.","Entre ustedes no debe suceder así. Al contrario, el que quiera ser grande, que se haga servidor de ustedes;","y el que quiera ser el primero que se haga su esclavo:","como el Hijo del hombre, que no vino para ser servido, sino para servir y dar su vida en rescate por una multitud».","Cuando salieron de Jericó, mucha gente siguió a Jesús.","Había dos ciegos sentados al borde del camino y, al enterarse de que pasaba Jesús, comenzaron a gritar: «¡Señor, Hijo de David, ten piedad de nosotros!».","La multitud los reprendía para que se callaran, pero ellos gritaban más: «¡Señor, Hijo de David, ten piedad de nosotros!».","Jesús se detuvo, los llamó y les preguntó: «¿Qué quieren que haga por ustedes?».","Ellos le respondieron: «Señor, que se abran nuestros ojos».","Jesús se compadeció de ellos y tocó sus ojos. Inmediatamente, recobraron la vista y lo siguieron."],["Cuando se acercaron a Jerusalén y llegaron a Betfagé, al monte de los Olivos, Jesús envió a dos discípulos,","diciéndoles: «Vayan al pueblo que está enfrente, e inmediatamente encontrarán un asna atada, junto con su cría. Desátenla y tráiganmelos.","Y si alguien les dice algo, respondan: «El Señor los necesita y los va a devolver en seguida».","Esto sucedió para que se cumpliera lo anunciado por el Profeta:","\"Digan a la hija de Sión: Mira que tu rey viene hacia ti, humilde y montado sobre un asna, sobre la cría de un animal de carga\".","Los discípulos fueron e hicieron lo que Jesús les había mandado;","trajeron el asna y su cría, pusieron sus mantos sobre ellos y Jesús se montó.","Entonces la mayor parte de la gente comenzó a extender sus mantos sobre el camino, y otros cortaban ramas de los árboles y lo cubrían con ellas.","La multitud que iba delante de Jesús y la que lo seguía gritaba: «¡Hosana al Hijo de David! ¡Bendito el que viene en nombre del Señor! ¡Hosana en las alturas!","Cuando entró en Jerusalén, toda la ciudad se conmovió, y preguntaban: «¿Quién es este?».","Y la gente respondía: «Es Jesús, el profeta de Nazaret en Galilea».","Después Jesús entró en el Templo y echó a todos los que vendían y compraban allí, derribando las mesas de los cambistas y los asientos de los vendedores de palomas.","Y les decía: «Está escrito: Mi casa será llamada casa de oración, pero ustedes la han convertido en una cueva de ladrones».","En el Templo se le acercaron varios cielos paralíticos, y él los curó.","Al ver los prodigios que acababa de hacer y a los niños que gritaban en el Templo: «¡Hosana al Hijo de David!», los sumos sacerdotes y los escribas se indignaron","y le dijeron: «¿Oyes lo que dicen estos?». «Sí, respondió Jesús, ¿Pero nunca han leído este pasaje: \"De la boca de las criaturas y de los niños de pecho, has hecho brotar una alabanza\"?».","En seguida los dejó y salió de la ciudad para ir a Betania, donde pasó la noche.","A la mañana temprano, mientras regresaba a la ciudad, tuvo hambre.","Al ver una higuera cerca del camino, se acercó a ella, pero no encontró más que hojas. Entonces le dijo: «Nunca volverás a dar fruto». Y la higuera se secó de inmediato.","Cuando vieron esto, los discípulos dijeron llenos de asombro: «¿Cómo se ha secado la higuera tan repentinamente?».","Jesús les respondió: «Les aseguro que si tienen fe y no dudan, no sólo harán lo que yo acabo de hacer con la higuera, sino que podrán decir a esta montaña: «Retírate de ahí y arrójate al mar», y así lo hará.","Todo lo que pidan en la oración con fe, lo alcanzarán».","Jesús entró en el Templo y, mientras enseñaba, se le acercaron los sumos sacerdotes y los ancianos del pueblo, para decirle: «¿Con qué autoridad haces estas cosas? ¿Y quién te ha dado esa autoridad?».","Jesús les respondió: «Yo también quiero hacerles una sola pregunta. Si me responden, les diré con qué autoridad hago estas cosas.","¿De dónde venía el bautismo de Juan? ¿Del cielo o de los hombres?». Ellos se hacían este razonamiento: «Si respondemos: «Del cielo», él nos dirá: «Entonces, ¿por qué no creyeron en él?».","Y si decimos: «De los hombres», debemos temer a la multitud, porque todos consideran a Juan un profeta».","Por eso respondieron a Jesús: «No sabemos». El, por su parte, les respondió: «Entonces yo tampoco les diré con qué autoridad hago esto».","«¿Qué les parece? Un hombre tenía dos hijos y, dirigiéndose al primero, le dijo: \"Hijo, quiero que hoy vayas a trabajar a mi viña\".","El respondió: \"No quiero\". Pero después se arrepintió y fue.","Dirigiéndose al segundo, le dijo lo mismo y este le respondió: \"Voy, Señor\", pero no fue.","¿Cuál de los dos cumplió la voluntad de su padre?». «El primero», le respondieron. Jesús les dijo: «Les aseguro que los publicanos y las prostitutas llegan antes que ustedes al Reino de Dios.","En efecto, Juan vino a ustedes por el camino de la justicia y no creyeron en él; en cambio, los publicanos y las prostitutas creyeron en él. Pero ustedes, ni siquiera al ver este ejemplo, se han arrepentido ni han creído en él.","Escuchen otra parábola: Un hombre poseía una tierra y allí plantó una viña, la cercó, cavó un lagar y construyó una torre de vigilancia. Después la arrendó a unos viñadores y se fue al extranjero.","Cuando llegó el tiempo de la vendimia, envió a sus servidores para percibir los frutos.","Pero los viñadores se apoderaron de ellos, y a uno lo golpearon, a otro lo mataron y al tercero lo apedrearon.","El propietario volvió a enviar a otros servidores, en mayor número que los primeros, pero los trataron de la misma manera.","Finalmente, les envió a su propio hijo, pensando: \"Respetarán a mi hijo\".","Pero, al verlo, los viñadores se dijeron: \"Este es el heredero: vamos a matarlo para quedarnos con su herencia\".","Y apoderándose de él, lo arrojaron fuera de la viña y lo mataron.","Cuando vuelve el dueño, ¿qué les parece que hará con aquellos viñadores?».","Le respondieron: «Acabará con esos miserables y arrendará la viña a otros, que le entregarán el fruto a su debido tiempo».","Jesús agregó: «¿No han leído nunca en las Escrituras: \"La piedra que los constructores rechazaron ha llegado a ser la piedra angular: esta es la obra del Señor, admirable a nuestros ojos\"?","Por eso les digo que el Reino de Dios les será quitado a ustedes, para ser entregado a un pueblo que le hará producir sus frutos».","[El que caiga sobre esta piedra quedará destrozado, y aquel sobre quien caiga será aplastado].","Los sumos sacerdotes y los fariseos, al oír estas parábolas, comprendieron que se refería a ellos.","Entonces buscaron el modo de detenerlo, pero temían a la multitud, que lo consideraba un profeta."],["Jesús les habló otra vez en parábolas, diciendo:","«El Reino de los Cielos se parece a un rey que celebraba las bodas de su hijo.","Envió entonces a sus servidores para avisar a los invitados, pero estos se negaron a ir.","De nuevo envió a otros servidores con el encargo de decir a los invitados: \"Mi banquete está preparado; ya han sido matados mis terneros y mis mejores animales, y todo está a punto: Vengan a las bodas\".","Pero ellos no tuvieron en cuenta la invitación, y se fueron, uno a su campo, otro a su negocio;","y los demás se apoderaron de los servidores, los maltrataron y los mataron.","Al enterarse, el rey se indignó y envió a sus tropas para que acabaran con aquellos homicidas e incendiaran su ciudad.","Luego dijo a sus servidores: \"El banquete nupcial está preparado, pero los invitados no eran dignos de él.","Salgan a los cruces de los caminos e inviten a todos los que encuentren\".","Los servidores salieron a los caminos y reunieron a todos los que encontraron, buenos y malos, y la sala nupcial se llenó de convidados.","Cuando el rey entró para ver a los comensales, encontró a un hombre que no tenía el traje de fiesta.","\"Amigo, le dijo, ¿cómo has entrado aquí sin el traje de fiesta?\". El otro permaneció en silencio.","Entonces el rey dijo a los guardias: \"Atenlo de pies y manos, y arrójenlo afuera, a las tinieblas. Allí habrá llanto y rechinar de dientes\".","Porque muchos son llamados, pero pocos son elegidos».","Los fariseos se reunieron entonces para sorprender a Jesús en alguna de sus afirmaciones.","Y le enviaron a varios discípulos con unos herodianos, para decirle: «Maestro, sabemos que eres sincero y que enseñas con toda fidelidad el camino de Dios, sin tener en cuenta la condición de las personas, porque tú no te fijas en la categoría de nadie.","Dinos qué te parece: ¿Está permitido pagar el impuesto al César o no?».","Pero Jesús, conociendo su malicia, les dijo: «Hipócritas, ¿por qué me tienden una trampa?","Muéstrenme la moneda con que pagan el impuesto». Ellos le presentaron un denario.","Y él les preguntó: «¿De quién es esta figura y esta inscripción?».","Le respondieron: «Del César». Jesús les dijo: «Den al César lo que es del César, y a Dios, lo que es de Dios».","Al oír esto, quedaron admirados y, dejando a Jesús, se fueron.","Aquel mismo día se le acercaron unos saduceos, que son los que niegan la resurrección, y le propusieron este caso:","«Maestro, Moisés dijo: \"Si alguien muere sin tener hijos, que su hermano, para darle descendencia, se case con la viuda\".","Ahora bien, había entre nosotros siete hermanos. El primero se casó y como murió sin tener hijos, dejó su esposa al hermano.","Lo mismo ocurrió con el segundo, después con el tercero, y así sucesivamente hasta el séptimo.","Finalmente, murió la mujer.","Respóndenos: cuando resuciten los muertos, ¿de cuál de los siete será esposa, ya que lo fue de todos?».","Jesús les dijo: «Están equivocados, porque desconocen las Escrituras y el poder de Dios.","En la resurrección ni los hombres ni las mujeres se casarán, sino que todos serán como ángeles en el cielo.","Y con respecto a la resurrección de los muertos, ¿no han leído la palabra de Dios, que dice:","\"Yo soy el Dios de Abraham, el Dios de Isaac y el Dios de Jacob\"? ¡El no es un Dios de muertos, sino de vivientes!».","La multitud, que había oído esto, quedó asombrada de su enseñanza.","Cuando los fariseos se enteraron de que Jesús había hecho callar a los saduceos, se reunieron en ese lugar,","y uno de ellos, que era doctor de la Ley, le preguntó para ponerlo a prueba:","«Maestro, ¿cuál es el mandamiento más grande de la Ley?».","Jesús le respondió: «Amarás al Señor, tu Dios, con todo tu corazón, con toda tu alma y con todo tu espíritu.","Este es el más grande y el primer mandamiento.","El segundo es semejante al primero: Amarás a tu prójimo como a ti mismo.","De estos dos mandamientos dependen toda la Ley y los Profetas».","Mientras los fariseos estaban reunidos, Jesús les hizo esta pregunta:","«¿Qué piensan acerca del Mesías? ¿De quién es hijo?». Ellos le respondieron: «De David».","Jesús les dijo: «¿Por qué entonces, David, movido por el Espíritu, lo llama \"Señor\", cuando dice:","\"Dijo el Señor a mi Señor: Siéntate a mi derecha, hasta que ponga a tus enemigos debajo de tus pies\"?","Si David lo llama \"Señor\", ¿cómo puede ser hijo suyo?».","Ninguno fue capaz de responderle una sola palabra, y desde aquel día nadie se atrevió a hacerle más preguntas."],["Entonces Jesús dijo a la multitud y a sus discípulos:","«Los escribas y fariseos ocupan la cátedra de Moisés;","ustedes hagan y cumplan todo lo que ellos les digan, pero no se guíen por sus obras, porque no hacen lo que dicen.","Atan pesadas cargas y las ponen sobre los hombros de los demás, mientras que ellos no quieren moverlas ni siquiera con el dedo.","Todo lo hacen para que los vean: agradan las filacterias y alargas los flecos de sus mantos;","les gusta ocupar los primeros puestos en los banquetes y los primeros asientos en las sinagogas,","ser saludamos en las plazas y oírse llamar \"mi maestro\" por la gente.","En cuanto a ustedes, no se hagan llamar \"maestro\", porque no tienen más que un Maestro y todos ustedes son hermanos.","Nadie en el mundo llamen \"padre\", porque no tienen sino uno, el Padre celestial.","No se dejen llamar tampoco \"doctores\", porque sólo tienen un Doctor, que es el Mesías.","Que el más grande de entre ustedes se haga servidor de los otros,","porque el que se ensalza será humillado, y el que se humilla será ensalzado».","«¡Ay de ustedes, escribas y fariseos hipócritas, que cierran a los hombres el Reino de los Cielos! Ni entran ustedes, ni dejan entrar a los que quisieran.","[¡Ay de ustedes, escribas y fariseos hipócritas, que devoran los bienes de las viudas y fingen hacer largas oraciones! Por eso serán juzgados con más severidad.]","¡Ay de ustedes, escribas y fariseos hipócritas, que recorren mar y tierra para conseguir un prosélito, y cuando lo han conseguido lo hacen dos veces más digno de la Gehena que ustedes!","¡Ay de ustedes, guías, ciegos, que dicen: \"Si se jura por el santuario, el juramento no vale; pero si se jura por el oro del santuario, entonces sí que vale\"!","¡Insensatos y ciegos! ¿Qué es más importante: el oro o el santuario que hace sagrado el oro?","Ustedes dicen también: \"Si se jura por el altar, el juramento no vale, pero vale si se jura por la ofrenda que está sobre el altar\".","¡Ciegos! ¿Qué es más importante, la ofrenda o el altar que hace sagrada esa ofrenda?","Ahora bien, jurar por el altar, es jurar por él y por todo lo que está sobre él.","Jurar por el santuario, es jurar por él y por aquel que lo habita.","Jurar por el cielo, es jurar por el trono de Dios y por aquel que está sentado en él.","¡Ay de ustedes, escribas y fariseos hipócritas, que pagan el diezmo de la menta, del hinojo y del comino, y descuidan lo esencial de la Ley; la justicia, la misericordia y la fidelidad! Hay que practicar esto, sin descuidar aquello.","¡Guías ciegos, que filtran el mosquito y se tragan el camello!","¡Ay de ustedes, escribas y fariseos hipócritas, que limpian por fuera la copa y el plato, mientras que por dentro están llenos de codicia y desenfreno!","¡Fariseo ciego! Limpia primero la copa por dentro, y así también quedará limpia por fuera.","¡Ay de ustedes, escribas y fariseos hipócritas, que parecen sepulcros blanqueados: hermosos por fuera, pero por dentro llenos de huesos de muertos y de podredumbre!","Así también son ustedes: por fuera parecen justos delante de los hombres, pero por dentro están llenos de hipocresía y de iniquidad.","¡Ay de ustedes, escribas y fariseos hipócritas, que construyen los sepulcros de los profetas y adornan las tumbas de los justos,","diciendo: \"Si hubiéramos vivido en el tiempo de nuestros padres, no nos hubiéramos unido a ellos para derramar la sangre de los profetas\"!","De esa manera atestiguan contra ustedes mismos que son hijos de los que mataron a los profetas.","¡Colmen entonces la medida de sus padres!","¡Serpientes, raza de víboras! ¿Cómo podrán escapar a la condenación de la Gehena?","Por eso, yo voy a enviarles profetas, sabios y escribas; ustedes matarán y crucificarán a unos, azotarán a otros en las sinagogas, y los perseguirán de ciudad en ciudad.","Así caerá sobre ustedes toda la sangre del justo Abel, hasta la sangre de Zacarías, hijo de Baraquías, al que ustedes asesinaron entre el santuario y el altar.","Les aseguro que todo esto sobrevendrá a la presente generación.","¡Jerusalén, Jerusalén, que matas a los profetas y apedreas a los que te son enviados! ¡Cuántas veces quise reunir a tus hijos, como la gallina reúne bajo sus alas a los pollitos, y tú no quisiste!","Por eso, a ustedes la casa les quedará desierta.","Les aseguro que ya no me verán más, hasta que digan: ¡Bendito el que viene en nombre del Señor!»."],["Jesús salió del Templo y, mientras iba caminando, sus discípulos se acercaron a él para hacerle notar las construcciones del mismo.","Pero él les dijo: «¿Ven todo esto? Les aseguro que no quedará aquí piedra sobre piedra: todo será destruido».","Cuando llegó al monte de los Olivos, Jesús se sentó y sus discípulos le preguntaron en privado: «¿Cuándo sucederá esto y cuál será la señal de tu Venida y del fin del mundo?».","El les respondió: «Tengan cuidado de que no los engañen,","porque muchos se presentarán en mi Nombre, diciendo: \"Yo soy el Mesías\", y engañarán a mucha gente.","Ustedes oirán hablar de guerras y de rumores de guerras; no se alarmen: todo esto debe suceder, pero todavía no será el fin.","En efecto, se levantará nación contra nación y reino contra reino. En muchas partes habrá hambre y terremotos.","Todo esto no será más que el comienzo de los dolores del parto.","Ustedes serán entregados a la tribulación y a la muerte, y serán odiados por todas las naciones a causa de mi Nombre.","Entonces muchos sucumbirán; se traicionarán y se odiarán los unos a los otros.","Aparecerá una multitud de falsos profetas, que engañarán a mucha gente.","Al aumentar la maldad se enfriará el amor de muchos,","pero el que persevere hasta el fin, se salvará.","Esta Buena Noticia del Reino será proclamada en el mundo entero como testimonio delante de todos los pueblos, y entonces llegará el fin.","Cuando vean en el Lugar santo la Abominación de la desolación, de la que habló el profeta Daniel –el que lea esto, entiéndalo bien–","los que estén en Judea, que se refugien en las montañas;","el que esté en la azotea de su casa, no baje a buscar sus cosas;","y el que esté en el campo, que no vuelva a buscar su manto.","¡Ay de las mujeres que estén embarazadas o tengas niños de pecho en aquellos días!","Rueguen para que no tengan que huir en invierno o en día sábado.","Porque habrá entonces una gran tribulación, como no la hubo desde el comienzo del mundo hasta ahora, ni la habrá jamás.","Y si no fuera abreviado ese tiempo, nadie se salvaría; pero será abreviado, a causa de los elegidos.","Si alguien les dice entonces: «El Mesías está aquí o está allí», no lo crean.","Porque aparecerán falsos mesías y falsos profetas que harán milagros y prodigios asombrosos, capaces de engañar, si fuera posible, a los mismos elegidos.","Por eso los prevengo.","Si les dicen: \"El Mesías está en el desierto\", no vayan; o bien: \"Está escondido en tal lugar\", no lo crean.","Como el relámpago que sale del oriente y brilla hasta el occidente, así será la Venida del Hijo del hombre.","Donde esté el cadáver, se juntarán los buitres.","Inmediatamente después de la tribulación de aquellos días, el sol se oscurecerá, la luna dejará de brillar, las estrellas caerán del cielo y los astros se conmoverán.","Entonces aparecerá en el cielo la señal del Hijo del hombre. Todas las razas de la tierra se golpearán el pecho y verán al Hijo del hombre venir sobre las nubes del cielo, lleno de poder y de gloria.","Y él enviará a sus ángeles para que, al sonido de la trompeta, congreguen a sus elegidos de los cuatro puntos cardinales, de un extremo al otro del horizonte.","Aprendan esta comparación, tomada de la higuera: cuando sus ramas se hacen flexibles y brotan las hojas, ustedes se dan cuenta de que se acerca el verano.","Así también, cuando vean todas estas cosas, sepan que el fin está cerca, a la puerta.","Les aseguro que no pasará esta generación, sin que suceda todo esto.","El cielo y la tierra pasarán, pero mis palabras no pasarán.","En cuanto a ese día y esa hora, nadie los conoce, ni los ángeles del cielo, ni el Hijo, sino sólo el Padre.","Cuando venga el Hijo del hombre, sucederá como en tiempos de Noé.","En los días que precedieron al diluvio, la gente comía, bebía y se casaba, hasta que Noé entró en el arca;","y no sospechaban nada, hasta que llegó el diluvio y los arrastró a todos. Lo mismo sucederá cuando venga el Hijo del hombre.","De dos hombres que estén en el campo, uno será llevado y el otro dejado.","De dos mujeres que estén moliendo, una será llevada y la otra dejada.","Estén prevenidos, porque ustedes no saben qué día vendrá su Señor.","Entiéndanlo bien: si el dueño de casa supiera a qué hora de la noche va a llegar el ladrón, velaría y no dejaría perforar las paredes de su casa.","Ustedes también estén preparados, porque el Hijo del hombre vendrá a la hora menos pensada.","¿Cuál es, entonces, el servidor fiel y previsor, a quien el Señor ha puesto al frente de su personal, para distribuir el alimento en el momento oportuno?","Feliz aquel servidor a quien su señor, al llegar, encuentre ocupado en este trabajo.","Les aseguro que lo hará administrador de todos sus bienes.","Pero si es un mal servidor, que piensa: «Mi señor tardará»,","y se dedica a golpear a sus compañeros, a comer y a beber con los borrachos,","su señor llegará el día y la hora menos pensada,","y lo castigará. Entonces él correrá la misma suerte que los hipócritas. Allí habrá llanto y rechinar de dientes."],["Por eso, el Reino de los Cielos será semejante a diez jóvenes que fueron con sus lámparas al encuentro del esposo.","Cinco de ellas eran necias y cinco, prudentes.","Las necias tomaron sus lámparas, pero sin proveerse de aceite,","mientras que las prudentes tomaron sus lámparas y también llenaron de aceite sus frascos.","Como el esposo se hacía esperar, les entró sueño a todas y se quedaron dormidas.","Pero a medianoche se oyó un grito: \"¡Ya viene el esposo, salgan a su encuentro!\".","Entonces las jóvenes se despertaron y prepararon sus lámparas.","Las necias dijeron a las prudentes: \"¿Podrían darnos un poco de aceite, porque nuestras lámparas se apagan?\".","Pero estas les respondieron: \"No va a alcanzar para todas. Es mejor que vayan a comprarlo al mercado\".","Mientras tanto, llegó el esposo: las que estaban preparadas entraron con él en la sala nupcial y se cerró la puerta.","Después llegaron las otras jóvenes y dijeron: \"Señor, señor, ábrenos\",","pero él respondió: \"Les aseguro que no las conozco\".","Estén prevenidos, porque no saben el día ni la hora.","El reino de los Cielos es también como un hombre que, al salir de viaje, llamó a sus servidores y les confió sus bienes.","A uno le dio cinco talentos, a otro dos, y uno solo a un tercero, a cada uno según su capacidad; y después partió. En seguida,","el que había recibido cinco talentos, fue a negociar con ellos y ganó otros cinco.","De la misma manera, el que recibió dos, ganó otros dos,","pero el que recibió uno solo, hizo un pozo y enterró el dinero de su señor.","Después de un largo tiempo, llegó el señor y arregló las cuentas con sus servidores.","El que había recibido los cinco talentos se adelantó y le presentó otros cinco. \"Señor, le dijo, me has confiado cinco talentos: aquí están los otros cinco que he ganado\".","\"Está bien, servidor bueno y fiel, le dijo su señor, ya que respondiste fielmente en lo poco, te encargaré de mucho más: entra a participar del gozo de tu señor\".","Llegó luego el que había recibido dos talentos y le dijo: \"Señor, me has confiado dos talentos: aquí están los otros dos que he ganado\".","\"Está bien, servidor bueno y fiel, ya que respondiste fielmente en lo poco, te encargaré de mucho más: entra a participar del gozo de tu señor\".","Llegó luego el que había recibido un solo talento. \"Señor, le dijo, sé que eres un hombre exigente: cosechas donde no has sembrado y recoges donde no has esparcido.","Por eso tuve miedo y fui a enterrar tu talento: ¡aquí tienes lo tuyo!\".","Pero el señor le respondió: \"Servidor malo y perezoso, si sabías que cosecho donde no he sembrado y recojo donde no he esparcido,","tendrías que haber colocado el dinero en el banco, y así, a mi regreso, lo hubiera recuperado con intereses.","Quítenle el talento para dárselo al que tiene diez,","porque a quien tiene, se le dará y tendrá de más, pero al que no tiene, se le quitará aun lo que tiene.","Echen afuera, a las tinieblas, a este servidor inútil; allí habrá llanto y rechinar de dientes\".","Cuando el Hijo del hombre venga en su gloria rodeado de todos los ángeles, se sentará en su trono glorioso.","Todas las naciones serán reunidas en su presencia, y él separará a unos de otros, como el pastor separa las ovejas de los cabritos,","y pondrá a aquellas a su derecha y a estos a su izquierda.","Entonces el Rey dirá a los que tenga a su derecha: \"Vengan, benditos de mi Padre, y reciban en herencia el Reino que les fue preparado desde el comienzo del mundo,","porque tuve hambre, y ustedes me dieron de comer; tuve sed, y me dieron de beber; estaba de paso, y me alojaron;","desnudo, y me vistieron; enfermo, y me visitaron; preso, y me vinieron a ver\".","Los justos le responderán: \"Señor, ¿cuándo te vimos hambriento, y te dimos de comer; sediento, y te dimos de beber?","¿Cuándo te vimos de paso, y te alojamos; desnudo, y te vestimos?","¿Cuándo te vimos enfermo o preso, y fuimos a verte?\".","Y el Rey les responderá: \"Les aseguro que cada vez que lo hicieron con el más pequeño de mis hermanos, lo hicieron conmigo\".","Luego dirá a los de su izquierda: \"Aléjense de mí, malditos; vayan al fuego eterno que fue preparado para el demonio y sus ángeles,","porque tuve hambre, y ustedes no me dieron de comer; tuve sed, y no me dieron de beber;","estaba de paso, y no me alojaron; desnudo, y no me vistieron; enfermo y preso, y no me visitaron\".","Estos, a su vez, le preguntarán: \"Señor, ¿cuando te vimos hambriento o sediento, de paso o desnudo, enfermo o preso, y no te hemos socorrido?\".","Y él les responderá: \"Les aseguro que cada vez que no lo hicieron con el más pequeño de mis hermanos, tampoco lo hicieron conmigo\".","Estos irán al castigo eterno, y los justos a la Vida eterna»."],["Cuando Jesús terminó de decir todas estas palabras, dijo a sus discípulos:","«Ya saben que dentro de dos días se celebrará la Pascua, y el Hijo del hombre será entregado para ser crucificado».","Entonces los sumos sacerdotes y los ancianos del pueblo se reunieron en el palacio del Sumo Sacerdote, llamado Caifás,","y se pusieron de acuerdo para detener a Jesús con astucia y darle muerte.","Pero decían: «No lo hagamos durante la fiesta, para que no se produzca un tumulto en el pueblo».","Cuando Jesús se encontraba en Betania, en casa de Simón el leproso,","se acercó una mujer con un frasco de alabastro, que contenía un perfume valioso, y lo derramó sobre su cabeza, mientras él estaba comiendo.","Al ver esto, sus discípulos, indignados, dijeron: «¿Para qué este derroche?","Se hubiera podido vender el perfume a buen precio para repartir el dinero entre los pobres».","Jesús se dio cuenta y les dijo: «¿Por qué molestan a esta mujer? Ha hecho una buena obra conmigo.","A los pobres los tendrán siempre con ustedes, pero a mí no me tendrán siempre.","Al derramar este perfume sobre mi cuerpo, ella preparó mi sepultura.","Les aseguro que allí donde se proclame esta Buena Noticia, en todo el mundo, se contará también en su memoria lo que ella hizo».","Entonces uno de los Doce, llamado Judas Iscariote, fue a ver a los sumos sacerdotes","y les dijo: «¿Cuánto me darán si se lo entrego?». Y resolvieron darle treinta monedas de plata.","Desde ese momento, Judas buscaba una ocasión favorable para entregarlo.","El primer día de los Acimos, los discípulos fueron a preguntar a Jesús: «¿Dónde quieres que te preparemos la comida pascual?».","El respondió: «Vayan a la ciudad, a la casa de tal persona, y díganle: «El Maestro dice: Se acerca mi hora, voy a celebrar la Pascua en tu casa con mis discípulos».","Ellos hicieron como Jesús les había ordenado y prepararon la Pascua.","Al atardecer, estaba a la mesa con los Doce","y, mientras comían, Jesús les dijo: «Les aseguro que uno de ustedes me entregará».","Profundamente apenados, ellos empezaron a preguntarle uno por uno: «¿Seré yo, Señor?».","El respondió: «El que acaba de servirse de la misma fuente que yo, ese me va a entregar.","El Hijo del hombre se va, como está escrito de él, pero ¡ay de aquel por quien el Hijo del hombre será entregado: más le valdría no haber nacido!».","Judas, el que lo iba a entregar, le preguntó: «¿Seré yo, Maestro?». «Tú lo has dicho», le respondió Jesús.","Mientras comían, Jesús tomó el pan, pronunció la bendición, lo partió y lo dio a sus discípulos, diciendo: «Tomen y coman, esto es mi Cuerpo».","Después tomó una copa, dio gracias y se la entregó, diciendo: «Beban todos de ella,","porque esta es mi Sangre, la Sangre de la Alianza, que se derrama por muchos para la remisión de los pecados.","Les aseguro que desde ahora no beberé más de este fruto de la vid, hasta el día en que beba con ustedes el vino nuevo en el Reino de mi Padre».","Después del canto de los Salmos, salieron hacia el monto de los Olivos.","Entonces Jesús les dijo: «Esta misma noche, ustedes se van a escandalizar a causa de mí. Porque dice la Escritura: Heriré al pastor, y se dispersarán las ovejas del rebaño.","Pero después que yo resucite, iré antes que ustedes a Galilea».","Pedro, tomando la palabra, le dijo: «Aunque todos se escandalicen por tu causa, yo no me escandalizaré jamás».","Jesús le respondió: «Te aseguro que esta misma noche, antes que cante el gallo, me habrás negado tres veces».","Pedro le dijo: «Aunque tenga que morir contigo, jamás te negaré». Y todos los discípulos dijeron lo mismo.","Cuando Jesús llegó con sus discípulos a una propiedad llamada Getsemaní, les dijo: «Quédense aquí, mientras yo voy allí a orar».","Y llevando con él a Pedro y a los dos hijos de Zebedeo, comenzó a entristecerse y a angustiarse.","Entonces les dijo: «Mi alma siente una tristeza de muerte. Quédense aquí, velando conmigo».","Y adelantándose un poco, cayó con el rostro en tierra, orando así: «Padre mío, si es posible, que pase lejos de mí este cáliz, pero no se haga mi voluntad, sino la tuya».","Después volvió junto a sus discípulos y los encontró durmiendo. Jesús dijo a Pedro: «¿Es posible que no hayan podido quedarse despiertos conmigo, ni siquiera una hora?","Estén prevenidos y oren para no caer en tentación, porque el espíritu está dispuesto, pero la carne es débil».","Se alejó por segunda vez y suplicó: «Padre mío, si no puede pasar este cáliz sin que yo lo beba, que se haga tu voluntad».","Al regresar los encontró otra vez durmiendo, porque sus ojos se cerraban de sueño.","Nuevamente se alejó de ellos y oró por tercera vez, repitiendo las mismas palabras.","Luego volvió junto a sus discípulos y les dijo: «Ahora pueden dormir y descansar: ha llegado la hora en que el Hijo del hombre va a ser entregado en manos de los pecadores.","¡Levántense! ¡Vamos! Ya se acerca el que me va a entregar».","Jesús estaba hablando todavía, cuando llegó Judas, uno de los Doce, acompañado de una multitud con espadas y palos, enviada por los sumos sacerdotes y los ancianos del pueblo.","El traidor les había dado la señal: «Es aquel a quien voy a besar. Deténganlo».","Inmediatamente se acercó a Jesús, diciéndole: «Salud, Maestro», y lo besó.","Jesús le dijo: «Amigo, ¡cumple tu cometido!». Entonces se abalanzaron sobre él y lo detuvieron.","Uno de los que estaban con Jesús sacó su espada e hirió al servidor del Sumo Sacerdote, cortándole la oreja.","Jesús le dijo: «Guarda tu espada, porque el que a hierro mata a hierro muere.","¿O piensas que no puedo recurrir a mi Padre? El pondría inmediatamente a mi disposición más de doce legiones de ángeles.","Pero entonces, ¿cómo se cumplirían las Escrituras, según las cuales debe suceder así?».","Y en ese momento dijo Jesús a la multitud: «¿Soy acaso un ladrón, para que salgan a arrestarme con espadas y palos? Todos los días me sentaba a enseñar en el Templo, y ustedes no me detuvieron».","Todo esto sucedió para que se cumpliera lo que escribieron los profetas. Entonces todos los discípulos lo abandonaron y huyeron.","Los que habían arrestado a Jesús lo condujeron a la casa del Sumo Sacerdote Caifás, donde se habían reunido los escribas y los ancianos.","Pedro lo seguía de lejos hasta el palacio del Sumo Sacerdote; entró y se sentó con los servidores, para ver cómo terminaba todo.","Los sumos sacerdotes y todo el Sanedrín buscaban un falso testimonio contra Jesús para poder condenarlo a muerte;","pero no lo encontraron, a pesar de haberse presentado numerosos testigos falsos. Finalmente, se presentaron dos","que declararon: «Este hombre dijo: \"Yo puedo destruir el Templo de Dios y reconstruirlo en tres días\"».","El Sumo Sacerdote, poniéndose de pie, dijo a Jesús: «¿No respondes nada? ¿Qué es lo que estos declaran contra ti?».","Pero Jesús callaba. El Sumo Sacerdote insistió: «Te conjuro por el Dios vivo a que me digas si tú eres el Mesías, el Hijo de Dios».","Jesús le respondió: «Tú lo has dicho. Además, les aseguro que de ahora en adelante verán al hijo del hombre sentarse a la derecha del Todopoderoso y venir sobre las nubes del cielo».","Entonces el Sumo Sacerdote rasgó sus vestiduras, diciendo: «Ha blasfemado. ¿Qué necesidad tenemos ya de testigos? Ustedes acaban de oír la blasfemia.","¿Qué les parece?». Ellos respondieron: «Merece la muerte».","Luego lo escupieron en la cara y lo abofetearon. Otros lo golpeaban,","diciéndole: «Tú, que eres el Mesías, profetiza, dinos quién te golpeó».","Mientras tanto, Pedro estaba sentado afuera, en el patio. Una sirvienta se acercó y le dijo: «Tú también estabas con Jesús, el Galileo».","Pero él lo negó delante de todos, diciendo: «No sé lo que quieres decir».","Al retirarse hacia la puerta, lo vio otra sirvienta y dijo a los que estaban allí: «Este es uno de los que acompañaban a Jesús, el Nazareno».","Y nuevamente Pedro negó con juramento: «Yo no conozco a ese hombre».","Un poco más tarde, los que estaban allí se acercaron a Pedro y le dijeron: «Seguro que tú también eres uno de ellos; hasta tu acento te traiciona».","Entonces Pedro se puso a maldecir y a jurar que no conocía a ese hombre. En seguida cantó el gallo,","y Pedro recordó las palabras que Jesús había dicho: «Antes que cante el gallo, me negarás tres veces». Y saliendo, lloró amargamente."],["Cuando amaneció, todos los sumos sacerdotes y ancianos del pueblo deliberaron sobre la manera de hacer ejecutar a Jesús.","Después de haberlo atado, lo llevaron ante Pilato, el gobernador, y se lo entregaron.","Judas, el que lo entregó, viendo que Jesús había sido condenado, lleno de remordimiento, devolvió las treinta monedas de plata a los sumos sacerdotes y a los ancianos,","diciendo: «He pecado, entregando sangre inocente». Ellos respondieron: «¿Qué nos importa? Es asunto tuyo».","Entonces él, arrojando las monedas en el Templo, salió y se ahorcó.","Los sumos sacerdotes, juntando el dinero, dijeron: «No está permitido ponerlo en el tesoro, porque es precio de sangre».","Después de deliberar, compraron con él un campo, llamado «del alfarero», para sepultar a los extranjeros.","Por esta razón se lo llama hasta el día de hoy «Campo de sangre».","Así se cumplió lo anunciado por el profeta Jeremías: Y ellos recogieron las treinta monedas de plata, cantidad en que fue tasado aquel a quien pusieron precio los israelitas.","Con el dinero se compró el «Campo del alfarero», como el Señor me lo había ordenado.","Jesús compareció ante el gobernador, y este le preguntó: «¿Tú eres el rey de los judíos?». El respondió: «Tú lo dices».","Al ser acusado por los sumos sacerdotes y los ancianos, no respondió nada.","Pilato le dijo: «¿No oyes todo lo que declaran contra ti?».","Jesús no respondió a ninguna de sus preguntas, y esto dejó muy admirado al gobernador.","En cada Fiesta, el gobernador acostumbraba a poner en libertad a un preso, a elección del pueblo.","Había entonces uno famoso, llamado Barrabás.","Pilato preguntó al pueblo que estaba reunido: «¿A quién quieren que ponga en libertad, a Barrabás o a Jesús, llamado el Mesías?».","El sabía bien que lo habían entregado por envidia.","Mientras estaba sentado en el tribunal, su mujer le mandó decir: «No te mezcles en el asunto de ese justo, porque hoy, por su causa, tuve un sueño que me hizo sufrir mucho».","Mientras tanto, los sumos sacerdotes y los ancianos convencieron a la multitud que pidiera la libertad de Barrabás y la muerte de Jesús.","Tomando de nuevo la palabra, el gobernador les preguntó: «¿A cuál de los dos quieren que ponga en libertad?». Ellos respondieron: «A Barrabás».","Pilato continuó: «¿Y qué haré con Jesús, llamado el Mesías?». Todos respondieron: «¡Que sea crucificado!».","El insistió: «¿Qué mal ha hecho?». Pero ellos gritaban cada vez más fuerte: «¡Que sea crucificado!».","Al ver que no se llegaba a nada, sino que aumentaba el tumulto, Pilato hizo traer agua y se lavó las manos delante de la multitud, diciendo: «Yo soy inocente de esta sangre. Es asunto de ustedes».","Y todo el pueblo respondió: «Que su sangre caiga sobre nosotros y sobre nuestros hijos».","Entonces, Pilato puso en libertad a Barrabás; y a Jesús, después de haberlo hecho azotar, lo entregó para que fuera crucificado.","Los soldados del gobernador llevaron a Jesús al pretorio y reunieron a toda la guardia alrededor de él.","Entonces lo desvistieron y le pusieron un manto rojo.","Luego tejieron una corona de espinas y la colocaron sobre su cabeza, pusieron una caña en su mano derecha y, doblando la rodilla delante de él, se burlaban, diciendo: «Salud, rey de los judíos».","Y escupiéndolo, le quitaron la caña y con ella le golpeaban la cabeza.","Después de haberse burlado de él, le quitaron el manto, le pusieron de nuevo sus vestiduras y lo llevaron a crucificar.","Al salir, se encontraron con un hombre de Cirene, llamado Simón, y lo obligaron a llevar la cruz.","Cuando llegaron al lugar llamado Gólgota, que significa «lugar del Cráneo»,","le dieron de beber vino con hiel. El lo probó, pero no quiso tomarlo.","Después de crucificarlo, los soldados sortearon sus vestiduras y se las repartieron;","y sentándose allí, se quedaron para custodiarlo.","Colocaron sobre su cabeza una inscripción con el motivo de su condena: «Este es Jesús, el rey de los judíos».","Al mismo tiempo, fueron crucificados con él dos ladrones, uno a su derecha y el otro a su izquierda.","Los que pasaban, lo insultaban y, moviendo la cabeza,","decían: «Tú, que destruyes el Templo y en tres días lo vuelves a edificar, ¡sálvate a ti mismo, si eres Hijo de Dios, y baja de la cruz!».","De la misma manera, los sumos sacerdotes, junto con los escribas y los ancianos, se burlaban, diciendo:","«¡Ha salvado a otros y no puede salvarse a sí mismo! Es rey de Israel: que baje ahora de la cruz y creeremos en él.","Ha confiado en Dios; que él lo libre ahora si lo ama, ya que él dijo: «Yo soy Hijo de Dios».","También lo insultaban los ladrones crucificados con él.","Desde el mediodía hasta las tres de la tarde, las tinieblas cubrieron toda la región.","Hacia las tres de la tarde, Jesús exclamó en alta voz: «Elí, Elí, lemá sabactani», que significa: «Dios mío, Dios mío, ¿por qué me has abandonado?».","Algunos de los que se encontraban allí, al oírlo, dijeron: «Está llamando a Elías».","En seguida, uno de ellos corrió a tomar una esponja, la empapó en vinagre y, poniéndola en la punta de una caña, le dio de beber.","Pero los otros le decían: «Espera, veamos si Elías viene a salvarlo».","Entonces Jesús, clamando otra vez con voz potente, entregó su espíritu.","Inmediatamente, el velo del Templo se rasgó en dos, de arriba abajo, la tierra tembló, las rocas se partieron","y las tumbas se abrieron. Muchos cuerpos de santos que habían muerto resucitaron","y, saliendo de las tumbas después que Jesús resucitó, entraron en la Ciudad santa y se aparecieron a mucha gente.","El centurión y los hombres que custodiaban a Jesús, al ver el terremoto y todo lo que pasaba, se llenaron de miedo y dijeron: «¡Verdaderamente, este era el Hijo de Dios!».","Había allí muchas mujeres que miraban de lejos: eran las mismas que habían seguido a Jesús desde Galilea para servirlo.","Entre ellas estaban María Magdalena, María –la madre de Santiago y de José– y la madre de los hijos de Zebedeo.","Al atardecer, llegó un hombre rico de Arimatea, llamado José, que también se había hecho discípulo de Jesús,","y fue a ver a Pilato para pedirle el cuerpo de Jesús. Pilato ordenó que se lo entregaran.","Entonces José tomó el cuerpo, lo envolvió en una sábana limpia","y lo depositó en un sepulcro nuevo que se había hecho cavar en la roca. Después hizo rodar una gran piedra a la entrada del sepulcro, y se fue.","María Magdalena y la otra María estaban sentadas frente al sepulcro.","A la mañana siguiente, es decir, después del día de la Preparación, los sumos sacerdotes y los fariseos se reunieron y se presentaron ante Pilato,","diciéndole: «Señor, nosotros nos hemos acordado de que ese impostor, cuando aún vivía, dijo: «A los tres días resucitaré».","Ordena que el sepulcro sea custodiado hasta el tercer día, no sea que sus discípulos roben el cuerpo y luego digan al pueblo: ¡Ha resucitado!». Este último engaño sería peor que el primero».","Pilato les respondió: «Ahí tienen la guardia, vayan y aseguren la vigilancia como lo crean conveniente».","Ellos fueron y aseguraron la vigilancia del sepulcro, sellando la piedra y dejando allí la guardia."],["Pasado el sábado, al amanecer del primer día de la semana, María Magdalena y la otra María fueron a visitar el sepulcro.","De pronto, se produjo un gran temblor de tierra: el Angel del Señor bajó del cielo, hizo rodar la piedra del sepulcro y se sentó sobre ella.","Su aspecto era como el de un relámpago y sus vestiduras eran blancas como la nieve.","Al verlo, los guardias temblaron de espanto y quedaron como muertos.","El Angel dijo a las mujeres: «No teman, yo sé que ustedes buscan a Jesús, el Crucificado.","No está aquí, porque ha resucitado como lo había dicho. Vengan a ver el lugar donde estaba,","y vayan en seguida a decir a sus discípulos: «Ha resucitado de entre los muertos, e irá antes que ustedes a Galilea: allí lo verán». Esto es lo que tenía que decirles».","Las mujeres, atemorizadas pero llenas de alegría, se alejaron rápidamente del sepulcro y fueron a dar la noticia a los discípulos.","De pronto, Jesús salió a su encuentro y las saludó, diciendo: «Alégrense». Ellas se acercaron y, abrazándole los pies, se postraron delante de él.","Y Jesús les dijo: «No teman; avisen a mis hermanos que vayan a Galilea, y allí me verán».","Mientras ellas se alejaban, algunos guardias fueron a la ciudad para contar a los sumos sacerdotes todo lo que había sucedido.","Estos se reunieron con los ancianos y, de común acuerdo, dieron a los soldados una gran cantidad de dinero,","con esta consigna: «Digan así: «Sus discípulos vinieron durante la noche y robaron su cuerpo, mientras dormíamos».","Si el asunto llega a oídos del gobernador, nosotros nos encargaremos de apaciguarlo y de evitarles a ustedes cualquier contratiempo».","Ellos recibieron el dinero y cumplieron la consigna. Esta versión se ha difundido entre los judíos hasta el día de hoy.","Los once discípulos fueron a Galilea, a la montaña donde Jesús los había citado.","Al verlo, se postraron delante de el; sin embargo, algunos todavía dudaron.","Acercándose, Jesús les dijo: «Yo he recibido todo poder en el cielo y en la tierra.","Vayan, y hagan que todos los pueblos sean mis discípulos, bautizándolos en el nombre del Padre y del Hijo y del Espíritu Santo,","y enseñándoles a cumplir todo lo que yo les he mandado. Y yo estaré siempre con ustedes hasta el fin del mundo»."]],"mc":[["Comienzo de la Buena Noticia de Jesús, Mesías, Hijo de Dios.","Como está escrito en el libro del profeta Isaías: \"Mira, yo envío a mi mensajero delante de ti para prepararte el camino.","Una voz grita en el desierto: Preparen el camino del Señor, allanen sus senderos\",","así se presentó Juan el Bautista en el desierto, proclamando un bautismo de conversión para el perdón de los pecados.","Toda la gente de Judea y todos los habitantes de Jerusalén acudían a él, y se hacían bautizar en las aguas del Jordán, confesando sus pecados.","Juan estaba vestido con una piel de camello y un cinturón de cuero, y se alimentaba con langostas y miel silvestre. Y predicaba, diciendo:","«Detrás de mi vendrá el que es más poderoso que yo, y yo ni siquiera soy digno de ponerme a sus pies para desatar la correa de sus sandalias.","Yo los he bautizado a ustedes con agua, pero él los bautizará con el Espíritu Santo».","En aquellos días, Jesús llegó desde Nazaret de Galilea y fue bautizado por Juan en el Jordán.","Y al salir del agua, vio que los cielos se abrían y que el Espíritu Santo descendía sobre él como una paloma;","y una voz desde el cielo dijo: «Tú eres mi Hijo muy querido, en ti tengo puesta toda mi predilección».","En seguida el Espíritu lo llevó al desierto,","donde estuvo cuarenta días y fue tentado por Satanás. Vivía entre las fieras, y los ángeles lo servían.","Después que Juan fue arrestado, Jesús se dirigió a Galilea. Allí proclamaba la Buena Noticia de Dios, diciendo:","«El tiempo se ha cumplido: el Reino de Dios está cerca. Conviértanse y crean en la Buena Noticia». Los primeros discípulos","Mientras iba por la orilla del mar de Galilea, vio a Simón y a su hermano Andrés, que echaban las redes en el agua, porque eran pescadores.","Jesús les dijo: «Síganme, y yo los haré pescadores de hombres».","Inmediatamente, ellos dejaron sus redes y lo siguieron.","Y avanzando un poco, vio a Santiago, hijo de Zebedeo, y a su hermano Juan, que estaban también en su barca arreglando las redes. En seguida los llamó,","y con ellos, dejando en la barca a su padre Zebedeo con los jornaleros, lo siguieron.","Entraron en Cafarnaúm, y cuando llegó el sábado, Jesús fue a la sinagoga y comenzó a enseñar.","Todos estaban asombrados de su enseñanza, porque les enseñaba como quien tiene autoridad y no como los escribas.","Y había en la sinagoga un hombre poseído de un espíritu impuro, que comenzó a gritar;","«¿Qué quieres de nosotros, Jesús Nazareno? ¿Has venido para acabar con nosotros? Ya sé quién eres: el Santo de Dios».","Pero Jesús lo increpó, diciendo: «Cállate y sal de este hombre».","El espíritu impuro lo sacudió violentamente, y dando un alarido, salió de ese hombre.","Todos quedaron asombrados y se preguntaban unos a otros: «¿Qué es esto? ¡Enseña de una manera nueva, llena de autoridad; da órdenes a los espíritus impuros, y estos le obedecen!».","Y su fama se extendió rápidamente por todas partes, en toda la región de Galilea.","Cuando salió de la sinagoga, fue con Santiago y Juan a casa de Simón y Andrés.","La suegra de Simón estaba en cama con fiebre, y se lo dijeron de inmediato.","El se acercó, la tomó de la mano y la hizo levantar. Entonces ella no tuvo más fiebre y se puso a servirlos.","Al atardecer, después de ponerse el sol, le llevaron a todos los enfermos y endemoniados,","y la ciudad entera se reunió delante de la puerta.","Jesús curó a muchos enfermos, que sufrían de diversos males, y expulsó a muchos demonios; pero a estos no los dejaba hablar, porque sabían quién era él.","Por la mañana, antes que amaneciera, Jesús se levantó, salió y fue a un lugar desierto; allí estuvo orando.","Simón salió a buscarlo con sus compañeros,","y cuando lo encontraron, le dijeron: «Todos te andan buscando».","El les respondió: «Vayamos a otra parte, a predicar también en las poblaciones vecinas, porque para eso he salido».","Y fue predicando en las sinagogas de toda la Galilea y expulsando demonios","Entonces se le acercó un leproso para pedirle ayuda y, cayendo de rodillas, le dijo: «Si quieres, puedes purificarme».","Jesús, conmovido, extendió la mano y lo tocó, diciendo: «Lo quiero, queda purificado».","En seguida la lepra desapareció y quedó purificado.","Jesús lo despidió, advirtiéndole severamente:","«No le digas nada a nadie, pero ve a presentarte al sacerdote y entrega por tu purificación la ofrenda que ordenó Moisés, para que les sirva de testimonio».","Sin embargo, apenas se fue, empezó a proclamarlo a todo el mundo, divulgando lo sucedido, de tal manera que Jesús ya no podía entrar públicamente en ninguna ciudad, sino que debía quedarse afuera, en lugares desiertos, Y acudían a él de todas partes."],["Unos días después, Jesús volvió a Cafarnaúm y se difundió la noticia de que estaba en la casa.","Se reunió tanta gente, que no había más lugar ni siguiera delante de la puerta, y él les anunciaba la Palabra.","Le trajeron entonces a un paralítico, llevándolo entre cuatro hombres.","Y como no podían acercarlo a él, a causa de la multitud, levantaron el techo sobre el lugar donde Jesús estaba, y haciendo un agujero descolgaron la camilla con el paralítico.","Al ver la fe de esos hombres, Jesús dijo al paralítico: «Hijo, tus pecados te son perdonados».","Unos escribas que estaban sentados allí pensaban en su interior:","«¿Qué está diciendo este hombre? ¡Está blasfemando! ¿Quién puede perdonar los pecados, sino sólo Dios?","Jesús, advirtiendo en seguida que pensaban así, les dijo: «¿Qué están pensando?","¿Qué es más fácil, decir al paralítico: \"Tus pecados te son perdonados\", o \"Levántate, toma tu camilla y camina\"?","Para que ustedes sepan que el Hijo de hombre tiene sobre la tierra el poder de perdonar los pecados","–dijo al paralítico– yo te lo mando, levántate, toma tu camilla y vete a tu casa».","El se levantó en seguida, tomó su camilla y salió a la vista de todos. La gente quedó asombrada y glorificaba a Dios, diciendo: «Nunca hemos visto nada igual».","Jesús salió nuevamente a la orilla del mar; toda la gente acudía allí, y él les enseñaba.","Al pasar vio a Leví, hijo de Alfeo, sentado a la mesa de recaudación de impuestos, y le dijo: «Sígueme». El se levantó y lo siguió.","Mientras Jesús estaba comiendo en su casa, muchos publicanos y pecadores se sentaron a comer con él y sus discípulos;","Los escribas del grupo de los fariseos, al ver que comía con pecadores y publicanos, decían a los discípulos: «¿Por qué come con publicanos y pecadores?».","Jesús, que había oído, les dijo: «No son los sanos los que tienen necesidad del médico, sino los enfermos. Yo no he venido a llamar a los justos, sino a los pecadores».","Un día en que los discípulos de Juan y los fariseos, fueron a decirle a Jesús: «¿Por qué tus discípulos no ayunan, como lo hacen los discípulos de Juan y los discípulos de los fariseos?».","Jesús les respondió: «¿Acaso los amigos del esposo pueden ayunar cuando el esposo está con ellos? Es natural que no ayunen, mientras tienen consigo al esposo.","Llegará el momento en que el esposo les será quitado, y entonces ayunarán.","Nadie usa un pedazo de género nuevo para remendar un vestido viejo, porque el pedazo añadido tira del vestido viejo y la rotura se hace más grande.","Tampoco se pone vino nuevo en odres viejos, porque hará reventar los odres, y ya no servirán más ni el vino ni los odres. ¡A vino nuevo, odres nuevos!».","Un sábado en que Jesús atravesaba unos sembrados, sus discípulos comenzaron a arrancar espigas al pasar.","Entonces los fariseos le dijeron: «¡Mira! ¿Por qué hacen en sábado lo que no está permitido?».","El les respondió: «¿Ustedes no han leído nunca lo que hizo David, cuando él y sus compañeros se vieron obligados por el hambre,","cómo entró en la Casa de Dios, en el tiempo del Sumo Sacerdote Abiatar, y comió y dio a sus compañeros los panes de la ofrenda, que sólo pueden comer los sacerdotes?».","Y agregó: «El sábado ha sido hecho para el hombre, y no el hombre para el sábado.","De manera que el Hijo del hombre es dueño también del sábado»."],["Jesús entró nuevamente en una sinagoga, y había allí un hombre que tenía una mano paralizada.","Los fariseos observaban atentamente a Jesús para ver si lo curaba en sábado, con el fin de acusarlo.","Jesús dijo al hombre de la mano paralizada: «Ven y colócate aquí delante».","Y les dijo: «¿Está permitido en sábado hacer el bien o el mal, salvar una vida o perderla?». Pero ellos callaron.","Entonces, dirigiendo sobre ellos una mirada llena de indignación y apenado por la dureza de sus corazones, dijo al hombre: «Extiende tu mano». El la extendió y su mano quedó curada.","Los fariseos salieron y se confabularon con los herodianos para buscar la forma de acabar con él.","Jesús se retiró con sus discípulos a la orilla del mar, y lo siguió mucha gente de Galilea.","Al enterarse de lo que hacía, también fue a su encuentro una gran multitud de Judea, de Jerusalén, de Idumea, de la Transjordania y de la región de Tiro y Sidón.","Entonces mandó a sus discípulos que le prepararan una barca, para que la muchedumbre no lo apretujara.","Porque, como curaba a muchos, todos los que padecían algún mal se arrojaban sobre él para tocarlo.","Y los espíritus impuros, apenas lo veían, se tiraban a sus pies, gritando: «¡Tú eres el Hijo de Dios!».","Pero Jesús les ordenaba terminantemente que no lo pusieran de manifiesto.","Después subió a la montaña y llamó a su lado a los que quiso. Ellos fueron hacia él,","y Jesús instituyó a doce para que estuvieran con él, y para enviarlos a predicar","con el poder de expulsar a los demonios.","Así instituyó a los Doce: Simón, al que puso el sobrenombre de Pedro;","Santiago, hijo de Zebedeo, y Juan, hermano de Santiago, a los que dio el nombre de Boanerges, es decir, hijos del trueno;","luego, Andrés, Felipe, Bartolomé, Mateo, Tomás, Santiago, hijo de Alfeo, Tadeo, Simón, el Cananeo,","y Judas Iscariote, el mismo que lo entregó.","Jesús regresó a la casa, y de nuevo se juntó tanta gente que ni siquiera podían comer.","Cuando sus parientes se enteraron, salieron para llevárselo, porque decían: «Es un exaltado».","Los escribas que habían venido de Jerusalén decían: «Está poseído por Belzebul y expulsa a los demonios por el poder del Príncipe de los Demonios».","Jesús los llamó y por medio de comparaciones les explicó: «¿Cómo Satanás va a expulsar a Satanás?","Un reino donde hay luchas internas no puede subsistir,","Y una familia dividida tampoco puede subsistir.","Por lo tanto, si Satanás se dividió, levantándose contra sí mismo, ya no puede subsistir, sino que ha llega a su fin.","Pero nadie puede entrar en la casa de un hombre fuerte y saquear sus bienes, si primero no lo ata. Sólo así podrá saquear la casa.","Les aseguro que todo será perdonado a los hombres: todos los pecados y cualquier blasfemia que profieran.","Pero el que blasfeme contra el Espíritu Santo, no tendrá perdón jamás: es culpable de pecado para siempre».","Jesús dijo esto porque ellos decían: «Está poseído por un espíritu impuro».","Entonces llegaron su madre y sus hermanos y, quedándose afuera, lo mandaron llamar.","La multitud estaba sentada alrededor de Jesús, y le dijeron: «Tu madre y tus hermanos te buscan ahí fuera».","El les respondió: «¿Quién es mi madre y quiénes son mis hermanos?».","Y dirigiendo su mirada sobre los que estaban sentados alrededor de él, dijo: «Estos son mi madre y mis hermanos.","Porque el que hace la voluntad de Dios, ese es mi hermano, mi hermana y mi madre»."],["Jesús comenzó a enseñar de nuevo a orillas del mar. Una gran multitud se reunió junto a él, de manera que debió subir a una barca dentro del mar, y sentarse en ella. Mientras tanto, la multitud estaba en la orilla.","El les enseñaba muchas cosas por medio de parábolas, y esto era lo que les enseñaba:","«¡Escuchen! El sembrador salió a sembrar.","Mientras sembraba, parte de la semilla cayó al borde del camino, y vinieron los pájaros y se la comieron.","Otra parte cayó en terreno rocoso, donde no tenía mucha tierra, y brotó en seguida porque la tierra era poco profunda;","pero cuando salió el sol, se quemó y, por falta de raíz, se secó.","Otra cayó entre las espinas; estas crecieron, la sofocaron, y no dio fruto.","Otros granos cayeron en buena tierra y dieron fruto: fueron creciendo y desarrollándose, y rindieron ya el treinta, ya el sesenta, ya el ciento por uno».","Y decía: «¡El que tenga oídos para oír, que oiga!».","Cuando se quedó solo, los que estaban alrededor de él junto con los Doce, le preguntaban por el sentido de las parábolas.","Y Jesús les decía: «A ustedes se les ha confiado el misterio del Reino de Dios; en cambio, para los de afuera, todo es parábola,","a fin de que miren y no vean, oigan y no entiendan, no sea que se conviertan y alcancen el perdón».","Jesús les dijo: «¿No entienden esta parábola? ¿Cómo comprenderán entonces todas las demás?","El sembrador siembra la Palabra.","Los que están al borde del camino, son aquellos en quienes se siembra la Palabra; pero, apenas la escuchan, viene Satanás y se lleva la semilla sembrada en ellos.","Igualmente, los que reciben la semilla en terreno rocoso son los que, al escuchar la Palabra, la acogen en seguida con alegría;","pero no tienen raíces, sino que son inconstantes y, en cuanto sobreviene la tribulación o la persecución a causa de la Palabra, inmediatamente sucumben.","Hay otros que reciben la semilla entre espinas: son los que han escuchado la Palabra,","pero las preocupaciones del mundo, la seducción de las riquezas y las demás concupiscencias penetran en ellos y ahogan la Palabra, y esta resulta infructuosa.","Y los que reciben la semilla en tierra buena, son los que escuchan la Palabra, la aceptan y dan fruto al treinta, al sesenta y al ciento por uno».","Jesús les decía: «¿Acaso se trae una lámpara para ponerla debajo de un cajón o debajo de la cama? ¿No es más bien para colocarla sobre el candelero?.","Porque no hay nada oculto que no deba ser revelado y nada secreto que no deba manifestarse.","¡Si alguien tiene oídos para oír, que oiga!».","Y les decía: «¡Presten atención a lo que oyen! La medida con que midan se usará para ustedes, y les darán más todavía.","Porque al que tiene, se le dará, pero al que no tiene, se le quitará aun lo que tiene».","Y decía: «El Reino de Dios es como un hombre que echa la semilla en la tierra:","sea que duerma o se levante, de noche y de día, la semilla germina y va creciendo, sin que él sepa cómo.","La tierra por sí misma produce primero un tallo, luego una espiga, y al fin grano abundante en la espiga.","Cuando el fruto está a punto, él aplica en seguida la hoz, porque ha llegado el tiempo de la cosecha».","También decía: «¿Con qué podríamos comparar el Reino de Dios? ¿Qué parábola nos servirá para representarlo?","Se parece a un grano de mostaza. Cuando se la siembra, es la más pequeña de todas las semillas de la tierra,","pero, una vez sembrada, crece y llega a ser la más grande de todas las hortalizas, y extiende tanto sus ramas que los pájaros del cielo se cobijan a su sombra».","Y con muchas parábolas como estas les anunciaba la Palabra, en la medida en que ellos podían comprender.","No les hablaba sino en parábolas, pero a sus propios discípulos, en privado, les explicaba todo.","Al atardecer de ese mismo día, les dijo: «Crucemos a la otra orilla».","Ellos, dejando a la multitud, lo llevaron a la barca, así como estaba. Había otras barcas junto a la suya.","Entonces se desató un fuerte vendaval, y las olas entraban en la barca, que se iba llenando de agua.","Jesús estaba en la popa, durmiendo sobre el cabezal.","Lo despertaron y le dijeron: «¡Maestro! ¿No te importa que nos ahoguemos?». Despertándose, él increpó al viento y dijo al mar: «¡Silencio! ¡Cállate!». El viento se aplacó y sobrevino una gran calma.","Después les dijo: «¿Por qué tienen miedo? ¿Cómo no tienen fe?».","Entonces quedaron atemorizados y se decían unos a otros: «¿Quién es este, que hasta el viento y el mar le obedecen»."],["Llegaron a la otra orilla del mar, a la región de los gerasenos.","Apenas Jesús desembarcó, le salió al encuentro desde el cementerio un hombre poseído por un espíritu impuro.","El habitaba en los sepulcros, y nadie podía sujetarlo, ni siquiera con cadenas.","Muchas veces lo habían atado con grillos y cadenas pero el había roto las cadenas y destrozado los grillos, y nadie podía dominarlo.","Día y noche, vagaba entre los sepulcros y por la montaña, dando alaridos e hiriéndose con piedras.","Al ver de lejos a Jesús, vino corriendo a postrarse ante él,","gritando con fuerza: «¿Qué quieres de mí, Jesús, Hijo de Dios, el Altísimo? ¡Te conjuro por Dios, no me atormentes!».","Porque Jesús le había dicho: «¡Sal de este hombre, espíritu impuro!».","Después le preguntó: «¿Cuál es tu nombre?». El respondió: «Mi nombre es Legión, porque somos muchos».","Y le rogaba con insistencia que no lo expulsara de aquella región.","Había allí una gran piara de cerdos que estaba paciendo en la montaña.","Los espíritus impuros suplicaron a Jesús: «Envíanos a los cerdos, para que entremos en ellos».","El se lo permitió. Entonces los espíritus impuros salieron de aquel hombre, entraron en los cerdos, y desde lo alto del acantilado, toda la piara –unos dos mil animales– se precipitó al mar y se ahogó.","Los cuidadores huyeron y difundieron la noticia en la ciudad y en los poblados. La gente fue a ver qué había sucedido.","Cuando llegaron adonde estaba Jesús, vieron sentado, vestido y en su sano juicio, al que había estado poseído por aquella Legión, y se llenaron de temor.","Los testigos del hecho les contaron lo que había sucedido con el endemoniado y con los cerdos.","Entonces empezaron a pedir a Jesús que se alejara de su territorio.","En el momento de embarcarse, el hombre que había estado endemoniado le pidió que lo dejara quedarse con él.","Jesús no se lo permitió, sino que le dijo: «Vete a tu casa con tu familia, y anúnciales todo lo que el Señor hizo contigo al compadecerse de ti».","El hombre se fue y comenzó a proclamar por la región de la Decápolis lo que Jesús había hecho por él, y todos quedaban admirados.","Cuando Jesús regresó en la barca a la otra orilla, una gran multitud se reunió a su alrededor, y él se quedó junto al mar.","Entonces llegó uno de los jefes de la sinagoga, llamado Jairo, y al verlo, se arrojó a sus pies,","rogándole con insistencia: «Mi hijita se está muriendo; ven a imponerle las manos, para que se cure y viva».","Jesús fue con él y lo seguía una gran multitud que lo apretaba por todos lados.","Se encontraba allí una mujer que desde hacía doce años padecía de hemorragias.","Había sufrido mucho en manos de numerosos médicos y gastado todos sus bienes sin resultado; al contrario, cada vez estaba peor.","Como había oído hablar de Jesús, se le acercó por detrás, entre la multitud, y tocó su manto,","porque pensaba: «Con sólo tocar su manto quedaré curada».","Inmediatamente cesó la hemorragia, y ella sintió en su cuerpo que estaba curada de su mal.","Jesús se dio cuenta en seguida de la fuerza que había salido de él, se dio vuelta y, dirigiéndose a la multitud, preguntó: «¿Quién tocó mi manto?».","Sus discípulos le dijeron: «¿Ves que la gente te aprieta por todas partes y preguntas quién te ha tocado?».","Pero él seguía mirando a su alrededor, para ver quién había sido.","Entonces la mujer, muy asustada y temblando, porque sabía bien lo que le había ocurrido, fue a arrojarse a los pies y le confesó toda la verdad.","Jesús le dijo: «Hija, tu fe te ha salvado. Vete en paz, y queda curada de tu enfermedad».","Todavía estaba hablando, cuando llegaron unas personas de la casa del jefe de la sinagoga y le dijeron: «Tu hija ya murió; ¿para qué vas a seguir molestando al Maestro?».","Pero Jesús, sin tener en cuenta esas palabras, dijo al jefe de la sinagoga: «No temas, basta que creas».","Y sin permitir que nadie lo acompañara, excepto Pedro, Santiago y Juan, el hermano de Santiago,","fue a casa del jefe de la sinagoga. Allí vio un gran alboroto, y gente que lloraba y gritaba.","Al entrar, les dijo: «¿Por qué se alborotan y lloran? La niña no está muerta, sino que duerme».","Y se burlaban de él. Pero Jesús hizo salir a todos, y tomando consigo al padre y a la madre de la niña, y a los que venían con él, entró donde ella estaba.","La tomó de la mano y le dijo: «Talitá kum», que significa: «¡Niña, yo te lo ordeno, levántate».","En seguida la niña, que ya tenía doce años, se levantó y comenzó a caminar. Ellos, entonces, se llenaron de asombro,","y él les mandó insistentemente que nadie se enterara de lo sucedido. Después dijo que le dieran de comer."],["Jesús salió de allí y se dirigió a su pueblo, seguido de sus discípulos.","Cuando llegó el sábado, comenzó a enseñar en la sinagoga, y la multitud que lo escuchaba estaba asombrada y decía: «¿De dónde saca todo esto? ¿Qué sabiduría es esa que le ha sido dada y esos grandes milagros que se realizan por sus manos?","¿No es acaso el carpintero, el hijo de María, hermano de Santiago, de José, de Judas y de Simón? ¿Y sus hermanos no viven aquí entre nosotros?». Y Jesús era para ellos un motivo de escándalo.","Por eso les dijo: «Un profeta es despreciado solamente en su pueblo, en su familia y en su casa».","Y no pudo hacer allí ningún milagro, fuera de curar a unos pocos enfermos, imponiéndoles las manos.","Y él se asombraba de su falta de fe. Jesús recorría las poblaciones de los alrededores, enseñando a la gente.","Entonces llamó a los Doce y los envió de dos en dos, dándoles poder sobre los espíritus impuros.","Y les ordenó que no llevaran para el camino más que un bastón; ni pan, ni alforja, ni dinero;","que fueran calzados con sandalias y que no tuvieran dos túnicas.","Les dijo: «Permanezcan en la casa donde les den alojamiento hasta el momento de partir.","Si no los reciben en un lugar y la gente no los escucha, al salir de allí, sacudan hasta el polvo de sus pies, en testimonio contra ellos».","Entonces fueron a predicar, exhortando a la conversión;","expulsaron a muchos demonios y curaron a numerosos enfermos, ungiéndolos con óleo.","El rey Herodes oyó hablar de Jesús, porque su fama se había extendido por todas partes. Algunos decían: «Juan el Bautista ha resucitado, y por eso se manifiestan en él poderes milagrosos:.","Otros afirmaban: «Es Elías». Y otros: «Es un profeta como los antiguos».","Pero Herodes, al oír todo esto, decía: «Este hombre es Juan, a quien yo mandé decapitar y que ha resucitado».","Herodes, en efecto, había hecho arrestar y encarcelar a Juan a causa de Herodías, la mujer de su hermano Felipe, con la que se había casado.","Porque Juan decía a Herodes: «No te es lícito tener a la mujer de tu hermano».","Herodías odiaba a Juan e intentaba matarlo, pero no podía,","porque Herodes lo respetaba, sabiendo que era un hombre justo y santo, y lo protegía.","Un día se presentó la ocasión favorable. Herodes festejaba su cumpleaños, ofreciendo un banquete a sus dignatarios, a sus oficiales y a los notables de Galilea.","La hija de Herodías salió a bailar, y agradó tanto a Herodes y a sus convidados, que el rey dijo a la joven: «Pídeme lo que quieras y te lo daré».","Y le aseguró bajo juramento: «Te daré cualquier cosa que me pidas, aunque sea la mitad de mi reino».","Ella fue a preguntar a su madre: «¿Qué debo pedirle?». «La cabeza de Juan el Bautista», respondió esta.","La joven volvió rápidamente adonde estaba el rey y le hizo este pedido: «Quiero que me traigas ahora mismo, sobre una bandeja, la cabeza de Juan el Bautista».","El rey se entristeció mucho, pero a causa de su juramento, y por los convidados, no quiso contrariarla.","En seguida mandó a un guardia que trajera la cabeza de Juan.","El guardia fue a la cárcel y le cortó la cabeza. Después la trajo sobre una bandeja, la entregó a la joven y esta se la dio a su madre.","Cuando los discípulos de Juan lo supieron, fueron a recoger el cadáver y lo sepultaron.","Los Apóstoles se reunieron con Jesús y le contaron todo lo que habían hecho y enseñado.","El les dijo: «Vengan ustedes solos a un lugar desierto, para descansar un poco». Porque era tanta la gente que iba y venía, que no tenían tiempo ni para comer.","Entonces se fueron solos en la barca a un lugar desierto.","Al verlos partir, muchos los reconocieron, y de todas las ciudades acudieron por tierra a aquel lugar y llegaron antes que ellos.","Al desembarcar, Jesús vio una gran muchedumbre y se compadeció de ella, porque eran como ovejas sin pastor, y estuvo enseñándoles largo rato.","Como se había hecho tarde, sus discípulos se acercaron y le dijeron: «Este es un lugar desierto, y ya es muy tarde.","Despide a la gente, para que vaya a las poblaciones cercanas a comprar algo para comer».","El respondió: «Denles de comer ustedes mismos». Ellos le dijeron: «Habría que comprar pan por valor de doscientos denarios para dar de comer a todos».","Jesús preguntó: «¿Cuántos panes tienen ustedes? Vayan a ver». Después de averiguarlo, dijeron: «Cinco panes y dos pescados».","El les ordenó que hicieran sentar a todos en grupos, sobre la hierba verde,","y la gente se sentó en grupos de cien y de cincuenta.","Entonces él tomó los cinco panes y los dos pescados, y levantando los ojos al cielo, pronunció la bendición, partió los panes y los fue entregando a sus discípulos para que los distribuyeran. También repartió los dos pescados entre la gente.","Todos comieron hasta saciarse,","y se recogieron doce canastas llenas de sobras de pan y de restos de pescado.","Los que comieron eran cinco mil hombres.","En seguida, Jesús obligó a sus discípulos a que subieran a la barca y lo precedieran en la otra orilla, hacia Betsaida, mientras él despedía a la multitud.","Una vez que los despidió, se retiró a la montaña para orar.","Al caer la tarde, la barca estaba en medio del mar y él permanecía solo en tierra.","Al ver que remaban muy penosamente, porque tenían viento en contra, cerca de la madrugada fue hacia ellos caminando sobre el mar, e hizo como si pasara de largo.","Ellos, al verlo caminar sobre el mar, pensaron que era un fantasma y se pusieron a gritar,","porque todos lo habían visto y estaban sobresaltados. Pero él les habló enseguida y les dijo: «Tranquilícense, soy yo; no teman».","Luego subió a la barca con ellos y el viento se calmó. Así llegaron al colmo de su estupor,","porque no habían comprendido el milagro de los panes y su mente estaba enceguecida.","Después de atravesar el lago, llegaron a Genesaret y atracaron allí.","Apenas desembarcaron, la gente reconoció en seguida a Jesús,","y comenzaron a recorrer toda la región para llevar en camilla a los enfermos, hasta el lugar donde sabían que él estaba.","En todas partes donde entraba, pueblos, ciudades y poblados, ponían a los enfermos en las plazas y le rogaban que los dejara tocar tan sólo los flecos de su manto, y los que lo tocaban quedaban curados."],["Los fariseos con algunos escribas llegados de Jerusalén se acercaron a Jesús,","y vieron que algunos de sus discípulos comían con las manos impuras, es decir, sin lavar.","Los fariseos, en efecto, y los judíos en general, no comen sin lavarse antes cuidadosamente las manos, siguiendo la tradición de sus antepasados;","y al volver del mercado, no comen sin hacer primero las abluciones. Además, hay muchas otras prácticas, a las que están aferrados por tradición, como el lavado de los vasos, de las jarras y de la vajilla de bronce.","Entonces los fariseos y los escribas preguntaron a Jesús: «¿Por qué tus discípulos no proceden de acuerdo con la tradición de nuestros antepasados, sino que comen con las manos impuras?».","El les respondió: «¡Hipócritas! Bien profetizó de ustedes Isaías, en el pasaje de la Escritura que dice: Este pueblo me honra con los labios, pero su corazón está lejos de mí.","En vano me rinde culto: las doctrinas que enseñan no son sino preceptos humanos.","Ustedes dejan de lado el mandamiento de Dios, por seguir la tradición de los hombres».","Y les decía: «Por mantenerse fieles a su tradición, ustedes descartan tranquilamente el mandamiento de Dios.","Porque Moisés dijo: Honra a tu padre y a tu madre, y además: El que maldice a su padre y a su madre será condenado a muerte.","En cambio, ustedes afirman: «Si alguien dice a su padre o a su madre: Declaro \"corbán\" –es decir, ofrenda sagrada– todo aquello con lo que podría ayudarte...»","En ese caso, le permiten no hacer más nada por su padre o por su madre.","Así anulan la palabra de Dios por la tradición que ustedes mismos se han transmitido. ¡Y como estas, hacen muchas otras cosas!».","Y Jesús, llamando otra vez a la gente, les dijo: «Escúchenme todos y entiéndanlo bien.","Ninguna cosa externa que entra en el hombre puede mancharlo; lo que lo hace impuro es aquello que sale del hombre.","¡Si alguien tiene oídos para oír, que oiga!».","Cuando se apartó de la multitud y entró en la casa, sus discípulos le preguntaron por el sentido de esa parábola.","El les dijo: «¿Ni siquiera ustedes son capaces de comprender? ¿No saben que nada de lo que entra de afuera en el hombre puede mancharlo,","porque eso no va al corazón sino al vientre, y después se elimina en lugares retirados?». Así Jesús declaraba que eran puros todos los alimentos.","Luego agregó: «Lo que sale del hombre es lo que lo hace impuro.","Porque es del interior, del corazón de los hombres, de donde provienen las malas intenciones, las fornicaciones, los robos, los homicidios,","los adulterios, la avaricia, la maldad, los engaños, las deshonestidades, la envidia, la difamación, el orgullo, el desatino.","Todas estas cosas malas proceden del interior y son las que manchan al hombre».","Después Jesús partió de allí y fue a la región de Tiro. Entró en una casa y no quiso que nadie lo supiera, pero no pudo permanecer oculto.","En seguida una mujer cuya hija estaba poseída por un espíritu impuro, oyó hablar de él y fue a postrarse a sus pies.","Esta mujer, que era pagana y de origen sirofenicio, le pidió que expulsara de su hija al demonio.","El le respondió: «Deja que antes se sacien los hijos; no está bien tomar el pan de los hijos para tirárselo a los cachorros».","Pero ella le respondió: «Es verdad, Señor, pero los cachorros, debajo de la mesa, comen las migajas que dejan caer los hijos».","Entonces él le dijo: «A causa de lo que has dicho, puedes irte: el demonio ha salido de tu hija».","Ella regresó a su casa y encontró a la niña acostada en la cama y liberada del demonio.","Cuando Jesús volvía de la región de Tiro, pasó por Sidón y fue hacia el mar de Galilea, atravesando el territorio de la Decápolis.","Entonces le presentaron a un sordomudo y le pidieron que le impusiera las manos.","Jesús lo separó de la multitud y, llevándolo aparte, le puso los dedos en las orejas y con su saliva le tocó la lengua.","Después, levantando los ojos al cielo, suspiró y dijo: «Efatá», que significa: «Abrete».","Y enseguida se abrieron sus oídos, se le soltó la lengua y comenzó a hablar normalmente.","Jesús les mandó insistentemente que no dijeran nada a nadie, pero cuanto más insistía, ellos más lo proclamaban","y, en el colmo de la admiración, decían: «Todo lo ha hecho bien: hace oír a los sordos y hablar a los mudos»."],["En esos días, volvió a reunirse una gran multitud, y como no tenían qué comer, Jesús llamó a sus discípulos y les dijo:","«Me da pena esta multitud, porque hace tres días que están conmigo y no tienen qué comer.","Si los mando en ayunas a sus casas, van a desfallecer en el camino, y algunos han venido de lejos».","Los discípulos le preguntaron: «¿Cómo se podría conseguir pan en este lugar desierto para darles de comer?».","el les dijo: «¿Cuántos panes tienen ustedes?». Ellos respondieron: «Siete».","Entonces él ordenó a la multitud que se sentara en el suelo, después tomó los siete panes, dio gracias, los partió y los fue entregando a sus discípulos para que los distribuyeran. Ellos los repartieron entre la multitud.","Tenían, además, unos cuantos pescados pequeños, y después de pronunciar la bendición sobre ellos, mandó que también los repartieran.","Comieron hasta saciarse y todavía se recogieron siete canastas con lo que había sobrado.","Eran unas cuatro mil personas. Luego Jesús los despidió.","En seguida subió a la barca con sus discípulos y fue a la región de Dalmanuta.","Entonces llegaron los fariseos, que comenzaron a discutir con él; y, para ponerlo a prueba, le pedían un signo del cielo.","Jesús, suspirando profundamente, dijo: «¿Por qué esta generación pide un signo? Les aseguro que no se le dará ningún signo».","Y dejándolos, volvió a embarcarse hacia la otra orilla.","Los discípulos se habían olvidado de llevar pan y no tenían más que un pan en la barca.","Jesús les hacía esta recomendación: «Estén atentos, cuídense de la levadura de los fariseos y de la levadura de Herodes».","Ellos discutían entre sí, porque no habían traído pan.","Jesús se dio cuenta y les dijo: «¿A qué viene esa discusión porque no tienen pan? ¿Todavía no comprenden ni entienden? Ustedes tienen la mente enceguecida.","Tienen ojos y no ven, oídos y no oyen. ¿No recuerdan","cuántas canastas llenas de sobras recogieron, cuando repartí cinco panes entre cinco mil personas?». Ellos le respondieron: «Doce».","«Y cuando repartí siete panes entre cuatro mil personas, ¿cuántas canastas llenas de trozos recogieron?». Ellos le respondieron: «Siete».","Entonces Jesús les dijo: «¿Todavía no comprenden?».","Cuando llegaron a Betsaida, le trajeron a un ciego y le rogaban que lo tocara.","El tomó al ciego de la mano y lo condujo a las afueras del pueblo. Después de ponerla saliva en los ojos e imponerle las manos, Jesús le preguntó: «¿Ves algo?».","El ciego, que comenzaba a ver, le respondió: «Veo hombres, como si fueran árboles que caminan».","Jesús le puso nuevamente las manos sobre los ojos, y el hombre recuperó la vista. Así quedó curado y veía todo con claridad.","Jesús lo mandó a su casa, diciéndole: «Ni siquiera entres en el pueblo».","Jesús salió con sus discípulos hacia los poblados de Cesarea de Filipo, y en el camino les preguntó: «¿Quién dice la gente que soy yo?.","Ellos le respondieron: «Algunos dicen que eres Juan el Bautista; otros, Elías; y otros, alguno de los profetas».","«Y ustedes, Tú eres el Mesías».","Jesús les ordenó terminantemente que no dijeran nada acerca de él.","Y comenzó a enseñarles que el Hijo del hombre debía sufrir mucho y ser rechazado por los ancianos, los sumos sacerdotes y los escribas; que debía ser condenado a muerte y resucitar después de tres días;","y les hablaba de esto con toda claridad. Pedro, llevándolo aparte, comenzó a reprenderlo.","Pero Jesús, dándose vuelta y mirando a sus discípulos, lo reprendió, diciendo: «¡Retírate, ve detrás de mí, Satanás! Porque tus pensamientos no son los de Dios, sino los de los hombres».","Entonces Jesús, llamando a la multitud, junto con sus discípulos, les dijo: «El que quiera venir detrás de mí, que renuncie a sí mismo, que cargue con su cruz y me siga.","Porque el que quiera salvar su vida, la perderá; y el que pierda su vida por mí y por la Buena Noticia, la salvará.","¿De qué le servirá al hombre ganar el mundo entero, si pierde su vida?","¿Y qué podrá dar el hombre a cambio de su vida?","Porque si alguien se avergüenza de mí y de mis palabras en esta generación adúltera y pecadora, también el Hijo del hombre se avergonzará de él cuando venga en la gloria de su Padre con sus santos ángeles»."],["Y les decía: «Les aseguro que algunos de los que están aquí presentes no morirán antes de haber visto que el Reino de Dios ha llegado con poder».","Seis días después, Jesús tomó a Pedro, Santiago y Juan, y los llevo a ellos solos a un monte elevado. Allí se transfiguró en presencia de ellos.","Sus vestiduras se volvieron resplandecientes, tan blancas como nadie en el mundo podría blanquearlas.","Y se les aparecieron Elías y Moisés, conversando con Jesús.","Pedro dijo a Jesús: «Maestro, ¡qué bien estamos aquí! Hagamos tres carpas, una para ti, otra para Moisés y otra para Elías».","Pedro no sabía qué decir, porque estaban llenos de temor.","Entonces una nube los cubrió con su sombra, y salió de ella una voz: «Este es mi Hijo muy querido, escúchenlo».","De pronto miraron a su alrededor y no vieron a nadie, sino a Jesús solo con ellos.","Mientras bajaban del monte, Jesús les prohibió contar lo que habían visto, hasta que el Hijo del hombre resucitara de entre los muertos.","Ellos cumplieron esta orden, pero se preguntaban qué significará «resucitar de entre los muertos».","Y le hicieron esta pregunta: «¡Por qué dicen los escribas que antes debe venir Elías?».","Jesús les respondió: «Sí, Elías debe venir antes para restablecer el orden en todo. Pero, ¿no dice la Escritura que el Hijo del hombre debe sufrir mucho y ser despreciado?","Les aseguro que Elías ya ha venido e hicieron con él lo que quisieron, como estaba escrito».","Cuando volvieron a donde estaban los otros discípulos, los encontraron en medio de una gran multitud, discutiendo con algunos escribas.","En cuanto la multitud distinguió a Jesús, quedó asombrada y corrieron a saludarlo.","El les preguntó: «¿Sobre qué estaban discutiendo?».","Uno de ellos le dijo: «Maestro, te he traído a mi hijo, que está poseído de un espíritu mudo.","Cuando se apodera de él, lo tira al suelo y le hace echar espuma por la boca; entonces le crujen sus dientes y se queda rígido. Le pedí a tus discípulos que lo expulsaran pero no pudieron».","«Generación incrédula, respondió Jesús, ¿hasta cuando estaré con ustedes? ¿Hasta cuando tendré que soportarlos? Tráiganmelo».","Y ellos se lo trajeron. En cuanto vio a Jesús, el espíritu sacudió violentamente al niño, que cayó al suelo y se revolcaba, echando espuma por la boca.","Jesús le preguntó al padre: «¿Cuánto tiempo hace que está así?». «Desde la infancia, le respondió,","y a menudo lo hace caer en el fuego o en el agua para matarlo. Si puedes hacer algo, ten piedad de nosotros y ayúdanos».","«¡Si puedes...!», respondió Jesús. «Todo es posible para el que cree».","Inmediatamente el padre del niño exclamó: «Creo, ayúdame porque tengo poca fe».","Al ver que llegaba más gente, Jesús increpó al espíritu impuro, diciéndole: «Espíritu mudo y sordo, yo te lo ordeno, sal de él y no vuelvas más».","El demonio gritó, sacudió violentamente al niño y salió de él, dejándolo como muerto, tanto que muchos decían: «Está muerto».","Pero Jesús, tomándolo de la mano, lo levantó, y el niño se puso de pie.","Cuando entró a la casa y quedaron solos, los discípulos le preguntaron: «¿Por qué nosotros no pudimos expulsarlo?».","El les respondió: «Esta clase de demonios se expulsa sólo con la oración».","Al salir de allí atravesaron la Galilea; Jesús no quería que nadie lo supiera,","porque enseñaba y les decía: «El Hijo del hombre va a ser entregado en manos de los hombres; lo matarán y tres días después de su muerte, resucitará».","Pero los discípulos no comprendían esto y temían hacerle preguntas.","Llegaron a Cafarnaúm y, una vez que estuvieron en la casa, les preguntó: «¿De qué hablaban en el camino?».","Ellos callaban, porque habían estado discutiendo sobre quién era el más grande.","Entonces, sentándose, llamó a los Doce y les dijo: «El que quiere ser el primero, debe hacerse el último de todos y el servidor de todos».","Después, tomando a un niño, lo puso en medio de ellos y, abrazándolo, les dijo:","«El que recibe a uno de estos pequeños en mi Nombre, me recibe a mí, y el que me recibe, no es a mí al que recibe, sino a aquel que me ha enviado».","Juan le dijo: «Maestro, hemos visto a uno que expulsaba demonios en tu Nombre, y tratamos de impedírselo porque no es de los nuestros».","Pero Jesús les dijo: «No se lo impidan, porque nadie puede hacer un milagro en mi Nombre y luego hablar mal de mí.","Y el que no está contra nosotros, está con nosotros.","Les aseguro que no quedará sin recompensa el que les dé de beber un vaso de agua por el hecho de que ustedes pertenecen a Cristo.","Si alguien llegara a escandalizar a uno de estos pequeños que tienen fe, sería preferible para él que le ataran al cuello una piedra de moler y lo arrojaran al mar.","Si tu mano es para ti ocasión de pecado, córtala, porque más te vale entrar en la Vida manco, que ir con tus dos manos a la Gehena, al fuego inextinguible.","","Y si tu pie es para ti ocasión de pecado, córtalo, porque más te vale entrar lisiado en la Vida, que ser arrojado con tus dos pies a la Gehena.","","Y si tu ojo es para ti ocasión de pecado, arráncalo, porque más te vale entrar con un solo ojo en el Reino de Dios, que ser arrojado con tus dos ojos a la Gehena,","donde el gusano no muere y el fuego no se apaga.","Porque cada uno será salado por el fuego.","La sal es una cosa excelente, pero si se vuelve insípida, ¿con qué la volverán a salar? Que haya sal en ustedes mismos y vivan en paz unos con otros»."],["Después que partió de allí, Jesús fue a la región de Judea y al otro lado del Jordán. Se reunió nuevamente la multitud alrededor de él y, como de costumbre, les estuvo enseñando una vez más.","Se acercaron algunos fariseos y, para ponerlo a prueba, le plantearon esta cuestión: «¿Es lícito al hombre divorciarse de su mujer?».","El les respondió: «¿Qué es lo que Moisés les ha ordenado?».","Ellos dijeron: «Moisés permitió redactar una declaración de divorcio y separarse de ella».","Entonces Jesús les respondió: «Si Moisés les dio esta prescripción fue debido a la dureza del corazón de ustedes.","Pero desde el principio de la creación, Dios los hizo varón y mujer.","Por eso, el hombre dejará a su padre y a su madre.","y los dos no serán sino una sola carne. De manera que ya no son dos, sino una sola carne.","Que el hombre no separe lo que Dios ha unido».","Cuando regresaron a la casa, los discípulos le volvieron a preguntar sobre esto.","El les dijo: «El que se divorcia de su mujer y se casa con otra, comete adulterio contra aquella;","y si una mujer se divorcia de su marido y se casa con otro, también comete adulterio».","Le trajeron entonces a unos niños para que los tocara, pero los discípulos los reprendieron.","Al ver esto, Jesús se enojó y les dijo: «Dejen que los niños se acerquen a mí y no se lo impidan, porque el Reino de Dios pertenece a los que son como ellos.","Les aseguro que el que no recibe el Reino de Dios como un niño, no entrará en él».","Después los abrazó y los bendijo, imponiéndoles las manos","Cuando se puso en camino, un hombre corrió hacia él y, arrodillándose, le preguntó: «Maestro bueno, ¿qué debo hacer para heredar la Vida eterna?».","Jesús le dijo: «¿Por qué me llamas bueno? Sólo Dios es bueno.","Tú conoces los mandamientos: No matarás, no cometerás adulterio, no robarás, no darás falso testimonio, no perjudicarás a nadie, honra a tu padre y a tu madre».","El hombre le respondió: «Maestro, todo eso lo he cumplido desde mi juventud».","Jesús lo miró con amor y le dijo: «Sólo te falta una cosa: ve, vende lo que tienes y dalo a los pobres; así tendrás un tesoro en el cielo. Después, ven y sígueme».","El, al oír estas palabras, se entristeció y se fue apenado, porque poseía muchos bienes.","Entonces Jesús, mirando alrededor, dijo a sus discípulos: «¡Qué difícil será para los ricos entrar en el Reino de Dios!».","Los discípulos se sorprendieron por estas palabras, pero Jesús continuó diciendo: «Hijos míos, ¡Qué difícil es entrar en el Reino de Dios!.","Es más fácil que un camello pase por el ojo de una aguja, que un rico entre en el Reino de Dios».","Los discípulos se asombraron aún más y se preguntaban unos a otros: «Entonces, ¿quién podrá salvarse?».","Jesús, fijando en ellos su mirada, les dijo: «Para los hombres es imposible, pero no para Dios, porque para él todo es posible».","Pedro le dijo: «Tú sabes que nosotros lo hemos dejado todo y te hemos seguido».","Jesús respondió: «Les aseguro que el que haya dejado casa, hermanos y hermanas, madre y padre, hijos o campos por mí y por la Buena Noticia,","desde ahora, en este mundo, recibirá el ciento por uno en casas, hermanos y hermanas, madres, hijos, campos, en medio de las persecuciones; y en el mundo futuro recibirá la Vida eterna.","Muchos de los primeros serán los últimos y los últimos serán los primeros».","Mientras iban de camino para subir a Jerusalén, Jesús se adelantaba a sus discípulos; ellos estaban asombrados y los que lo seguían tenían miedo. Entonces reunió nuevamente a los Doce y comenzó a decirles lo que le iba a suceder:","«Ahora subimos a Jerusalén; allí el Hijo del hombre será entregado a los sumos sacerdotes y a los escribas. Lo condenarán a muerte y lo entregarán a los paganos:","ellos se burlarán de él, lo escupirán, lo azotarán y lo matarán. Y tres días después, resucitará».","Santiago y Juan, los hijos de Zebedeo, se acercaron a Jesús y le dijeron: «Maestro, queremos que nos concedas lo que te vamos a pedir».","El les respondió: «¿Qué quieren que haga por ustedes?».","Ellos le dijeron: «Concédenos sentarnos uno a tu derecha y el otro a tu izquierda, cuando estés en tu gloria».","Jesús le dijo: «No saben lo que piden. ¿Pueden beber el cáliz que yo beberé y recibir el bautismo que yo recibiré?».","«Podemos», le respondieron. Entonces Jesús agregó: «Ustedes beberán el cáliz que yo beberé y recibirán el mismo bautismo que yo.","En cuanto a sentarse a mi derecha o a mi izquierda, no me toca a mí concederlo, sino que esos puestos son para quienes han sido destinados».","Los otros diez, que habían oído a Santiago y a Juan, se indignaron contra ellos.","Jesús los llamó y les dijo: «Ustedes saben que aquellos a quienes se considera gobernantes, dominan a las naciones como si fueran sus dueños, y los poderosos les hacen sentir su autoridad.","Entre ustedes no debe suceder así. Al contrario, el que quiera ser grande, que se haga servidor de ustedes;","y el que quiera ser el primero, que se haga servidor de todos.","Porque el mismo Hijo del hombre no vino para ser servido, sino para servir y dar su vida en rescate por una multitud».","Después llegaron a Jericó. Cuando Jesús salía de allí, acompañado de sus discípulos y de una gran multitud, el hijo de Timeo –Bartimeo, un mendigo ciego– estaba sentado junto al camino.","Al enterarse de que pasaba Jesús, el Nazareno, se puso a gritar: «¡Jesús, Hijo de David, ten piedad de mí!».","Muchos lo reprendían para que se callara, pero él gritaba más fuerte: «¡Hijo de David, ten piedad de mí!».","Jesús se detuvo y dijo: «Llámenlo». Entonces llamaron al ciego y le dijeron: «¡Animo, levántate! El te llama».","Y el ciego, arrojando su manto, se puso de pie de un salto y fue hacia él.","Jesús le preguntó: «¿Qué quieres que haga por ti?. El le respondió: «Maestro, que yo pueda ver».","Jesús le dijo: «Vete, tu fe te ha salvado». En seguida comenzó a ver y lo siguió por el camino."],["Cuando se aproximaban a Jerusalén, estando ya al pie del monte de los Olivos, cerca de Betfagé y de Betania, Jesús envió a dos de sus discípulos,","diciéndoles: «Vayan al pueblo que está enfrente y, al entrar, encontrarán un asno atado, que nadie ha montado todavía. Desátenlo y tráiganlo;","y si alguien les pregunta: «¿Qué están haciendo?», respondan: «El Señor lo necesita y lo va a devolver en seguida».","Ellos fueron y encontraron un asno atado cerca de una puerta, en la calle, y lo desataron.","algunos de los que estaban allí les preguntaron: «¿Qué hacen? ¿Por qué desatan ese asno?».","Ellos respondieron como Jesús les había dicho y nadie los molestó.","Entonces le llevaron el asno, pusieron sus mantos sobre él y Jesús se montó.","Muchos extendían sus mantos sobre el camino; otros, lo cubrían con ramas que cortaban en el campo.","Los que iban delante y los que seguían a Jesús, gritaban: «¡Hosana! ¡Bendito el que viene en nombre del Señor!","¡Bendito sea el Reino que ya viene, el Reino de nuestro padre David! ¡Hosana en las alturas!».","Jesús llegó a Jerusalén y fue al Templo; después de observarlo todo, como ya era tarde, salió con los Doce hacia Betania.","Al día siguiente, cuando salieron de Betania, Jesús sintió hambre.","Al divisar de lejos una higuera cubierta de hojas, se acercó para ver si encontraba algún fruto, pero no había más que hojas; porque no era la época de los higos.","Dirigiéndose a la higuera, le dijo: «Que nadie más coma de tus frutos». Y sus discípulos lo oyeron.","Cuando llegaron a Jerusalén, Jesús entró en el Templo y comenzó a echar a los que vendían y compraban en él. Derribó las mesas de los cambistas y los puestos de los vendedores de palomas,","y prohibió que transportaran cargas por el Templo.","Y les enseñaba: «¿Acaso no está escrito: Mi Casa será llamada Casa de oración para todas las naciones? Pero ustedes la han convertido en una cueva de ladrones».","Cuando se enteraron los sumos sacerdotes y los escribas, buscaban la forma de matarlo, porque le tenían miedo, ya que todo el pueblo estaba maravillado de su enseñanza.","Al caer la tarde, Jesús y sus discípulos salieron de la ciudad.","A la mañana siguiente, al pasar otra vez, vieron que la higuera se había secado de raíz.","Pedro, acordándose, dijo a Jesús: «Maestro, la higuera que has maldecido se ha secado».","Jesús respondió: «Tengan fe en Dios.","Porque yo les aseguro que si alguien dice a esta montaña: «Retírate de ahí y arrójate al mar», sin vacilar en su interior, sino creyendo que sucederá lo que dice, lo conseguirá.","Por eso les digo: Cuando pidan algo en la oración, crean que ya lo tienen y lo conseguirán.","Y cuando ustedes se pongan de pie para orar, si tienen algo en contra de alguien, perdónenlo, y el Padre que está en el cielo les perdonará también sus faltas».","(Pero si no perdonan, tampoco el Padre que está en el cielo los perdonará a ustedes)","Y llegaron de nuevo a Jerusalén. Mientras Jesús caminaba por el Templo, los sumos sacerdotes, los escribas y los ancianos se acercaron a él","y le dijeron: «¿Con qué autoridad haces estas cosas? ¿O quién te dio autoridad para hacerlo?».","Jesús les respondió: «Yo también quiero hacerles una sola pregunta. Si me responden, les diré con qué autoridad hago estas cosas.","Díganme: el bautismo de Juan, ¿venía del cielo o de los hombres?».","Ellos se hacían este razonamiento: «Si contestamos: \"Del cielo\", él nos dirá: \"¿Por qué no creyeron en él\"?.","¿Diremos entonces: \"De los hombres\"?». Pero como temían al pueblo, porque todos consideraban que Juan había sido realmente un profeta,","respondieron a Jesús: «No sabemos». Y él les respondió: «Yo tampoco les diré con qué autoridad hago estas cosas»."],["Jesús se puso a hablarles en parábolas: «Un hombre plantó una viña, la cercó, cavó un lugar y construyó una torre de vigilancia. Después la arrendó a unos viñadores y se fue al extranjero.","A su debido tiempo, envió a un servidor para percibir de los viñadores la parte de los frutos que le correspondía.","Pero ellos lo tomaron, lo golpearon y lo echaron con las manos vacías.","De nuevo les envió a otro servidor, y a este también lo maltrataron y lo llenaron de ultrajes.","Envió a un tercero, y a este lo mataron. Y también golpearon o mataron a muchos otros.","Todavía le quedaba alguien, su hijo, a quien quería mucho, y lo mandó en último término, pensando: \"Respetarán a mi hijo\".","Pero los viñadores se dijeron: \"Este es el heredero: vamos a matarlo y la herencia será nuestra\".","Y apoderándose de él, lo mataron y lo arrojaron fuera de la viña.","¿Qué hará el dueño de la viña? Vendrá, acabará con los viñadores y entregará la viña a otros.","¿No han leído este pasaje de la Escritura: \"La piedra que los constructores rechazaron ha llegado a ser la piedra angular:","esta es la obra del Señor, admirable a nuestros ojos\"?».","Entonces buscaban la manera de detener a Jesús, porque comprendían que esta parábola la había dicho por ellos, pero tenían miedo de la multitud. Y dejándolo, se fueron.","Le enviaron después a unos fariseos y herodianos para sorprenderlo en alguna de sus afirmaciones.","Ellos fueron y le dijeron: «Maestro, sabemos que eres sincero y no tienes en cuenta la condición de las personas, porque no te fijas en la categoría de nadie, sino que enseñas con toda fidelidad el camino de Dios. ¿Está permitido pagar el impuesto al César o no? ¿Debemos pagarla o no?».","Pero él, conociendo su hipocresía, les dijo: «¿Por qué me tienden una trampa? Muéstrenme un denario».","Cuando se lo mostraron, preguntó: «¿De quién es esta figura y esta inscripción?». Respondieron: «Del César».","Entonces Jesús les dijo: «Den al César lo que es del César, y a Dios, lo que es de Dios». Y ellos quedaron sorprendidos por la respuesta.","Se le acercaron unos saduceos, que son los que niegan la resurrección, y le propusieron este caos:","«Maestro, Moisés nos ha ordenado lo siguiente: «Si alguien está casado y muere sin tener hijos, que su hermano, para darle descendencia, se case con la viuda».","Ahora bien, había siete hermanos. El primero se casó y murió sin tener hijos.","El segundo se casó con la viuda y también murió sin tener hijos; lo mismo ocurrió con el tercero;","y así ninguno de los siete dejó descendencia. Después de todos ellos, murió la mujer.","Cuando resuciten los muertos, ¿de quién será esposa, ya que los siete la tuvieron por mujer?».","Jesús les dijo: «¿No será que ustedes están equivocados por no comprender las Escrituras ni el poder de Dios?","Cuando resuciten los muertos, ni los hombres ni las mujeres se casarán, sino que serán como ángeles en el cielo.","Y con respecto a la resurrección de los muertos, ¿no han leído en el Libro de Moisés, en el pasaje de la zarza, lo que Dios le dijo: Yo soy el Dios de Abraham, el Dios de Isaac y el Dios de Jacob?","El no es un Dios de muertos, sino de vivientes. Ustedes están en un grave error».","Un escriba que los oyó discutir, al ver que les había respondido bien, se acercó y le preguntó: «¿Cuál es el primero de los mandamientos?».","Jesús respondió: «El primero es: Escucha, Israel: el Señor nuestro Dios es el único Señor;","y tú amarás al Señor, tu Dios, con todo tu corazón y con toda tu alma, con todo tu espíritu y con todas tus fuerzas.","El segundo es: Amarás a tu prójimo como a ti mismo. No hay otro mandamiento más grande que estos».","El escriba le dijo: «Muy bien, Maestro, tienes razón al decir que hay un solo Dios y no hay otro más que él,","y que amarlo con todo el corazón, con toda la inteligencia y con todas las fuerzas, y amar al prójimo como a sí mismo, vale más que todos los holocaustos y todos los sacrificios».","Jesús, al ver que había respondido tan acertadamente, le dijo: «Tú no estás lejos del Reino de Dios». Y nadie se atrevió a hacerle más preguntas.","Jesús se puso a enseñar en el Templo y preguntaba: «¿Cómo pueden decir los escribas que el Mesías es hijo de David?","El mismo David ha dicho, movido por el Espíritu Santo: Dijo el Señor a mi Señor: Siéntate a mi derecha, hasta que ponga a tus enemigos debajo de tus pies.","Si el mismo David lo llama Señor, ¿Cómo puede ser hijo suyo? La multitud escuchaba a Jesús con agrado.","Y él les enseñaba: «Cuídense de los escribas, a quienes les gusta pasearse con largas vestiduras, ser saludados en las plazas","y ocupar los primeros asientos en las sinagogas y los banquetes;","que devoran los bienes de las viudas y fingen hacer largas oraciones. Estos serán juzgados con más severidad».","Jesús se sentó frente a la sala del tesoro del Templo y miraba cómo la gente depositaba su limosna. Muchos ricos daban en abundancia.","Llegó una viuda de condición humilde y colocó dos pequeñas monedas de cobre.","Entonces él llamó a sus discípulos y les dijo: «Les aseguro que esta pobre viuda ha puesto más que cualquiera de los otros,","porque todos han dado de lo que les sobraba, pero ella, de su indigencia, dio todo lo que poseía, todo lo que tenía para vivir»."],["Cuando Jesús salía del Templo, uno de sus discípulos le dijo: «¡Maestro, mira qué piedras enormes y qué construcción!».","Jesús le respondió: «¿Ves esa gran construcción? De todo esto no quedará piedra sobre piedra: todo será destruido».","Y después, estando sentado en el monto de los Olivos, frente al Templo, Pedro, Santiago, Juan y Andrés le preguntaron en privado:","«Dinos cuándo sucederá esto y cuál será la señal de que ya están por cumplirse todas estas cosas».","Entonces Jesús comenzó a decirles: «Tengan cuidado de que no los engañen,","porque muchos se presentarán en mi Nombre, diciendo: \"Soy yo\", y engañarán a mucha gente.","No se alarmen cuando oigan hablar de guerras y de rumores de guerras: es necesario que esto ocurra, pero todavía no será el fin.","Se levantará nación contra nación y reino contra reino. En muchas partes, habrá terremotos y hambre. Este será el comienzo de los dolores del parto.","Estén atentos: los entregarán a los tribunales y los azotarán en las sinagogas, y por mi causa serán llevados ante gobernadores y reyes, para dar testimonio delante de ellos.","Pero antes, la Buena Noticia será proclamada a todas las naciones.","Cuando los entreguen, no se preocupen por lo que van a decir: digan lo que se les enseñe en ese momento, porque no serán ustedes los que hablarán, sino el Espíritu Santo.","El hermano entregará a su hermano para que sea condenado a muerte, y el padre a su hijo; los hijos se rebelarán contra sus padres y los matarán.","Serán odiados por todos a causa de mi Nombre, pero el que persevere hasta el fin, se salvará.","Cuando vean la Abominación de la desolación usurpando el lugar que no le corresponde –el que lea esto, entiéndalo bien– los que estén en Judea, que se refugien en las montañas;","el que esté en la azotea de su casa, no baje a buscar sus cosas;","y el que esté en el campo, que no vuelva atrás a buscar su manto.","¡Ay de las mujeres que estén embarazadas o tengan niños de pecho en aquellos días!","Rueguen para que no suceda en invierno.","Porque habrá entonces una gran tribulación, como no la hubo desde el comienzo del mundo hasta ahora, ni la habrá jamás.","Y si el Señor no abreviara ese tiempo, nadie se salvaría; pero lo abreviará a causa de los elegidos.","Si alguien les dice entonces: \"El Mesías está aquí o está allí\", no lo crean.","Porque aparecerán falsos mesías y falsos profetas que harán milagros y prodigios capaces de engañar, si fuera posible, a los mismos elegidos.","Pero ustedes tengan cuidado: yo los he prevenido de todo.","En ese tiempo, después de esta tribulación, el sol se oscurecerá, la luna dejará de brillar,","las estrellas caerán del cielo y los astros se conmoverán.","Y se verá al Hijo del hombre venir sobre las nubes, lleno de poder y de gloria.","Y él enviará a los ángeles para que congreguen a sus elegidos desde los cuatro puntos cardinales, de un extremo al otro del horizonte.","Aprendan esta comparación, tomada de la higuera: cuando sus ramas se hacen flexibles y brotan las hojas, ustedes se dan cuenta de que se acerca el verano.","Así también, cuando vean que suceden todas estas cosas, sepan que el fin está cerca, a la puerta.","Les aseguro que no pasará esta generación, sin que suceda todo esto.","El cielo y la tierra pasarán, pero mis palabras no pasarán.","En cuanto a ese día y a la hora, nadie los conoce, ni los ángeles del cielo, ni el Hijo, nadie sino el Padre.»","«Tengan cuidado y estén prevenidos porque no saben cuándo llegará el momento.","Será como un hombre que se va de viaje, deja su casa al cuidado de sus servidores, asigna a cada uno su tarea, y recomienda al portero que permanezca en vela.","Estén prevenidos, entonces, porque no saben cuándo llegará el dueño de casa, si al atardecer, a medianoche, al canto del gallo o por la mañana.","No sea que llegue de improviso y los encuentre dormidos.","Y esto que les digo a ustedes, lo digo a todos: \"¡Estén prevenidos!\"»."],["Faltaban dos días para la fiesta de la Pascua y de los panes Acimos. Los sumos sacerdotes y los escribas buscaban la manera de arrestar a Jesús con astucia, para darle muerte.","Porque decían: «No lo hagamos durante la fiesta, para que no se produzca un tumulto en el pueblo».","Mientras Jesús estaba en Betania, comiendo en casa de Simón el leproso, llegó una mujer con un frasco lleno de un valioso perfume de nardo puro, y rompiendo el frasco, derramó el perfume sobre la cabeza de Jesús.","Entonces algunos de los que estaban allí se indignaron y comentaban entre sí: «¿Para qué este derroche de perfume?","Se hubiera podido vender por más de trescientos denarios para repartir el dinero entre los pobres». Y la criticaban.","Pero Jesús dijo: «Déjenla, ¿por qué la molestan? Ha hecho una buena obra conmigo.","A los pobres los tendrán siempre con ustedes y podrán hacerles bien cuando quieran, pero a mí no me tendrán siempre.","Ella hizo lo que podía; ungió mi cuerpo anticipadamente para la sepultura.","Les aseguro que allí donde se proclame la Buena Noticia, en todo el mundo, se contará también en su memoria lo que ella hizo».","Judas Iscariote, uno de los Doce, fue a ver a los sumos sacerdotes para entregarles a Jesús.","Al oírlo, ellos se alegraron y prometieron darle dinero. Y Judas buscaba una ocasión propicia para entregarlo.","El primer día de la fiesta de los panes Acimos, cuando se inmolaba la víctima pascual, los discípulos dijeron a Jesús: «¿Dónde quieres que vayamos a prepararte la comida pascual?».","El envió a dos de sus discípulos, diciéndoles: «Vayan a la ciudad; allí se encontrarán con un hombre que lleva un cántaro de agua. Síganlo,","y díganle al dueño de la casa donde entre: El Maestro dice: «¿Dónde está mi sala, en la que voy a comer el cordero pascual con mis discípulos?».","El les mostrará en el piso alto una pieza grande, arreglada con almohadones y ya dispuesta; prepárennos allí lo necesario».","Los discípulos partieron y, al llegar a la ciudad, encontraron todo como Jesús les había dicho y prepararon la Pascua.","Al atardecer, Jesús llegó con los Doce.","Y mientras estaban comiendo, dijo: «Les aseguro que uno de ustedes me entregará, uno que come conmigo».","Ellos se entristecieron y comenzaron a preguntarle, uno tras otro: «¿Seré yo?»","El les respondió: «Es uno de los Doce, uno que se sirve de la misma fuente que yo.","El Hijo del hombre se va, como está escrito de él, pero ¡ay de aquel por quien el Hijo del hombre será entregado: más le valdría no haber nacido!».","Mientras comían, Jesús tomo el pan, pronunció la bendición, lo partió y lo dio a sus discípulos, diciendo: «Tomen, esto es mi Cuerpo».","Después tomó una copa, dio gracias y se la entregó, y todos bebieron de ella.","Y les dijo: «Esta es mi Sangre, la Sangre de la Alianza, que se derrama por muchos.","Les aseguro que no beberá más del fruto de la vid hasta el día en que beba el vino nuevo en el Reino de Dios».","Después del canto de los Salmos, salieron hacia el monte de los Olivos.","Y Jesús les dijo: «Todos ustedes se van a escandalizar, porque dice la Escritura: Heriré al pastor y se dispersarán las ovejas.","Pero después que yo resucite, iré antes que ustedes a Galilea».","Pedro le dijo: «Aunque todos se escandalicen, o no me escandalizaré».","Jesús le respondió: «Te aseguro que hoy, esta misma noche, antes que cante el gallo por segunda vez, me habrás negado tres veces».","Pero él insistía: «Aunque tenga que morir contigo, jamás te negaré». Y todos decían lo mismo.","Llegaron a una propiedad llamada Getsemaní, y Jesús dijo a sus discípulos: «Quédense aquí, mientras yo voy a orar».","Después llevó con él a Pedro, Santiago y Juan, y comenzó a sentir temor y a angustiarse.","Entonces les dijo: «Mi alma siente una tristeza de muerte. Quédense aquí velando».","Y adelantándose un poco, se postró en tierra y rogaba que, de ser posible, no tuviera que pasar por esa hora.","Y decía: «Abba –Padre– todo te es posible: aleja de mí este cáliz, pero que no se haga mi voluntad, sino la tuya».","Después volvió y encontró a sus discípulos dormidos. Y Jesús dijo a Pedro: «Simón, ¿duermes? ¿No has podido quedarte despierto ni siquiera una hora?","Permanezcan despiertos y oren para no caer en la tentación, porque es espíritu está dispuesto, pero la carne es débil».","Luego se alejó nuevamente y oró, repitiendo las mismas palabras.","Al regresar, los encontró otra vez dormidos, porque sus ojos se cerraban de sueño, y no sabían qué responderle.","Volvió por tercera vez y les dijo: «Ahora pueden dormir y descansar. Esto se acabó. Ha llegado la hora en que el Hijo del hombre va a ser entregado en manos de los pecadores.","¡Levántense! ¡Vamos! Ya se acerca el que me va a entregar».","Jesús estaba hablando todavía, cuando se presentó Judas, uno de los Doce, acompañado de un grupo con espadas y palos, enviado por los sumos sacerdotes, los escribas y los ancianos.","El traidor les había dado esta señal: «Es aquel a quien voy a besar. Deténganlo y llévenlo bien custodiado».","Apenas llegó, se le acercó y le dijo: «Maestro», y lo besó.","Los otros se abalanzaron sobre él y lo arrestaron.","Uno de los que estaban allí sacó la espada e hirió al servidor del Sumo Sacerdote, cortándole la oreja.","Jesús les dijo: «Como si fuera un bandido, han salido a arrestarme con espadas y palos.","Todos los días estaba entre ustedes enseñando en el Templo y no me arrestaron. Pero esto sucede para que se cumplan las Escrituras».","Entonces todos lo abandonaron y huyeron.","Lo seguía un joven, envuelto solamente con una sábana, y lo sujetaron;","pero él, dejando la sábana, se escapó desnudo.","Llevaron a Jesús ante el Sumo Sacerdote, y allí se reunieron todos los sumos sacerdotes, los ancianos y los escribas.","Pedro lo había seguido de lejos hasta el interior del palacio del Sumo Sacerdote y estaba sentado con los servidores, calentándose junto al fuego.","Los sumos sacerdotes y todo el Sanedrín buscaban un testimonio contra Jesús, para poder condenarlo a muerte, pero no lo encontraban.","Porque se presentaron muchos con falsas acusaciones contra él, pero sus testimonios no concordaban.","Algunos declaraban falsamente contra Jesús:","«Nosotros lo hemos oído decir: \"Yo destruiré este Templo hecho por la mano del hombre, y en tres días volveré a construir otro que no será hecho por la mano del hombre\"».","Pero tampoco en esto concordaban sus declaraciones.","El Sumo Sacerdote, poniéndose de pie ante la asamblea, interrogó a Jesús: «¿No respondes nada a lo que estos atestiguan contra ti?».","El permanecía en silencio y no respondía nada. El Sumo Sacerdote lo interrogó nuevamente: «¿Eres el Mesías, el Hijo de Dios bendito?».","Jesús respondió: «Así, yo lo soy: y ustedes verán al Hijo del hombre sentarse a la derecha del Todopoderoso y venir entre las nubes del cielo».","Entonces el Sumo Sacerdote rasgó sus vestiduras y exclamó: «¿Qué necesidad tenemos ya de testigos?","Ustedes acaban de oír la blasfemia. ¿Qué les parece?». Y todos sentenciaron que merecía la muerte.","Después algunos comenzaron a escupirlo y, tapándole el rostro, lo golpeaban, mientras le decían: «¡Profetiza!». Y también los servidores le daban bofetadas.","Mientras Pedro estaba abajo, en el patio, llegó una de las sirvientas del Sumo Sacerdote","y, al ver a Pedro junto al fuego, lo miró fijamente y le dijo: «Tú también estabas con Jesús, el Nazareno».","El lo negó, diciendo: «No sé nada; no entiendo de qué estás hablando». Luego salió al vestíbulo.","La sirvienta, al verlo, volvió a decir a los presentes: «Este es uno de ellos».","Pero él lo negó nuevamente. Un poco más tarde, los que estaban allí dijeron a Pedro: «Seguro que eres uno de ellos, porque tú también eres galileo».","Entonces él se puso a maldecir y a jurar que no conocía a ese hombre del que estaban hablando.","En seguida cantó el gallo por segunda vez. Pedro recordó las palabras que Jesús le había dicho: «Antes que cante el gallo por segunda vez, tú me habrás negado tres veces». Y se puso a llorar."],["En cuanto amaneció, los sumos sacerdotes se reunieron en Consejo con los ancianos, los escribas y todo el Sanedrín. Y después de atar a Jesús, lo llevaron y lo entregaron a Pilato.","Este lo interrogó: «¿Tú eres el rey de los judíos?». Jesús le respondió: «Tú lo dices».","Los sumos sacerdotes multiplicaban las acusaciones contra él.","Pilato lo interrogó nuevamente: «¿No respondes nada? ¡Mira de todo lo que te acusan!».","Pero Jesús ya no respondió a nada más, y esto dejó muy admirado a Pilato.","En cada Fiesta, Pilato ponía en libertad a un preso, a elección del pueblo.","Había en la cárcel uno llamado Barrabás, arrestado con otros revoltosos que habían cometido un homicidio durante la sedición.","La multitud subió y comenzó a pedir el indulto acostumbrado.","Pilato les dijo: «¿Quieren que les ponga en libertad al rey de los judíos?».","El sabía, en efecto, que los sumos sacerdotes lo habían entregado por envidia.","Pero los sumos sacerdotes incitaron a la multitud a pedir la libertad de Barrabás.","Pilato continuó diciendo: «¿Qué debo hacer, entonces, con el que ustedes llaman rey de los judíos?».","Ellos gritaron de nuevo: «¡Crucifícalo!».","Pilato les dijo: ¿Qué mal ha hecho? Pero ellos gritaban cada vez más fuerte: ¡Crucifícalo!","Pilato, para contentar a la multitud, les puso en libertad a Barrabás; y a Jesús, después de haberlo hecho azotar, lo entregó para que fuera crucificado.","Los soldados lo llevaron dentro del palacio, al pretorio, y convocaron a toda la guardia.","lo vistieron con un manto de púrpura, hicieron una corona de espinas y se la colocaron.","Y comenzaron a saludarlo: «¡Salud, rey de los judíos!».","Y le golpeaban la cabeza con una caña, le escupían y, doblando la rodilla, le rendían homenaje.","Después de haberse burlado de él, le quitaron el manto de púrpura y le pusieron de nuevo sus vestiduras. Luego lo hicieron salir para crucificarlo.","Como pasaba por allí Simón de Cirene, padre de Alejandro y de Rufo, que regresaba del campo, lo obligaron a llevar la cruz de Jesús.","Y condujeron a Jesús a un lugar llamado Gólgota, que significa: «lugar del Cráneo».","Le ofrecieron vino mezclado con mirra, pero él no lo tomó.","Después lo crucificaron. Los soldados se repartieron sus vestiduras, sorteándolas para ver qué le tocaba a cada uno.","Ya mediaba la mañana cuando lo crucificaron.","La inscripción que indicaba la causa de su condena decía: «El rey de los judíos».","Con él crucificaron a dos ladrones, uno a su derecha y el otro a su izquierda.","(Y se cumplió la Escritura que dice: «Fue contado entre los malhechores»)","Los que pasaban lo insultaban, movían la cabeza y decían: ¡«Eh, tú, que destruyes el Templo y en tres días lo vuelves a edificar,","sálvate a ti mismo y baja de la cruz!».","De la misma manera, los sumos sacerdotes y los escribas se burlaban y decían entre sí: «¡Ha salvado a otros y no puede salvarse a sí mismo!","Es el Mesías, el rey de Israel, ¡que baje ahora de la cruz, para que veamos y creamos!». También lo insultaban los que habían sido crucificados con él.","Al mediodía, se oscureció toda la tierra hasta las tres de la tarde;","y a esa hora, Jesús exclamó en alta voz: «Eloi, Eloi, lamá sabactani», que significa: «Dios mío, Dios mío, ¿por qué me has abandonado?».","Algunos de los que se encontraban allí, al oírlo, dijeron: «Está llamando a Elías».","Uno corrió a mojar una esponja en vinagre y, poniéndola en la punta de una caña le dio de beber, diciendo: «Vamos a ver si Elías viene a bajarlo».","Entonces Jesús, dando un grito, expiró.","El velo del Templo se rasgó en dos, de arriba abajo.","Al verlo expirar así, el centurión que estaba frente a él, exclamó: «¡Verdaderamente, este hombre era Hijo de Dios!».","Había también allí algunas mujeres que miraban de lejos. Entre ellas estaban María Magdalena, María, la madre de Santiago el menor y de José, y Salomé,","que seguían a Jesús y lo habían servido cuando estaba en Galilea; y muchas otras que habían subido con él a Jerusalén.","Era día de Preparación, es decir, vísperas de sábado. Por eso, al atardecer,","José de Arimatea –miembro notable del Sanedrín, que también esperaba el Reino de Dios– tuvo la audacia de presentarse ante Pilato para pedirle el cuerpo de Jesús.","Pilato se asombró de que ya hubiera muerto; hizo llamar al centurión y le preguntó si hacía mucho que había muerto.","Informado por el centurión, entregó el cadáver a José.","Este compró una sábana, bajó el cuerpo de Jesús, lo envolvió en ella y lo depositó en un sepulcro cavado en la roca. Después hizo rodar una piedra a la entrada del sepulcro.","María Magdalena y María, la madre de José, miraban dónde lo habían puesto."],["Pasado el sábado, María Magdalena, María, la madre de Santiago, y Salomé compraron perfumes para ungir el cuerpo de Jesús.","A la madrugada del primer día de la semana, cuando salía el sol, fueron al sepulcro.","Y decían entre ellas: «¿Quién nos correrá la piedra de la entrada del sepulcro?»","Pero al mirar, vieron que la piedra había sido corrida; era una piedra muy grande.","Al entrar al sepulcro, vieron a un joven sentado a la derecha, vestido con una túnica blanca. Ellas quedaron sorprendidas.","pero él les dijo: «No teman. Ustedes buscan a Jesús de Nazaret, el Crucificado. Ha resucitado, no está aquí. Miren el lugar donde lo habían puesto.","Vayan ahora a decir a sus discípulos y a Pedro que él irá antes que ustedes a Galilea; allí lo verán, como él se lo había dicho».","Ellas salieron corriendo del sepulcro, porque estaban temblando y fuera de sí. Y no dijeron nada a nadie, porque tenían miedo.","Jesús, que había resucitado a la mañana del primer día de la semana, se apareció primero a María Magdalena, aquella de quien había echado siete demonios.","Ella fue a contarlo a los que siempre lo habían acompañado, que estaban afligidos y lloraban.","Cuando la oyeron decir que Jesús estaba vivo y que lo había visto, no le creyeron.","Después, se mostró con otro aspecto a dos de ellos, que iban caminando hacia un poblado.","Y ellos fueron a anunciarlo a los demás, pero tampoco les creyeron.","En seguida, se apareció a los Once, mientras estaban comiendo, y les reprochó su incredulidad y su obstinación porque no habían creído a quienes lo habían visto resucitado.","Entonces les dijo: «Vayan por todo el mundo, anuncien la Buena Noticia a toda la creación.","El que crea y se bautice, se salvará. El que no crea, se condenará.","Y estos prodigios acompañarán a los que crean: arrojarán a los demonios en mi Nombre y hablarán nuevas lenguas;","podrán tomar a las serpientes con sus manos, y si beben un veneno mortal no les hará ningún daño; impondrán las manos sobre los enfermos y los curarán».","Después de decirles esto, el Señor Jesús fue llevado al cielo y está sentado a la derecha de Dios.","Ellos fueron a predicar por todas partes, y el Señor los asistía y confirmaba su palabra con los milagros que la acompañaban."]],"lc":[["Muchos han tratado de relatar ordenadamente los acontecimientos que se cumplieron entre nosotros,","tal como nos fueron transmitidos por aquellos que han sido desde el comienzo testigos oculares y servidores de la Palabra.","Por eso, después de informarme cuidadosamente de todo desde los orígenes, yo también he decidido escribir para ti, excelentísimo Teófilo, un relato ordenado,","a fin de que conozcas bien la solidez de las enseñanzas que has recibido.","En tiempos de Herodes, rey de Judea, había un sacerdote llamado Zacarías, de la clase sacerdotal de Abías. Su mujer, llamada Isabel, era descendiente de Aarón.","Ambos eran justos a los ojos de Dios y seguían en forma irreprochable todos los mandamientos y preceptos del Señor.","Pero no tenían hijos, porque Isabel era estéril; y los dos eran de edad avanzada.","Un día en que su clase estaba de turno y Zacarías ejercía la función sacerdotal delante de Dios,","le tocó en suerte, según la costumbre litúrgica, entrar en el Santuario del Señor para quemar el incienso.","Toda la asamblea del pueblo permanecía afuera, en oración, mientras se ofrecía el incienso.","Entonces se le apareció el Angel del Señor, de pie, a la derecha del altar del incienso.","Al verlo, Zacarías quedó desconcertado y tuvo miedo.","Pero el Angel le dijo: «No temas, Zacarías; tu súplica ha sido escuchada. Isabel, tu esposa, te dará un hijo al que llamarás Juan.","El será para ti un motivo de gozo y de alegría, y muchos se alegrarán de su nacimiento,","porque será grande a los ojos del Señor. No beberá vino ni bebida alcohólica; estará lleno del Espíritu Santo desde el seno de su madre,","y hará que muchos israelitas vuelvan al Señor, su Dios.","Precederá al Señor con el espíritu y el poder de Elías, para reconciliar a los padres con sus hijos y atraer a los rebeldes a la sabiduría de los justos, preparando así al Señor un Pueblo bien dispuesto».","Pero Zacarías dijo al Angel: «¿Cómo puedo estar seguro de esto? Porque yo soy anciano y mi esposa es de edad avanzada».","El Angel le respondió: «Yo soy Gabriel, el que está delante de Dios, y he sido enviado para hablarte y anunciarte esta buena noticia.","Te quedarás mudo, sin poder hablar hasta el día en que sucedan estas cosas, por no haber creído en mis palabras, que se cumplirán a su debido tiempo».","Mientras tanto, el pueblo estaba esperando a Zacarías, extrañado de que permaneciera tanto tiempo en el Santuario.","Cuando salió, no podía hablarles, y todos comprendieron que había tenido alguna visión en el Santuario. El se expresaba por señas, porque había quedado mudo.","Al cumplirse el tiempo de su servicio en el Templo, regresó a su casa.","Poco después, su esposa Isabel concibió un hijo y permaneció oculta durante cinco meses.","Ella pensaba: «Esto es lo que el Señor ha hecho por mí, cuando decidió librarme de lo que me avergonzaba ante los hombres».","En el sexto mes, el ángel Gabriel fue enviado por Dios a una ciudad de Galilea, llamada Nazaret,","a una virgen que estaba comprometida con un hombre perteneciente a la familia de David, llamado José. El nombre de la virgen era María.","El Angel entró en su casa y la saludó, diciendo: «¡Alégrate!, llena de gracia, el Señor está contigo».","Al oír estas palabras, ella quedó desconcertada y se preguntaba qué podía significar ese saludo.","Pero el Angel le dijo: «No temas, María, porque Dios te ha favorecido.","Concebirás y darás a luz un hijo, y le pondrás por nombre Jesús;","él será grande y será llamado Hijo del Altísimo. El Señor Dios le dará el trono de David, su padre,","reinará sobre la casa de Jacob para siempre y su reino no tendrá fin».","María dijo al Angel: «¿Cómo puede ser eso, si yo no tengo relaciones con ningún hombre?».","El Angel le respondió: «El Espíritu Santo descenderá sobre ti y el poder del Altísimo te cubrirá con su sombra. Por eso el niño será Santo y será llamado Hijo de Dios.","También tu parienta Isabel concibió un hijo a pesar de su vejez, y la que era considerada estéril, ya se encuentra en su sexto mes,","porque no hay nada imposible para Dios».","María dijo entonces: «Yo soy la servidora del Señor, que se cumpla en mí lo que has dicho».Y el Angel se alejó.","En aquellos días, María partió y fue sin demora a un pueblo de la montaña de Judá.","Entró en la casa de Zacarías y saludó a Isabel.","Apenas esta oyó el saludo de María, el niño saltó de alegría en su seno, e Isabel, llena del Espíritu Santo,","exclamó: «¡Tú eres bendita entre todas las mujeres y bendito es el fruto de tu vientre!","¿Quién soy yo, para que la madre de mi Señor venga a visitarme?","Apenas oí tu saludo, el niño saltó de alegría en mi seno.","Feliz de ti por haber creído que se cumplirá lo que te fue anunciado de parte del Señor».","María dijo entonces: «Mi alma canta la grandeza del Señor,","y mi espíritu se estremece de gozo en Dios, mi salvador,","porque el miró con bondad la pequeñez de tu servidora. En adelante todas las generaciones me llamarán feliz,","porque el Todopoderoso he hecho en mí grandes cosas: ¡su Nombre es santo!","Su misericordia se extiende de generación en generación sobre aquellos que lo temen.","Desplegó la fuerza de su brazo, dispersó a los soberbios de corazón.","Derribó a los poderosos de su trono y elevó a los humildes.","Colmó de bienes a los hambrientos y despidió a los ricos con las manos vacías.","Socorrió a Israel, su servidor, acordándose de su misericordia,","como lo había prometido a nuestros padres, en favor de Abraham y de su descendencia para siempre».","María permaneció con Isabel unos tres meses y luego regresó a su casa.","Cuando llegó el tiempo en que Isabel debía ser madre, dio a luz un hijo.","Al enterarse sus vecinos y parientes de la gran misericordia con que Dios la había tratado, se alegraban con ella.","A los ocho días, se reunieron para circuncidar al niño, y querían llamarlo Zacarías, como su padre;","pero la madre dijo: «No, debe llamarse Juan».","Ellos le decían: «No hay nadie en tu familia que lleve ese nombre».","Entonces preguntaron por señas al padre qué nombre quería que le pusieran.","Este pidió una pizarra y escribió: «Su nombre es Juan». Todos quedaron admirados. ]","Y en ese mismo momento, Zacarías recuperó el habla y comenzó a alabar a Dios.","Este acontecimiento produjo una gran impresión entre la gente de los alrededores, y se lo comentaba en toda la región montañosa de Judea.","Todos los que se enteraron guardaban este recuerdo en su corazón y se decían: «¿Qué llegará a ser este niño?». Porque la mano del Señor estaba con él.","Entonces Zacarías, su padre, quedó lleno del Espíritu Santo y dijo proféticamente:","«Bendito sea el Señor, el Dios de Israel, porque ha visitado y redimido a su Pueblo,","y nos ha dado un poderoso Salvador en la casa de David, su servidor,","como lo había anunciado mucho tiempo antes, por boca de sus santos profetas,","para salvarnos de nuestros enemigos y de las manos de todos los que nos odian.","Así tuvo misericordia de nuestros padres y se acordó de su santa Alianza,","del juramento que hizo a nuestro padre Abraham","de concedernos que, libres de temor, arrancados de las manos de nuestros enemigos,","lo sirvamos en santidad y justicia, bajo su mirada, durante toda nuestra vida.","Y tú, niño, serás llamado Profeta del Altísimo, porque irás delante del Señor preparando sus caminos,","para hacer conocer a su Pueblo la salvación mediante el perdón de los pecados;","gracias a la misericordiosa ternura de nuestro Dios, que nos traerá del cielo la visita del Sol naciente,","para iluminar a los que están en las tinieblas y en la sombra de la muerte, y guiar nuestros pasos por el camino de la paz».","El niño iba creciendo y se fortalecía en su espíritu; y vivió en lugares desiertos hasta el día en que se manifestó a Israel."],["En aquella época apareció un decreto del emperador Augusto, ordenando que se realizara un censo en todo el mundo.","Este primer censo tuvo lugar cuando Quirino gobernaba la Siria.","Y cada uno iba a inscribirse a su ciudad de origen.","José, que pertenecía a la familia de David, salió de Nazaret, ciudad de Galilea, y se dirigió a Belén de Judea, la ciudad de David,","para inscribirse con María, su esposa, que estaba embarazada.","Mientras se encontraban en Belén, le llegó el tiempo de ser madre;","y María dio a luz a su Hijo primogénito, lo envolvió en pañales y lo acostó en un pesebre, porque no había lugar para ellos en el albergue.","En esa región acampaban unos pastores, que vigilaban por turno sus rebaños durante la noche.","De pronto, se les apareció el Angel del Señor y la gloria del Señor los envolvió con su luz. Ellos sintieron un gran temor,","pero el Angel les dijo: «No teman, porque les traigo una buena noticia, una gran alegría para todo el pueblo:","Hoy, en la ciudad de David, les ha nacido un Salvador, que es el Mesías, el Señor.","Y esto les servirá de señal: encontrarán a un niño recién nacido envuelto en pañales y acostado en un pesebre».","Y junto con el Angel, apareció de pronto una multitud del ejército celestial, que alababa a Dios, diciendo:","¡Gloria a Dios en las alturas, y en la tierra, paz a los hombres amados por él».","Después que los ángeles volvieron al cielo, los pastores se decían unos a otros: «Vayamos a Belén, y veamos lo que ha sucedido y que el Señor nos ha anunciado».","Fueron rápidamente y encontraron a María, a José, y al recién nacido acostado en el pesebre.","Al verlo, contaron lo que habían oído decir sobre este niño,","y todos los que los escuchaban quedaron admirados de que decían los pastores.","Mientras tanto, María conservaba estas cosas y las meditaba en su corazón.","Y los pastores volvieron, alabando y glorificando a Dios por todo lo que habían visto y oído, conforme al anuncio que habían recibido.","Ocho días después, llegó el tiempo de circuncidar al niño y se le puso el nombre de Jesús, nombre que le había sido dado por el Angel antes de su concepción.","Cuando llegó el día fijado por la Ley de Moisés para la purificación, llevaron al niño a Jerusalén para presentarlo al Señor,","como está escrito en la Ley: \"Todo varón primogénito será consagrado al Señor\".","También debían ofrecer un sacrificio un par de tórtolas o de pichones de paloma, como ordena la Ley del Señor.","Vivía entonces en Jerusalén un hombre llamado Simeón, que era justo y piadoso, y esperaba el consuelo de Israel. El Espíritu Santo estaba en él","y le había revelado que no moriría antes de ver al Mesías del Señor.","Conducido por el mismo Espíritu, fue al Templo, y cuando los padres de Jesús llevaron al niño para cumplir con él las prescripciones de la Ley,","Angel lo tomó en sus brazos y alabó a Dios, diciendo:","«Ahora, Señor, puedes dejar que tu servidor muera en paz, como lo has prometido,","porque mis ojos han visto la salvación","que preparaste delante de todos los pueblos:","luz para iluminar a las naciones paganas y gloria de tu pueblo Israel».","Su padre y su madre estaban admirados por lo que oían decir de él.","Simeón, después de bendecirlos, dijo a María, la madre: «Este niño será causa de caída y de elevación para muchos en Israel; será signo de contradicción,","y a ti misma una espada te atravesará el corazón. Así se manifestarán claramente los pensamientos íntimos de muchos».","Había también allí una profetisa llamada Ana, hija de Fanuel, de la familia de Aser, mujer ya entrada en años, que, casa en su juventud, había vivido siete años con su marido.","Desde entonces había permanecido viuda, y tenía ochenta y cuatro años. No se apartaba del Templo, sirviendo a Dios noche y día con ayunos y oraciones.","Se presentó en ese mismo momento y se puso a dar gracias a Dios. Y hablaba acerca del niño a todos los que esperaban la redención de Jerusalén.","Después de cumplir todo lo que ordenaba la Ley del Señor, volvieron a su ciudad de Nazaret, en Galilea.","El niño iba creciendo y se fortalecía, lleno de sabiduría, y la gracia de Dios estaba con él.","Sus padres iban todos los años a Jerusalén en la fiesta de la Pascua.","Cuando el niño cumplió doce años, subieron como de costumbre,","y acababa la fiesta, María y José regresaron, pero Jesús permaneció en Jerusalén sin que ellos se dieran cuenta.","Creyendo que estaba en la caravana, caminaron todo un día y después comenzaron a buscarlo entre los parientes y conocidos.","Como no lo encontraron, volvieron a Jerusalén en busca de él.","Al tercer día, lo hallaron en el Templo en medio de los doctores de la Ley, escuchándolos y haciéndoles preguntas.","Y todos los que los oían estaban asombrados de su inteligencia y sus respuestas.","Al ver, sus padres quedaron maravillados y su madre le dijo: «Hijo mío, ¿por qué nos has hecho esto? Piensa que tu padre y yo te buscábamos angustiados».","Jesús les respondió: «¿Por qué me buscaban? ¿No sabían que yo debo ocuparme de los asuntos de mi Padre?».","Ellos no entendieron lo que les decía.","El regresó con sus padres a Nazaret y vivía sujeto a ellos. Su madre conservaba estas cosas en su corazón.","Jesús iba creciendo en sabiduría, en estatura y en gracia, delante de Dios y de los hombres."],["El año decimoquinto del reinado del emperador Tiberio, cuando Poncio Pilato gobernaba la Judea, siendo Herodes tetrarca de Galilea, su hermano Felipe tetrarca de Iturea y Traconítide, y Lisanias tetrarca de Abilene,","bajo el pontificado de Anás y Caifás, Dios dirigió su palabra a Juan, hijo de Zacarías, que estaba en el desierto.","Este comenzó entonces a recorrer toda la región del río Jordán, anunciando un bautismo de conversión para el perdón de los pecados,","como está escrito en el libro del profeta Isaías: \"Una voz grita en desierto: Preparen el camino del Señor, allanen sus senderos.","Los valles serán rellenados, las montañas y las colinas serán aplanadas. Serán enderezados los senderos sinuosos y nivelados los caminos desparejos.","Entonces, todos los hombres verán la Salvación de Dios.\"","Juan decía a la multitud que venía a hacerse bautizar por él: «Raza de víboras, ¿quién les enseñó a escapar de la ira de Dios que se acerca?","Produzcan los frutos de una sincera conversión, y no piensen: «Tenemos por padre a Abraham». Porque yo les digo que de estas piedras Dios puede hacer surgir hijo de Abraham.","El hacha ya está puesta a la raíz de los árboles; el árbol que no produce buen fruto será cortado y arrojado al fuego».","La gente le preguntaba: «¿Qué debemos hacer entonces?».","El les respondía: «El que tenga dos túnicas, dé una al que no tiene; y el que tenga qué comer, haga otro tanto».","Algunos publicanos vinieron también a hacer bautizar y le preguntaron: «Maestro, ¿qué debemos hacer?».","El les respondió: «No exijan más de lo estipulado».","A su vez, unos soldados le preguntaron: «Y nosotros, ¿qué debemos hacer?». Juan les respondió: «No extorsionen a nadie, no hagan falsas denuncias y conténtense con su sueldo».","Como el pueblo estaba a la expectativa y todos se preguntaban si Juan no sería el Mesías,","él tomó la palabra y les dijo: «Yo los bautizo con agua, pero viene uno que es más poderoso que yo, y yo ni siquiera soy digno de desatar la correa de sus sandalias; él los bautizará en el Espíritu Santo y en el fuego.","Tiene en su mano la horquilla para limpiar su era y recoger el trigo en su granero. Pero consumirá la paja en el fuego inextinguible»","Y por medio de muchas otras exhortaciones, anunciaba al pueblo la Buena Noticia.","Mientras tanto el tetrarca Herodes, a quien Juan censuraba a causa de Herodías – la mujer de su hermano– y por todos los delitos que había cometido,","cometió uno más haciendo encarcelar a Juan.","Todo el pueblo se hacía bautizar, y también fue bautizado Jesús. Y mientras estaba orando, se abrió el cielo.","y el Espíritu Santo descendió sobre él en forma corporal, como una paloma. Se oyó entonces una voz del cielo: «Tú eres mi Hijo muy querido, en quien tengo puesta toda mi predilección».","Cuando comenzó su ministerio, Jesús tenía unos treinta años y se lo consideraba hijo de José. José era hijo de Elí;","Elí, hijo de Matat; Mata, hijo de Leví; Leví, hijo de Melquí; Melquí, hijo de Janai; Janai, hijo de José;","José, hijo de Matatías; Matatías, hijo de Amós; Amós, hijo de Naúm; Naúm, hijo de Eslí; Eslí, hijo de Nagai;","Nagai, hijo de Maat; Maat, hijo de Matatías; Matatías, hijo de Semein; Semein, hijo de Iosec; Iosec, hijo de Iodá;","Iodá, hijo de Joanán; Joanán, hijo de Resá; Resá, hijo de Zorobabel. Zorobabel era hijo de Salatiel; Salatiel, hijo de Nerí;","Nerí, hijo de Melquí; Melquí, hijo de Adí; Adí, hijo de Cosam; Cosam, hijo de Elmadam; Elmadam, hijo de Er;","Er, hijo de Jesús; Jesús, hijo de Eliezer; Eliezer, hijo de Jorím; Jorím, hijo de Matat; Matat, hijo de Leví;","Leví, hijo de Angel; Angel, hijo de Judá; Judá, hijo de José; José, hijo de Jonam; Jonam, hijo de Eliaquim;","Eliaquim, hijo de Meleá; Meleá, hijo de Mená; Mená, hijo de Matatá; Matatá, hijo de Natán; Natán, hijo de David.","David era hijo de Jesé; Jesé, hijo de Jobed; Jobed, hijo de Booz; Booz, hijo de Sela; Sela hijo de Naasón;","Naasón, hijo de Aminadab; Aminadab, hijo de Admín; Admín, hijo de Arní; Arní, hijo de Esrom; Esrom, hijo de Fares; Fares, hijo de Judá;","Judá, hijo de Jacob; Jacob, hijo de Isaac; Isaac, hijo de Abraham. Abraham era hijo de Tera; Tera, hijo de Najor;","Najor, hijo de Serúj; Serúj, hijo de Ragau; Ragau, hijo de Péleg; Péleg, hijo de Eber; Eber, hijo de Sela;","Sela, hijo de Cainán; Cainán, hijo de Arfaxad; Arfaxad, hijo de Sem. Sem era hijo de Noé; Noé, hijo de Lamec;","Lamec, hijo de Matusalén; Matusalén, hijo de Henoc; Henoc, hijo de Jaret; Jaret, hijo de Malaleel; Malaleel, hijo de Cainán;","Cainán, hijo de Enós; Enós, hijo de Set; Set, hijo de Adán; Adán, hijo de Dios."],["Jesús, lleno del Espíritu Santo, regresó de las orillas del Jordán y fue conducido por el Espíritu al desierto,","donde fue tentado por el demonio durante cuarenta días. No comió nada durante esos días, y al cabo de ellos tuvo hambre.","El demonio le dijo entonces: «Si tú eres Hijo de Dios, manda a esta piedra que se convierta en pan».","Pero Jesús le respondió: «Dice la Escritura: \"El hombre no vive solamente de pan\"».","Luego el demonio lo llevó a un lugar más alto, le mostró en un instante todos los reinos de la tierra","y le dijo: «Te daré todo este poder y esplendor de estos reinos, porque me han sido entregados, y yo los doy a quien quiero.","Si tú te postras delante de mí, todo eso te pertenecerá».","Pero Jesús le respondió: «Está escrito: \"Adorarás al Señor, tu Dios, y a él solo rendirás culto\"».","Después el demonio lo condujo a Jerusalén, lo puso en la parte más alta del Templo y le dijo: «Si tú eres Hijo de Dios, tírate de aquí abajo,","porque está escrito: \"El dará órdenes a sus ángeles para que ellos te cuiden\".","Y también: \"Ellos te llevarán en sus manos para que tu pie no tropiece con ninguna piedra\"».","Pero Jesús le respondió: «Está escrito: \"No tentarás al Señor, tu Dios\"».","Una vez agotadas todas las formas de tentación, el demonio se alejó de él, hasta el momento oportuno.","Jesús volvió a Galilea con el poder el Espíritu y su fama se extendió en toda la región.","Enseñaba en las sinagogas y todos lo alababan.","Jesús fue a Nazaret, donde se había criado; el sábado entró como de costumbre en la sinagoga y se levantó para hacer la lectura.","Le presentaron el libro del profeta Isaías y, abriéndolo, encontró el pasaje donde estaba escrito:","\"El Espíritu del Señor está sobre mí, porque me ha consagrado por la unción. El me envió a llevar la Buena Noticia a los pobres, a anunciar la liberación a los cautivos y la vista a los ciegos, a dar la libertad a los oprimidos","y proclamar un año de gracia del Señor\".","Jesús cerró el Libro, lo devolvió al ayudante y se sentó. Todos en la sinagoga tenían los ojos fijos en él.","Entonces comenzó a decirles: «Hoy se ha cumplido este pasaje de la Escritura que acaban de oír».","Todos daban testimonio a favor de él y estaban llenos de admiración por las palabras de gracia que salían de su boca. Y decían: «¿No es este el hijo de José?».","Pero él les respondió: «Sin duda ustedes me citarán el refrán: \"Médico, cúrate a ti mismo\". Realiza también aquí, en tu patria, todo lo que hemos oído que sucedió en Cafarnaúm».","Después agregó: «Les aseguro que ningún profeta es bien recibido en su tierra.","Yo les aseguro que había muchas viudas en Israel en el tiempo de Elías, cuando durante tres años y seis meses no hubo lluvia del cielo y el hambre azotó a todo el país.","Sin embargo, a ninguna de ellas fue enviado Elías, sino a una viuda de Sarepta, en el país de Sidón.","También había muchos leprosos en Israel, en el tiempo del profeta Eliseo, pero ninguno de ellos fue curado, sino Naamán, el sirio».","Al oír estas palabras, todos los que estaban en la sinagoga se enfurecieron","y, levantándose, lo empujaron fuera de la ciudad, hasta un lugar escarpado de la colina sobre la que se levantaba la ciudad, con intención de despeñarlo.","Pero Jesús, pasando en medio de ellos, continuó su camino.","Jesús bajó a Cafarnaúm, ciudad de Galilea, y enseñaba los sábados.","Y todos estaban asombrados de su enseñanza, porque hablaba con autoridad.","En la sinagoga había un hombre que estaba poseído por el espíritu de un demonio impuro; y comenzó a gritar con fuerza;","«¿Qué quieres de nosotros, Jesús Nazareno? ¿Has venido para acabar con nosotros? Ya sé quién eres: el Santo de Dios».","Pero Jesús lo increpó, diciendo: «Cállate y sal de este hombre». El demonio salió de él, arrojándolo al suelo en medio de todos. sin hacerle ningún daño.","El temor se apoderó de todos, y se decían unos a otros: «¿Qué tiene su palabra? ¡Manda con autoridad y poder a los espíritus impuros, y ellos salen!».","Y su fama se extendía por todas partes en aquella región.","Al salir de la sinagoga, entró en la casa de Simón. La suegra de Simón tenía mucha fiebre, y le pidieron que hiciera algo por ella.","Inclinándose sobre ella, Jesús increpó a la fiebre y esta desapareció. En seguida, ella se levantó y se puso a servirlos.","Al atardecer, todos los que tenían enfermos afectados de diversas dolencias se los llevaron, y él, imponiendo las manos sobre cada uno de ellos, los curaba.","De muchos salían demonios, gritando: «Tú eres el Hijo de Dios!». Pero él los increpaba y no los dejaba hablar, porque ellos sabían que era el Mesías.","Cuando amaneció, Jesús salió y se fue a un lugar desierto. La multitud comenzó a buscarlo y, cuando lo encontraron, querían retenerlo para que no se alejara de ellos.","Pero él les dijo: «También a las otras ciudades debo anunciar la Buena Noticia del Reino de Dios, porque para eso he sido enviado».","Y predicaba en las sinagogas de toda la Judea."],["En una oportunidad, la multitud se amontonaba alrededor de Jesús para escuchar la Palabra de Dios, y él estaba de pie a la orilla del lago de Genesaret.","Desde allí vio dos barcas junto a la orilla del lago; los pescadores habían bajado y estaban limpiando las redes.","Jesús subió a una de las barcas, que era de Simón, y le pidió que se apartara un poco de la orilla; después se sentó, y enseñaba a la multitud desde la barca.","Cuando terminó de hablar, dijo a Simón: «Navega mar adentro, y echen las redes».","Simón le respondió: «Maestro, hemos trabajado la noche entera y no hemos sacado nada, pero si tú lo dices, echaré las redes».","Así lo hicieron, y sacaron tal cantidad de peces, que las redes estaban a punto de romperse.","Entonces hicieron señas a los compañeros de la otra barca para que fueran a ayudarlos. Ellos acudieron, y llenaron tanto las dos barcas, que casi se hundían.","Al ver esto, Simón Pedro se echó a los pies de Jesús y le dijo: «Aléjate de mí, Señor, porque soy un pecador».","El temor se había apoderado de él y de los que lo acompañaban, por la cantidad de peces que habían recogido;","y lo mismo les pasaba a Santiago y a Juan, hijos de Zebedeo, compañeros de Simón. Pero Jesús dijo a Simón: «No temas, de ahora en adelante serás pescador de hombres».","Ellos atracaron las barcas a la orilla y, abandonándolo todo, lo siguieron.","Mientras Jesús estaba en una ciudad, se presentó un hombre cubierto de lepra. Al ver a Jesús, se postró ante él y le rogó: «Señor, si quieres, puedes purificarme».","Jesús extendió la mano y lo tocó, diciendo: «Lo quiero, queda purificado». Y al instante la lepra desapareció.","El le ordenó que no se lo dijera a nadie, pero añadió: «Ve a presentarte al sacerdote y entrega por tu purificación la ofrenda que ordenó Moisés, para que les sirva de testimonio».","Su fama se extendía cada vez más y acudían grandes multitudes para escucharlo y hacerse curar de sus enfermedades.","Pero él se retiraba a lugares desiertos para orar.","Un día, mientras Jesús enseñaba, había entre los presente algunos fariseos y doctores de la Ley, llegados de todas las regiones de Galilea, de Judea y de Jerusalén. La fuerza del Señor le daba poder para curar.","Llegaron entonces unas personas transportando a un paralítico sobre una camilla y buscaban el modo de entrar, para llevarlo ante Jesús.","Como no sabían por dónde introducirlo a causa de la multitud, subieron a la terraza y, desde el techo, lo bajaron con su camilla en medio de la concurrencia y lo pusieron delante de Jesús.","Al ver su fe, Jesús le dijo: «Hombre, tus pecados te son perdonados».","Los escribas y los fariseos comenzaron a preguntarse: «¿Quién es este que blasfema? ¿Quién puede perdonar los pecados, sino sólo Dios?».","Pero Jesús, conociendo sus pensamientos, les dijo: «¿Qué es lo que están pensando?","¿Qué es más fácil decir: \"Tus pecados están perdonados\", o \"Levántate y camina\"?","Para que ustedes sepan que el Hijo del hombre tiene sobre la tierra el poder de perdonar los pecados –dijo al paralítico– yo te lo mando, levántate, toma tu camilla y vuelve a tu casa».","Inmediatamente se levantó a la vista de todos, tomó su camilla y se fue a su casa alabando a Dios.","Todos quedaron llenos de asombro y glorificaban a Dios, diciendo con gran temor: «Hoy hemos visto cosas maravillosas».","Después Jesús salió y vio a un publicano llamado Leví, que estaba sentado junto a la mesa de recaudación de impuestos, y le dijo: «Sígueme».","El, dejándolo todo, se levantó y lo siguió.","Leví ofreció a Jesús un gran banquete en su casa. Había numerosos publicanos y otras personas que estaban a la mesa con ellos.","Los fariseos y los escribas murmuraban y decían a los discípulos de Jesús: «¿Por qué ustedes comen y beben con publicanos y pecadores?».","Pero Jesús tomó la palabra y les dijo: «No son los sanos que tienen necesidad del médico, sino los enfermos.","Yo no he venido a llamar a los justos, sino a los pecadores, para que se conviertan».","Luego le dijeron: «Los discípulos de Juan ayunan frecuentemente y hacen oración, lo mismo que los discípulos de los fariseos; en cambio, los tuyos comen y beben».","Jesús les contestó: «¿Ustedes pretenden hacer ayunar a los amigos del esposo mientras él está con ellos?","Llegará el momento en que el esposo les será quitado; entonces tendrán que ayunar».","Les hizo además esta comparación: «Nadie corta un pedazo de un vestido nuevo para remendar uno viejo, porque se romperá el nuevo, y el pedazo sacado a este no quedará bien en el vestido viejo.","Tampoco se pone vino en odres viejos, porque hará reventar los odres; entonces el vino se derramará y los odres ya no servirán más.","¡A vino nuevo, odres nuevos!","Nadie, después de haber gustado el vino viejo, quiere vino nuevo, porque dice: El añejo es mejor»."],["Un sábado, en que Jesús atravesaba unos sembrados, sus discípulos arrancaban espigas y, frotándolas entre las manos, las comían.","Algunos fariseos les dijeron: «¿Por qué ustedes hacen lo que no está permitido en sábado?».","Jesús les respondió: «¿Ni siquiera han leído lo que hizo David cuando él y sus compañeros tuvieron hambre,","cómo entró en la Casa de Dios y, tomando los panes de la ofrenda, que sólo pueden comer los sacerdotes, comió él y dio de comer a sus compañeros?».","Después les dijo: «El hijo del hombre es dueño del sábado».","Otro sábado, entró en la sinagoga y comenzó a enseñar. Había allí un hombre que tenía la mano derecha paralizada.","Los escribas y los fariseos observaban atentamente a Jesús para ver si curaba en sábado, porque querían encontrar algo de qué acusarlo.","Pero Jesús, conociendo sus intenciones, dijo al hombre que tenía la mano paralizada: «Levántate y quédate de pie delante de todos». El se levantó y permaneció de pie.","Luego les dijo: «Yo les pregunto: ¿Está permitido en sábado, hacer el bien o el mal, salvar una vida o perderla?».","Y dirigiendo una mirada a todos, dijo al hombre: «Extiende tu mano». El la extendió y su mano quedó curada.","Pero ellos se enfurecieron, y deliberaban entre sí para ver qué podían hacer contra Jesús.","En esos días, Jesús se retiró a una montaña para orar, y pasó toda la noche en oración con Dios.","Cuando se hizo de día, llamó a sus discípulos y eligió a doce de ellos, a los que dio el nombre de Apóstoles:","Simón, a quien puso el sobrenombre de Pedro, Andrés, su hermano, Santiago, Juan, Felipe, Bartolomé,","Mateo, Tomás, Santiago, hijo de Alfeo, Simón, llamado el Zelote,","Judas, hijo de Santiago y Judas Iscariote, que fue el traidor.","Al bajar con ellos se detuvo en una llanura. Estaban allí muchos de sus discípulos y una gran muchedumbre que había llegado de toda la Judea, de Jerusalén y de la región costera de Tiro y Sidón,","para escucharlo y hacerse curar de sus enfermedades. Los que estaban atormentados por espíritus impuros quedaban curados;","y toda la gente quería tocarlo, porque salía de él una fuerza que sanaba a todos.","Entonces Jesús, fijando la mirada en sus discípulos, dijo: «¡Felices ustedes, los pobres, porque el Reino de Dios les pertenece!","¡Felices ustedes, los que ahora tienen hambre, porque serán saciados! ¡Felices ustedes, los que ahora lloran, porque reirán!","¡Felices ustedes, cuando los hombres los odien, los excluyan, los insulten y los proscriban, considerándolos infames y los proscriban, considerándolos infames a causa del Hijo del hombre!","¡Alégrense y llénense de gozo en ese día, porque la recompensa de ustedes será grande en el cielo. De la misma manera los padres de ellos trataban a los profetas!","Pero ¡ay de ustedes los ricos, porque ya tienen su consuelo!","¡Ay de ustedes, los que ahora están satisfechos, porque tendrán hambre! ¡Ay de ustedes, los que ahora ríen, porque conocerán la aflicción y las lágrimas!","¡Ay de ustedes cuando todos los elogien! ¡De la misma manera los padres de ellos traban a los falsos profetas!","Pero yo les digo a ustedes que me escuchan: Amen a sus enemigos, hagan el bien a los que los odian.","Bendigan a los que los maldicen, rueguen por lo que los difaman.","Al que te pegue en una mejilla, preséntale también la otra; al que te quite el manto, no le niegues la túnica.","Dale a todo el que te pida, y al que tome lo tuyo no se lo reclames.","Hagan por lo demás lo que quieren que los hombres hagan por ustedes.","Si aman a aquellos que los aman, ¿qué mérito tienen? Porque hasta los pecadores aman a aquellos que los aman.","Si hacen el bien a aquellos que se lo hacen a ustedes, ¿qué mérito tienen? Eso lo hacen también los pecadores.","Y si prestan a aquellos de quienes esperan recibir, ¿qué mérito tienen? También los pecadores prestan a los pecadores, para recibir de ellos lo mismo.","Amen a sus enemigos, hagan el bien y presten sin esperar nada en cambio. Entonces la recompensa de ustedes será grande y serán hijos del Altísimo, porque él es bueno con los desagradecidos y los malos.","Sean misericordiosos, como el Padre de ustedes es misericordioso.","No juzguen y no serán juzgados; no condenen y no serán condenados; perdonen y serán perdonados.","Den, y se les dará. Les volcarán sobre el regazo una buena medida, apretada, sacudida y desbordante. Porque la medida con que ustedes midan también se usará para ustedes».","Les hizo también esta comparación: «¿Puede un ciego guiar a otro ciego? ¿No caerán los dos en un pozo?","El discípulo no es superior al maestro; cuando el discípulo llegue a ser perfecto, será como su maestro.","¿Por qué miras la paja que hay en el ojo de tu hermano y no ves la viga que está en el tuyo?","¿Cómo puedes decir a tu hermano: «Hermano, deja que te saque la paja de tu ojo», tú, que no ves la viga que tienes en el tuyo? ¡Hipócrita, saca primero la viga de tu ojo, y entonces verás claro para sacar la paja del ojo de tu hermano.","No hay árbol bueno que dé frutos malos, ni árbol malo que dé frutos buenos:","cada árbol se reconoce por su fruto. No se recogen higos de los espinos ni se cosechan uvas de las zarzas.","El hombre bueno saca el bien del tesoro de bondad que tiene en su corazón. El malo saca el mal de maldad, porque de la abundancia del corazón habla la boca.","¿Por qué ustedes me llaman: \"Señor, Señor\", y no hacen lo que les digo?","Yo les diré a quién se parece todo aquel que viene a mí, escucha mis palabras y las practica.","Se parece a un hombre que, queriendo construir una casa, cavó profundamente y puso los cimientos sobre la roca. Cuando vino la creciente, las aguas se precipitaron con fuerza contra esa casa, pero no pudieron derribarla, porque estaba bien construida.","En cambio, el que escucha la Palabra y no la pone en práctica, se parece a un hombre que construyó su casa sobre tierra, sin cimientos. Cuando las aguas se precipitaron contra ella, en seguida se derrumbó, y el desastre que sobrevino a esa casa fue grande»."],["Cuando Jesús terminó de decir todas estas cosas al pueblo, entró en Cafarnaúm.","Había allí un centurión que tenía un sirviente enfermo, a punto de morir, al que estimaba mucho.","Como había oído hablar de Jesús, envió a unos ancianos judíos para rogarle que viniera a curar a su servidor.","Cuando estuvieron cerca de Jesús, le suplicaron con insistencia, diciéndole: «El merece que le hagas este favor,","porque ama a nuestra nación y nos ha construido la sinagoga».","Jesús fue con ellos, y cuando ya estaba cerca de la casa, el centurión le mandó decir por unos amigos: «Señor, no te molestes, porque no soy digno de que entres en mi casa;","por eso no me consideré digno de ir a verte personalmente. Basta que digas una palabra y mi sirviente se sanará.","Porque yo –que no soy más que un oficial subalterno, pero tengo soldados a mis órdenes– cuando digo a uno: \"Ve\", él va; y a otro: \"Ven\", él viene; y cuando digo a mi sirviente: \"¡Tienes que hacer esto!\", él lo hace».","Al oír estas palabras, Jesús se admiró de él y, volviéndose a la multitud que lo seguí, dijo: «Yo les aseguro que ni siquiera en Israel he encontrado tanta fe».","Cuando los enviados regresaron a la casa, encontraron al sirviente completamente sano.","En seguida, Jesús se dirigió a una ciudad llamada Naím, acompañado de sus discípulos y de una gran multitud.","Justamente cuando se acercaba a la puerta de la ciudad, llevaban a enterrar al hijo único de una mujer viuda, y mucha gente del lugar la acompañaba.","Al verla, el Señor se conmovió y le dijo: «No llores».","Después se acercó y tocó el féretro. Los que los llevaban se detuvieron y Jesús dijo: «Joven, yo te lo ordeno, levántate».","El muerto se incorporó y empezó a hablar. Y Jesús se lo entregó a su madre.","Todos quedaron sobrecogidos de temor y alababan a Dios, diciendo: «Un gran profeta ha aparecido en medio de nosotros y Dios ha visitado a su Pueblo».","El rumor de lo que Jesús acababa de hacer se difundió por toda la Judea y en toda la región vecina.","Juan fue informado de todo esto por sus discípulos y, llamando a dos de ellos,","los envió a decir al Señor: «¿Eres tú el que ha de venir o debemos esperar a otro?».","Cuando se presentaron ante él, le dijeron: «Juan el Bautista nos envía a preguntarte: \"¿Eres tú el que ha de venir o debemos esperar a otro?\"».","En esa ocasión, Jesús curó mucha gente de sus enfermedades, de sus dolencias y de los malos espíritus, y devolvió la vista a muchos ciegos.","Entonces respondió a los enviados: «Vayan a contar a Juan lo que han visto y oído: los ciegos ven, los paralíticos caminan, los leprosos son purificados y los sordos oyen, los muertos resucitan, la Buena Noticia es anunciada a los pobres.","¡Y feliz aquel para quien yo no sea motivo de escándalo!».","Cuando los enviados de Juan partieron, Jesús comenzó a hablar de él a la multitud, diciendo: «¿Qué salieron a ver en el desierto? ¿Una caña agitada por el viento?","¿Qué salieron a ver? ¿Un hombre vestido con refinamiento? Los que llevan suntuosas vestiduras y viven en la opulencia, están en los palacios de los reyes.","¿Qué salieron a ver entonces? ¿Un profeta? Les aseguro que sí, y más que un profeta.","El es aquel de quien está escrito: Yo envío a mi mensajero delante de ti para prepararte el camino.","Les aseguro que no hay ningún hombre más grande que Juan, y sin embargo, el más pequeño en el Reino de Dios es más grande que él.","Todo el pueblo que lo escuchaba, incluso los publicanos, reconocieron la justicia de Dios, recibiendo el bautismo de Juan.","Pero los fariseos y los doctores de la Ley, al no hacerse bautizar por él, frustraron el designio de dios para con ellos.","«¿Con quién puedo comparar a los hombres de esta generación? ¿A quién se parecen?","Se parecen a esos muchachos que están sentados en la plaza y se dicen entre ellos:\"¡Les tocamos la flauta, y ustedes no bailaron! ¡Entonamos cantos fúnebres, y no lloraron!\".","Porque llegó Juan el Bautista, que no come pan ni bebe vino, y ustedes dicen: \"¡Ha perdido la cabeza!\".","Llegó el Hijo del hombre, que come y bebe, y dicen: \"¡Es un glotón y un borracho, amigo de publicanos y pecadores!\".","Pero la Sabiduría ha sido reconocida como justa por todos sus hijos».","Un fariseo invitó a Jesús a comer con él. Jesús entró en la casa y se sentó a la mesa.","Entonces una mujer pecadora que vivía en la ciudad, al enterarse de que Jesús estaba comiendo en casa del fariseo, se presentó con un frasco de perfume.","Y colocándose detrás de él, se puso a llorar a sus pies y comenzó a bañarlos con sus lágrimas; los secaba con sus cabellos, los cubría de besos y los ungía con perfume.","Al ver esto, el fariseo que lo había invitado pensó: «Si este hombre fuera profeta, sabría quién es la mujer que lo toca y lo que ella es: ¡una pecadora!»","Pero Jesús le dijo: «Simón, tengo algo que decirte». «Di, Maestro!, respondió él.","«Un prestamista tenía dos deudores: uno le debía quinientos denarios, el otro cincuenta.","Como no tenían con qué pagar, perdonó a ambos la deuda. ¿Cuál de los dos amará más?».","Simón contestó: «Pienso que aquel a quien perdonó más». Jesús le dijo: «Has juzgado bien».","Y volviéndose hacia la mujer, dijo de Simón: «¿Ves a esta mujer? Entré en tu casa y tú no derramaste agua sobre mis pies; en cambio, ella los bañó con sus lágrimas y los secó con sus cabellos.","Tú no me besaste; ella, en cambio, desde que entré, no cesó de besar mis pies.","Tú no ungiste mi cabeza; ella derramó perfume sobre mis pies.","Por eso te digo que sus pecados, sus numerosos pecados, le han sido perdonados porque ha demostrado mucho amor. Pero aquel a quien se le perdona poco, demuestra poco amor».","Después dijo a la mujer: «Tus pecados te son perdonados».","Los invitados pensaron: «¿Quién es este hombre, que llega hasta perdonar los pecados?».","Pero Jesús dijo a la mujer: «Tu fe te ha salvado, vete en paz»."],["Después, Jesús recorría las ciudades y los pueblos, predicando y anunciando la Buena Noticia del Reino de Dios. Lo acompañaban los Doce","y también algunas mujeres que habían sido curadas de malos espíritus y enfermedades: María, llamada Magdalena, de la que habían salido siete demonios;","Juana, esposa de Cusa, intendente de Herodes, Susana y muchas otras, que los ayudaban con sus bienes.","Como se reunía una gran multitud y acudía a Jesús gente de todas las ciudades, él les dijo, valiéndose de una parábola:","«El sembrador salió a sembrar su semilla. Al sembrar, una parte de la semilla cayó al borde del camino, donde fue pisoteada y se la comieron los pájaros del cielo.","Otra parte cayó sobre las piedras y, al brotar, se secó por falta de humedad.","Otra cayó entre las espinas, y estas, brotando al mismo tiempo, la ahogaron.","Otra parte cayó en tierra fértil, brotó y produjo fruto al ciento por uno». Y una vez que dijo esto, exclamó: «¡El que tenga oídos para oír, que oiga!».","Sus discípulos le preguntaron qué significaba esta parábola,","y Jesús les dijo: «A ustedes se les ha concedido conocer los misterios del Reino de Dios; a los demás, en cambio, se les habla en parábolas, para que miren sin ver y oigan sin comprender.","La parábola quiere decir esto: La semilla es la Palabra de Dios.","Los que están al borde del camino son los que escuchan, pero luego viene el demonio y arrebata la Palabra de sus corazones, para que no crean y se salven.","Los que están sobre las piedras son los que reciben la Palabra con alegría, apenas la oyen; pero no tienen raíces: creen por un tiempo, y en el momento de la tentación se vuelven atrás.","Lo que cayó entre espinas son los que escuchan, pero con las preocupaciones, las riquezas y los placeres de la vida, se van dejando ahogar poco a poco, y no llegan a madurar.","Lo que cayó en tierra fértil son los que escuchan la Palabra con un corazón bien dispuesto, la retienen, y dan fruto gracias a su constancia.","No se enciende una lámpara para cubrirla con un recipiente o para ponerla debajo de la cama, sino que se la coloca sobre un candelero, para que los que entren vean la luz.","Porque no hay nada oculto que no se descubra algún día, ni nada secreto que no deba ser conocido y divulgado.","Presten atención y oigan bien, porque al que tiene, se le dará, pero al que no tiene, se le quitará hasta lo que cree tener».","Su madre y sus hermanos fueron a verlo, pero no pudieron acercarse a causa de la multitud.","Entonces le anunciaron a Jesús: «Tu madre y tus hermanos están ahí afuera y quieren verte».","Pero él les respondió: «Mi madre y mis hermanos son los que escuchan la Palabra de Dios y la practican».","Un día, Jesús subió con sus discípulos a una barca y les dijo: «Pasemos a la otra orilla del lago». Ellos partieron,","y mientras navegaban, Jesús se durmió. Entonces se desencadenó sobre el lago un fuerte vendaval; la barca se iba llenando de agua, y ellos corrían peligro.","Los discípulos se acercaron y lo despertaron, diciendo: «¡Maestro, Maestro, nos hundimos!». El se despertó e increpó al viento y a las olas; estas se apaciguaron y sobrevino la calma.","Después les dijo: «¿Dónde está la fe de ustedes?». Y ellos, llenos de temor y admiración, se decían unos a otros: «¿Quién es este que ordena incluso al viento y a las olas, y le obedecen?».","Después llegaron a la región de los gerasenos, que está situada frente a Galilea.","Jesús acababa de desembarcar, cuando salió a su encuentro un hombre de la ciudad, que estaba endemoniado. Desde hacía mucho tiempo no se vestía, y no vivía en una casa, sino en los sepulcros.","Al ver a Jesús, comenzó a gritar, cayó a sus pies y dijo con voz potente: «¿Qué quieres de mí, Jesús, Hijo de Dios, el Altísimo? Te ruego que no me atormentes».","Jesús, en efecto, estaba ordenando al espíritu impuro que saliera de aquel hombre. Muchas veces el espíritu se había apoderado de él, y aunque lo ataban con cadenas y grillos para sujetarlo, él rompía sus ligaduras y el demonio lo arrastraba a lugares desiertos.","Jesús le preguntó: «¿Cuál es tu nombre?». «Legión», respondió, porque eran muchos los demonios que habían entrado en él.,","Y le suplicaban que no les ordenara precipitarse al abismo.","Había allí una gran piara de cerdos que estaba paciendo en la montaña. Los demonios suplicaron a Jesús que les permitiera entrar en los cerdos. El se lo permitió.","Entonces salieron de aquel hombre, entraron en los cerdos, y desde lo alto del acantilado, la piara se precipitó al mar y se ahogó.","Al ver lo que había pasado, los cuidadores huyeron y difundieron la noticia en la ciudad y en los poblados.","En seguida la gente fue a ver lo que había sucedido. Cuando llegaron adonde estaba Jesús, vieron sentado a sus pies, vestido y en su sano juicio, al hombre del que habían salido los demonios, y se llenaron de temor.","Los que habían presenciado el hecho les contaron cómo había sido curado el endemoniado.","Todos los gerasenos pidieron a Jesús que se alejará de allí, porque estaban atemorizados; y él, subiendo a la barca, regresó.","El hombre del que salieron los demonios le rogaba que lo llevara con él, pero Jesús lo despidió, diciéndole:","«Vuelve a tu casa y cuenta todo lo que Dios has hecho por ti». El se fue y proclamó en toda la ciudad lo que Jesús había hecho por él.","A su regreso, Jesús fue recibido por la multitud, porque todos lo estaban esperando.","De pronto, se presentó un hombre llamado Jairo, que era jefe de la sinagoga, y cayendo a los pies de Jesús, le suplicó que fuera a su casa,","porque su única hija, que tenía unos doce años, se estaba muriendo. Mientras iba, la multitud lo apretaba hasta sofocarlo.","Una mujer que padecía de hemorragias desde hacía doce años y a quien nadie había podido curar,","se acercó por detrás y tocó los flecos de su manto; inmediatamente cesó la hemorragia.","Jesús preguntó: «¿Quién me ha tocado?». Como todos lo negaban, Pedro y sus compañeros le dijeron: «Maestro, es la multitud que te está apretujando».","Pero Jesús respondió: «Alguien me ha tocado, porque he sentido que una fuerza salía de mí».","Al verse descubierta, la mujer se acercó temblando, y echándose a sus pies, contó delante de todos por qué lo había tocado y cómo fue curada instantáneamente.","Jesús le dijo entonces: «Hija, tu fe te ha salvado, vete en paz».","Todavía estaba hablando, cuando llegó alguien de la casa del jefe de sinagoga y le dijo: «Tu hija ha muerto, no molestes más al Maestro».","Pero Jesús, que había oído, respondió: «No temas, basta que creas y se salvará».","Cuando llegó a la casa no permitió que nadie entrara con él, sino Pedro, Juan y Santiago, junto con el padre y la madre de la niña.","Todos lloraban y se lamentaban. «No lloren, dijo Jesús, no está muerta, sino que duerme».","Y se burlaban de él, porque sabían que la niña estaba muerta.","Pero Jesús la tomó de la mano y la llamó, diciendo: «Niña, levántate».","Ella recuperó el aliento y se levantó en el acto. Después Jesús ordenó que le dieran de comer.","Sus padres se quedaron asombrados, pero él les prohibió contar lo que había sucedido."],["Jesús convocó a los Doce y les dio poder y autoridad para expulsar a toda clase de demonios y para curar las enfermedades.","Y los envió a proclamar el Reino de Dios y a sanar a los enfermos,","diciéndoles: «No lleven nada para el camino, ni bastón, ni alforja, ni pan, ni dinero, ni tampoco dos túnicas cada uno.","Permanezcan en la casa donde se alojen, hasta el momento de partir.","Si no los reciben, al salir de esa ciudad sacudan hasta el polvo de sus pies, en testimonio contra ellos».","Fueron entonces de pueblo en pueblo, anunciando la Buena Noticia y curando enfermos en todas partes.","El tetrarca Herodes se enteró de todo lo que pasaba, y estaba muy desconcertado porque algunos decían: «Es Juan, que ha resucitado».","Otros decían: «Es Elías, que se ha aparecido», y otros: «Es uno de los antiguos profetas que ha resucitado».","Pero Herodes decía: «A Juan lo hice decapitar. Entonces, ¿quién es este del que oigo decir semejantes cosas?». Y trataba de verlo.","Al regresar, los Apóstoles contaron a Jesús todo lo que habían hecho. El los llevó consigo, y se retiró a solas con ellos hacia una ciudad llamada Betsaida.","Pero la multitud se dio cuenta y lo siguió. El los recibió, les habló del Reino de Dios y devolvió la salud a los que tenían necesidad de ser curados.","Al caer la tarde, se acercaron los Doce y le dijeron: «Despide a la multitud, para que vayan a los pueblos y caseríos de los alrededores en busca de albergue y alimento, porque estamos en un lugar desierto».","El les respondió: «Denles de comer ustedes mismos». Pero ellos dijeron: «No tenemos más que cinco panes y dos pescados, a no ser que vayamos nosotros a comprar alimentos para toda esta gente».","Porque eran alrededor de cinco mil hombres. Entonces Jesús les dijo a sus discípulos: «Háganlos sentar en grupos de cincuenta».","Y ellos hicieron sentar a todos.","Jesús tomó los cinco panes y los dos pescados y, levantando los ojos al cielo, pronunció sobre ellos la bendición, los partió y los fue entregando a sus discípulos para que se los sirviera a la multitud.","Todos comieron hasta saciarse y con lo que sobró se llenaron doce canastas.","Un día en que Jesús oraba a solas y sus discípulos estaban con él, les preguntó: «¿Quién dice la gente que soy yo?».","Ellos le respondieron: «Unos dicen que eres Juan el Bautista; otros, Elías; y otros, alguno de los antiguos profetas que ha resucitado».","«Pero ustedes, les preguntó, ¿quién dicen que soy yo?». Pedro, tomando la palabra, respondió: «Tú eres el Mesías de Dios».","Y él les ordenó terminantemente que no lo dijeran a nadie.","«El hijo del hombre, les dijo, debe sufrir mucho, ser rechazado por los ancianos, los sumos sacerdotes y los escribas, ser condenado a muerte y resucitar al tercer día».","Después dijo a todos: «El que quiera venir detrás de mí, que renuncie a sí mismo, que cargue con su cruz cada día y me siga.","Porque el que quiera salvar su vida, la perderá y el que pierda su vida por mí, la salvará. ]","¿De qué le servirá al hombre ganar el mundo entero, si pierde y arruina su vida?","Porque si alguien se avergüenza de mí y de mis palabras, el Hijo del Hombre se avergonzará de él cuando venga en su gloria y en la gloria del Padre y de los santos ángeles.","Les aseguro que algunos de los que están aquí presentes no morirán antes de ver el Reino de Dios».","Unos ocho días después de decir esto, Jesús tomó a Pedro, Juan y Santiago, y subió a la montaña para orar.","Mientras oraba, su rostro cambió de aspecto y sus vestiduras se volvieron de una blancura deslumbrante.","Y dos hombres conversaban con él: eran Moisés y Elías,","que aparecían revestidos de gloria y hablaban de la partida de Jesús, que iba a cumplirse en Jerusalén.","Pedro y sus compañeros tenían mucho sueño, pero permanecieron despiertos, y vieron la gloria de Jesús y a los dos hombres que estaban con él.","Mientras estos se alejaban, Pedro dijo a Jesús: «¡Maestro, ¡qué bien estamos aquí! Hagamos tres carpas, una para ti, otra para Moisés y otra para Elías». El no sabía lo que decía.","Mientras hablaba, una nube los cubrió con su sombra y al entrar en ella, los discípulos se llenaron de temor.","Desde la nube se oyó entonces una voz que decía: «Este es mi Hijo, el Elegido, escúchenlo».","Y cuando se oyó la voz, Jesús estaba solo. Los discípulos callaron y durante todo ese tiempo no dijeron a nadie lo que habían visto.","Al día siguiente, cuando bajaron de la montaña, una multitud vino a su encuentro.","De pronto, un hombre grito: «Maestro, por favor, mira a mi hijo, el único que tengo.","Cada tanto un espíritu se apodera de él y se pone a gritar; lo sacude con violencia y le hace echar espuma por la boca. A duras penas se aparta de él, dejándolo extenuado.","Les pedí a tus discípulos que lo expulsaran, pero no pudieron».","Jesús le respondió: «Generación incrédula y perversa, ¿hasta cuándo estaré con ustedes y tendré que soportarlos? Trae aquí a tu hijo».","El niño se estaba acercando, cuando el demonio lo arrojó al suelo y lo sacudió violentamente. Pero Jesús increpó al espíritu impuro, curó al niño y lo entregó a su padre.","Todos estaban maravillados de la grandeza de Dios. Mientras todos se admiraban por las cosas que hacía, Jesús dijo a sus discípulos:","«Escuchen bien esto que les digo: El Hijo del hombre va a ser entregado en manos de los hombres».","Pero ellos no entendían estas palabras: su sentido les estaba velado de manera que no podían comprenderlas, y temían interrogar a Jesús acerca de esto.","Entonces se les ocurrió preguntarse quién sería el más grande.","Pero Jesús, conociendo sus pensamientos, tomó a un niño y acercándolo,","les dijo: «El que recibe a este niño en mi Nombre, me recibe a mí, y el que me recibe a mí, recibe a aquel que me envió; porque el más pequeño de ustedes, ese es el más grande».","Juan, dirigiéndose a Jesús, le dijo: «Maestro, hemos visto a uno que expulsaba demonios en tu Nombre y tratamos de impedírselo, porque no es de los nuestros».","Pero Jesús le dijo: «No se lo impidan, porque el que no está contra ustedes, está con ustedes».","Cuando estaba por cumplirse el tiempo de su elevación al cielo, Jesús se encaminó decididamente hacia Jerusalén","y envió mensajeros delante de él. Ellos partieron y entraron en un pueblo de Samaría para prepararle alojamiento.","Pero no lo recibieron porque se dirigía a Jerusalén.","Cuando sus discípulos Santiago y Juan vieron esto, le dijeron: «Señor, ¿quieres que mandemos caer fuego del cielo para consumirlos?».","Pero él se dio vuelta y los reprendió.","Y se fueron a otro pueblo.","Mientras iban caminando, alguien le dijo a Jesús: «¡Te seguiré adonde vayas!».","Jesús le respondió: «Los zorros tienen sus cuevas y las aves del cielo sus nidos, pero el Hijo del hombre no tiene dónde reclinar la cabeza».","Y dijo a otro: «Sígueme». El respondió: «Permíteme que vaya primero a enterrar a mi padre».","Pero Jesús le respondió: «Deja que los muertos entierren a sus muertos; tú ve a anunciar el Reino de Dios».","Otro le dijo: «Te seguiré, Señor, pero permíteme antes despedirme de los míos».","Jesús le respondió: «El que ha puesto la mano en el arado y mira hacia atrás, no sirve para el Reino de Dios»."],["Después de esto, el Señor designó a otros setenta y dos, y los envió de dos en dos para que lo precedieran en todas las ciudades y sitios adonde él debía ir.","Y les dijo: «La cosecha es abundante, pero los trabajadores son pocos. Rueguen al dueño de los sembrados que envíe trabajadores para la cosecha.","¡Vayan! Yo los envío como a ovejas en medio de lobos.","No lleven dinero, ni alforja, ni calzado, y no se detengan a saludar a nadie por el camino.","Al entrar en una casa, digan primero: «¡Que descienda la paz sobre esta casa!».","Y si hay allí alguien digno de recibirla, esa paz reposará sobre él; de lo contrario, volverá a ustedes.","Permanezcan en esa misma casa, comiendo y bebiendo de lo que haya, porque el que trabaja merece su salario. No vayan de casa en casa.","En las ciudades donde entren y sean recibidos, coman lo que les sirvan;","curen a sus enfermos y digan a la gente: «El Reino de Dios está cerca de ustedes».","Pero en todas las ciudades donde entren y no los reciban, salgan a las plazas y digan:","¡Hasta el polvo de esta ciudad que se ha adherido a nuestros pies, lo sacudimos sobre ustedes! Sepan, sin embargo, que el Reino de Dios está cerca».","Les aseguro que en aquel Día, Sodoma será tratada menos rigurosamente que esa ciudad.","¡Ay de ti, Corozaín! ¡Ay de ti, Betsaida! Porque si en Tiro y en Sidón se hubieran hecho los milagros realizados entre ustedes, hace tiempo que se habrían convertido, poniéndose cilicio y sentándose sobre ceniza.","Por eso Tiro y Sidón, en el día del Juicio, serán tratadas menos rigurosamente que ustedes.","Y tú, Cafarnaúm, ¿acaso crees que serás elevada hasta el cielo? No, serás precipitada hasta el infierno.","El que los escucha a ustedes, me escucha a mí; el que los rechaza a ustedes, me rechaza a mí; y el que me rechaza, rechaza a aquel que me envió».","Los setenta y dos volvieron y le dijeron llenos de gozo: «Señor, hasta los demonios se nos someten en tu Nombre».","El les dijo: «Yo veía a Satanás caer del cielo como un rayo.","Les he dado poder de caminar sobre serpientes y escorpiones y para vencer todas las fuerzas del enemigo; y nada podrá dañarlos.","No se alegren, sin embargo, de que los espíritus se les sometan; alégrense más bien de que sus nombres estén escritos en el cielo».","En aquel momento Jesús se estremeció de gozo, movido por el Espíritu Santo, y dijo: «Te alabo, Padre, Señor del cielo y de la tierra, por haber ocultado estas cosas a los sabios y a los prudentes y haberlas revelado a los pequeños. Sí, Padre, porque así lo has querido.","Todo me ha sido dado por mi Padre, y nadie sabe quién es el Hijo, sino el Padre, como nadie sabe quién es el Padre, sino el Hijo y aquel a quien el Hijo se lo quiera revelar».","Después, volviéndose hacia sus discípulos, Jesús les dijo a ellos solos: «¡Felices los ojos que ven lo que ustedes ven!","¡Les aseguro que muchos profetas y reyes quisieron ver lo que ustedes ven y no lo vieron, oír lo que ustedes oyen y no lo oyeron!».","Y entonces, un doctor de la Ley se levantó y le preguntó para ponerlo a prueba: «Maestro, ¿qué tengo que hacer para heredar la Vida eterna?».","Jesús le preguntó a su vez: «¿Qué está escrito en la Ley? ¿Qué lees en ella?».","El le respondió: «Amarás al Señor, tu Dios, con todo tu corazón, con toda tu alma, con todas tus fuerzas y con todo tu espíritu, y a tu prójimo como a ti mismo».","«Has respondido exactamente, le dijo Jesús; obra así y alcanzarás la vida».","Pero el doctor de la Ley, para justificar su intervención, le hizo esta pregunta: «¿Y quién es mi prójimo?».","Jesús volvió a tomar la palabra y le respondió: «Un hombre bajaba de Jerusalén a Jericó y cayó en manos de unos ladrones, que lo despojaron de todo, lo hirieron y se fueron, dejándolo medio muerto.","Casualmente bajaba por el mismo camino un sacerdote: lo vio y siguió de largo.","También pasó por allí un levita: lo vio y siguió su camino.","Pero un samaritano que viajaba por allí, al pasar junto a él, lo vio y se conmovió.","Entonces se acercó y vendó sus heridas, cubriéndolas con aceite y vino; después lo puso sobre su propia montura, lo condujo a un albergue y se encargó de cuidarlo.","Al día siguiente, sacó dos denarios y se los dio al dueño del albergue, diciéndole: \"Cuídalo, y lo que gastes de más, te lo pagaré al volver\"","¿Cuál de los tres te parece que se portó como prójimo del hombre asaltado por los ladrones?».","«El que tuvo compasión de él», le respondió el doctor. Y Jesús le dijo: «Ve, y procede tú de la misma manera».El encuentro de Jesús con Marta y María","Mientras iban caminando, Jesús entró en un pueblo, y una mujer que se llamaba Marta lo recibió en su casa.","Tenía una hermana llamada María, que sentada a los pies del Señor, escuchaba su Palabra.","Marta, que muy estaba muy ocupada con los quehaceres de la casa, dijo a Jesús: «Señor, ¿no te importa que mi hermana me deje sola con todo el trabajo? Dile que me ayude».","Pero el Señor le respondió: «Marta, Marta, te inquietas y te agitas por muchas cosas,","y sin embargo, pocas cosas, o más bien, una sola es necesaria, María eligió la mejor parte, que no le será quitada»."],["Un día, Jesús estaba orando en cierto lugar, y cuando terminó, uno de sus discípulos le dijo: «Señor, enséñanos a orar, así como Juan enseñó a sus discípulos».","El les dijo entonces: «Cuando oren, digan: Padre, santificado sea tu Nombre, que venga tu Reino,","danos cada día nuestro pan cotidiano;","perdona nuestros pecados, porque también nosotros perdonamos a aquellos que nos ofenden; y no nos dejes caer en la tentación».","Jesús agregó: «Supongamos que alguno de ustedes tiene un amigo y recurre a él a medianoche, para decirle: \"Amigo, préstame tres panes,","porque uno de mis amigos llegó de viaje y no tengo nada que ofrecerle\",","y desde adentro él le responde: \"No me fastidies; ahora la puerta está cerrada, y mis hijos y yo estamos acostados. No puedo levantarme para dártelos\".","Yo les aseguro que aunque él no se levante para dárselos por ser su amigo, se levantará al menos a causa de su insistencia y le dará todo lo necesario.","También les aseguro: pidan y se les dará, busquen y encontrarán, llamen y se les abrirá.","Porque el que pide, recibe; el que busca, encuentra; y al que llama, se le abre.","¿Hay entre ustedes algún padre que da a su hijo una piedra cuando le pide pan? ¿Y si le pide un pescado, le dará en su lugar una serpiente?","¿Y si le pide un huevo, le dará un escorpión?","Si ustedes, que son malos, saben dar cosas buenas a sus hijos, cuánto más el Padre del cielo dará el Espíritu Santo a aquellos que se lo pidan».","Jesús estaba expulsando a un demonio que era mudo. Apenas salió el demonio, el mudo empezó a hablar. La muchedumbre quedó admirada,","pero algunos de ellos decían: «Este expulsa a los demonios por el poder de Belzebul, el Príncipe de los demonios».","Otros, para ponerlo a prueba, exigían de él un signo que viniera del cielo.","Jesús, que conocía sus pensamientos, les dijo: «Un reino donde hay luchas internas va a la ruina y sus casas caen una sobre otra.","Si Satanás lucha contra sí mismo, ¿cómo podrá subsistir su reino? Porque –como ustedes dicen– yo expulso a los demonios con el poder de Belzebul.","Si yo expulso a los demonios con el poder de Belzebul, ¿con qué poder los expulsan los discípulos de ustedes? Por eso, ustedes los tendrán a ellos como jueces.","Pero si yo expulso a los demonios con la fuerza del dedo de Dios, quiere decir que el Reino de Dios ha llegado a ustedes.","Cuando un hombre fuerte y bien armado hace guardia en su palacio, todas sus posesiones están seguras,","pero si viene otro más fuerte que él y lo domina, le quita el arma en la que confiaba y reparte sus bienes.","El que no está conmigo, está contra mí; y el que no recoge conmigo, desparrama.","Cuando el espíritu impuro sale de un hombre, vaga por lugares desiertos en busca de reposo, y al no encontrarlo, piensa: \"Volveré a mi casa, de donde salí\".","Cuando llega, la encuentra barrida y ordenada.","Entonces va a buscar a otros siete espíritus peores que él; entran y se instalan allí. Y al final, ese hombre se encuentra peor que al principio».","Cuando Jesús terminó de hablar, una mujer levantó la voz en medio de la multitud y le dijo: «¡Feliz el seno que te llevó y los pechos que te amamantaron!».","Jesús le respondió: «Felices más bien los que escuchan la Palabra de Dios y la practican».","Al ver Jesús que la multitud se apretujaba, comenzó a decir: «Esta es una generación malvada. Pide un signo y no le será dado otro que el de Jonás.","Así como Jonás fue un signo para los ninivitas, también el Hijo del hombre lo será para esta generación.","El día del Juicio, la Reina del Sur se levantará contra los hombres de esta generación y los condenará, porque ella vino de los confines de la tierra para escuchar la sabiduría de Salomón y aquí hay alguien que es más que Salomón.","El día del Juicio, los hombres de Nínive se levantarán contra esta generación y la condenarán, porque ellos se convirtieron por la predicación de Jonás y aquí hay alguien que es más que Jonás.","Cuando uno enciende una lámpara, no la esconde ni la cubre, sino que la pone sobre el candelero, para que los que entran vean la claridad.","La lámpara del cuerpo es tu ojo. Cuando tu ojo está sano, todo tu cuerpo está iluminado; pero si tu ojo está enfermo, también tu cuerpo estará en tinieblas.","Ten cuidado de que la luz que hay en ti no se oscurezca.","Si todo tu cuerpo está iluminado, sin nada de sombra, tendrá tanta luz como cuando la lámpara te ilumina con sus rayos».","Cuando terminó de hablar, un fariseo lo invitó a cenar a su casa. Jesús entró y se sentó a la mesa.","El fariseo extrañó de que no se lavara antes de comer.","Pero el Señor le dijo: «¡Así son ustedes, los fariseos! Purifican por fuera la copa y el plato, y por dentro están llenos de voracidad y perfidia.","¡Insensatos! El que hizo lo de afuera, ¿no hizo también lo de adentro?","Den más bien como limosna lo que tienen y todo será puro.","Pero ¡ay de ustedes, fariseos, que pagan el impuesto de la menta, de la ruda y de todas las legumbres, y descuidan la justicia y el amor de Dios! Hay que practicar esto, sin descuidar aquello.","¡Ay de ustedes, fariseos, porque les gusta ocupar el primer asiento en las sinagogas y ser saludados en las plazas!","¡Ay de ustedes, porque son como esos sepulcros que no se ven y sobre los cuales se camina sin saber!».","Un doctor de la Ley tomó entonces la palabra y dijo: «Maestro, cuando hablas así, nos insultas también a nosotros».","El le respondió: «¡Ay de ustedes también, porque imponen a los demás cargas insoportables, pero ustedes no las tocan ni siquiera con un dedo!","¡Ay de ustedes, que construyen los sepulcros de los profetas, a quienes sus mismos padres han matado!","Así se convierten en testigos y aprueban los actos de sus padres: ellos los mataron y ustedes les construyen sepulcros.","Por eso la Sabiduría de Dios ha dicho: Yo les enviaré profetas y apóstoles: matarán y perseguirán a muchos de ellos.","Así se pedirá cuanta a esta generación de la sangre de todos los profetas, que ha sido derramada desde la creación del mundo:","desde la sangre de Abel hasta la sangre de Zacarías, que fue asesinado entre el altar y el santuario. Sí, les aseguro que a esta generación se le pedirá cuenta de todo esto.","¡Ay de ustedes, doctores de la Ley, porque se han apoderado de la llave de la ciencia! No han entrado ustedes, y a los que quieren entrar, se lo impiden».","Cuando Jesús salió de allí, los escribas y los fariseos comenzaron a acosarlo, exigiéndole respuesta sobre muchas cosas","y tendiéndole trampas para sorprenderlo en alguna afirmación."],["Mientras tanto se reunieron miles de personas, hasta el punto de atropellarse unos a otros. Jesús comenzó a decir, dirigiéndose primero a sus discípulos: «Cuídense de la levadura de los fariseos, que es la hipocresía.","No hay nada oculto que no deba ser revelado, ni nada secreto que no deba ser conocido.","Por eso, todo lo que ustedes han dicho en la oscuridad, será escuchado en pleno día; y lo que han hablado al oído, en las habitaciones más ocultas, será proclamado desde lo alto de las casas.","A ustedes, mis amigos, les digo: No teman a los que matan el cuerpo y después no pueden hacer nada más.","Yo les indicaré a quién deben matar, tiene el poder de arrojar a la Gehena. Sí, les repito, teman a ese.","¿No se venden acaso cinco pájaros por dos monedas? Sin embargo, Dios no olvida a ninguno de ellos.","Ustedes tienen contados todos sus cabellos: no teman, porque valen más que muchos pájaros.","Les aseguro que aquel que me reconozca abiertamente delante de los hombres, el Hijo del hombre lo reconocerá ante los ángeles de Dios.","Pero el que no me reconozca delante de los hombres, no será reconocido ante los ángeles de Dios.","Al que diga una palabra contra el Hijo del hombre, se le perdonará; pero al que blasfeme contra el Espíritu Santo, no se le perdonará.","Cuando los lleven ante las sinagogas, ante los magistrados y las autoridades, no se preocupen de cómo se van a defender o qué van a decir,","porque el Espíritu Santo les enseñará en ese momento lo que deban decir».","Uno de la multitud le dijo: «Maestro, dile a mi hermano que comparta conmigo la herencia».","Jesús le respondió: «Amigo, ¿quién me ha constituido juez o árbitro entre ustedes?».","Después les dijo: «Cuídense de la abundancia, la vida de un hombre no está asegurada por sus riquezas».","Les dijo entonces una parábola: «Había un hombre rico, cuyas tierras habían producido mucho,","y se preguntaba a sí mismo \"¿Qué voy a hacer? No tengo dónde guardar mi cosecha\".","Después pensó: \"Voy a hacer esto: demoleré mis graneros, construiré otros más grandes y amontonaré allí todo mi trigo y mis bienes,","y diré a mi alma: Alma mía, tienes bienes almacenados para muchos años; descansa, como, bebe y date buena vida\".","Pero Dios le dijo: \"Insensato, esta misma noche vas a morir. ¿Y para quién será lo que has amontonado?\".","Esto es lo que sucede al que acumula riquezas para sí, y no es rico a los ojos de Dios».","Después dijo a sus discípulos: «Por eso les digo: No se inquieten por la vida, pensando qué van a comer, ni por el cuerpo, pensando con qué se van a vestir.","Porque la vida vale más que la comida, y el cuerpo más que el vestido.","Fíjense en los cuervos: no siembran ni cosecha, no tienen despensa ni granero, y Dios los alimenta. ¡Cuánto más valen ustedes que los pájaros!","¿Y quién de ustedes, por mucho que se inquiete, puede añadir un instante al tiempo de su vida?","Si aun las cosas más pequeñas superan sus fuerzas, ¿por qué se inquietan por las otras?","Fíjense en los lirios: no hilan ni tejen; sin embargo, les aseguro que ni Salomón, en el esplendor de su gloria, se vistió como uno de ellos.","Si Dios viste así a la hierba, que hoy está en el campo y mañana es echada al fuego, ¡cuánto más hará por ustedes, hombres de poca fe!","Tampoco tienen que preocuparse por lo que van a comer o beber; no se inquieten,","porque son los paganos de este mundo los que van detrás de esas cosas. El Padre sabe que ustedes las necesitan.","Busquen más bien su Reino, y lo demás se les dará por añadidura.","No temas, pequeño Rebaño, porque el Padre de ustedes ha querido darles el Reino.","Vendan sus bienes y denlos como limosna. Háganse bolsas que no se desgasten y acumulen un tesoro inagotable en el cielo, donde no se acerca el ladrón ni destruye la polilla.","Porque allí donde tengan su tesoro, tendrán también su corazón.","Estén preparados, ceñidos y con las lámparas encendidas.","Sean como los hombres que esperan el regreso de su señor, que fue a una boda, para abrirle apenas llegue y llame a la puerta.","¡Felices los servidores a quienes el señor encuentra velando a su llegada! Les aseguro que él mismo recogerá su túnica, los hará sentar a la mesa y se pondrá a servirlo.","¡Felices ellos, si el señor llega a medianoche o antes del alba y los encuentra así!","Entiéndalo bien: si el dueño de casa supiera a qué hora va a llegar el ladrón, no dejaría perforar las paredes de su casa.","Ustedes también estén preparados, porque el Hijo del hombre llegará a la hora menos pensada».","Pedro preguntó entonces: «Señor, ¿esta parábola la dices para nosotros o para todos?».","El Señor le dijo: «¿Cuál es el administrador fiel y previsor, a quien el Señor pondrá al frente de su personal para distribuirle la ración de trigo en el momento oportuno?","¡Feliz aquel a quien su señor, al llegar, encuentra ocupado en este trabajo!","Les aseguro que lo hará administrador de todos sus bienes.","Pero si este servidor piensa: \"Mi señor tardará en llegar\", y se dedica a golpear a los servidores y a las sirvientas, y se pone a comer, a beber y a emborracharse,","su señor llegará el día y la hora menos pensada, lo castigará y le hará correr la misma suerte que los infieles.","El servidor que, conociendo la voluntad de su señor, no tuvo las cosas preparadas y no obró conforme a lo que él había dispuesto, recibirá un castigo severo.","Pero aquel que sin saberlo, se hizo también culpable, será castigado menos severamente. Al que se le dio mucho, se le pedirá mucho; y al que se le confió mucho, se le reclamará mucho más.","Yo he venido a traer fuego sobre la tierra, ¡y cómo desearía que ya estuviera ardiendo!","Tengo que recibir un bautismo, ¡y qué angustia siento hasta que esto se cumpla plenamente!","¿Piensan ustedes que he venido a traer la paz a la tierra? No, les digo que he venido a traer la división.","De ahora en adelante, cinco miembros de una familia estarán divididos, tres contra dos y dos contra tres:","el padre contra el hijo y el hijo contra el padre, la madre contra la hija y la hija contra la madre, la suegra contra la nuera y la nuera contra la suegra».","Dijo también a la multitud: «Cuando ven que una nube se levanta en occidente, ustedes dicen en seguida que va a llover, y así sucede.","Y cuando sopla viento del sur, dicen que hará calor, y así sucede.","¡Hipócritas! Ustedes saben discernir el aspecto de la tierra y del cielo; ¿cómo entonces no saben discernir el tiempo presente?","¿Por qué no juzgan ustedes mismos lo que es justo?","Cuando vas con tu adversario a presentarte ante el magistrado, trata de llegar a un acuerdo con él en el camino, no sea que el adversario te lleve ante el juez, y el juez te entregue al guardia, y este te ponga en la cárcel.","Te aseguro que no saldrás de allí hasta que hayas pagado el último centavo»."],["En ese momento se presentaron unas personas que comentaron a Jesús el caso de aquellos galileos, cuya sangre Pilato mezcló con la de las víctimas de sus sacrificios.","El respondió: «¿Creen ustedes que esos galileos sufrieron todo esto porque eran más pecadores que los demás?","Les aseguro que no, y si ustedes no se convierten, todos acabarán de la misma manera.","¿O creen que las dieciocho personas que murieron cuando se desplomó la torre de Siloé, eran más culpables que los demás habitantes de Jerusalén?","Les aseguro que no, y si ustedes no se convierten, todos acabarán de la misma manera».","Les dijo también esta parábola: «Un hombre tenía una higuera plantada en su viña. Fue a buscar frutos y nos encontró.","Dijo entonces al viñador: \"Hace tres años que vengo a buscar frutos en esta higuera y nos encuentro. Córtala, ¿para qué malgastar la tierra?\".","Pero él respondió: \"Señor, déjala todavía este año; yo removeré la tierra alrededor de ella y la abonaré.","Puede ser que así dé frutos en adelante. Si no, la cortarás\"».","Un sábado, Jesús enseñaba en una sinagoga.","Había allí una mujer poseída de un espíritu, que la tenía enferma desde hacía dieciocho años. Estaba completamente encorvada y no podía enderezarse de ninguna manera.","Jesús, al verla, la llamó y le dijo: «Mujer, estás curada de tu enfermedad»,","y le impuso las manos. Ella se enderezó en seguida y glorificaba a Dios.","Pero el jefe de la sinagoga, indignado porque Jesús había curado en sábado, dijo a la multitud: «Los días de trabajo son seis; vengan durante esos días para hacerse curar, y no el sábado».","El Señor le respondió: «¡Hipócritas! Cualquiera de ustedes, aunque sea sábado, ¿no desata del pesebre a su buey o a su asno para llevarlo a beber?","Y esta hija de Abraham, a la que Satanás tuvo aprisionada durante dieciocho años, ¿no podía ser librada de sus cadenas el día sábado?».","Al oír estas palabras, todos sus adversarios se llenaron de confusión, pero la multitud se alegraba de las maravillas que él hacía.","Jesús dijo entonces: «¿A qué se parece el Reino de Dios? ¿Con qué podré compararlo?","Se parece a un grano de mostaza que un hombre sembró en su huerta; creció, se convirtió en un arbusto y los pájaros del cielo se cobijaron en sus ramas».","Dijo también: «¿Con qué podré comparar el Reino de Dios?","Se parece a un poco de levadura que una mujer mezcló con gran cantidad de harina, hasta que fermentó toda la masa».","Jesús iba enseñando por las ciudades y pueblos, mientras se dirigía a Jerusalén.","Una persona le preguntó: «Señor, ¿es verdad que son pocos los que se salvan?». El respondió:","«Traten de entrar por la puerta estrecha, porque les aseguro que muchos querrán entrar y no lo conseguirán.","En cuanto el dueño de casa se levante y cierre la puerta, ustedes, desde afuera, se pondrán a golpear la puerta, diciendo: \"Señor, ábrenos\". Y él les responderá: \"No sé de dónde son ustedes\".","Entonces comenzarán a decir: \"Hemos comido y bebido contigo, y tú enseñaste en nuestras plazas\".","Pero él les dirá: \"No sé de dónde son ustedes; ¡apártense de mí todos los que hacen el mal!\".","Allí habrá llantos y rechinar de dientes, cuando vean a Abraham, a Isaac, a Jacob y a todos los profetas en el Reino de Dios, y ustedes sean arrojados afuera.","Y vendrán muchos de Oriente y de Occidente, del Norte y del Sur, a ocupar su lugar en el banquete del Reino de Dios.","Hay algunos que son los últimos y serán los primeros, y hay otros que son los primeros y serán los últimos».","En ese momento se acercaron algunos fariseos que le dijeron: «Aléjate de aquí, porque Herodes quiere matarte».","El les respondió: «Vayan a decir a ese zorro: hoy y mañana expulso a los demonios y realizo curaciones, y al tercer día habré terminado.","Pero debo seguir mi camino hoy, mañana y pasado, porque no puede ser que un profeta muera fuera de Jerusalén.","¡Jerusalén, Jerusalén, que matas a los profetas y apedreas a los que te son enviados! ¡Cuántas veces quise reunir a tus hijos, como la gallina reúne bajo sus alas a los pollitos, y tú no quisiste!","Por eso, a ustedes la casa les quedará vacía. Les aseguro que ya no me verán más, hasta que llegue el día en que digan: ¡Bendito el viene en nombre del Señor!»."],["Un sábado, Jesús entró a comer en casa de uno de los principales fariseos. Ellos lo observaban atentamente.","Delante de él había un hombre enfermo de hidropesía.","Jesús preguntó a los doctores de la Ley y a los fariseos: «¿Está permitido curar en sábado o no?».","Pero ellos guardaron silencio. Entonces Jesús tomó de la mano al enfermo, lo curó y lo despidió.","Y volviéndose hacia ellos, les dijo: «Si a alguno de ustedes se le cae en un pozo su hijo o su buey, ¿acaso no lo saca en seguida, aunque sea sábado?».","A esto no pudieron responder nada.","Y al notar cómo los invitados buscaban los primeros puestos, les dijo esta parábola:","«Si te invitan a un banquete de bodas, no te coloques en el primer lugar, porque puede suceder que haya sido invitada otra persona más importante que tú,","y cuando llegue el que los invitó a los dos, tenga que decirte: \"Déjale el sitio\", y así, lleno de vergüenza, tengas que ponerte en el último lugar.","Al contrario, cuando te inviten, ve a colocarte en el último sitio, de manera que cuando llegue el que te invitó, te diga: \"Amigo, acércate más\", y así quedarás bien delante de todos los invitados.","Porque todo el que ensalza será humillado, y el que se humilla será ensalzado».","Después dijo al que lo había invitado: «Cuando des un almuerzo o una cena, no invites a tus amigos, ni a tus hermanos, ni a tus parientes, ni a los vecinos ricos, no sea que ellos te inviten a su vez, y así tengas tu recompensa.","Al contrario, cuando des un banquete, invita a los pobres, a los lisiados, a los paralíticos, a los ciegos.","¡Feliz de ti, porque ellos no tienen cómo retribuirte, y así tendrás tu recompensa en la resurrección de los justos!».","Al oír estas palabras, uno de los invitados le dijo: «¡Feliz el que se siente a la mesa en el Reino de Dios!».","Jesús le respondió: «Un hombre preparó un gran banquete y convidó a mucha gente.","A la hora de cenar, mandó a su sirviente que dijera a los invitados: «Vengan, todo está preparado».","Pero todos, sin excepción, empezaron a excusarse. El primero le dijo: \"Acabo de comprar un campo y tengo que ir a verlo. Te ruego me disculpes\".","El segundo dijo: \"He comprado cinco yuntas de bueyes y voy a probarlos. Te ruego me disculpes\"","Y un tercero respondió: \"Acabo de casarme y por esa razón no puedo ir\".","A su regreso, el sirviente contó todo esto al dueño de casa, este, irritado, le dijo: \"Recorre en seguida las plazas y las calles de la ciudad, y trae aquí a los pobres, a los lisiados, a los ciegos y a los paralíticos\".","Volvió el sirviente y dijo: \"Señor, tus órdenes se han cumplido y aún sobra lugar\".","El señor le respondió: \"Ve a los caminos y a lo largo de los cercos, e insiste a la gente para que entre, de manera que se llene mi casa.","Porque les aseguro que ninguno de los que antes fueron invitados ha de probar mi cena\"».","Junto con Jesús iba un gran gentío, y él, dándose vuelta, les dijo:","«Cualquiera que venga a mí y no me ame más que a su padre y a su madre, a su mujer y a sus hijos, a sus hermanos y hermanas, y hasta a su propia vida, no puede ser mi discípulo.","El que no carga con su cruz y me sigue, no puede ser mi discípulo.","¿Quién de ustedes, si quiere edificar una torre, no se sienta primero a calcular los gastos, para ver si tiene con qué terminarla?","No sea que una vez puestos los cimientos, no pueda acabar y todos los que lo vean se rían de él, diciendo:","\"Este comenzó a edificar y no pudo terminar\".","¿Y qué rey, cuando sale en campaña contra otro, no se sienta antes a considerar si con diez mil hombres puede enfrentar al que viene contra él con veinte mil?","Por el contrario, mientras el otro rey está todavía lejos, envía una embajada para negociar la paz. ]","De la misma manera, cualquiera de ustedes que no renuncie a todo lo que posee, no puede ser mi discípulo.","La sal es una cosa excelente, pero si pierde su sabor, ¿con qué se la volverá a salar?","Ya no sirve ni para la tierra ni para abono: hay que tirarla. ¡El que tenga oídos para oír, que oiga!»."],["Todos los publicanos y pecadores se acercaban a Jesús para escucharlo.","Los fariseos y los escribas murmuraban, diciendo: «Este hombre recibe a los pecadores y come con ellos».","Jesús les dijo entonces esta parábola:","«Si alguien tiene cien ovejas y pierde una, ¿no deja acaso las noventa y nueve en el campo y va a buscar la que se había perdido, hasta encontrarla?","Y cuando la encuentra, la carga sobre sus hombros, lleno de alegría,","y al llegar a su casa llama a sus amigos y vecinos, y les dice: \"Alégrense conmigo, porque encontré la oveja que se me había perdido\".","Les aseguro que, de la misma manera, habrá más alegría en el cielo por un solo pecador que se convierta, que por noventa y nueve justos que no necesitan convertirse».","Y les dijo también: «Si una mujer tiene diez dracmas y pierde una, ¿no enciende acaso la lámpara, barre la casa y busca con cuidado hasta encontrarla?","Y cuando la encuentra, llama a sus amigas y vecinas, y les dice: \"Alégrense conmigo, porque encontré la dracma que se me había perdido\".","Les aseguro que, de la misma manera, se alegran los ángeles de Dios por un solo pecador que se convierte».","Jesús dijo también: «Un hombre tenía dos hijos.","El menor de ellos dijo a su padre: \"Padre, dame la parte de herencia que me corresponde\". Y el padre les repartió sus bienes.","Pocos días después, el hijo menor recogió todo lo que tenía y se fue a un país lejano, donde malgastó sus bienes en una vida licenciosa.","Ya había gastado todo, cuando sobrevino mucha miseria en aquel país, y comenzó a sufrir privaciones.","Entonces se puso al servicio de uno de los habitantes de esa región, que lo envió a su campo para cuidar cerdos.","El hubiera deseado calmar su hambre con las bellotas que comían los cerdos, pero nadie se las daba.","Entonces recapacitó y dijo: \"¡Cuántos jornaleros de mi padre tienen pan en abundancia, y yo estoy aquí muriéndome de hambre!\".","Ahora mismo iré a la casa de mi padre y le diré: \"Padre, pequé contra el Cielo y contra ti;","ya no merezco ser llamado hijo tuyo, trátame como a uno de tus jornaleros\".","Entonces partió y volvió a la casa de su padre. Cuando todavía estaba lejos, su padre lo vio y se conmovió profundamente, corrió a su encuentro, lo abrazó y lo besó.","El joven le dijo: \"Padre, pequé contra el Cielo y contra ti; no merezco ser llamado hijo tuyo\".","Pero el padre dijo a sus servidores: \"Traigan enseguida la mejor ropa y vístanlo, pónganle un anillo en el dedo y sandalias en los pies.","Traigan el ternero engordado y mátenlo. Comamos y festejemos,","porque mi hijo estaba muerto y ha vuelto a la vida, estaba perdido y fue encontrado\". Y comenzó la fiesta.","El hijo mayor estaba en el campo. Al volver, ya cerca de la casa, oyó la música y los coros que acompañaban la danza.","Y llamando a uno de los sirvientes, le preguntó que significaba eso.","El le respondió: \"Tu hermano ha regresado, y tu padre hizo matar el ternero y engordado, porque lo ha recobrado sano y salvo\".","El se enojó y no quiso entrar. Su padre salió para rogarle que entrara,","pero él le respondió: \"Hace tantos años que te sirvo sin haber desobedecido jamás ni una sola de tus órdenes, y nunca me diste un cabrito para hacer una fiesta con mis amigos.","¡Y ahora que ese hijo tuyo ha vuelto, después de haber gastado tus bienes con mujeres, haces matar para él el ternero engordado!\".","Pero el padre le dijo: \"Hijo mío, tú estás siempre conmigo, y todo lo mío es tuyo.","Es justo que haya fiesta y alegría, porque tu hermano estaba muerto y ha vuelto a la vida, estaba perdido y ha sido encontrado\"»."],["Decía también a los discípulos: «Había un hombre rico que tenía un administrador, al cual acusaron de malgastar sus bienes.","Lo llamó y le dijo: \"¿Qué es lo que me han contado de ti? Dame cuenta de tu administración, porque ya no ocuparás más ese puesto\".","El administrador pensó entonces: \"¿Qué voy a hacer ahora que mi señor me quita el cargo? ¿Cavar? No tengo fuerzas. ¿Pedir limosna? Me da vergüenza.","¡Ya sé lo que voy a hacer para que, al dejar el puesto, haya quienes me reciban en su casa!\".","Llamó uno por uno a los deudores de su señor y preguntó al primero: \"¿Cuánto debes a mi señor?\".","\"Veinte barriles de aceite\", le respondió. El administrador le dijo: \"Toma tu recibo, siéntate en seguida, y anota diez\".","Después preguntó a otro: \"Y tú, ¿cuánto debes?\". \"Cuatrocientos quintales de trigo\", le respondió. El administrador le dijo: \"Toma tu recibo y anota trescientos\".","Y el señor alabó a este administrador deshonesto, por haber obrado tan hábilmente. Porque los hijos de este mundo son más astutos en su trato con lo demás que los hijos de la luz.","Pero yo les digo: Gánense amigos con el dinero de la injusticia, para que el día en que este les falte, ellos los reciban en las moradas eternas.","El que es fiel en lo poco, también es fiel en lo mucho, y el que es deshonesto en lo poco, también es deshonesto en lo mucho.","Si ustedes no son fieles en el uso del dinero injusto, ¿quién les confiará el verdadero bien?","Y si no son fieles con lo ajeno, ¿quién les confiará lo que les pertenece a ustedes?","Ningún servidor puede servir a dos señores, porque aborrecerá a uno y amará al otro, o bien se interesará por el primero y menospreciará al segundo. No puede servir a Dios y al Dinero».","Los fariseos, que eran amigos del dinero, escuchaban todo esto y se burlaban de Jesús.","El les dijo: «Ustedes aparentan rectitud ante los hombres, pero Dios conoce sus corazones. Porque lo que es estimable a los ojos de los hombres, resulta despreciable para Dios.","La Ley y los Profetas llegan hasta Juan. Desde entonces se proclama el Reino de Dios, y todos tienen que esforzarse para entrar en él.","Es más fácil que dejen de existir el cielo y la tierra, antes que desaparezca una coma de la Ley.","El que se divorcia de su mujer y se casa con otra, comete adulterio, y el que se casa con una mujer abandonada por su marido, comete adulterio.","Había un hombre rico que se vestía de púrpura y lino finísimo y cada día hacía espléndidos banquetes.","A su puerta, cubierto de llagas, yacía un pobre llamado Lázaro,","que ansiaba saciarse con lo que caía de la mesa del rico; y hasta los perros iban a lamer sus llagas.","El pobre murió y fue llevado por los ángeles al seno de Abraham. El rico también murió y fue sepultado.","En la morada de los muertos, en medio de los tormentos, levantó los ojos y vio de lejos a Abraham, y a Lázaro junto a él.","Entonces exclamó: \"Padre Abraham, ten piedad de mí y envía a Lázaro para que moje la punta de su dedo en el agua y refresque mi lengua, porque estas llamas me atormentan\".","\"Hijo mío, respondió Abraham, recuerda que has recibido tus bienes en vida y Lázaro, en cambio, recibió males; ahora él encuentra aquí su consuelo, y tú, el tormento.","Además, entre ustedes y nosotros se abre un gran abismo. De manera que los que quieren pasar de aquí hasta allí no pueden hacerlo, y tampoco se puede pasar de allí hasta aquí\".","El rico contestó: \"Te ruego entonces, padre, que envíes a Lázaro a la casa de mi padre,","porque tengo cinco hermanos: que él los prevenga, no sea que ellos también caigan en este lugar de tormento\".","Abraham respondió: \"Tienen a Moisés y a los Profetas; que los escuchen\".","\"No, padre Abraham, insistió el rico. Pero si alguno de los muertos va a verlos, se arrepentirán\".","Pero Abraham respondió: \"Si no escuchan a Moisés y a los Profetas, aunque resucite alguno de entre los muertos, tampoco se convencerán\"»."],["Después dijo a sus discípulos: «Es inevitable que haya escándalos, pero ¡ay de aquel que los ocasiona!","Más le valdría que le ataran al cuello una piedra de moler y lo precipitaran al mar, antes que escandalizar a uno de estos pequeños.","Por lo tanto, ¡tengan cuidado! Si tu hermano peca, repréndelo, y si se arrepiente, perdónalo.","Y si peca siete veces al día contra ti, y otras tantas vuelve a ti, diciendo: «Me arrepiento», perdónalo».","Los Apóstoles dijeron al Señor: «Auméntanos la fe».","El respondió: «Si ustedes tuvieran fe del tamaño de un grano de mostaza, y dijeran a esa morera que está ahí: \"Arráncate de raíz y plántate en el mar\", ella les obedecería.","Supongamos que uno de ustedes tiene un servidor para arar o cuidar el ganado. Cuando este regresa del campo, ¿acaso le dirá: \"Ven pronto y siéntate a la mesa\"?","¿No le dirá más bien: \"Prepárame la cena y recógete la túnica para servirme hasta que yo haya comido y bebido, y tú comerás y beberás después\"?","¿Deberá mostrarse agradecido con el servidor porque hizo lo que se le mandó?","Así también ustedes, cuando hayan hecho todo lo que se les mande, digan: \"Somos simples servidores, no hemos hecho más que cumplir con nuestro deber\"».","Mientras se dirigía a Jerusalén, Jesús pesaba a través de Samaría y Galilea.","Al entrar en un poblado, le salieron al encuentro diez leprosos, que se detuvieron a distancia","y empezaron a gritarle: «¡Jesús, Maestro, ten compasión de nosotros!».","Al verlos, Jesús les dijo: «Vayan a presentarse a los sacerdotes». Y en el camino quedaron purificados.","Uno de ellos, al comprobar que estaba curado, volvió atrás alabando a Dios en voz alta","y se arrojó a los pies de Jesús con el rostro en tierra, dándole gracias. Era un samaritano.","Jesús le dijo entonces: «¿Cómo, no quedaron purificados los diez? Los otros nueve, ¿dónde están?","¿Ninguno volvió a dar gracias a Dios, sino este extranjero?».","Y agregó: «Levántate y vete, tu fe te ha salvado».","Los fariseos le preguntaron cuándo llegará el Reino de Dios. El les respondió: «El Reino de Dios no viene ostensiblemente,","y no se podrá decir: «Está aquí» o «Está allí». Porque el Reino de Dios está entre ustedes».","Jesús dijo después a sus discípulos: «Vendrá el tiempo en que ustedes desearán ver uno solo de los días del Hijo del hombre y no lo verán.","Les dirán: «Está aquí» o «Está allí», pero no corran a buscarlo.","Como el relámpago brilla de un extremo al otro del cielo, así será el Hijo del hombre cuando llegue su Día.","Pero antes tendrá que sufrir mucho y será rechazado por esta generación.","En los días del Hijo del hombre sucederá como en tiempo de Noé.","La gente comía, bebía y se casaba, hasta el día en que Noé entró en el arca y llegó el diluvio, que los hizo morir a todos.","Sucederá como en tiempos de Lot: se comía y se bebía, se compraba y se vendía, se plantaba y se construía.","Pero el día en que Lot salió de Sodoma, cayó del cielo una lluvia de fuego y de azufre que los hizo morir a todos.","Lo mismo sucederá el Día en que se manifieste el Hijo del hombre.","En ese Día, el que esté en la azotea y tenga sus cosas en la casa, no baje a buscarlas. Igualmente, el que esté en el campo, no vuelva atrás.","Acuérdense de la mujer de Lot.","El que trate de salvar su vida, la perderá; y el que la pierda, la conservará.","Les aseguro que en esa noche, de dos hombres que estén comiendo juntos, uno será llevado y el otro dejado;","de dos mujeres que estén moliendo juntas, una será llevada y la otra dejada».","[De dos que estén en un campo, uno será llevado y el otro dejado.]","Entonces le preguntaron: «¿Dónde sucederá esto, Señor?». Jesús les respondió: «Donde esté el cadáver, se juntarán los buitres»."],["Después le enseñó con una parábola que era necesario orar siempre sin desanimarse:","«En una ciudad había un juez que no temía a Dios ni le importaban los hombres;","y en la misma ciudad vivía una viuda que recurría a él, diciéndole: \"Te ruego que me hagas justicia contra mi adversario\".","Durante mucho tiempo el juez se negó, pero después dijo: \"Yo no temo a Dios ni me importan los hombres,","pero como esta viuda me molesta, le haré justicia para que no venga continuamente a fastidiarme\".»","Y el Señor dijo: «Oigan lo que dijo este juez injusto.","Y Dios, ¿no hará justicia a sus elegidos, que claman a él día y noche, aunque los haga esperar?","Les aseguro que en un abrir y cerrar de ojos les hará justicia. Pero cuando venga el Hijo del hombre, ¿encontrará fe sobre la tierra?».","Y refiriéndose a algunos que se tenían por justos y despreciaban a los demás, dijo también esta parábola:","«Dos hombres subieron al Templo para orar; uno era fariseo y el otro, publicano.","El fariseo, de pie, oraba así: \"Dios mío, te doy gracias porque no soy como los demás hombres, que son ladrones, injustos y adúlteros; ni tampoco como ese publicano.","Ayuno dos veces por semana y pago la décima parte de todas mis entradas\".","En cambio el publicano, manteniéndose a distancia, no se animaba siquiera a levantar los ojos al cielo, sino que se golpeaba el pecho, diciendo: \"¡Dios mío, ten piedad de mí, que soy un pecador!\".","Les aseguro que este último volvió a su casa justificado, pero no el primero. Porque todo el que se ensalza será humillado y el que se humilla será ensalzado».","También le presentaban a los niños pequeños, para que los tocara; pero, al ver esto, los discípulos los reprendían.","Entonces Jesús los hizo llamar y dijo: «Dejen que los niños se acerquen a mí y no se lo impidan, porque el Reino de Dios pertenece a los que son como ellos.","Les aseguro que el que no recibe el Reino de Dios como un niño, no entrará en él».","Un hombre importante le preguntó: «Maestro bueno, ¿qué debo hacer para heredar la Vida eterna?».","Jesús le dijo: ¿Por qué me llamas bueno? Sólo Dios es bueno.","Tú conoces los mandamientos: No cometerás adulterio, no matarás, no robarás, no darás falso testimonio, honra a tu padre y a tu madre».","El hombre le respondió: «Todo esto lo he cumplido desde mi juventud».","Al oírlo, Jesús le dijo: «Una cosa te falta todavía: vende todo lo que tienes y distribúyelo entre los pobres, y tendrás un tesoro en el cielo. Después ven y sígueme».","Al oír estas palabras, el hombre se entristeció, porque era muy rico.","Viéndolo así, Jesús dijo: «¡Qué difícil será para los ricos entrar en el Reino de Dios!","Sí, es más fácil que un camello pase por el ojo de una aguja, que un rico entre en el Reino de Dios».","Los que escuchaban dijeron: «Pero entonces, ¿quién podrá salvarse?».","Jesús respondió: «Lo que es imposible para los hombres, es posible para Dios».","Pedro le dijo: «Nosotros hemos dejado todo lo que teníamos y te hemos seguido».","Jesús respondió: «Les aseguro que el que haya dejado casa, mujer, hermanos, padres o hijos, por el Reino de Dios,","recibirá mucho más en ese mundo; y en el mundo futuro, recibirá la Vida eterna».","Después, Jesús llevó aparte a los Doce y les dijo: «Ahora subimos a Jerusalén, donde se cumplirá todo lo que anunciaron los profetas sobre el Hijo del hombre.","Será entregado a los paganos, se burlarán de él, lo insultarán, lo escupirán","y, después de azotarlo, lo matarán. Pero al tercer día resucitará».","Ellos no comprendieron nada de todo esto; les resultaba oscuro y no captaban el sentido de estas palabras.","Cuando se acercaba a Jericó, un ciego estaba sentado al borde del camino, pidiendo limosna.","Al oír que pasaba mucha gente, preguntó qué sucedía.","Le respondieron que pasaba Jesús de Nazaret.","El ciego se puso a gritar: «¡Jesús, Hijo de David, ten compasión de mí!».","Los que iban delante lo reprendían para que se callara, pero él gritaba más fuerte: «¡Hijo de David, ten compasión de mí!».","Jesús se detuvo y mandó que se lo trajeran. Cuando lo tuvo a su lado, le preguntó:","¿Qué quieres que haga por ti?». «Señor, que yo vea otra vez».","Y Jesús le dijo: «Recupera la vista, tu fe te ha salvado».","En el mismo momento, el ciego recuperó la vista y siguió a Jesús, glorificando a Dios. Al ver esto, todo el pueblo alababa a Dios."],["Jesús entró en Jericó y atravesaba la cuidad.","Allí vivía un hombre muy rico llamado Zaqueo, que era el jefe de los publicanos.","El quería ver quién era Jesús, pero no podía a causa de la multitud, porque era de baja estatura.","Entonces se adelantó y subió a un sicomoro para poder verlo, porque iba a pasar por allí,","Al llegar a ese lugar, Jesús miró hacia arriba y le dijo: «Zaqueo, baja pronto, porque hoy tengo que alojarme en tu casa».","Zaqueo bajó rápidamente y lo recibió con alegría.","Al ver esto, todos murmuraban, diciendo: «Se ha ido a alojar en casa de un pecador».","Pero Zaqueo dijo resueltamente al Señor: «Señor, voy a dar la mitad de mis bienes a los pobres, y si he perjudicado a alguien, le daré cuatro veces más».","Y Jesús le dijo: «Hoy ha llegado la salvación a esta casa, ya que también este hombre es un hijo de Abraham,","porque el Hijo del hombre vino a buscar y a salvar lo que estaba perdido».","Como la gente seguía escuchando, añadió una parábola, porque estaba cerca de Jerusalén y ellos pensaban que el Reino de Dios iba a aparecer de un momento a otro.","El les dijo: «Un hombre de familia noble fue a un país lejano para recibir la investidura real y regresar en seguida.","Llamó a diez de sus servidores y les entregó cien monedas de plata a cada uno, diciéndoles: \"Háganlas producir hasta que yo vuelva\".","Pero sus conciudadanos lo odiaban y enviaron detrás de él una embajada encargada de decir: \"No queremos que este sea nuestro rey\".","Al regresar, investido de la dignidad real, hizo llamar a los servidores a quienes había dado el dinero, para saber lo que había ganado cada uno.","El primero se presentó y le dijo: \"Señor, tus cien monedas de plata han producido diez veces más\".","\"Está bien, buen servidor, le respondió, ya que has sido fiel en tan poca cosa, recibe el gobierno de diez ciudades\".","Llegó el segundo y el dijo: \"Señor, tus cien monedas de plata han producido cinco veces más\".","A él también le dijo: \"Tú estarás al frente de cinco ciudades\".","Llegó el otro y le dijo: \"Señor, aquí tienes tus cien monedas de plata, que guardé envueltas en un pañuelo.","Porque tuve miedo de ti, que eres un hombre exigente, que quieres percibir lo que no has depositado y cosechar lo que no has sembrado\".","El le respondió: \"Yo te juzgo por tus propias palabras, mal servidor. Si sabías que soy un hombre exigente, que quiero percibir lo que no deposité y cosechar lo que no sembré,","¿por qué no entregaste mi dinero en préstamo? A mi regreso yo lo hubiera recuperado con intereses\"","Y dijo a los que estaban allí: \"Quítenle las cien monedas y dénselas al que tiene diez veces más\".","\"¡Pero, señor, le respondieron, ya tiene mil!\".","\"Les aseguro que al que tiene, se le dará; pero al que no tiene, se le quitará aún lo que tiene.","En cuanto a mis enemigos, que no me han querido por rey, tráiganlos aquí y mátenlos en mi presencia\"».","Después de haber dicho esto, Jesús siguió adelante, subiendo a Jerusalén.","Cuando se acercó a Betfagé y Betania, al pie del monte llamado de los Olivos, envió a dos de sus discípulos, diciéndoles:","«Vayan al pueblo que está enfrente y, al entrar, encontrarán un asno atado, que nadie ha montado todavía. Desátenlo y tráiganlo;","y si alguien les pregunta: «¿Por qué lo desatan?», respondan: «El Señor lo necesita».","Los enviados partieron y encontraron todo como él les había dicho.","Cuando desataron el asno, sus dueños les dijeron: «¿Por qué lo desatan?».","Y ellos respondieron: «El Señor lo necesita».","Luego llevaron el asno adonde estaba Jesús y, poniendo sobre él sus mantos, lo hicieron montar.","Mientras él avanzaba, la gente extendía sus mantos sobre el camino.","Cuando Jesús se acercaba a la pendiente del monte de los Olivos, todos los discípulos, llenos de alegría, comenzaron a alabar a Dios en alta voz, por todos los milagros que habían visto.","Y decían:»¡Bendito sea el Rey que viene en nombre del Señor! ¡Paz en el cielo y gloria en las alturas!».","Algunos fariseos que se encontraban entre la multitud le dijeron: «Maestro, reprende a tus discípulos».","Pero él respondió: «Les aseguro que si ellos callan, gritarán las piedras","Cuando estuvo cerca y vio la ciudad, se puso a llorar por ella,","diciendo: «¡Si tú también hubieras comprendido en ese día el mensaje de paz! Pero ahora está oculto a tus ojos.","Vendrán días desastrosos para ti, en que tus enemigos te cercarán con empalizadas, te sitiarán y te atacarán por todas partes.","Te arrasarán junto con tus hijos, que están dentro de ti, y no dejarán en ti piedra sobre piedra, porque no has sabido reconocer el tiempo en que fuiste visitada por Dios».","Y al entrar al Templo, se puso a echar a los vendedores,","diciéndoles: «Está escrito: Mi casa será una casa de oración, pero ustedes la han convertido en una cueva de ladrones».","Y diariamente enseñaba en el Templo. Los sumos sacerdotes, los escribas y los más importantes del pueblo, buscaban la forma de matarlo.","Pero no sabían cómo hacerlo, porque todo el pueblo lo escuchaba y estaba pendiente de sus palabras."],["Un día en que Jesús enseñaba al pueblo en el Templo y anunciaba la Buena Noticia, se le acercaron los sumos sacerdotes y los escribas con los ancianos,","y le dijeron: «Dinos con qué autoridad haces estas cosas o quién te ha dado esa autoridad».","Jesús les respondió: «Yo también quiero preguntarles algo. Díganme:","El bautismo de Juan, ¿venía del cielo o de los hombres?».","Ellos se hacían este razonamiento: «Si respondemos: \"Del cielo\", él nos dirá: \"¿Por qué no creyeron en él?\".","Y si respondemos: \"De los hombres\", todo el pueblo nos apedreará, porque está convencido de que Juan es un profeta».","Y le dijeron que no sabían de dónde venía.","Jesús les respondió: «Yo tampoco les diré con qué autoridad hago esto».","Y luego dijo al pueblo esta parábola: «Un hombre plantó una viña, la arrendó a unos viñadores y se fue por largo tiempo al extranjero.","Llegado el momento, les envió a un servidor para que le entregaran la parte de los frutos que le correspondía. Pero los viñadores lo golpearon y lo echaron con las manos vacías.","Envió a otro servidor, y también a este lo golpearon, lo ultrajaron y lo echaron con las manos vacías.","Mandó después a un tercero, y a él también lo hirieron y lo arrojaron afuera.","El dueño de la viña pensó entonces: \"¿Qué haré? Voy a enviar a mi hijo muy querido: quizá tengan consideración con él\".","Pero los viñadores, al verlo, se dijeron: \"Este es el heredero, vamos a matarlo, y la herencia será nuestra\".","Y arrojándolo fuera de la viña, lo mataron. ¿Qué hará con ellos el dueño de la viña?","Vendrá, acabará con esos viñadores y entregará la viña a otros». Al oír estas palabras, dijeron: «¡Dios no lo permita!».","Pero fijando en ellos su mirada, Jesús les dijo: «¿Qué significa entonces lo que está escrito: \"La piedra que los constructores rechazaron ha llegado a ser la piedra angular\"?","El que caiga sobre esta piedra quedará destrozado, y aquel sobre quien ella caiga, será aplastado».","Los escribas y los sumos sacerdotes querían detenerlo en ese mismo momento, porque comprendían que esta parábola la había dicho por ellos, pero temieron al pueblo.","Ellos comenzaron a acecharlo y le enviaron espías, que fingían ser hombres de bien, para lograr sorprenderlo en alguna de sus afirmaciones, y entregarlo al poder y a la autoridad del gobernador.","Y le dijeron: «Maestro, sabemos que hablas y enseñas con rectitud y que no tienes en cuenta la condición de las personas, sino que enseñas con toda fidelidad el camino de Dios.","¿Nos está permitido pagar el impuesto al César o no?».","Pero Jesús, conociendo su astucia, les dijo:","«Muéstrenme un denario. ¿De quién es la figura y la inscripción que tiene?». «Del César», respondieron.","Jesús les dijo: «Den al César lo que es del César, y a Dios, lo que es de Dios».","Así no pudieron sorprenderlo en ninguna palabra delante del pueblo y, llenos de admiración por su respuesta, tuvieron que callarse.","Se le acercaron algunos saduceos, que niegan la resurrección,","y le dijeron: «Maestro, Moisés nos ha ordenado: \"Si alguien está casado y muere sin tener hijos, que su hermano, para darle descendencia, se case con la viuda\".","Ahora bien, había siete hermanos. El primero se casó y murió sin tener hijos.","El segundo","se casó con la viuda, y luego el tercero. Y así murieron los siete sin dejar descendencia.","Finalmente, también murió la mujer.","Cuando resuciten los muertos, ¿de quién será esposa, ya que los siete la tuvieron por mujer?».","Jesús les respondió: «En este mundo los hombres y las mujeres se casa,","pero los que sean juzgados dignos de participar del mundo futuro y de la resurrección, no se casarán.","Ya no pueden morir, porque son semejantes a los ángeles y son hijos de Dios, al ser hijos de la resurrección.","Que los muertos van a resucitar, Moisés lo ha dado a entender en el pasaje de la zarza, cuando llama al Señor el Dios de Abraham, el Dios de Isaac y el Dios de Jacob.","Porque él no es Dios de muertos, sino de vivientes; todos, en efecto, viven para él».","Tomando la palabra, algunos escribas le dijeron: «Maestro, has hablado bien».","Y ya no se atrevían a preguntarle nada.","Jesús les dijo entonces: «¿Cómo se puede decir que el Mesías es hijo de David,","si el mismo David ha dicho en el Libro de los Salmos: \"Dijo el Señor a mi Señor: Siéntate a mi derecha,","hasta que ponga a tus enemigos debajo de tus pies\"?","Si David lo llama \"Señor\", ¿cómo puede ser hijo suyo?».","Y dijo a los discípulos, de manera que lo oyera todo el pueblo:","«Tengan cuidado de los escribas, a quienes les gusta pasearse con largas vestiduras, ser saludados en las plazas y ocupar los primeros asientos en las sinagogas y en los banquetes;","que devoran los bienes de las viudas y fingen hacer largas oraciones. Esos serán juzgados con más severidad»."],["Después, levantado los ojos, Jesús vio a unos ricos que ponían sus ofrendas en el tesoro del Templo.","Vio también a una viuda de condición muy humilde, que ponía dos pequeñas monedas de cobre,","y dijo: «Les aseguro que esta pobre viuda ha dado más que a nadie.","Porque todos los demás dieron como ofrenda algo de lo que les sobraba, pero ella, de su indigencia, dio todo lo que tenía para vivir».","Y como algunos, hablando del Templo, decían que estaba adornado con hermosas piedras y ofrendas votivas, Jesús dijo:","«De todo lo que ustedes contemplan, un día no quedará piedra sobre piedra: todo será destruido».","Ellos le preguntaron» «Maestro, ¿cuándo tendrá lugar esto, y cuál será la señal de que va suceder?».","Jesús respondió: «Tengan cuidado, no se dejen engañar, porque muchos se presentarán en mi Nombre, diciendo: \"Soy yo\", y también: \"El tiempo está cerca\". No los sigan.","Cuando oigan hablar de guerras y revoluciones no se alarmen; es necesario que esto ocurra antes, pero no llegará tan pronto el fin».","Después les dijo: «Se levantará nación contra nación y reino contra reino.","Habrá grandes terremotos; peste y hambre en muchas partes; se verán también fenómenos aterradores y grandes señales en cielo.","Pero antes de todo eso, los detendrán, los perseguirán, los entregarán a las sinagogas y serán encarcelados; los llevarán ante reyes y gobernadores a causa de mi Nombre,","y esto les sucederá para que puedan dar testimonio de mí.","Tengan bien presente que no deberán preparar su defensa,","porque yo mismo les daré una elocuencia y una sabiduría que ninguno de sus adversarios podrá resistir ni contradecir.","Serán entregados hasta por sus propios padres y hermanos, por sus parientes y amigos; y a muchos de ustedes los matarán.","Serán odiados por todos a causa de mi Nombre.","Pero ni siquiera un cabello se les caerá de la cabeza.","Gracias a la constancia salvarán sus vidas.","Cuando vean a Jerusalén sitiada por los ejércitos, sepan que su ruina está próxima.","Los que estén en Judea, que se refugien en las montañas; los que estén dentro de la ciudad, que se alejen; y los que estén en los campos, que no vuelvan a ella.","Porque serán días de escarmiento, en que todo lo que está escrito deberá cumplirse.","¡Ay de las que estén embarazadas o tengan niños de pecho en aquellos días! Será grande la desgracia de este país y la ira de Dios pesará sobre este pueblo.","Caerán al filo de la espada, serán llevados cautivos a todas las naciones, y Jerusalén será pisoteada por los paganos, hasta que el tiempo de los paganos llegue a su cumplimiento.","Habrá señales en el sol, en la luna y en las estrellas; y en la tierra, los pueblos serán presa de la angustia ante el rugido del mar y la violencia de las olas.","Los hombres desfallecerán de miedo por lo que sobrevendrá al mundo, porque los astros se conmoverán.","Entonces se verá al Hijo del hombre venir sobre una nube, lleno de poder y de gloria.","Cuando comience a suceder esto, tengan ánimo y levanten la cabeza, porque está por llegarles la liberación».","Y Jesús les hizo esta comparación: «Miren lo que sucede con la higuera o con cualquier otro árbol.","Cuando comienza a echar brotes, ustedes se dan cuenta de que se acerca el verano.","Así también, cuando vean que suceden todas estas cosas, sepan que el Reino de Dios está cerca.","Les aseguro que no pasará esta generación hasta que se cumpla todo esto.","El cielo y la tierra pasarán, pero mis palabras no pasarán.","Tengan cuidado de no dejarse aturdir por los excesos, la embriaguez y las preocupaciones de la vida, para que ese día no caiga de improviso sobre ustedes","como una trampa, porque sobrevendrá a todos los hombres en toda la tierra.","Estén prevenidos y oren incesantemente, para quedar a salvo de todo lo que ha de ocurrir. Así podrán comparecer seguros ante del Hijo del hombre».","Durante el día enseñaba en el Templo, y por la noche se retiraba al monte llamado de los Olivos.","Y todo el pueblo madrugaba para ir al Templo a escucharlo."],["Estaba cerca la fiesta de los Azimos, llamada Pascua.","Los sumos sacerdotes y los escribas buscaban la manera de eliminar a Jesús, porque tenían medio del pueblo.","Entonces Satanás entró en Judas, llamado Iscariote, que era uno de los Doce.","Este fue a tratar con los sumos sacerdotes y los jefes de la guardia sobre el modo de entregárselo.","Ellos se alegraron y convinieron en darle dinero.","Judas aceptó y buscaba una ocasión propicia para entregarlo sin que se enterara el pueblo.","Llegó el día de los Azimos, en el que se debía inmolar la víctima pascual.","Jesús envió a Pedro y a Juan, diciéndoles: «Vayan a prepararnos lo necesario para la comida pascual».","Ellos le preguntaron: «¿Dónde quieres que la preparemos?».","Jesús les respondió: «Al entrar en la ciudad encontrarán a un hombre que lleva un cántaro de agua. Síganlo hasta la casa donde entre,","y digan a su dueño: El Maestro manda preguntarte: \"¿Dónde está la sala en que podré comer la Pascua con mis discípulos?\".","El les mostrará en el piso alto una pieza grande, arreglada con almohadones: preparen allí lo necesario».","Los discípulos partieron, encontraron todo como Jesús les había dicho y prepararon la Pascua.","Llegada la hora, Jesús se sentó a la mesa con los Apóstoles y les dijo:","«He deseado ardientemente comer esta Pascua con ustedes antes de mi Pasión,","porque les aseguro que ya no la comeré más hasta que llegue a su pleno cumplimiento en el Reino de Dios».","Y tomando una copa, dio gracias y dijo: «Tomen y compártanla entre ustedes.","Porque les aseguro que desde ahora no beberé más del fruto de la vid hasta que llegue el Reino de Dios».","Luego tomó el pan, dio gracias, lo partió y lo dio a sus discípulos, diciendo: «Esto es mi Cuerpo, que se entrega por ustedes. Hagan esto en memoria mía».","Después de la cena hizo lo mismo con la copa, diciendo: «Esta copa es la Nueva Alianza sellada con mi Sangre, que se derrama por ustedes.","La mano del traidor está sobre la mesa, junto a mí.","Porque el Hijo del hombre va por el camino que le ha sido señalado, pero ¡ay de aquel que lo va a entregar!».","Entonces comenzaron a preguntarse unos a otros quién de ellos sería el que iba a hacer eso.","Y surgió una discusión sobre quién debía ser considerado como el más grande.","Jesús les dijo: «Los reyes de las naciones dominan sobre ellas, y los que ejercen el poder sobre el pueblo se hacen llamar bienhechores.","Pero entre ustedes no debe ser así. Al contrario, el que es más grande, que se comporte como el menor, y el que gobierna, como un servidor.","Porque, ¿quién es más grande, el que está a la mesa o el que sirve? ¿No es acaso el que está a la mesa? Y sin embargo, yo estoy entre ustedes como el que sirve.","Ustedes son los que han permanecido siempre conmigo en medio de mis pruebas.","Por eso yo les confiero la realeza, como mi Padre me la confirió a mí,","Y en mi Reino, ustedes comerán y beberán en mi mesa, y se sentarán sobre tronos para juzgar a las doce tribus de Israel.","Simón, Simón, mira que Satanás ha pedido poder para zarandearlos como el trigo,","pero yo he rogado por ti, para que no te falte la fe. Y tú, después que hayas vuelto, confirma a tus hermanos».","«Señor, le dijo Pedro, estoy dispuesto a ir contigo a la cárcel y a la muerte».","Pero Jesús replicó: «Yo te aseguro, Pedro, que hoy, antes que cante el gallo, habrás negado tres veces que me conoces».","Después les dijo: «Cuando los envié sin bolsa, ni alforja, ni sandalias, ¿les faltó alguna cosa?».","«Nada», respondieron. El agregó: «Pero ahora el que tenga una bolsa, que la lleve; el que tenga una alforja, que la lleve también; y el que no tenga espada, que venda su manto para comprar una.","Porque les aseguro que debe cumplirse en mí esta palabra de la Escritura: Fue contado entre los malhechores. Ya llega a su fin todo lo que se refiere a mí».","«Señor, le dijeron, aquí hay dos espadas». El les respondió: «Basta».","En seguida Jesús salió y fue como de costumbre al monte de los Olivos, seguido de sus discípulos.","Cuando llegaron, les dijo: «Oren, para no caer en la tentación».","Después se alejó de ellos, más o menos a la distancia de un tiro de piedra, y puesto de rodillas, oraba:","«Padre, si quieres, aleja de mí este cáliz. Pero que no se haga mi voluntad, sino la tuya».","Entonces se le apareció un ángel del cielo que lo reconfortaba.","En medio de la angustia, él oraba más intensamente, y su sudor era como gotas de sangre que corrían hasta el suelo.","Después de orar se levantó, fue hacia donde estaban sus discípulos y los encontró adormecidos por la tristeza.","Jesús les dijo: «¿Por qué están durmiendo? Levántense y oren para no caer en la tentación».","Todavía estaba hablando, cuando llegó una multitud encabezada por el que se llamaba Judas, uno de los Doce. Este se acercó a Jesús para besarlo.","Jesús le dijo: «Judas, ¿con un beso entregas al Hijo del hombre?».","Los que estaban con Jesús, viendo lo que iba a suceder, le preguntaron: «Señor, ¿usamos la espada?»","Y uno de ellos hirió con su espada al servidor del Sumo Sacerdote, cortándole la oreja derecha.","Pero Jesús dijo: «Dejen, ya está». Y tocándole la oreja, lo curó.","Después dijo a los sumos sacerdotes, a los jefes de la guardia del Templo y a los ancianos que habían venido a arrestarlo: «¿Soy acaso un ladrón para que vengan con espadas y palos?","Todos los días estaba con ustedes en el Templo y no me arrestaron. Pero esta es la hora de ustedes y el poder de las tinieblas».","Después de arrestarlo, lo condujeron a la casa del Sumo Sacerdote. Pedro lo seguía de lejos.","Encendieron fuego en medio del patio, se sentaron alrededor de él y Pedro se sentó entre ellos.","Una sirvienta que lo vio junto al fuego, lo miró fijamente y dijo: «Este también estaba con él».","Pedro lo negó diciendo: «Mujer, no lo conozco».","Poco después, otro lo vio y dijo: «Tú también eres uno de aquellos». Pero Pedro respondió: «No, hombre, no lo soy».","Alrededor de una hora más tarde, otro insistió, diciendo: «No hay duda de que este hombre estaba con él; además, él también es galileo».","«Hombre, dijo Pedro, no sé lo que dices». En ese momento, cuando todavía estaba hablando, cantó el gallo.","El Señor, dándose vuelta, miró Pedro. Este recordó las palabras que el Señor le había dicho: «Hoy, antes que cante el gallo, me habrás negado tres veces».","Y saliendo afuera, lloró amargamente.","Los hombres que custodiaban a Jesús lo ultrajaban y lo golpeaban;","y tapándole el rostro, le decían: «Profetiza, ¿quién te golpeó?».","Y proferían contra él toda clase de insultos.","Cuando amaneció, se reunió el Consejo de los ancianos del pueblo, junto con los sumos sacerdotes y los escribas. Llevaron a Jesús ante el tribunal","y le dijeron: «Dinos si eres el Mesías». El les dijo: «Si yo les respondo, ustedes no me creerán,","y si los interrogo, no me responderán.","Pero en adelante, el Hijo del hombre se sentará a la derecha de Dios todopoderoso».","Todos preguntaron: «¿Entonces eres el Hijo de Dios?». Jesús respondió: «Tienen razón, yo lo soy».","Ellos dijeron: «¿Acaso necesitamos otro testimonio? Nosotros mismos lo hemos oído de su propia boca»."],["Después se levantó toda la asamblea y lo llevaron ante Pilato.","Y comenzaron a acusarlo, diciendo: «Hemos encontrado a este hombre incitando a nuestro pueblo a la rebelión, impidiéndole pagar los impuestos al Emperador y pretendiendo ser el rey Mesías».","Pilato lo interrogó, diciendo: «¿Eres tú el rey de los judíos?». «Tú lo dices», le respondió Jesús.","Pilato dijo a los sumos sacerdotes y a la multitud: «No encuentro en este hombre ningún motivo de condena».","Pero ellos insistían: «Subleva al pueblo con su enseñanza en toda la Judea. Comenzó en Galilea y ha llegado hasta aquí».","Al oír esto, Pilato preguntó si ese hombre era galileo.","Y habiéndose asegurado de que pertenecía a la jurisdicción de Herodes, se lo envió. en esos días, también Herodes se encontraba en Jerusalén.","Herodes se alegró mucho al ver a Jesús. Hacía tiempo que deseaba verlo, por lo que había oído decir de él, y esperaba que hiciera algún prodigio en su presencia.","Le hizo muchas preguntas, pero Jesús no le respondió nada.","Entre tanto, los sumos sacerdotes y los escribas estaban allí y lo acusaban con vehemencia.","Herodes y sus guardias, después de tratarlo con desprecio y ponerlo en ridículo, lo cubrieron con un magnífico manto y lo enviaron de nuevo a Pilato.","Y ese mismo día, Herodes y Pilato, que estaban enemistados, se hicieron amigos.","Pilato convocó a los sumos sacerdotes, a los jefes y al pueblo,","y les dijo: «Ustedes me han traído a este hombre, acusándolo de incitar al pueblo a la rebelión. Pero yo lo interrogué delante de ustedes y no encontré ningún motivo de condena en los cargos de que lo acusan;","ni tampoco Herodes, ya que él lo ha devuelto a este tribunal. Como ven, este hombre no ha hecho nada que merezca la muerte.","Después de darle un escarmiento, lo dejaré en libertad».","[En cada fiesta, el gobernador acostumbraba a poner en libertad a un preso.]","Pero la multitud comenzó a gritar: «¡Que muera este hombre! ¡Suéltanos a Barrabás!».","A Barrabás lo habían encarcelado por una sedición que tuvo lugar en la ciudad y por homicidio.","Pilato volvió a dirigirles la palabra con la intención de poner en libertad a Jesús.","Pero ellos seguían gritando: «¡Crucifícalo! ¡Crucifícalo!».","Por tercera vez les dijo: «¿Qué mal ha hecho este hombre? No encuentro en él nada que merezca la muerte. Después de darle un escarmiento, lo dejaré en libertad».","Pero ellos insistían a gritos, reclamando que fuera crucificado, y el griterío se hacía cada vez más violento.","Al fin, Pilato resolvió acceder al pedido del pueblo.","Dejó en libertad al que ellos pedían, al que había sido encarcelado por sedición y homicidio, y a Jesús lo entregó al arbitrio de ellos.","Cuando lo llevaban, detuvieron a un tal Simón de Cirene, que volvía del campo, y lo cargaron con la cruz, para que la llevara detrás de Jesús.","Lo seguían muchos del pueblo y un buen número de mujeres, que se golpeaban el pecho y se lamentaban por él.","Pero Jesús, volviéndose hacia ellas, les dijo: «¡Hijas de Jerusalén!, no lloren por mí; lloren más bien por ustedes y por sus hijos.","Porque se acerca el tiempo en que se dirá: \"¡Felices las estériles, felices los senos que no concibieron y los pechos que no amamantaron!\"","Entonces se dirá a las montañas: \"¡Caigan sobre nosotros!\", y a los cerros: \"¡Sepúltennos!\"","Porque si así tratan a la leña verde, ¿qué será de la leña seca?».","Con él llevaban también a otros dos malhechores, para ser ejecutados.","Cuando llegaron al lugar llamado «del Cráneo», lo crucificaron junto con los malhechores, uno a su derecha y el otro a su izquierda.","Jesús decía: «Padre, perdónalos, porque no saben lo que hacen». Después se repartieron sus vestiduras, sorteándolas entre ellos.","El pueblo permanecía allí y miraba. Sus jefes, burlándose, decían: «Ha salvado a otros: ¡que se salve a sí mismo, si es el Mesías de Dios, el Elegido!».","También los soldados se burlaban de él y, acercándose para ofrecerle vinagre,","le decían: «Si eres el rey de los judíos, ¡sálvate a ti mismo!».","Sobre su cabeza había una inscripción: «Este es el rey de los judíos».","Uno de los malhechores crucificados lo insultaba, diciendo: «¿No eres tú el Mesías? Sálvate a ti mismo y a nosotros».","Pero el otro lo increpaba, diciéndole: «¿No tienes temor de Dios, tú que sufres la misma pena que él?","Nosotros la sufrimos justamente, porque pagamos nuestras culpas, pero él no ha hecho nada malo».","Y decía: «Jesús, acuérdate de mí cuando vengas a establecer tu Reino».","El le respondió: «Yo te aseguro que hoy estarás conmigo en el Paraíso».","Era alrededor del mediodía. El sol se eclipsó y la oscuridad cubrió toda la tierra hasta las tres de la tarde.","El velo del Templo se rasgó por el medio.","Jesús, con un grito, exclamó: «Padre, en tus manos encomiendo mi espíritu». Y diciendo esto, expiró.","Cuando el centurión vio lo que había pasado, alabó a Dios, exclamando: «Realmente este hombre era un justo».","Y la multitud que se había reunido para contemplar el espectáculo, al ver lo sucedido, regresaba golpeándose el pecho.","Todos sus amigos y las mujeres que lo habían acompañado desde Galilea permanecían a distancia, contemplando lo sucedido.","Llegó entonces un miembro del Consejo, llamado José, hombre recto y justo,","que había disentido con las decisiones y actitudes de los demás. Era de Arimatea, ciudad de Judea, y esperaba el Reino de Dios.","Fue a ver a Pilato para pedirle el cuerpo de Jesús.","Después de bajarlo de la cruz, lo envolvió en una sábana y lo colocó en un sepulcro cavado en la roca, donde nadie había sido sepultado.","Era el día de la Preparación, y ya comenzaba el sábado.","Las mujeres que habían venido de Galilea con Jesús siguieron a José, observaron el sepulcro y vieron cómo había sido sepultado.","Después regresaron y prepararon los bálsamos y perfumes, pero el sábado observaron el descanso que prescribía la Ley."],["El primer día de la semana, al amanecer, las mujeres fueron al sepulcro con los perfumes que habían preparado.","Ellas encontraron removida la piedra del sepulcro","y entraron, pero no hallaron el cuerpo del Señor Jesús.","Mientras estaban desconcertadas a causa de esto, se les aparecieron dos hombres con vestiduras deslumbrantes.","Como las mujeres, llenas de temor, no se atrevían a levantar la vista del suelo, ellos les preguntaron: «¿Por qué buscan entre los muertos al que está vivo?","No está aquí, ha resucitado. Recuerden lo que él les decía cuando aún estaba en Galilea:","«Es necesario que el Hijo del Hombre sea entregado en manos de los pecadores, que sea crucificado y que resucite al tercer día».","Y las mujeres recordaron sus palabras.","Cuando regresaron del sepulcro, refirieron esto a los Once y a todos los demás.","Eran María Magdalena, Juana y María, la madre de Santiago, y las demás mujeres que las acompañaban. Ellas contaron todo a los Apóstoles,","pero a ellos les pareció que deliraban y no les creyeron.","Pedro, sin embargo, se levantó y corrió hacia el sepulcro, y al asomarse, no vio más que las sábanas. Entonces regresó lleno de admiración por lo que había sucedido.","Ese mismo día, dos de los discípulos iban a un pequeño pueblo llamado Emaús, situado a unos diez kilómetros de Jerusalén.","En el camino hablaban sobre lo que había ocurrido.","Mientras conversaban y discutían, el mismo Jesús se acercó y siguió caminando con ellos.","Pero algo impedía que sus ojos lo reconocieran.","El les dijo: «¿Qué comentaban por el camino?». Ellos se detuvieron, con el semblante triste,","y uno de ellos, llamado Cleofás, le respondió: «¡Tú eres el único forastero en Jerusalén que ignora lo que pasó en estos días!».","«¿Qué cosa?», les preguntó. Ellos respondieron: «Lo referente a Jesús, el Nazareno, que fue un profeta poderoso en obras y en palabras delante de Dios y de todo el pueblo,","y cómo nuestros sumos sacerdotes y nuestros jefes lo entregaron para ser condenado a muerte y lo crucificaron.","Nosotros esperábamos que fuera él quien librara a Israel. Pero a todo esto ya van tres días que sucedieron estas cosas.","Es verdad que algunas mujeres que están con nosotros nos han desconcertado: ellas fueron de madrugada al sepulcro","y al no hallar el cuerpo de Jesús, volvieron diciendo que se les había aparecido unos ángeles, asegurándoles que él está vivo.","Algunos de los nuestros fueron al sepulcro y encontraron todo como las mujeres habían dicho. Pero a él no lo vieron».","Jesús les dijo: «¡Hombres duros de entendimiento, cómo les cuesta creer todo lo que anunciaron los profetas!","¿No será necesario que el Mesías soportara esos sufrimientos para entrar en su gloria?»","Y comenzando por Moisés y continuando en todas las Escrituras lo que se refería a él.","Cuando llegaron cerca del pueblo adonde iban, Jesús hizo ademán de seguir adelante.","Pero ellos le insistieron: «Quédate con nosotros, porque ya es tarde y el día se acaba». El entró y se quedó con ellos.","Y estando a la mesa, tomó el pan y pronunció la bendición; luego lo partió y se lo dio.","Entonces los ojos de los discípulos se abrieron y lo reconocieron, pero él había desaparecido de su vista.","Y se decían: «¿No ardía acaso nuestro corazón, mientras nos hablaba en el camino y nos explicaba las Escrituras?».","En ese mismo momento, se pusieron en camino y regresaron a Jerusalén. Allí encontraron reunidos a los Once y a los demás que estaban con ellos,","y estos les dijeron: «Es verdad, ¡el Señor ha resucitado y se apareció a Simón!».","Ellos, por su parte, contaron lo que les había pasado en el camino y cómo lo habían reconocido al partir el pan.","Todavía estaban hablando de esto, cuando Jesús se apareció en medio de ellos y les dijo: «La paz esté con ustedes».","Atónitos y llenos de temor, creían ver un espíritu,","pero Jesús les preguntó: «¿Por qué están turbados y se les presentan esas dudas?","Miren mis manos y mis pies, soy yo mismo. Tóquenme y vean. Un espíritu no tiene carne ni huesos, como ven que yo tengo».","Y diciendo esto, les mostró sus manos y sus pies.","Era tal la alegría y la admiración de los discípulos, que se resistían a creer. Pero Jesús les preguntó: «¿Tienen aquí algo para comer?».","Ellos le presentaron un trozo de pescado asado;","él lo tomó y lo comió delante de todos.","Después les dijo: «Cuando todavía estaba con ustedes, yo les decía: Es necesario que se cumpla todo lo que está escrito de mí en la Ley de Moisés, en los Profetas y en los Salmos».","Entonces les abrió la inteligencia para que pudieran comprender las Escrituras,","y añadió: «Así esta escrito: el Mesías debía sufrir y resucitar de entre los muertos al tercer día,","y comenzando por Jerusalén, en su Nombre debía predicarse a todas las naciones la conversión para el perdón de los pecados.","Ustedes son testigos de todo esto.","Y yo les enviaré lo que mi Padre les ha prometido. Permanezcan en la ciudad, hasta que sean revestidos con la fuerza que viene de lo alto».","Después Jesús los llevó hasta las proximidades de Betania y, elevando sus manos, los bendijo.","Mientras los bendecía, se separó de ellos y fue llevado al cielo.","Los discípulos, que se habían postrado delante de él, volvieron a Jerusalén con gran alegría,","y permanecían continuamente en el Templo alabando a Dios."]],"jn":[["Al principio existía la Palabra, y la Palabra estaba junto a Dios, y la Palabra era Dios.","Al principio estaba junto a Dios.","Todas las cosas fueron hechas por medio de la Palabra y sin ella no se hizo nada de todo lo que existe.","En ella estaba la vida, y la vida era la luz de los hombres.","La luz brilla en las tinieblas, y las tinieblas no la percibieron.","Apareció un hombre enviado por Dios, que se llamaba Juan.","Vino como testigo, para dar testimonio de la luz, para que todos creyeran por medio de él.","El no era luz, sino el testigo de la luz.","La Palabra era la luz verdadera que, al venir a este mundo, ilumina a todo hombre.","Ella estaba en el mundo, y el mundo fue hecho por medio de ella, y el mundo no la conoció.","Vino a los suyos, y los suyos no la recibieron.","Pero a todos los que la recibieron, a los que creen en su Nombre, les dio el poder de llegar a ser hijos de Dios.","Ellos no nacieron de la sangre, ni por obra de la carne, ni de la voluntad del hombre, sino que fueron engendrados por Dios.","Y la Palabra se hizo carne y habitó entre nosotros. Y nosotros hemos visto su gloria, la gloria que recibe del Padre como Hijo único, lleno de gracia y de verdad.","Juan da testimonio de él, al declarar: «Este es aquel del que yo dije: El que viene después de mí me ha precedido, porque existía antes que yo».","De su plenitud, todos nosotros hemos participado y hemos recibido gracia sobre gracia:","porque la Ley fue dada por medio de Moisés, pero la gracia y la verdad nos han llegado por Jesucristo.","Nadie ha visto jamás a Dios; el que lo ha revelado es el Hijo único, que está en el seno del Padre.","Este es el testimonio que dio Juan, cuando los judíos enviaron sacerdotes y levitas desde Jerusalén, para preguntarle: «¿Quién eres tú?».","El confesó y no lo ocultó, sino que dijo claramente: «Yo no soy el Mesías».","«¿Quién eres, entonces?», le preguntaron: «¿Eres Elías?». Juan dijo: «No». «¿Eres el Profeta?». «Tampoco», respondió.","Ellos insistieron: «¿Quién eres, para que podamos dar una respuesta a los que nos han enviado? ¿Qué dices de ti mismo?»","Y él les dijo: «Yo soy una voz que grita en el desierto: Allanen el camino del Señor, como dijo el profeta Isaías».","Algunos de los enviados eran fariseos,","y volvieron a preguntarle: «¿Por qué bautizas, entonces, si tú no eres el Mesías, ni Elías, ni el Profeta?».","Juan respondió: «Yo bautizo con agua, pero en medio de ustedes hay alguien al que ustedes no conocen:","él viene después de mí, y yo no soy digno de desatar la correa de su sandalia».","Todo esto sucedió en Betania, al otro lado del Jordán donde Juan bautizaba.","Al día siguiente, Juan vio acercarse a Jesús y dijo: «Este es el Cordero de Dios, que quita el pecado del mundo.","A él me refería, cuando dije: Después de mí viene un hombre que me precede, porque existía antes que yo.","Yo no lo conocía, pero he venido a bautizar con agua para que él fuera manifestado a Israel».","Y Juan dio este testimonio: «He visto al Espíritu descender del cielo en forma de paloma y permanecer sobre él.","Yo no lo conocía, pero el que me envió a bautizar con agua me dijo: \"Aquel sobre el que veas descender el Espíritu y permanecer sobre él, ese es el que bautiza en el Espíritu Santo\".","Yo lo he visto y doy testimonio de que él es el Hijo de Dios».","Al día siguiente, estaba Juan otra vez allí con dos de sus discípulos","y, mirando a Jesús que pasaba, dijo: «Este es el Cordero de Dios».","Los dos discípulos, al oírlo hablar así, siguieron a Jesús.","El se dio vuelta y, viendo que lo seguían, les preguntó: «¿Qué quieren?». Ellos le respondieron: «Rabbí –que traducido significa Maestro– ¿dónde vives?».","«Vengan y lo verán», les dijo. Fueron, vieron dónde vivía y se quedaron con él ese día. Era alrededor de las cuatro de la tarde.","Uno de los dos que oyeron las palabras de Juan y siguieron a Jesús era Andrés, el hermano de Simón Pedro.","Al primero que encontró fue a su propio hermano Simón, y le dijo «Hemos encontrado al Mesías», que traducido significa Cristo.","Entonces lo llevó a donde estaba Jesús. Jesús lo miró y le dijo: «Tú eres Simón, el hijo de Juan: tú te llamarás Cefas», que traducido significa Pedro.","Al día siguiente, Jesús resolvió partir hacia Galilea. Encontró a Felipe y le dijo: «Sígueme».","Felipe era de Betsaida, la ciudad de Andrés y de Pedro.","Felipe encontró a Natanael y le dijo: «Hemos hallado a aquel de quien se habla en la Ley de Moisés y en los Profetas. Es Jesús, el hijo de José de Nazaret».","Natanael le preguntó: «¿Acaso puede salir algo bueno de Nazaret?». «Ven y verás», le dijo Felipe.","Al ver llegar a Natanael, Jesús dijo: «Este es un verdadero israelita, un hombre sin doblez».","«¿De dónde me conoces?», le preguntó Natanael. Jesús le respondió: «Yo te vi antes que Felipe te llamara, cuando estabas debajo de la higuera».","Natanael le respondió: «Maestro, tú eres el hijo de Dios, tú eres el Rey de Israel».","Jesús continuó: «Porque te dije: \"Te vi debajo de la higuera\", crees. Verás cosas más grandes todavía».","Y agregó: «Les aseguro que verán el cielo abierto, y a los ángeles de Dios subir y bajar sobre el Hijo del hombre»."],["Tres días después se celebraron unas bodas en Caná de Galilea, y la madre de Jesús estaba allí.","Jesús también fue invitado con sus discípulos.","Y como faltaba vino, la madre de Jesús le dijo: «No tienen vino».","Jesús le respondió: «Mujer, ¿qué tenemos que ver nosotros? Mi hora no ha llegado todavía».","Pero su madre dijo a los sirvientes: «Hagan todo lo que él les diga».","Había allí seis tinajas de piedra destinadas a los ritos de purificación de los judíos, que contenían unos cien litros cada una.","Jesús dijo a los sirvientes: «Llenen de agua estas tinajas». Y las llenaron hasta el borde.","«Saquen ahora, agregó Jesús, y lleven al encargado del banquete». Así lo hicieron.","El encargado probó el agua cambiada en vino y como ignoraba su o rigen, aunque lo sabían los sirvientes que habían sacado el agua, llamó al esposo","y les dijo: «Siempre se sirve primero el buen vino y cuando todos han bebido bien, se trae el de inferior calidad. Tú, en cambio, has guardado el buen vino hasta este momento».","Este fue el primero de los signos de Jesús, y lo hizo en Caná de Galilea. Así manifestó su gloria, y sus discípulos creyeron en él.","Después de esto, descendió a Cafarnaúm con su madre, sus hermanos y sus discípulos, y permanecieron allí unos pocos días.","Se acercaba la Pascua de los judíos. Jesús subió a Jerusalén","y encontró en el Templo a los vendedores de bueyes, ovejas y palomas y a los cambistas sentados delante de sus mesas.","Hizo un látigo de cuerdas y los echó a todos del Templo, junto con sus ovejas y sus bueyes; desparramó las monedas de los cambistas, derribó sus mesas","y dijo a los vendedores de palomas: «Saquen esto de aquí y no hagan de la casa de mi Padre una casa de comercio».","Y sus discípulos recordaron las palabras de la Escritura: El celo por tu Casa me consumirá.","Entonces los judíos le preguntaron: «¿Qué signo nos das para obrar así?».","Jesús les respondió: «Destruyan este templo y en tres días lo volveré a levantar».","Los judíos le dijeron: «Han sido necesarios cuarenta y seis años para construir este Templo, ¿y tú lo vas a levantar en tres días?».","Pero él se refería al templo de su cuerpo.","Por eso, cuando Jesús resucitó, sus discípulos recordaron que él había dicho esto, y creyeron en la Escritura y en la palabra que había pronunciado.","Mientras estaba en Jerusalén, durante la fiesta de Pascua, muchos creyeron en su Nombre al ver los signos que realizaba.","Pero Jesús no se fiaba de ellos, porque los conocía a todos","y no necesitaba que lo informaran acerca de nadie: él sabía lo que hay en el interior del hombre."],["Había entre los fariseos un hombre llamado Nicodemo, que era uno de los notables entre los judíos.","Fue de noche a ver a Jesús y le dijo: «Maestro, sabemos que tú has venido de parte de Dios para enseñar, porque nadie puede realizar los signos que tú haces, si Dios no está con él».","Jesús le respondió: «Te aseguro que el que no renace de lo alto no puede ver el Reino de Dios.»","Nicodemo le preguntó: «¿Cómo un hombre puede nacer cuando ya es viejo? ¿Acaso puede entrar por segunda vez en el seno de su madre y volver a nacer?».","Jesús le respondió: «Te aseguro que el que no nace del agua y del Espíritu no puede entrar en el Reino de Dios.","Lo que nace de la carne es carne, lo que nace de Espíritu es espíritu.","No te extrañes de que te haya dicho: «Ustedes tienen que renacer de lo alto».","El viento sopla donde quiere: tú oyes su voz, pero no sabes de dónde viene ni a dónde va. Lo mismo sucede con todo el que ha nacido del Espíritu».","«¿Cómo es posible todo esto?», le volvió a preguntar Nicodemo.","Jesús le respondió: «¿Tú, que eres maestro en Israel, no sabes estas cosas?","Te aseguro que nosotros hablamos de lo que hablamos de lo que sabemos y damos testimonio de lo que hemos visto, pero ustedes no aceptan nuestro testimonio.","Si no creen cuando les hablo de las cosas de la tierra, ¿cómo creerán cuando les hable de las cosas del cielo?","Nadie ha subido al cielo, sino el que descendió del cielo, el Hijo del hombre que está en el cielo.","De la misma manera que Moisés levantó en alto la serpiente en el desierto, también es necesario que el Hijo del hombre sea levantado en alto,","para que todos los que creen en él tengan Vida eterna.","Sí, Dios amó tanto al mundo, que entregó a su Hijo único para que todo el que cree en él no muera, sino que tenga Vida eterna.","Porque Dios no envió a su Hijo para juzgar al mundo, sino para que el mundo se salve por él.","El que cree en él, no es condenado; el que no cree, ya está condenado, porque no ha creído en el nombre del Hijo único de Dios.","En esto consiste el juicio: la luz vino al mundo, y los hombres prefirieron las tinieblas a la luz, porque sus obras eran malas.","Todo el que obra mal odia la luz y no se acerca a ella, por temor de que sus obras sean descubiertas.","En cambio, el que obra conforme a la verdad se acerca a la luz, para que se ponga de manifiesto que sus obras han sido hechas en Dios».","Después de esto, Jesús fue con sus discípulos a Judea. Permaneció allí con ellos y bautizaba.","Juan seguía bautizando en Enón, cerca de Salim, porque había mucha agua en ese lugar y la gente acudía para hacerse bautizar.","Juan no había sido encarcelado todavía","Se originó entonces una discusión entre los discípulos de Juan y un judío, acerca de la purificación.","Fueron a buscar a Juan y le dijeron: «Maestro, el que estaba contigo al otro lado del Jordán y del que tú has dado testimonio, también bautiza y todos acuden a él».","Juan respondió: «Nadie puede atribuirse nada que no haya recibido del cielo.","Ustedes mismos son testigos de que he dicho: \"Yo no soy el Mesías, pero he sido enviado delante de él\".","En las bodas, el que se casa es el esposo; pero el amigo del esposo, que está allí y lo escucha, se llena de alegría al oír su voz. Por eso mi gozo es ahora perfecto.","Es necesario que él crezca y que yo disminuya».","El que viene de lo alto está por encima de todos. El que es de la tierra pertenece a la tierra y habla de la tierra. El que vino del cielo","da testimonio de lo que ha visto y oído, pero nadie recibe su testimonio.","El que recibe su testimonio certifica que Dios es veraz.","El que Dios envió dice las palabras de Dios, porque Dios le da el Espíritu sin medida.","El Padre ama al Hijo y ha puesto todo en sus manos.","El que cree en el Hijo tiene Vida eterna. El que se niega a creer en el Hijo no verá la Vida, sino que la ira de Dios pesa sobre él."],["Cuando Jesús se enteró de que los fariseos habían oído decir que él tenía más discípulos y bautizaba más que Juan","–en realidad él no bautizaba, sino sus discípulos–","dejó la Judea y volvió a Galilea.","Para eso tenía que atravesar Samaría.","Llegó a una ciudad de Samaría llamada Sicar, cerca de las tierras que Jacob había dado a su hijo José.","Allí se encuentra el pozo de Jacob. Jesús, fatigado del camino, se había sentado junto al pozo. Era la hora del mediodía.","Una mujer de Samaría fue a sacar agua, y Jesús le dijo: «Dame de beber».","Sus discípulos habían ido a la ciudad a comprar alimentos.","La samaritana le respondió: «¡Cómo! ¿Tú, que eres judío, me pides de beber a mí, que soy samaritana?». Los judíos, en efecto, no se trataban con los samaritanos.","Jesús le respondió: «Si conocieras el don de Dios y quién es el que te dice: «Dame de beber», tú misma se lo hubieras pedido, y él te habría dado agua viva».","«Señor, le dijo ella, no tienes nada para sacar el agua y el pozo es profundo. ¿De dónde sacas esa agua viva?","¿Eres acaso más grande que nuestro padre Jacob, que nos ha dado este pozo, donde él bebió, lo mismo que sus hijos y sus animales?».","Jesús le respondió: «El que beba de esta agua tendrá nuevamente sed,","pero el que beba del agua que yo le daré, nunca más volverá a tener sed. El agua que yo le daré se convertirá en él en manantial que brotará hasta la Vida eterna».","«Señor, le dijo la mujer, dame de esa agua para que no tenga más sed y no necesite venir hasta aquí a sacarla».","Jesús le respondió: «Ve, llama a tu marido y vuelve aquí».","La mujer respondió: «No tengo marido». Jesús continuó: «Tienes razón al decir que no tienes marido,","porque has tenido cinco y el que ahora tienes no es tu marido; en eso has dicho la verdad».","La mujer le dijo: «Señor, veo que eres un profeta.","Nuestros padres adoraron en esta montaña, y ustedes dicen que es en Jerusalén donde se debe adorar».","Jesús le respondió: «Créeme, mujer, llega la hora en que ni en esta montaña ni en Jerusalén se adorará al Padre.","Ustedes adoran lo que no conocen; nosotros adoramos lo que conocemos, porque la salvación viene de los judíos.","Pero la hora se acerca, y ya ha llegado, en que los verdaderos adoradores adorarán al Padre en espíritu y en verdad, porque esos son los adoradores que quiere el Padre.","Dios es espíritu, y los que lo adoran deben hacerlo en espíritu y en verdad».","La mujer le dijo: «Yo sé que el Mesías, llamado Cristo, debe venir. Cuando él venga, nos anunciará todo».","Jesús le respondió: «Soy yo, el que habla contigo».","En ese momento llegaron sus discípulos y quedaron sorprendidos al verlo hablar con una mujer. Sin embargo, ninguno le preguntó: «¿Qué quieres de ella?» o «¿Por qué hablas con ella?».","La mujer, dejando allí su cántaro, corrió a la ciudad y dijo a la gente:","«Vengan a ver a un hombre que me ha dicho todo lo que hice. ¿No será el Mesías?».","Salieron entonces de la ciudad y fueron a su encuentro.","Mientras tanto, los discípulos le insistían a Jesús, diciendo: «Come, Maestro».","Pero él les dijo: «Yo tengo para comer un alimento que ustedes no conocen».","Los discípulos se preguntaban entre sí: «¿Alguien le habrá traído de comer?».","Jesús les respondió: «Mi comida es hacer la voluntad de aquel que me envió y llevar a cabo su obra.","Ustedes dicen que aún faltan cuatro meses para la cosecha. Pero yo les digo: Levanten los ojos y miren los campos: ya están madurando para la siega.","Ya el segador recibe su salario y recoge el grano para la Vida eterna; así el que siembra y el que cosecha comparten una misma alegría.","Porque en esto se cumple el proverbio: «Uno siembra y otro cosecha».","Y o los envié a cosechar adonde ustedes no han trabajado; otros han trabajado, y ustedes recogen el fruto de sus esfuerzos».","Muchos samaritanos de esta ciudad habían creído en él por la palabra de la mujer, que atestiguaba: «Me ha dicho todo lo que hice».","Por eso, cuando los samaritanos se acercaron a Jesús, le rogaban que se quedara con ellos, y él permaneció allí dos días.","Muchos más creyeron en él, a causa de su palabra.","Y decían a la mujer: «Ya no creemos por lo que tú has dicho; nosotros mismos lo hemos oído y sabemos que él es verdaderamente el Salvador del mundo».","Transcurridos los dos días, Jesús partió hacia Galilea.","El mismo había declarado que un profeta no goza de prestigio en su propio pueblo.","Pero cuando llegó, los galileos lo recibieron bien, porque habían visto todo lo que había hecho en Jerusalén durante la Pascua; ellos también, en efecto, habían ido a la fiesta.","Y fue otra vez a Caná de Galilea, donde había convertido el agua en vino. Había allí un funcionario real, que tenía su hijo enfermo en Cafarnaúm.","Cuando supo que Jesús había llegado de Judea y se encontraba en Galilea, fue a verlo y le suplicó que bajara a curar a su hijo moribundo.","Jesús le dijo: «Si no ven signos y prodigios, ustedes no creen».","El funcionario le respondió: «Señor, baja antes que mi hijo se muera».","«Vuelve a tu casa, tu hijo vive», le dijo Jesús. El hombre creyó en la palabra que Jesús le había dicho y se puso en camino.","Mientras descendía, le salieron al encuentro sus servidores y la anunciaron que su hijo vivía.","El les preguntó a qué hora se había sentido mejor. «Ayer, a la una de la tarde, se le fue la fiebre», le respondieron.","El padre recordó que era la misma hora en que Jesús le había dicho: «Tu hijo vive». Y entonces creyó él y toda su familia.","Este fue el segundo signo que hizo Jesús cuando volvió de Judea a Galilea."],["Después de esto, se celebraba una fiesta de los judíos y Jesús subió a Jerusalén,","Junto a la puerta de las Ovejas, en Jerusalén, hay una piscina llamada en hebreo Betsata, que tiene cinco pórticos.","Bajo estos pórticos yacía una multitud de enfermos, ciegos, paralíticos y lisiados, que esperaban la agitación del agua.","[Porque el Angel del Señor descendía cada tanto a la piscina y movía el agua. El primero que entraba en la piscina, después que el agua se agitaba, quedaba curado, cualquiera fuera su mal.]","Había allí un hombre que estaba enfermo desde hacía treinta y ocho años.","Al verlo tendido, y sabiendo que hacía tanto tiempo que estaba así, Jesús le preguntó: «¿Quieres curarte?».","El respondió: «Señor, no tengo a nadie que me sumerja en la piscina cuando el agua comienza a agitarse; mientras yo voy, otro desciende antes».","Jesús le dijo: «Levántate, toma tu camilla y camina».","En seguida el hombre se curó, tomó su camilla y empezó a caminar. Era un sábado,","y los Judíos dijeron entonces al que acababa de ser curado: «Es sábado. No te está permitido llevar tu camilla».","El les respondió: «El que me curó me dijo: «Toma tu camilla y camina».","Ellos le preguntaron: «¿Quién es ese hombre que te dijo: «Toma tu camilla y camina?».","Pero el enfermo lo ignoraba, porque Jesús había desaparecido entre la multitud que estaba allí.","Después, Jesús lo encontró en el Templo y le dijo: «Has sido curado; no vuelvas a pecar, de lo contrario te ocurrirán peores cosas todavía».","El hombre fue a decir a los judíos que era Jesús el que lo había curado.","Ellos atacaban a Jesús, porque hacía esas cosas en sábado.","el les respondió: «Mi Padre trabaja siempre, y yo también trabajo».","Pero para los judíos esta era una razón más para matarlo, porque no sólo violaba el sábado, sino que se hacía igual a Dios, llamándolo su propio Padre.","Entonces Jesús tomó la palabra diciendo: «Les aseguro que el Hijo no puede hacer nada por sí mismo sino solamente lo que ve hacer al Padre; lo que hace el Padre, lo hace igualmente el Hijo.","Porque el Padre ama al Hijo y le muestra todo lo que hace. Y le mostrará obras más grandes aún, para que ustedes queden maravillados.","Así como el Padre resucita a los muertos y les da vida, del mismo modo el Hijo da vida al que él quiere.","Porque el Padre no juzga a nadie: él ha puesto todo juicio en manos de su Hijo,","para que todos honren al Hijo como honran al Padre. El que no honra al Hijo, no honra al Padre que lo envió.","Les aseguro que el que escucha mi palabra y cree en aquel que me ha enviado, tiene Vida eterna y no está sometido al juicio, sino que ya ha pasado de la muerte a la Vida.","Les aseguro que la hora se acerca, y ya ha llegado, en que los muertos oirán la voz del Hijo de Dios; y los que la oigan, vivirán.","Así como el Padre dispone de la Vida, del mismo modo ha concedido a su Hijo disponer de ella,","y le dio autoridad para juzgar porque él es el Hijo del hombre.","No se asombren: se acerca la hora en que todos los que están en las tumbas oirán su voz","y saldrán de ellas: los que hayan hecho el bien, resucitarán para la Vida; los que hayan hecho el mal, resucitarán para el juicio.","Nada puedo hacer por mí mismo. Yo juzgo de acuerdo con lo que oigo, y mi juicio es justo, porque lo que yo busco no es hacer mi voluntad, sino la de aquel que me envió.","Si yo diera testimonio de mí mismo, mi testimonio no valdría.","Pero hay otro que da testimonio de mí, y yo sé que ese testimonio es verdadero.","Ustedes mismos mandaron preguntar a Juan, y él ha dado testimonio de la verdad.","No es que yo dependa del testimonio de un hombre; si digo esto es para la salvación de ustedes.","Juan era la lámpara que arde y resplandece, y ustedes han querido gozar un instante de su luz.","Pero el testimonio que yo tengo es mayor que el de Juan: son las obras que el Padre me encargó llevar a cabo. Estas obras que yo realizo atestiguan que mi Padre me ha enviado.","Y el Padre que me envió ha dado testimonio de mí. Ustedes nunca han escuchado su voz ni han visto su rostro,","y su palabra no permanece en ustedes, porque no creen al que él envió.","Ustedes examinan las Escrituras, porque en ellas piensan encontrar Vida eterna: ellas dan testimonio de mí,","y sin embargo, ustedes no quieren venir a mí para tener Vida.","Mi gloria no viene de los hombres.","Además, yo los conozco: el amor de Dios no está en ustedes.","He venido en nombre de mi Padre y ustedes no me reciben, pero si otro viene en su propio nombre, a ese sí lo van a recibir.","¿Cómo es posible que crean, ustedes que se glorifican unos a otros y no se preocupan por la gloria que sólo viene de Dios?","No piensen que soy yo el que los acusaré ante el Padre; el que los acusará será Moisés, en el que ustedes han puesto su esperanza.","Si creyeran en Moisés, también creerían en mí, porque él ha escrito acerca de mí.","Pero si no creen lo que él ha escrito, ¿cómo creerán lo que yo les digo?»."],["Después de esto, Jesús atravesó el mar de Galilea, llamado Tiberíades.","Lo seguía una gran multitud, al ver los signos que hacía curando a los enfermos.","Jesús subió a la montaña y se sentó allí con sus discípulos.","Se acercaba la Pascua, la fiesta de los judíos.","Al levantar los ojos, Jesús vio que una gran multitud acudía a él y dijo a Felipe: «¿Dónde compraremos pan para darles de comer?».","El decía esto para ponerlo a prueba, porque sabía bien lo que iba a hacer.","Felipe le respondió: «Doscientos denarios no bastarían para que cada uno pudiera comer un pedazo de pan».","Uno de sus discípulos, Andrés, el hermano de Simón Pedro, le dijo:","«Aquí hay un niño que tiene cinco panes de cebada y dos pescados, pero ¿qué es esto para tanta gente?».","Jesús le respondió: «Háganlos sentar». Había mucho pasto en ese lugar. Todos se sentaron y eran uno cinco mil hombres.","Jesús tomó los panes, dio gracias y los distribuyó a los que estaban sentados. Lo mismo hizo con los pescados, dándoles todo lo que quisieron.","Cuando todos quedaron satisfechos, Jesús dijo a sus discípulos: «Recojan los pedazos que sobran, para que no se pierda nada».","Los recogieron y llenaron doce canastas con los pedazos que sobraron de los cinco panes de cebada.","Al ver el signo que Jesús acababa de hacer, la gente decía: «Este es, verdaderamente, el Profeta que debe venir al mundo».","Jesús, sabiendo que querían apoderarse de él para hacerlo rey, se retiró otra vez solo a la montaña.","Al atardecer, sus discípulos bajaron a la orilla del mar","y se embarcaron, para dirigirse a Cafarnaúm, que está en la otra orilla. Ya era de noche y Jesús aún no se había reunido con ellos.","El mar estaba agitado, porque soplaba un fuerte viento.","Cuando habían remado unos cinco kilómetros, vieron a Jesús acercarse a la barca caminando sobre el agua, y tuvieron miedo.","El les dijo: «Soy yo, no teman».","Ellos quisieron subirlo a la barca, pero esta tocó tierra en seguida en el lugar adonde iban","Al día siguiente, la multitud que se había quedado en la otra orilla vio que Jesús no había subido con sus discípulos en la única barca que había allí, sino que ellos habían partido solos.","Mientras tanto, unas barcas de Tiberíades atracaron cerca del lugar donde habían comido el pan, después que el Señor pronunció la acción de gracias.","Cuando la multitud se dio cuenta de que Jesús y sus discípulos no estaban allí, subieron a las barcas y fueron a Cafarnaúm en busca de Jesús.","Al encontrarlo en la otra orilla, le preguntaron: «Maestro, ¿cuándo llegaste?».","Jesús les respondió: «Les aseguro que ustedes me buscan, no porque vieron signos, sino porque han comido pan hasta saciarse.","Trabajen, no por el alimento perecedero, sino por el que permanece hasta la Vida eterna, el que les dará el Hijo del hombre; porque es él a quien Dios, el Padre, marcó con su sello».","Ellos le preguntaron: «¿Qué debemos hacer para realizar las obras de Dios?».","Jesús les respondió: «La obra de Dios es que ustedes crean en aquel que él ha enviado».","Y volvieron a preguntarle: «¿Qué signos haces para que veamos y creamos en ti? ¿Qué obra realizas?","Nuestros padres comieron el maná en el desierto, como dice la Escritura: Les dio de comer el pan bajado del cielo».","Jesús respondió: «Les aseguro que no es Moisés el que les dio el pan del cielo; mi Padre les da el verdadero pan del cielo;","porque el pan de Dios es el que desciende del cielo y da Vida al mundo».","Ellos le dijeron: «Señor, danos siempre de ese pan».","Jesús les respondió: «Yo soy el pan de Vida. El que viene a mí jamás tendrá hambre; el que cree en mí jamás tendrá sed.","Pero ya les he dicho: ustedes me han visto y sin embargo no creen.","Todo lo que me da el Padre viene a mí, y al que venga a mí yo no lo rechazaré,","porque he bajado del cielo, no para hacer mi voluntad, sino la del que me envió.","La voluntad del que me ha enviado es que yo no pierda nada de lo que él me dio, sino que lo resucite en el último día.","Esta es la voluntad de mi Padre: que el que ve al Hijo y cree en él, tenga Vida eterna y que yo lo resucite en el último día».","Los judíos murmuraban de él, porque había dicho: «Yo soy el pan bajado del cielo».","Y decían: «¿Acaso este no es Jesús, el hijo de José? Nosotros conocemos a su padre y a su madre. ¿Cómo puede decir ahora: «Yo he bajado del cielo»?","Jesús tomó la palabra y les dijo: «No murmuren entre ustedes.","Nadie puede venir a mí, si no lo atrae el Padre que me envió; y yo lo resucitaré en el último día.","Está escrito en el libro de los Profetas: \"Todos serán instruidos por Dios\". Todo el que oyó al Padre y recibe su enseñanza, viene a mí.","Nadie ha visto nunca al Padre, sino el que viene de Dios: sólo él ha visto al Padre.","Les aseguro que el que cree, tiene Vida eterna.","Yo soy el pan de Vida.","Sus padres, en el desierto, comieron el maná y murieron.","Pero este es el pan que desciende del cielo, para que aquel que lo coma no muera.","Yo soy el pan vivo bajado del cielo. El que coma de este pan vivirá eternamente, y el pan que yo daré es mi carne para la Vida del mundo».","Los judíos discutían entre sí, diciendo: «¿Cómo este hombre puede darnos a comer su carne?».","Jesús les respondió: «Les aseguro que si no comen la carne del Hijo del hombre y no beben su sangre, no tendrán Vida en ustedes.","El que come mi carne y bebe mi sangre tiene Vida eterna, y yo lo resucitaré en el último día.","Porque mi carne es la verdadera comida y mi sangre, la verdadera bebida.","El que come mi carne y bebe mi sangre permanece en mí y yo en él.","Así como yo, que he sido enviado por el Padre que tiene Vida, vivo por el Padre, de la misma manera, el que me come vivirá por mí.","Este es el pan bajado del cielo; no como el que comieron sus padres y murieron. El que coma de este pan vivirá eternamente».","Jesús enseñaba todo esto en la sinagoga de Cafarnaúm.","Después de oírlo, muchos de sus discípulos decían: «¡Es duro este lenguaje! ¿Quién puede escucharlo?».","Jesús, sabiendo lo que sus discípulos murmuraban, les dijo: «¿Esto los escandaliza?","¿Qué pasará entonces, cuando vean al Hijo del hombre subir donde estaba antes?","El Espíritu es el que da Vida, la carne de nada sirve. Las palabras que les dije son Espíritu y Vida.","Pero hay entre ustedes algunos que no creen». En efecto, Jesús sabía desde el primer momento quiénes eran los que no creían y quién era el que lo iba a entregar.","Y agregó: «Por eso les he dicho que nadie puede venir a mí, si el Padre no se lo concede».","Desde ese momento, muchos de sus discípulos se alejaron de él y dejaron de acompañarlo.","Jesús preguntó entonces a los Doce: «¿También ustedes quieren irse?».","Simón Pedro le respondió: «Señor, ¿a quién iremos? Tú tienes palabras de Vida eterna.","Nosotros hemos creído y sabemos que eres el Santo de Dios».","Jesús continuó: «¿No soy yo, acaso, el que los eligió a ustedes, los Doce? Sin embargo, uno de ustedes es un demonio».","Jesús hablaba de Judas, hijo de Simón Iscariote, que era uno de los Doce, el que lo iba a entregar."],["Después de esto, Jesús recorría la Galilea; no quería transitar por Judea porque los judíos intentaban matarlo.","Se acercaba la fiesta judía de las Chozas,","y sus hermanos le dijeron: «No te quedes aquí; ve a Judea, para que también tus discípulos de allí vean las obras que haces.","Cuando uno quiere hacerse conocer, no actúa en secreto; ya que tú haces estas cosas, manifiéstate al mundo».","Efectivamente, ni sus propios hermanos creían en él.","Jesús les dijo: «Mi tiempo no ha llegado todavía, mientras que para ustedes cualquier tiempo es bueno.","El mundo no tiene por qué odiarlos a ustedes; me odia a mí, porque atestiguo contra él que sus obras son malas.","Suban ustedes para la fiesta. Yo no subo a esa fiesta, porque mi tiempo no se ha cumplido todavía».","Después de decirles esto, permaneció en Galilea.","Sin embargo, cuando sus hermanos subieron para la fiesta, también él subió, pero en secreto, sin hacerse ver.","Los judíos lo buscaban durante la fiesta y decían: «¿Dónde está ese?».","Jesús era el comentario de la multitud. Unos opinaban: «Es un hombre de bien». Otros, en cambio, decían: «No, engaña al pueblo».","Sin embargo, nadie hablaba de él abiertamente, por temor a los judíos.","Promediaba ya la celebración de la fiesta, cuando Jesús subió al Templo y comenzó a enseñar.","Los judíos, admirados, decían: «¿Cómo conoce las Escrituras sin haber estudiado?».","Jesús les respondió: «Mi enseñanza no es mía sino de aquel que me envió.","El que quiere hacer la voluntad de Dios conocerá si esta enseñanza es de Dios o si yo hablo por mi cuenta.","El que habla por su cuenta busca su propia gloria, pero el que busca la gloria de aquel que lo envió, ese dice la verdad y no hay nada de falso en él.","¿Acaso Moisés no les dio la Ley? Pero ninguno de ustedes la cumple. ¿Por qué quieren matarme?».","La multitud respondió: «Estás poseído por el demonio: ¿quién quiere matarte?».","Jesús continuó: «Por una sola obra que realicé, ustedes están maravillados.","Moisés les dio la circuncisión –aunque ella no viene de Moisés, sino de los patriarcas– y ustedes la practican también en sábado.","Si se circuncida a un hombre en sábado para no quebrantar la Ley de Moisés, ¿cómo ustedes se enojan conmigo porque he curado completamente a un hombre en sábado?","No juzguen según las apariencias, sino conforme a la justicia».","Algunos de Jerusalén decían: «¿No es este aquel a quien querían matar?","¡Y miren como habla abiertamente y nadie le dice nada! ¿Habrán reconocido las autoridades que es verdaderamente el Mesías?","Pero nosotros sabemos de dónde es este; en cambio, cuando venga el Mesías, nadie sabrá de dónde es».","Entonces Jesús, que enseñaba en el Templo, exclamó: «¿Así que ustedes me conocen y saben de dónde soy? Sin embargo, yo no vine por mi propia cuenta; pero el que me envió dice la verdad, y ustedes no lo conocen.","Yo sí lo conozco, porque vengo de él y es él el que me envió».","Entonces quisieron detenerlo, pero nadie puso las manos sobre él, porque todavía no había llegado su hora.","Muchos de la multitud creyeron en él y decían: «Cuando venga el Mesías, ¿podrá hacer más signos de los que hace este hombre?».","Llegó a oídos de los fariseos lo que la gente comentaba de él, y enviaron guardias para detenerlo.","Después Jesús dijo: «Poco tiempo estaré aún con ustedes y me iré a aquel que me envió","Me buscarán y no me encontrarán, porque allí donde yo estoy ustedes no pueden venir».","Los judíos comentaban entre ellos: «¿A dónde irá, para que no podamos encontrarlo? ¿Acaso irá a reunirse con los judíos dispersos entre los paganos, para enseñar a los paganos?","¿Qué quiso decir con estas palabras: «Me buscarán y no me encontrarán, y allí donde yo estoy ustedes no pueden venir»?.","El último día, el más solemne de la fiesta, Jesús, poniéndose de pie, exclamó: «El que tenga sed, venga a mí; y beba","el que cree en mí». Como dice la Escritura: \"De su seno brotarán manantiales de agua viva\".","El se refería al Espíritu que debían recibir los que creyeran en él. Porque el Espíritu no había sido dado todavía, ya que Jesús aún no había sido glorificado.","Algunos de la multitud que lo habían oído, opinaban: «Este es verdaderamente el Profeta».","Otros decían: «Este es el Mesías». Pero otros preguntaban: «¿Acaso el Mesías vendrá de Galilea?","¿No dice la Escritura que el Mesías vendrá del linaje de David y de Belén, el pueblo de donde era David?».","Y por causa de él, se produjo una división entre la gente.","Algunos querían detenerlo, pero nadie puso las manos sobre él.","Los guardias fueron a ver a los sumos sacerdotes y a los fariseos, y estos les preguntaron: «¿Por qué no lo trajeron?».","Ellos respondieron: «Nadie habló jamás como este hombre».","Los fariseos respondieron: «¿También ustedes se dejaron engañar?","¿Acaso alguno de los jefes o de los fariseos ha creído en él?","En cambio, esa gente que no conoce la Ley está maldita».","Nicodemo, uno de ellos, que había ido a ver a Jesús, les dijo:","«¿Acaso nuestra Ley permite juzgar a un hombre sin escucharlo antes para saber lo que hizo?».","Le respondieron: «¿Tú también eres galileo? Examina las Escrituras y verás que de Galilea no surge ningún profeta».","Y cada uno regresó a su casa."],["Jesús fue al monte de los Olivos.","Al amanecer volvió al Templo, y todo el pueblo acudía a el. Entonces se sentó y comenzó a enseñarles.","Los escribas y los fariseos le trajeron a una mujer que había sido sorprendida en adulterio y, poniéndola en medio de todos,","dijeron a Jesús: «Maestro, esta mujer ha sido sorprendida en flagrante adulterio.","Moisés, en la Ley, nos ordenó apedrear a esta clase de mujeres. Y tú, ¿qué dices?».","Decían esto para ponerlo a prueba, a fin de poder acusarlo. Pero Jesús, inclinándose, comenzó a escribir en el suelo con el dedo.","Como insistían, se enderezó y les dijo: «El que no tenga pecado, que arroje la primera piedra».","E inclinándose nuevamente, siguió escribiendo en el suelo.","Al oír estas palabras, todos se retiraron, uno tras otro, comenzando por los más ancianos. Jesús quedó solo con la mujer, que permanecía allí,","e incorporándose, le preguntó: «Mujer, ¿dónde están tus acusadores? ¿Alguien te ha condenado?».","Ella le respondió: «Nadie, Señor». «Yo tampoco te condeno, le dijo Jesús. Vete, no peques más en adelante».","Jesús les dirigió una vez más la palabra, diciendo: «Yo soy la luz del mundo. El que me sigue no andará en tinieblas, sino que tendrá la luz de la Vida».","Los fariseos le dijeron: «Tú das testimonio de ti mismo: tu testimonio no vale».","Jesús les respondió: «Aunque yo doy testimonio de mí, mi testimonio vale porque sé de dónde vine y a dónde voy; pero ustedes no saben de dónde vengo ni a dónde voy.","Ustedes juzgan según la carne; yo no juzgo a nadie,","y si lo hago, mi juicio vale porque no soy yo solo el que juzga, sino yo y el Padre que me envió.","En la Ley de ustedes está escrito que el testimonio de dos personas es válido.","Yo doy testimonio de mí mismo, y también el Padre que me envió da testimonio de mí».","Ellos le preguntaron: «¿Dónde está tu Padre?». Jesús respondió: «Ustedes no me conocen ni a mí ni a mi Padre; si me conocieran a mí, conocerían también a mi Padre».","El pronunció estas palabras en la sala del Tesoro, cuando enseñaba en el Templo. Y nadie lo detuvo, porque aún no había llegado su hora.","Jesús les dijo también: «Yo me voy, y ustedes me buscarán y morirán en su pecado. Adonde yo voy, ustedes no pueden ir».","Los judíos se preguntaban: «¿Pensará matarse para decir: «Adonde yo voy, ustedes no pueden ir»?","Jesús continuó: «Ustedes son de aquí abajo, yo soy de lo alto. Ustedes son de este mundo, yo no soy de este mundo.","Por eso les he dicho: \"Ustedes morirán en sus pecados\". Porque si no creen que Yo Soy, morirán en sus pecados».","Los judíos le preguntaron: «¿Quién eres tú?». Jesús les respondió: «Esto es precisamente lo que les estoy diciendo desde el comienzo.","De ustedes, tengo mucho que decir, mucho que juzgar. Pero aquel que me envió es veraz, y lo que aprendí de él es lo que digo al mundo».","Ellos no comprendieron que Jesús se refería al Padre.","Después les dijo: «Cuando ustedes hayan levantado en alto al Hijo del hombre, entonces sabrán que Yo Soy y que no hago nada por mí mismo, sino que digo lo que el Padre me enseñó.","El que me envió está conmigo y no me ha dejado solo, porque yo hago siempre lo que le agrada».","Mientras hablaba así, muchos creyeron en él.","Jesús dijo a aquellos judíos que habían creído en él: «Si ustedes permanecen fieles a mi palabra, serán verdaderamente mis discípulos:","conocerán la verdad y la verdad los hará libres».","Ellos le respondieron: «Somos descendientes de Abraham y jamás hemos sido esclavos de nadie. ¿Cómo puedes decir entonces: \"Ustedes serán libres\"»?.","Jesús les respondió: «Les aseguro que todo el que peca es esclavo del pecado.","El esclavo no permanece para siempre en la casa; el hijo, en cambio, permanece para siempre.","Por eso, si el Hijo los libera, ustedes serán realmente libres.","Yo sé que ustedes son descendientes de Abraham, pero tratan de matarme porque mi palabra no penetra en ustedes.","Yo digo lo que he visto junto a mi Padre, y ustedes hacen lo que han aprendido de su padre».","Ellos le replicaron: «Nuestro padre es Abraham». Y Jesús les dijo: «Si ustedes fueran hijos de Abraham obrarían como él.","Pero ahora quieren matarme a mí, al hombre que les dice la verdad que ha oído de Dios. Abraham no hizo eso.","Pero ustedes obran como su padre». Ellos le dijeron: «Nosotros no hemos nacido de la prostitución; tenemos un solo Padre, que es Dios». Jesús prosiguió:","«Si Dios fuera su Padre, ustedes me amarían, porque yo he salido de Dios y vengo de él. No he venido por mí mismo, sino que él me envió.","¿Por qué ustedes no comprenden mi lenguaje? Es porque no pueden escuchar mi palabra.","Ustedes tienen por padre al demonio y quieren cumplir los deseos de su padre. Desde el comienzo él fue homicida y no tiene nada que ver con la verdad, porque no hay verdad en él. Cuando miente, habla conforme a lo que es, porque es mentiroso y padre de la mentira.","Pero a mí no me creen, porque les digo la verdad.","¿Quién de ustedes probará que tengo pecado? Y si les digo la verdad. ¿por qué no me creen?","El que es de Dios escucha las palabras de Dios; si ustedes no las escuchan, es porque no son de Dios».","Los judíos le replicaron: «¿No tenemos razón al decir que eres un samaritano y que estás endemoniado?». Jesús respondió:","«Yo no estoy endemoniado, sino que honro a mi Padre, y ustedes me deshonran a mí.","Yo no busco mi gloria; hay alguien que la busca, y es él el que juzga.","Les aseguro que el que es fiel a mi palabra, no morirá jamás».","Los judíos le dijeron: «Ahora sí estamos seguros de que estás endemoniado. Abraham murió, los profetas también, y tú dices: «El que es fiel a mi palabra, no morirá jamás».","¿Acaso eres más grande que nuestro padre Abraham, el cual murió? Los profetas también murieron. ¿Quién pretendes ser tú?»","Jesús respondió: «Si yo me glorificara a mí mismo, mi gloria no valdría nada. Es mi Padre el que me glorifica, el mismo al que ustedes llaman «nuestro Dios»,","y al que, sin embargo, no conocen. Yo lo conozco y si dijera: «No lo conozco», sería, como ustedes, un mentiroso. Pero yo lo conozco y soy fiel a su palabra.","Abraham, el padre de ustedes, se estremeció de gozo, esperando ver mi Día: lo vio y se llenó de alegría».","Los judíos le dijeron: «Todavía no tienes cincuenta años ¿y has visto a Abraham».","Jesús respondió: «Les aseguro que desde antes que naciera Abraham, Yo Soy».","Entonces tomaron piedras para apedrearlo, pero Jesús se escondió y salió del Templo."],["Al pasar, vio a un hombre ciego de nacimiento.","Sus discípulos le preguntaron: «Maestro, ¿quién ha pecado, él o sus padres, para que haya nacido ciego?».","«Ni él ni sus padres han pecado, respondió Jesús; nació así para que se manifiesten en él las obras de Dios.","Debemos trabajar en las obras de aquel que me envió, mientras es de día; llega la noche, cuando nadie puede trabajar.","Mientras estoy en el mundo, soy la luz del mundo»","Después que dijo esto, escupió en la tierra, hizo barro con la saliva y lo puso sobre los ojos del ciego,","diciéndole: «Ve a lavarte a la piscina de Siloé», que significa \"Enviado\". El ciego fue, se lavó y, al regresar, ya veía.","Los vecinos y los que antes lo habían visto mendigar, se preguntaban: «¿No es este el que se sentaba a pedir limosna?».","Unos opinaban: «Es el mismo». «No, respondían otros, es uno que se le parece». El decía: «Soy realmente yo».","Ellos le dijeron: «¿Cómo se te han abierto los ojos?».","El respondió: «Ese hombre que se llama Jesús hizo barro, lo puso sobre mis ojos y me dijo: «Ve a lavarte a Siloé». Yo fui, me lavé y vi».","Ellos le preguntaron: «¿Dónde está?». El respondió: «No lo sé».","El que había sido ciego fue llevado ante los fariseos.","Era sábado cuando Jesús hizo barro y le abrió los ojos.","Los fariseos, a su vez, le preguntaron cómo había llegado a ver. El les respondió: «Me puso barro sobre los ojos, me lavé y veo».","Algunos fariseos decían: «Ese hombre no viene de Dios, porque no observa el sábado». Otros replicaban: «¿Cómo un pecador puede hacer semejantes signos?». Y se produjo una división entre ellos.","Entonces dijeron nuevamente al ciego: «Y tú, ¿qué dices del que te abrió los ojos?». El hombre respondió: «Es un profeta».","Sin embargo, los judíos no querían creer que ese hombre había sido ciego y que había llegado a ver, hasta que llamaron a sus padres","y les preguntaron: «¿Es este el hijo de ustedes, el que dicen que nació ciego? ¿Cómo es que ahora ve?».","Sus padres respondieron: «Sabemos que es nuestro hijo y que nació ciego,","pero cómo es que ahora ve y quién le abrió los ojos, no lo sabemos. Pregúntenle a él: tiene edad para responder por su cuenta».","Sus padres dijeron esto por temor a los judíos, que ya se habían puesto de acuerdo para excluir de la sinagoga al que reconociera a Jesús como Mesías.","Por esta razón dijeron: «Tiene bastante edad, pregúntenle a él».","Los judíos llamaron por segunda vez al que había sido ciego y le dijeron: «Glorifica a Dios. Nosotros sabemos que ese hombre es un pecador».","«Yo no sé si es un pecador, respondió; lo que sé es que antes yo era ciego y ahora veo».","Ellos le preguntaron: «¿Qué te ha hecho? ¿Cómo te abrió los ojos?».","El les respondió: «Ya se lo dije y ustedes no me han escuchado. ¿Por qué quieren oírlo de nuevo? ¿También ustedes quieren hacerse discípulos suyos?».","Ellos lo injuriaron y le dijeron: «¡Tú serás discípulo de ese hombre; nosotros somos discípulos de Moisés!","Sabemos que Dios habló a Moisés, pero no sabemos de dónde es este».","El hombre les respondió: «Esto es lo asombroso: que ustedes no sepan de dónde es, a pesar de que me ha abierto los ojos.","Sabemos que Dios no escucha a los pecadores, pero si al que lo honra y cumple su voluntad.","Nunca se oyó decir que alguien haya abierto los ojos a un ciego de nacimiento.","Si este hombre no viniera de Dios, no podría hacer nada».","Ellos le respondieron: «Tú naciste lleno de pecado, y ¿quieres darnos lecciones?». Y lo echaron.","Jesús se enteró de que lo habían echado y, al encontrarlo, le preguntó: «¿Crees en el Hijo del hombre?».","El respondió: «¿Quién es, Señor, para que crea en él?».","Jesús le dijo: «Tú lo has visto: es el que te está hablando».","Entonces él exclamó: «Creo, Señor», y se postró ante él.","Después Jesús agregó: «He venido a este mundo para un juicio: Para que vean los que no ven y queden ciegos los que ven».","Los fariseos que estaban con él oyeron esto y le dijeron: «¿Acaso también nosotros somos ciegos?».","Jesús les respondió: «Si ustedes fueran ciegos, no tendrían pecado, pero como dicen: \"Vemos\", su pecado permanece»."],["«Les aseguro que el que no entra por la puerta en el corral de las ovejas, sino por otro lado, es un ladrón y un asaltante.","El que entra por la puerta es el pastor de las ovejas.","El guardián le abre y las ovejas escuchan su voz. El llama a cada una por su nombre y las hace salir.","Cuando las ha sacado a todas, va delante de ellas y las ovejas lo siguen, porque conocen su voz.","Nunca seguirán a un extraño, sino que huirán de él, porque no conocen su voz».","Jesús les hizo esta comparación, pero ellos no comprendieron lo que les quería decir.","Entonces Jesús prosiguió: «Les aseguro que yo soy la puerta de las ovejas.","Todos aquellos que han venido antes de mí son ladrones y asaltantes, pero las ovejas no los han escuchado.","Yo soy la puerta. El que entra por mí se salvará; podrá entrar y salir, y encontrará su alimento","El ladrón no viene sino para robar, matar y destruir. Pero yo he venido para que las ovejas tengan Vida, y la tengan en abundancia.","Yo soy el buen Pastor. El buen Pastor da su vida por las ovejas.","El asalariado, en cambio, que no es el pastor y al que no pertenecen las ovejas, cuando ve venir al lobo las abandona y huye. y el lobo las arrebata y la dispersa.","Como es asalariado, no se preocupa por las ovejas.","Yo soy el buen Pastor: conozco a mis ovejas, y mis ovejas me conocen a mí","–como el Padre me conoce a mí y yo conozco al Padre– y doy mi vida por las ovejas.","Tengo, además, otras ovejas que no son de este corral y a las que debo también conducir: ellas oirán mi voz, y así habrá un solo Rebaño y un solo Pastor.","El Padre me ama porque yo doy mi vida para recobrarla.","Nadie me la quita, sino que la doy por mí mismo. Tengo el poder de darla y de recobrarla: este es el mandato que recibí de mi Padre».","A causa de estas palabras, se produjo una nueva división entre los judíos.","Muchos de ellos decían: «Está poseído por un demonio y delira. ¿Por qué lo escuchan?».","Otros opinaban: «Estas palabras no son de un endemoniado. ¿Acaso un demonio puede abrir los ojos a los ciegos?».","Se celebraba entonces en Jerusalén la fiesta de la Dedicación. Era invierno,","y Jesús se paseaba por el Templo, en el Pórtico de Salomón.","Los Judíos lo rodearon y le preguntaron: «¿Hasta cuándo nos tendrás en suspenso? Si eres el Mesías, dilo abiertamente».","Jesús les respondió: «Ya se lo dije, pero ustedes no lo creen. Las obras que hago en nombre de mi Padre dan testimonio de mí,","pero ustedes no creen, porque no son de mis ovejas.","Mis ovejas escuchan mi voz, yo las conozco y ellas me siguen.","Yo les doy Vida eterna: ellas no perecerán jamás y nadie las arrebatará de mis manos.","Mi Padre, que me las ha dado, es superior a todos y nadie puede arrebatar nada de las manos de mi Padre.","El Padre y yo somos una sola cosa».","Los judíos tomaron piedras para apedrearlo.","Entonces Jesús dijo: «Les hice ver muchas obras buenas que vienen del Padre; ¿Por cuál de ellas me quieren apedrear?».","Los judíos le respondieron: «No queremos apedrearte por ninguna obra buena, sino porque blasfemas, ya que, siendo hombre, te haces Dios».","Jesús les respondió: «¿No está escrito en la Ley: \"Yo dije: Ustedes son dioses\"?","Si la Ley llama dioses a los que Dios dirigió su Palabra –y la Escritura no puede ser anulada–","¿Cómo dicen: \"Tú blasfemas\", a quien el Padre santificó y envió al mundo, porque dijo: \"Yo soy Hijo de Dios\"?","Si no hago las obras de mi Padre, no me crean;","pero si las hago, crean en las obras, aunque no me crean a mí. Así reconocerán y sabrán que el Padre está en mí y yo en el Padre».","Ellos intentaron nuevamente detenerlo, pero el se les escapó de las manos.","Jesús volvió a ir al otro lado del Jordán, al lugar donde Juan había bautizado, y se quedó allí.","Muchos fueron a verlo, y la gente decía: «Juan no ha hecho ningún signo, pero todo lo que dijo de este hombre era verdad».","Y en ese lugar muchos creyeron en él."],["Había un hombre enfermo, Lázaro de Betania, del pueblo de María y de su hermana Marta.","María era la misma que derramó perfume sobre el Señor y le secó los pies con sus cabellos. Su hermano Lázaro era el que estaba enfermo.","Las hermanas enviaron a decir a Jesús: «Señor, el que tú amas, está enfermo».","Al oír esto, Jesús dijo: «Esta enfermedad no es mortal; es para gloria de Dios, para que el Hijo de Dios sea glorificado por ella».","Jesús quería mucho a Marta, a su hermana y a Lázaro.","Sin embargo, cuando oyó que este se encontraba enfermo, se quedó dos días más en el lugar donde estaba.","Después dijo a sus discípulos: «Volvamos a Judea».","Los discípulos le dijeron: «Maestro, hace poco los judíos querían apedrearte, ¿quieres volver allá?».","Jesús les respondió: «¿Acaso no son doce las horas del día? El que camina de día no tropieza, porque ve la luz de este mundo;","en cambio, el que camina de noche tropieza, porque la luz no está en él».","Después agregó: «Nuestro amigo Lázaro duerme, pero yo voy a despertarlo».","Sus discípulos le dijeron: «Señor, si duerme, se curará».","Ellos pensaban que hablaba del sueño, pero Jesús se refería a la muerte.","Entonces les dijo abiertamente: «Lázaro ha muerto,","y me alegro por ustedes de no haber estado allí, a fin de que crean. Vayamos a verlo».","Tomás, llamado el Mellizo, dijo a los otros discípulos: «Vayamos también nosotros a morir con él».","Cuando Jesús llegó, se encontró con que Lázaro estaba sepultado desde hacía cuatro Días.","Betania distaba de Jerusalén sólo unos tres kilómetros.","Muchos judíos habían ido a consolar a Marta y a María, por la muerte de su hermano.","Al enterarse de que Jesús llegaba, Marta salió a su encuentro, mientras María permanecía en la casa.","Marta dio a Jesús: «Señor, si hubieras estado aquí, mi hermano no habría muerto.","Pero yo sé que aun ahora, Dios te concederá todo lo que le pidas».","Jesús le dijo: «Tu hermano resucitará».","Marta le respondió: «Sé que resucitará en la resurrección del último día».","Jesús le dijo: «Yo soy la Resurrección y la Vida. El que cree en mí, aunque muera, vivirá:","y todo el que vive y cree en mí, no morirá jamás. ¿Crees esto?».","Ella le respondió: «Sí, Señor, creo que tú eres el Mesías, el Hijo de Dios, el que debía venir al mundo».","Después fue a llamar a María, su hermana, y le dijo en voz baja: «El Maestro está aquí y te llama».","Al oír esto, ella se levantó rápidamente y fue a su encuentro.","Jesús no había llegado todavía al pueblo, sino que estaba en el mismo sitio donde Marta lo había encontrado.","Los Judíos que estaban en la casa consolando a María, al ver que esta se levantaba de repente y salía, la siguieron, pensando que iba al sepulcro para llorar allí.","María llegó adonde estaba Jesús y, al verlo, se postró a sus pies y le dijo: «Señor, si hubieras estado aquí, mi hermano no habría muerto».","Jesús, al verla llorar a ella, y también a los judíos que la acompañaban, conmovido y turbado,","preguntó: «¿Dónde lo pusieron?». Le respondieron: «Ven, Señor, y lo verás».","Y Jesús lloró.","Los judíos dijeron: «¡Cómo lo amaba!».","Pero algunos decían: «Este que abrió los ojos del ciego de nacimiento, ¿no podría impedir que Lázaro muriera?».","Jesús, conmoviéndose nuevamente, llegó al sepulcro, que era una cueva con una piedra encima,","y le dijo: «Quiten la piedra». Marta, la hermana del difunto, le respondió: «Señor, huele mal; ya hace cuatro días que está muerto».","Jesús le dijo: «¿No te he dicho que si crees, verás la gloria de Dios?».","Entonces quitaron la piedra, y Jesús, levantando los ojos al cielo, dijo: «Padre, te doy gracias porque me oíste.","Yo sé que siempre me oyes, pero le he dicho por esta gente que me rodea, para que crean que tú me has enviado».","Después de decir esto, gritó con voz fuerte: «¡Lázaro, ven afuera!».","El muerto salió con los pies y las manos atados con vendas, y el rostro envuelto en un sudario. Jesús les dijo: «Desátenlo para que pueda caminar».","Al ver lo que hizo Jesús, muchos de los judíos que habían ido a casa de María creyeron en él.","Pero otros fueron a ver a los fariseos y les contaron lo que Jesús había hecho.","Los sumos sacerdotes y los fariseos convocaron un Consejo y dijeron: «¿Qué hacemos? Porque este hombre realiza muchos signos.","Si lo dejamos seguir así, todos creerán en él, y los romanos vendrán y destruirán nuestro Lugar santo y nuestra nación».","Uno de ellos, llamado Caifás, que era Sumo Sacerdote ese año, les dijo: «Ustedes no comprenden nada.","¿No les parece preferible que un solo hombre muera por el pueblo y no que perezca la nación entera?».","No dijo eso por sí mismo, sino que profetizó como Sumo Sacerdote que Jesús iba a morir por la nación,","y no solamente por la nación, sino también para congregar en la unidad a los hijos de Dios que estaban dispersos.","A partir de ese día, resolvieron que debían matar a Jesús.","Por eso él no se mostraba más en público entre los judíos, sino que fue a una región próxima al desierto, a una ciudad llamada Efraím, y allí permaneció con sus discípulos.","Como se acercaba la Pascua de los judíos, mucha gente de la región había subido a Jerusalén para purificarse.","Buscaban a Jesús y se decían unos a otros en el Templo: «¿Qué les parece, vendrá a la fiesta o no?».","Los sumos sacerdotes y los fariseos habían dado orden de que si alguno conocía el lugar donde él se encontraba, lo hiciera saber para detenerlo."],["Seis días antes de la Pascua, Jesús volvió a Betania, donde estaba Lázaro, al que había resucitado.","Allí le prepararon una cena: Marta servía y Lázaro era uno de los comensales.","María, tomando una libra de perfume de nardo puro, de mucho precio, ungió con él los pies de Jesús y los secó con sus cabellos. La casa se impregnó con la fragancia del perfume.","Judas Iscariote, uno de sus discípulos, el que lo iba a entregar, dijo:","«¿Por qué no se vendió este perfume en trescientos denarios para dárselos a los pobres?».","Dijo esto, no porque se interesaba por los pobres, sino porque era ladrón y, como estaba encargado de la bolsa común, robaba lo que se ponía en ella.","Jesús le respondió: «Déjala. Ella tenía reservado este perfume para el día de mi sepultura.","A los pobres los tienen siempre con ustedes, pero a mí no me tendrán siempre».","Entre tanto, una gran multitud de judíos se enteró de que Jesús estaba allí, y fueron, no sólo por Jesús, sino también para ver a Lázaro, al que había resucitado.","Entonces los sumos sacerdotes resolvieron matar también a Lázaro,","porque muchos judíos se apartaban de ellos y creían en Jesús a causa de él.","Al día siguiente, la gran multitud que había venido para la fiesta, se enteró de que Jesús se dirigía a Jerusalén.","Y, tomando hojas de palmera, salieron a su encuentro y lo aclamaban diciendo: «¡Hosana! ¡Bendito el que viene en nombre del Señor, el rey de Israel!».","Al encontrar un asno, Jesús montó sobre él, conforme a lo que está escrito:","\"No temas, hija de Sión; ya viene tu rey, montado sobre la cría de una asna\".","Al comienzo, sus discípulos no comprendieron esto. Pero cuando Jesús fue glorificado, recordaron que todo lo que le había sucedido era lo que estaba escrito acerca de él.","La multitud que había estado con Jesús cuando ordenó a Lázaro que saliera del sepulcro y lo resucitó, daba testimonio de él.","Por eso la gente salió a su encuentro, porque se enteraron del signo que había realizado.","Los fariseos se dijeron unos a otros: «¿Ven que no adelantamos nada? Todo el mundo lo sigue».","Entre los que había subido para adorar durante la fiesta, había unos griegos","que se acercaron a Felipe, el de Betsaida de Galilea, y le dijeron: «Señor, queremos ver a Jesús».","Felipe fue a decírselo a Andrés, y ambos se lo dijeron a Jesús.","El les respondió: «Ha llegado la hora en que el Hijo del hombre va a ser glorificado.","Les aseguro que si el grano de trigo que cae en la tierra no muere, queda solo; pero si muere, da mucho fruto.","El que tiene apego a su vida la perderá; y el que no está apegado a su vida en este mundo, la conservará para la Vida eterna.","El que quiera servirme que me siga, y donde yo esté, estará también mi servidor. El que quiera servirme, será honrado por mi Padre.","Mi alma ahora está turbada, ¿Y qué diré: «Padre, líbrame de esta hora? ¡Sí, para eso he llegado a esta hora!","¡Padre, glorifica tu Nombre!». Entonces se oyó una voz del cielo: «Ya lo he glorificado y lo volveré a glorificar».","La multitud que estaba presente y oyó estas palabras, pensaba que era un trueno. Otros decían: «Le ha hablado un ángel».","Jesús respondió: «Esta voz no se oyó por mí, sino por ustedes.","Ahora ha llegado el juicio de este mundo, ahora el Príncipe de este mundo será arrojado afuera;","y cuando yo sea levantado en alto sobre la tierra, atraeré a todos hacia mí».","Jesús decía esto para indicar cómo iba a morir.","La multitud le respondió: «Sabemos por la Ley que el Mesías permanecerá para siempre. ¿Cómo puedes decir: «Es necesario que el Hijo del hombre sea levantado en alto»? ¿Quién es ese Hijo del hombre?».","Jesús les respondió: «La luz está todavía entre ustedes, pero por poco tiempo. Caminen mientras tengan la luz, no sea que las tinieblas los sorprendan: porque el que camina en tinieblas no sabe a dónde va.","Mientras tengan luz, crean en la luz y serán hijos de la luz». Después de hablarles así, Jesús se fue y se ocultó de ellos.","A pesar de los muchos signos que hizo en su presencia, ellos no creyeron en él.","Así debía cumplirse el oráculo del profeta Isaías, que dice: \"Señor, ¿quién ha creído en nuestra palabra? ¿A quién fue revelado el poder del Señor\"?","Ellos no podían creer, porque como dijo también Isaías:","\"El ha cegado sus ojos y ha endurecido su corazón, para que sus ojos no vean y su corazón no comprenda, para que no se conviertan ni yo los cure\".","Isaías dijo esto, porque vio la gloria de Jesús y habló acerca de él.","Sin embargo, muchos creyeron en él, aun entre las autoridades, pero a causa de los fariseos no lo manifestaron, para no ser expulsados de la sinagoga.","Preferían la gloria de los hombres a la gloria de Dios.","Jesús exclamó: «El que cree en mí, en realidad no cree en mí, sino en aquel que me envió.","Y el que me ve, ve al que me envió.","Yo soy la luz, y he venido al mundo para que todo el que crea en mí no permanezca en las tinieblas.","Al que escucha mis palabras y no las cumple, yo no lo juzgo, porque no vine a juzgar al mundo, sino a salvarlo.","El que me rechaza y no recibe mis palabras, ya tiene quien lo juzgue: la palabra que yo he anunciado es la que lo juzgará en el último día.","Porque yo no hablé por mí mismo: el Padre que me ha enviado me ordenó lo que debía decir y anunciar;","y yo sé que su mandato es Vida eterna. Las palabras que digo, las digo como el Padre me lo ordenó»."],["Antes de la fiesta de Pascua, sabiendo Jesús que había llegado la hora de pasar de este mundo al Padre, él, que había amado a los suyos que quedaban en el mundo, los amó hasta el fin.","Durante la Cena, cuando el demonio ya había inspirado a Judas Iscariote, hijo de Simón, el propósito de entregarlo,","sabiendo Jesús que el Padre había puesto todo en sus manos y que él había venido de Dios y volvía a Dios,","se levantó de la mesa, se sacó el manto y tomando una toalla se la ató a la cintura.","Luego echó agua en un recipiente y empezó a lavar los pies a los discípulos y a secárselos con la toalla que tenía en la cintura.","Cuando se acercó a Simón Pedro, este le dijo: «¿Tú, Señor, me vas a lavar los pies a mí?».","Jesús le respondió: «No puedes comprender ahora lo que estoy haciendo, pero después lo comprenderás».","«No, le dijo Pedro, ¡tú jamás me lavarás los pies a mí!». Jesús le respondió: «Si yo no te lavo, no podrás compartir mi suerte».","«Entonces, Señor, le dijo Simón Pedro, ¡no sólo los pies, sino también las manos y la cabeza!».","Jesús le dijo: «El que se ha bañado no necesita lavarse más que los pies, porque está completamente limpio. Ustedes también están limpios, aunque no todos».","El sabía quién lo iba a entregar, y por eso había dicho: «No todos ustedes están limpios».","Después de haberles lavado los pies, se puso el manto, volvió a la mesa y les dijo: «¿comprenden lo que acabo de hacer con ustedes?","Ustedes me llaman Maestro y Señor, y tienen razón, porque lo soy.","Si yo, que soy el Señor y el Maestro, les he lavado los pies, ustedes también deben lavarse los pies unos a otros.","Les he dado el ejemplo, para que hagan lo mismo que yo hice con ustedes.","Les aseguro que el servidor no es más grande que su señor, ni el enviado más grande que el que lo envía.","Ustedes serán felices si, sabiendo estas cosas, las practican.","No lo digo por todos ustedes; yo conozco a los que he elegido. Pero es necesario que se cumpla la Escritura que dice: El que comparte mi pan se volvió contra mí.","Les digo esto desde ahora, antes que suceda, para que cuando suceda, crean que Yo Soy.","Les aseguro que el que reciba al que yo envíe, me recibe a mí, y el que me recibe, recibe al que me envió».","Después de decir esto, Jesús se estremeció y manifestó claramente: «Les aseguro que uno de ustedes me entregará:.","Los discípulos se miraban unos a otros, no sabiendo a quién se refería.","Uno de ellos –el discípulo al que Jesús amaba– estaba reclinado muy cerca de Jesús.","Simón Pedro le hizo una seña y le dijo: «Pregúntale a quién se refiere».","El se reclinó sobre Jesús y le preguntó: «Señor, ¿quién es?».","Jesús le respondió: «Es aquel al que daré el bocado que voy a mojar en el plato». Y mojando un bocado, se lo dio a Judas, hijo de Simón Iscariote.","En cuanto recibió el bocado, Satanás entró en él. Jesús le dijo entonces: «Realiza pronto lo que tienes que hacer».","Pero ninguno de los comensales comprendió por qué le decía esto.","Como Judas estaba encargado de la bolsa común, algunos pensaban que Jesús quería decirle: «Compra lo que hace falta para la fiesta», o bien que le mandaba dar algo a los pobres.","Y en seguida, después de recibir el bocado, Judas salió. Ya era de noche.","Después que Judas salió, Jesús dijo: «Ahora el Hijo del hombre ha sido glorificado y Dios ha sido glorificado en él.","Si Dios ha sido glorificado en él, también lo glorificará en sí mismo, y lo hará muy pronto.","Hijos míos, ya no estaré mucho tiempo con ustedes. Ustedes me buscarán, pero yo les digo ahora lo mismo que dije a los judíos: «A donde yo voy, ustedes no pueden venir».","Les doy un mandamiento nuevo: ámense los unos a los otros. Así como yo los he amado, ámense también ustedes los unos a los otros.","En esto todos reconocerán que ustedes son mis discípulos: en el amor que se tengan los unos a los otros».","Simón Pedro le dijo: «Señor, ¿a dónde vas?». Jesús le respondió: «Adonde yo voy, tú no puedes seguirme ahora, pero más adelante me seguirás».","Pedro le preguntó: «¿Por qué no puedo seguirte ahora? Yo daré mi vida por ti».","Jesús le respondió: «¿Darás tu vida por mí? Te aseguro que no cantará el gallo antes que me hayas negado tres veces»."],["«No se inquieten. Crean en Dios y crean también en mí.","En la Casa de mi Padre hay muchas habitaciones; si no fuera así, se lo habría dicho a ustedes. Yo voy a prepararles un lugar.","Y cuando haya ido y les haya preparado un lugar, volveré otra vez para llevarlos conmigo, a fin de que donde yo esté, estén también ustedes.","Ya conocen el camino del lugar adonde voy».","Tomás le dijo: «Señor, no sabemos adónde vas. ¿Cómo vamos a conocer el camino?».","Jesús le respondió: «Yo soy el Camino, la Verdad y la Vida. Nadie va al Padre, sino por mí.","Si ustedes me conocen, conocerán también a mi Padre. Ya desde ahora lo conocen y lo han visto».","Felipe le dijo: «Señor, muéstranos al Padre y eso nos basta».","Jesús le respondió: «Felipe, hace tanto tiempo que estoy con ustedes, ¿y todavía no me conocen?. El que me ha visto, ha visto al Padre. ¿Como dices: «Muéstranos al Padre»?","¿No crees que yo estoy en el Padre y que el Padre está en mí? Las palabras que digo no son mías: el Padre que habita en mí es el que hace las obras.","Créanme: yo estoy en el Padre y el Padre está en mí. Créanlo, al menos, por las obras.","Les aseguro que el que cree en mí hará también las obras que yo hago, y aún mayores, porque yo me voy al Padre.","Y yo haré todo lo que ustedes pidan en mi Hombre, para que el Padre sea glorificado en el Hijo.","Si ustedes me piden algo en mi Nombre, yo lo haré.","Si ustedes me aman, cumplirán mis mandamientos.","Y yo rogaré al Padre, y él les dará otro Paráclito para que esté siempre con ustedes:","el Espíritu de la Verdad, a quien el mundo no puede recibir, porque no lo ve ni lo conoce. Ustedes, en cambio, lo conocen, porque él permanece con ustedes y estará en ustedes.","No los dejaré huérfanos, volveré a ustedes.","Dentro de poco el mundo ya no me verá, pero ustedes sí me verán, porque yo vivo y también ustedes vivirán.","Aquel día comprenderán que yo estoy en mi Padre, y que ustedes están en mí y yo en ustedes.","El que recibe mis mandamientos y los cumple, ese es el que me ama; y el que me ama será amado por mi Padre, y yo lo amaré y me manifestaré a él».","Judas –no el Iscariote– le dijo: «Señor, ¿por qué te vas a manifestar a nosotros y no al mundo?».","Jesús le respondió: «El que me ama será fiel a mi palabra, y mi Padre lo amará; iremos a él y habitaremos en él.","El que no me ama no es fiel a mis palabras. La palabra que ustedes oyeron no es mía, sino del Padre que me envió.","Yo les digo estas cosas mientras permanezco con ustedes.","Pero el Paráclito, el Espíritu Santo, que el Padre enviará en mi Nombre, les enseñará todo y les recordará lo que les he dicho.","Les dejo la paz, les doy mi paz, pero no como la da el mundo. ¡No se inquieten ni teman!","Me han oído decir: «Me voy y volveré a ustedes». Si me amaran, se alegrarían de que vuelva junto al Padre, porque el Padre es más grande que yo.","Les he dicho esto antes que suceda, para que cuando se cumpla, ustedes crean.","Ya no hablaré mucho más con ustedes, porque está por llegar el Príncipe de este mundo: él nada puede hacer contra mí,","pero es necesario que el mundo sepa que yo amo al Padre y obro como él me ha ordenado. Levántense, salgamos de aquí»."],["«Yo soy la verdadera vid y mi Padre es el viñador.","El corta todos mis sarmientos que no dan fruto; al que da fruto, lo poda para que dé más todavía.","Ustedes ya están limpios por la palabra que yo les anuncié.","Permanezcan en mí, como yo permanezco en ustedes. Así como el sarmiento no puede dar fruto si no permanece en la vid, tampoco ustedes, si no permanecen en mí.","Yo soy la vid, ustedes los sarmientos El que permanece en mí, y yo en él, da mucho fruto, porque separados de mí, nada pueden hacer.","Pero el que no permanece en mí, es como el sarmiento que se tira y se seca; después se recoge, se arroja al fuego y arde.","Si ustedes permanecen en mí y mis palabras permanecen en ustedes, pidan lo que quieran y lo obtendrán.","La gloria de mi Padre consiste en que ustedes den fruto abundante, y así sean mis discípulos.","Como el Padre me amó, también yo los he amado a ustedes. Permanezcan en mi amor.","Si cumplen mis mandamientos, permanecerán en mi amor. como yo cumplí los mandamientos de mi Padre y permanezco en su amor.","Les he dicho esto para que mi gozo sea el de ustedes, y ese gozo sea perfecto.","Este es mi mandamiento: Amense los unos a los otros, como yo los he amado.","No hay amor más grande que dar la vida por los amigos.","Ustedes son mis amigos si hacen lo que yo les mando.","Ya no los llamo servidores, porque el servidor ignora lo que hace su señor; yo los llamo amigos, porque les he dado a conocer todo lo que oí de mi Padre.","No son ustedes los que me eligieron a mí, sino yo el que los elegí a ustedes, y los destiné para que vayan y den fruto, y ese fruto sea duradero. Así todo lo que pidan al Padre en mi Nombre, él se lo concederá.","Lo que yo les mando es que se amen los unos a los otros.","Si el mundo los odia, sepan que antes me ha odiado a mí.","Si ustedes fueran del mundo, el mundo los amaría como cosa suya. Pero como no son del mundo, sino que yo los elegí y los saqué de él, él mundo los odia.","Acuérdense de lo que les dije: el servidor no es más grande que su señor. Si me persiguieron a mí, también los perseguirán a ustedes; si fueron fieles a mi palabra, también serán fieles a la de ustedes.","Pero los tratarán así a causa de mi Nombre, porque no conocen al que me envió.","Si yo hubiera venido ni les hubiera hablado, no tendrían pecado; pero ahora su pecado no tiene disculpa.","El que me odia, odia también a mi Padre.","Si yo no hubiera hecho entre ellos obras que ningún otro realizó, no tendrían pecado. Pero ahora las han visto, y sin embargo, me odian a mí y a mi Padre,","para que se cumpla lo que está escrito en la Ley: Me han odiado sin motivo.","Cuando venga el Paráclito que yo les enviaré desde el Padre, el Espíritu de la Verdad que proviene del Padre, él dará testimonio de mí.","Y ustedes también dan testimonio, porque están conmigo desde el principio»."],["«Les he dicho esto para que no se escandalicen.","Serán echados de las sinagogas, más aún, llegará la hora en que los mismos que les den muerte pensarán que tributan culto a Dios.","Y los tratarán así porque no han conocido ni al Padre ni a mí.","Les he advertido esto para que cuando llegue esa hora, recuerden que ya lo había dicho. No les dije estas cosas desde el principio, porque yo estaba con ustedes.","Ahora me voy al que me envió, y ninguno de ustedes me pregunta: «¿A dónde vas?».","Pero al decirles esto, ustedes se han entristecido.","Sin embargo, les digo la verdad: les conviene que yo me vaya, porque si no me voy, el Paráclito no vendrá a ustedes. Pero si me voy, se lo enviaré.","Y cuando él venga, probará al mundo dónde está el pecado, dónde está la justicia y cuál es el juicio.","El pecado está en no haber creído en mí.","La justicia, en que yo me voy al Padre y ustedes ya no me verán.","Y el juicio, en que el Príncipe de este mundo ya ha sido condenado.","Todavía tengo muchas cosas que decirles, pero ustedes no las pueden comprender ahora.","Cuando venga el Espíritu de la Verdad, él los introducirá en toda la verdad, porque no hablará por sí mismo, sino que dirá lo que ha oído y les anunciará lo que irá sucediendo.","El me glorificará, porque recibirá de lo mío y se lo anunciará a ustedes.","Todo lo que es del Padre es mío. Por eso les digo: «Recibirá de lo mío y se lo anunciará a ustedes».","Dentro de poco, ya no me verán, y poco después, me volverán a ver».","Entonces algunos de sus discípulos comentaban entre sí: «¿Qué significa esto que nos dice: «Dentro de poco ya no me verán, y poco después, me volverán a ver?».","Decían: «¿Qué es este poco de tiempo? No entendemos lo que quiere decir».","Jesús se dio cuenta de que deseaban interrogarlo y les dijo: «Ustedes se preguntan entre sí qué significan mis palabras: «Dentro de poco, ya no me verán, y poco después, me volverán a ver».","Les aseguro que ustedes van a llorar y se van a lamentar; el mundo, en cambio, se alegrará. Ustedes estarán tristes, pero esa tristeza se convertirá en gozo.","La mujer, cuando va a dar a luz, siente angustia porque le llegó la hora; pero cuando nace el niño, se olvida de su dolor, por la alegría que siente al ver que ha venido un hombre al mundo.","También ustedes ahora están tristes, pero yo los volveré a ver, y tendrán una alegría que nadie les podrá quitar.","Aquél día no me harán más preguntas. Les aseguro que todo lo que pidan al Padre, él se lo concederá en mi Nombre.","Hasta ahora, no han pedido nada en mi Nombre. Pidan y recibirán, y tendrán una alegría que será perfecta.","Les he dicho todo esto por medio de parábolas. Llega la hora en que ya no les hablaré por medio de parábolas, sino que les hablaré claramente del Padre.","Aquel día ustedes pedirán en mi Nombre; y no será necesario que yo ruegue al Padre por ustedes,","ya que él mismo los ama, porque ustedes me aman y han creído que yo vengo de Dios.","Salí del Padre y vine al mundo. Ahora dejo el mundo y voy al Padre».","Sus discípulos le dijeron: «Por fin hablas claro y sin parábolas.","Ahora conocemos que tú lo sabes todo y no hace falta hacerte preguntas. Por eso creemos que tú has salido de Dios».","Jesús les respondió: «¿Ahora creen?","Se acerca la hora, y ya ha llegado, en que ustedes se dispersarán cada uno por su lado, y me dejarán solo. Pero no, no estoy solo, porque el Padre está conmigo.","Les digo esto para que encuentren la paz en mí. En el mundo tendrán que sufrir; pero tengan valor: yo he vencido al mundo»."],["Después de hablar así, Jesús levantó los ojos al cielo, diciendo: «Padre, ha llegado la hora: glorifica a tu Hijo para que el Hijo te glorifique a ti,","ya que le diste autoridad sobre todos los hombres, para que él diera Vida eterna a todos los que tú les has dado.","Esta es la Vida eterna: que te conozcan a ti, el único Dios verdadero, y a tu Enviado, Jesucristo.","Yo te he glorificado en la tierra, llevando a cabo la obra que me encomendaste.","Ahora, Padre, glorifícame junto a ti, con la gloria que yo tenía contigo antes que el mundo existiera.","Manifesté tu Nombre a los que separaste del mundo para confiármelos. Eran tuyos y me los diste, y ellos fueron fieles a tu palabra.","Ahora saben que todo lo que me has dado viene de ti,","porque les comuniqué las palabras que tú me diste: ellos han reconocido verdaderamente que yo salí de ti, y han creído que tú me enviaste.","Yo ruego por ellos: no ruego por el mundo, sino por los que me diste, porque son tuyos.","Todo lo mío es tuyo y todo lo tuyo es mío, y en ellos he sido glorificado.","Ya no estoy más en el mundo, pero ellos están en él; y yo vuelvo a ti. Padre santo, cuida en tu Nombre a aquellos que me diste, para que sean uno, como nosotros.","Mientras estaba con ellos, cuidaba en tu Nombre a los que me diste; yo los protegía y no se perdió ninguno de ellos, excepto el que debía perderse, para que se cumpliera la Escritura.","Pero ahora voy a ti, y digo esto estando en el mundo, para que mi gozo sea el de ellos y su gozo sea perfecto.","Yo les comuniqué tu palabra, y el mundo los odió porque ellos no son del mundo, como tampoco yo soy del mundo.","No te pido que los saques del mundo, sino que los preserves del Maligno.","Ellos no son del mundo, como tampoco yo soy del mundo.","Conságralos en la verdad: tu palabra es verdad.","Así como tú me enviaste al mundo, yo también los envío al mundo.","Por ellos me consagro, para que también ellos sean consagrados en la verdad.","No ruego solamente por ellos, sino también por los que, gracias a su palabra, creerán en mí.","Que todos sean uno: como tú, Padre, estás en mí y yo en ti, que también ellos sean uno en nosotros, para que el mundo crea que tú me enviaste.","Yo les he dado la gloria que tú me diste, para que sean uno, como nosotros somos uno","–yo en ellos y tú en mí– para que sean perfectamente uno y el mundo conozca que tú me has enviado, y que yo los amé cómo tú me amaste.","Padre, quiero que los que tú me diste estén conmigo donde yo esté, para que contemplen la gloria que me has dado, porque ya me amabas antes de la creación del mundo.","Padre justo, el mundo no te ha conocido, pero yo te conocí, y ellos reconocieron que tú me enviaste.","Les di a conocer tu Nombre, y se lo seguiré dando a conocer, para que el amor con que tú me amaste esté en ellos, y yo también esté en ellos»."],["Después de haber dicho esto, Jesús fue con sus discípulos al otro lado del torrente Cedrón. Había en ese lugar una huerta y allí entró con ellos.","Judas, el traidor, también conocía el lugar porque Jesús y sus discípulos se reunían allí con frecuencia.","Entonces Judas, al frente de un destacamento de soldados y de los guardias designados por los sumos sacerdotes y los fariseos, llegó allí con faroles, antorchas y armas.","Jesús, sabiendo todo lo que le iba a suceder, se adelantó y les preguntó: «¿A quién buscan?».","A Jesús, el Nazareno. El les dijo: «Soy yo». Judas el que lo entregaba estaba con ellos.","Cuando Jesús les dijo: «Soy yo», ellos retrocedieron y cayeron en tierra.","Les preguntó nuevamente: «¿A quién buscan?». Le dijeron: «A Jesús, el Nazareno».","Jesús repitió: «Ya les dije que soy yo. Si es a mí a quien buscan, dejan que estos se vayan».","Así debía cumplirse la palabra que él había dicho: «No he perdido a ninguno de los que me confiaste».","Entonces Simón Pedro, que llevaba una espada, la sacó e hirió al servidor del Sumo Sacerdote, cortándole la oreja derecha. El servidor se llamaba Malco.","Jesús dijo a Simón Pedro: «Envaina tu espada. ¿Acaso no beberé el cáliz que me ha dado el Padre?","El destacamento de soldados, con el tribuno y los guardias judíos, se apoderaron de Jesús y lo ataron.","Lo llevaron primero ante Anás, porque era suegro de Caifás, Sumo Sacerdote aquel año.","Caifás era el que había aconsejado a los judíos: «Es preferible que un solo hombre muera por el pueblo».","Entre tanto, Simón Pedro, acompañado de otro discípulo, seguía a Jesús. Este discípulo, que era conocido del Sumo Sacerdote, entró con Jesús en el patio del Pontífice,","mientras Pedro permanecía afuera, en la puerta. El otro discípulo, el que era conocido del Sumo Sacerdote, salió, habló a la portera e hizo entrar a Pedro.","La portera dijo entonces a Pedro: «¿No eres tú también uno de los discípulos de ese hombre?». El le respondió: «No lo soy».","Los servidores y los guardias se calentaban junto al fuego, que habían encendido porque hacía frío. Pedro también estaba con ellos, junto al fuego.","El Sumo Sacerdote interrogó a Jesús acerca de sus discípulos y de su enseñanza.","Jesús le respondió: «He hablado abiertamente al mundo; siempre enseñé en la sinagoga y en el Templo, donde se reúnen todos los judíos, y no he dicho nada en secreto.","¿Por qué me interrogas a mí? Pregunta a los que me han oído qué les enseñé. Ellos saben bien lo que he dicho».","Apenas Jesús dijo esto, uno de los guardias allí presentes le dio una bofetada, diciéndole: «¿Así respondes al Sumo Sacerdote?».","Jesús le respondió: «Si he hablado mal, muestra en qué ha sido; pero si he hablado bien, ¿por qué me pegas?","Entonces Anás lo envió atado ante el Sumo Sacerdote Caifás.","Simón Pedro permanecía junto al fuego. Los que estaban con él le dijeron: «¿No eres tú también uno de sus discípulos?». El lo negó y dijo: «No lo soy».","Uno de los servidores del Sumo Sacerdote, pariente de aquel al que Pedro había cortado la oreja, insistió: «¿Acaso no te vi con él en la huerta?».","Pedro volvió a negarlo, y en seguida cantó el gallo.","Desde la casa de Caifás llevaron a Jesús al pretorio. Era de madrugada. Pero ellos no entraron en el pretorio, para no contaminarse y poder así participar en la comida de Pascua.","Pilato salió adonde estaban ellos y les preguntó: «¿Qué acusación traen contra este hombre?». Ellos respondieron:","«Si no fuera un malhechor, no te lo hubiéramos entregado».","Pilato les dijo: «Tómenlo y júzguenlo ustedes mismos, según la ley que tienen». Los judíos le dijeron: «A nosotros no nos está permitido dar muerte a nadie».","Así debía cumplirse lo que había dicho Jesús cuando indicó cómo iba a morir.","Pilato volvió a entrar en el pretorio, llamó a Jesús y le preguntó: «¿Eres tú el rey de los judíos?».","Jesús le respondió: «¿Dices esto por ti mismo u otros te lo han dicho de mí?».","Pilato explicó: «¿Acaso yo soy judío? Tus compatriotas y los sumos sacerdotes te han puesto en mis manos. ¿Qué es lo que has hecho».","Jesús respondió: «Mi realeza no es de este mundo. Si mi realeza fuera de este mundo, los que están a mi servicio habrían combatido para que yo no fuera entregado a los judíos. Pero mi realeza no es de aquí».","Pilato le dijo: «¿Entonces tú eres rey». Jesús respondió: «Tú lo dices: yo soy rey. Para esto he nacido y he venido al mundo: para dar testimonio de la verdad. El que es de la verdad, escucha mi voz».","Pilato le preguntó: «¿Qué es la verdad?». Al decir esto, salió nuevamente a donde estaban los judíos y les dijo: «Yo no encuentro en él ningún motivo para condenarlo.","Y ya que ustedes tienen la costumbre de que ponga en libertad a alguien, en ocasión de la Pascua, ¿quieren que suelte al rey de los judíos?».","Ellos comenzaron a gritar, diciendo: «¡A él no, a Barrabás!». Barrabás era un bandido."],["Pilato mandó entonces azotar a Jesús.","Los soldados tejieron una corona de espinas y se la pusieron sobre la cabeza. Lo revistieron con un manto rojo,","y acercándose, le decían: «¡Salud, rey de los judíos!», y lo abofeteaban.","Pilato volvió a salir y les dijo: «Miren, lo traigo afuera para que sepan que no encuentro en él ningún motivo de condena».","Jesús salió, llevando la corona de espinas y el manto rojo. Pilato les dijo: «¡Aquí tienen al hombre!».","Cuando los sumos sacerdotes y los guardias lo vieron, gritaron: «¡Crucifícalo! ¡Crucifícalo!». Pilato les dijo: «Tómenlo ustedes y crucifíquenlo. Yo no encuentro en él ningún motivo para condenarlo».","Los judíos respondieron: «Nosotros tenemos una Ley, y según esa Ley debe morir porque él pretende ser Hijo de Dios».","Al oír estas palabras, Pilato se alarmó más todavía.","Volvió a entrar en el pretorio y preguntó a Jesús: «¿De dónde eres tú?». Pero Jesús no lo respondió nada.","Pilato le dijo: «¿No quieres hablarme? ¿No sabes que tengo autoridad para soltarte y también para crucificarte?».","Jesús le respondió: «Tú no tendrías sobre mí ninguna autoridad, si no la hubieras recibido de lo alto. Por eso, el que me ha entregado a ti ha cometido un pecado más grave».","Desde ese momento, Pilato trataba de ponerlo en libertad. Pero los judíos gritaban: «Si lo sueltas, no eres amigo del César, porque el que se hace rey se opone al César».","Al oír esto, Pilato sacó afuera a Jesús y lo hizo sentar sobre un estrado, en el lugar llamado «el Empedrado», en hebreo, «Gábata».","Era el día de la Preparación de la Pascua, alrededor del mediodía. Pilato dijo a los judíos: «Aquí tienen a su rey».","Ellos vociferaban: «¡Que muera! ¡Que muera! ¡Crucifícalo!». Pilato les dijo: «¿Voy a crucificar a su rey?». Los sumos sacerdotes respondieron: «No tenemos otro rey que el César».","Entonces Pilato se lo entregó para que lo crucifiquen, y ellos se lo llevaron.","Jesús, cargando sobre sí la cruz, salió de la ciudad para dirigirse al lugar llamado «del Cráneo», en hebreo «Gólgota».","Allí lo crucificaron; y con él a otros dos, uno a cada lado y Jesús en el medio.","Pilato redactó una inscripción que decía: \"Jesús el Nazareno, rey de los judíos\", y la hizo poner sobre la cruz.","Muchos judíos leyeron esta inscripción, porque el lugar donde Jesús fue crucificado quedaba cerca de la ciudad y la inscripción estaba en hebreo, latín y griego.","Los sumos sacerdotes de los judíos dijeron a Pilato: «No escribas: \"El rey de los judíos\". sino: \"Este ha dicho: Yo soy el rey de los judíos\"».","Pilato respondió: «Lo escrito, escrito está».","Después que los soldados crucificaron a Jesús, tomaron sus vestiduras y las dividieron en cuatro partes, una para cada uno. Tomaron también la túnica, y como no tenía costura, porque estaba hecha de una sola pieza de arriba abajo,","se dijeron entre sí: «No la rompamos. Vamos a sortearla, para ver a quién le toca.» Así se cumplió la Escritura que dice: Se repartieron mis vestiduras y sortearon mi túnica. Esto fue lo que hicieron los soldados.","Junto a la cruz de Jesús, estaba su madre y la hermana de su madre, María, mujer de Cleofás, y María Magdalena.","Al ver a la madre y cerca de ella al discípulo a quien el amaba, Jesús le dijo: «Mujer, aquí tienes a tu hijo».","Luego dijo al discípulo: «Aquí tienes a tu madre». Y desde aquel momento, el discípulo la recibió en su casa.","Después, sabiendo que ya todo estaba cumplido, y para que la Escritura se cumpliera hasta el final, Jesús dijo: Tengo sed.","Había allí un recipiente lleno de vinagre; empaparon en él una esponja, la ataron a una rama de hisopo y se la acercaron a la boca.","Después de beber el vinagre, dijo Jesús: «Todo se ha cumplido». E inclinando la cabeza, entregó su espíritu.","Era el día de la Preparación de la Pascua. Los judíos pidieron a Pilato que hiciera quebrar las piernas de los crucificados y mandara retirar sus cuerpos, para que no quedaran en la cruz durante el sábado, porque ese sábado era muy solemne.","Los soldados fueron y quebraron las piernas a los dos que habían sido crucificados con Jesús.","Cuando llegaron a él, al ver que ya estaba muerto, no le quebraron las piernas,","sino que uno de los soldados le atravesó el costado con la lanza, y en seguida brotó sangre y agua.","El que vio esto lo atestigua: su testimonio es verdadero y él sabe que dice la verdad, para que también ustedes crean.","Esto sucedió para que se cumpliera la Escritura que dice: \"No le quebrarán ninguno de sus huesos\".","Y otro pasaje de la Escritura, dice: \"Verán al que ellos mismos traspasaron\".","Después de esto, José de Arimatea, que era discípulo de Jesús –pero secretamente, por temor a los judíos– pidió autorización a Pilato para retirar el cuerpo de Jesús. Pilato se la concedió, y él fue a retirarlo.","Fue también Nicodemo, el mismo que anteriormente había ido a verlo de noche, y trajo una mezcla de mirra y áloe, que pesaba unos treinta kilos.","Tomaron entonces el cuerpo de Jesús y lo envolvieron con vendas, agregándole la mezcla de perfumes, según la costumbre de sepultar que tienen los judíos.","En el lugar donde lo crucificaron había una huerta y en ella, una tumba nueva, en la que todavía nadie había sido sepultado.","Como era para los judíos el día de la Preparación y el sepulcro estaba cerca, pusieron allí a Jesús."],["El primer día de la semana, de madrugada, cuando todavía estaba oscuro, María Magdalena fue al sepulcro y vio que la piedra había sido sacada.","Corrió al encuentro de Simón Pedro y del otro discípulo al que Jesús amaba, y les dijo: «Se han llevado del sepulcro al Señor y no sabemos dónde lo han puesto».","Pedro y el otro discípulo salieron y fueron al sepulcro.","Corrían los dos juntos, pero el otro discípulo corrió más rápidamente que Pedro y llegó antes.","Asomándose al sepulcro, vio las vendas en el suelo, aunque no entró.","Después llegó Simón Pedro, que lo seguía, y entró en el sepulcro; vio las vendas en el suelo,","y también el sudario que había cubierto su cabeza; este no estaba con las vendas, sino enrollado en un lugar aparte.","Luego entró el otro discípulo, que había llegado antes al sepulcro: él también vio y creyó.","Todavía no habían comprendido que, según la Escritura, él debía resucitar de entre los muertos.","Los discípulos regresaron entonces a su casa.","María se había quedado afuera, llorando junto al sepulcro. Mientras lloraba, se asomó al sepulcro","y vio a dos ángeles vestidos de blanco, sentados uno a la cabecera y otro a los pies del lugar donde había sido puesto el cuerpo de Jesús.","Ellos le dijeron: «Mujer, ¿por qué lloras?». María respondió: «Porque se han llevado a mi Señor y no sé dónde lo han puesto».","Al decir esto se dio vuelta y vio a Jesús, que estaba allí, pero no lo reconoció.","Jesús le preguntó: «Mujer, ¿por qué lloras? ¿A quién buscas?». Ella, pensando que era el cuidador de la huerta, le respondió: «Señor, si tú lo has llevado, dime dónde lo has puesto y yo iré a buscarlo».","Jesús le dijo: «¡María!». Ella lo reconoció y le dijo en hebreo: «¡Raboní!», es decir «¡Maestro!».","Jesús le dijo: «No me retengas, porque todavía no he subido al Padre. Ve a decir a mis hermanos: «Subo a mi Padre, el Padre de ustedes; a mi Dios, el Dios de ustedes».","María Magdalena fue a anunciar a los discípulos que había visto al Señor y que él le había dicho esas palabras.","Al atardecer de ese mismo día, el primero de la semana, estando cerradas las puertas del lugar donde se encontraban los discípulos, por temor a los judíos, llegó Jesús y poniéndose en medio de ellos, les dijo: «¡La paz esté con ustedes!».","Mientras decía esto, les mostró sus manos y su costado. Los discípulos se llenaron de alegría cuando vieron al Señor.","Jesús les dijo de nuevo: «¡La paz esté con ustedes! Como el Padre me envió a mí, yo también los envío a ustedes»","Al decirles esto, sopló sobre ellos y añadió «Reciban al Espíritu Santo.","Los pecados serán perdonados a los que ustedes se los perdonen, y serán retenidos a los que ustedes se los retengan».","Tomás, uno de los Doce, de sobrenombre el Mellizo, no estaba con ellos cuando llegó Jesús.","Los otros discípulos le dijeron: «¡Hemos visto al Señor!». El les respondió: «Si no veo la marca de los clavos en sus manos, si no pongo el dedo en el lugar de los clavos y la mano en su costado, no lo creeré».","Ocho días más tarde, estaban de nuevo los discípulos reunidos en la casa, y estaba con ellos Tomás. Entonces apareció Jesús, estando cerradas las puertas, se puso en medio de ellos y les dijo: «¡La paz esté con ustedes!».","Luego dijo a Tomás: «Trae aquí tu dedo: aquí están mis manos. Acerca tu mano: Métela en mi costado. En adelante no seas incrédulo, sino hombre de fe».","Tomas respondió: «¡Señor mío y Dios mío!.","Jesús le dijo: «Ahora crees, porque me has visto. ¡Felices los que creen sin haber visto!».","Jesús realizó además muchos otros signos en presencia de sus discípulos, que no se encuentran relatados en este Libro.","Estos han sido escritos para que ustedes crean que Jesús es el Mesías, el Hijo de Dios, y creyendo, tengan Vida en su Nombre."],["Después de esto, Jesús se apareció otra vez a los discípulos a orillas del mar de Tiberíades. Sucedió así:","estaban junto Simón Pedro, Tomás, llamado el Mellizo, Natanael, el de Caná de Galilea, los hijos de Zebedeo y otros dos discípulos.","Simón Pedro les dijo: «Voy a pescar». Ellos le respondieron: «Vamos también nosotros». Salieron y subieron a la barca. Pero esa noche no pescaron nada.","Al amanecer, Jesús estaba en la orilla, aunque los discípulos no sabían que era él.","Jesús les dijo: «Muchachos, ¿tienen algo para comer?». Ellos respondieron: «No».","el les dijo: «Tiren la red a la derecha de la barca y encontrarán». Ellos la tiraron y se llenó tanto de peces que no podían arrastrarla.","El discípulo al que Jesús amaba dio a Pedro: «¡Es el Señor!». Cuando Simón Pedro oyó que era el Señor, se ciñó la túnica, que era lo único que llevaba puesto, y se tiró al agua.","Los otros discípulos fueron en la barca, arrastrando la red con los peces, porque estaban sólo a unos cien metros de la orilla.","Al bajar a tierra vieron que había fuego preparado, un pescado sobre las brasas y pan.","Jesús les dijo: «Traigan algunos de los pescados que acaban de sacar».","Simón Pedro subió a la barca y sacó la red a tierra, llena de peces grandes: eran ciento cincuenta y tres y, a pesar de ser tantos, la red no se rompió.","Jesús les dijo: «Vengan a comer». Ninguno de los discípulos se atrevía a preguntarle: «¿Quién eres», porque sabían que era el Señor.","Jesús se acercó, tomó el pan y se lo dio, e hizo lo mismo con el pescado.","Esta fue la tercera vez que Jesús resucitado se apareció a sus discípulos.","Después de comer, Jesús dijo a Simón Pedro: «Simón, hijo de Juan, ¿me amas más que estos?». El le respondió: «Sí, Señor, tú sabes que te quiero». Jesús le dijo: «Apacienta mis corderos».","Le volvió a decir por segunda vez: «Simón, hijo de Juan, ¿me amas?». El le respondió: «Sí, Señor, saber que te quiero». Jesús le dijo: «Apacienta mis ovejas».","Le preguntó por tercera vez: «Simón, hijo de Juan, ¿me quieres?». Pedro se entristeció de que por tercera vez le preguntara si lo quería, y le dijo: «Señor, tú lo sabes todo; sabes que te quiero». Jesús le dijo: «Apacienta mis ovejas.","Te aseguro que cuando eras joven tú mismo te vestías e ibas a donde querías. Pero cuando seas viejo, extenderás tus brazos, y otro te atará y te llevará a donde no quieras».","De esta manera, indicaba con qué muerte Pedro debía glorificar a Dios. Y después de hablar así, le dijo: «Sígueme».","Pedro, volviéndose, vio que lo seguía el discípulo al que Jesús amaba, el mismo que durante la Cena se había reclinado sobre Jesús y le había preguntado: «Señor, ¿quién es el que te va a entregar?».","Cuando Pedro lo vio, preguntó a Jesús: «Señor, ¿y qué será de este?».","Jesús le respondió: «Si yo quiero que él quede hasta mi venida, ¿qué importa? Tú sígueme».","Entonces se divulgó entre los hermanos el rumor de que aquel discípulo no moriría, pero Jesús no había dicho a Pedro: «El no morirá», sino: «Si yo quiero que él quede hasta mi venida, ¿qué te importa?».","Este mismo discípulo es el que da testimonio de estas cosas y el que las ha escrito, y sabemos que su testimonio es verdadero.","Jesús hizo también muchas otras cosas. Si se las relata detalladamente, pienso que no bastaría todo el mundo para contener los libros que se escribirían."]],"hch":[["En mi primer Libro, querido Teófilo, me referí a todo lo que hizo y enseñó Jesús, desde el comienzo,","hasta el día en que subió al cielo, después de haber dado, por medio del Espíritu Santo, sus últimas instrucciones a los Apóstoles que había elegido.","Después de su Pasión, Jesús se manifestó a ellos dándoles numerosas pruebas de que vivía, y durante cuarenta días se le apareció y les habló del Reino de Dios.","En una ocasión, mientras estaba comiendo con ellos, les recomendó que no se alejaran de Jerusalén y esperaran la promesa del Padre: «La promesa, les dijo, que yo les he anunciado.","Porque Juan bautizó con agua, pero ustedes serán bautizados en el Espíritu Santo, dentro de pocos días».","Los que estaban reunidos le preguntaron: «Señor, ¿es ahora cuando vas a restaurar el reino de Israel?».","El les respondió: «No les corresponde a ustedes conocer el tiempo y el momento que el Padre ha establecido con su propia autoridad.","Pero recibirán la fuerza del Espíritu Santo que descenderá sobre ustedes, y serán mis testigos en Jerusalén, en toda Judea y Samaría, y hasta los confines de la tierra».","Dicho esto, los Apóstoles lo vieron elevarse, y una nube lo ocultó de la vista de ellos.","Como permanecían con la mirada puesta en el cielo mientras Jesús subía, se les aparecieron dos hombres vestidos de blanco,","que les dijeron: «Hombres de Galilea, ¿por qué siguen mirando al cielo? Este Jesús que les ha sido quitado y fue elevado al cielo, vendrá de la misma manera que lo han visto partir».","Los Apóstoles regresaron entonces del monte de los Olivos a Jerusalén: la distancia entre ambos sitios es la que está permitida recorrer en día sábado.","Cuando llegaron a la ciudad, subieron a la sala donde solían reunirse. Eran Pedro, Juan, Santiago, Andrés, Felipe y Tomás, Bartolomé, Mateo, Santiago, hijo de Alfeo, Simón el Zelote y Judas, hijo de Santiago.","Todos ellos, íntimamente unidos, se dedicaban a la oración, en compañía de algunas mujeres, de María, la madre de Jesús, y de sus hermanos.","Uno de esos días, Pedro se puso de pie en medio de los hermanos –los que estaban reunidos eran alrededor de ciento veinte personas– y dijo:","«Hermanos, era necesario que se cumpliera la Escritura en la que el Espíritu Santo, por boca de David, habla de Judas, que fue el jefe de los que apresaron a Jesús.","El era uno de los nuestros y había recibido su parte en nuestro ministerio.","Pero después de haber comprado un campo con el precio de su crimen, cayó de cabeza, y su cuerpo se abrió, dispersándose sus entrañas.","El hecho fue tan conocido por todos los habitantes de Jerusalén, que ese campo fue llamado en su idioma Hacéldama, que quiere decir: «Campo de sangre».","En el libro de los Salmos está escrito: Que su casa quede desierta y nadie la habite. Y más adelante: Que otro ocupe su cargo.","Es necesario que uno de los que han estado en nuestra compañía durante todo el tiempo que el Señor Jesús permaneció con nosotros,","desde el bautismo de Juan hasta el día de la ascensión, sea constituido junto con nosotros testigo de su resurrección».","Se propusieron dos: José, llamado Barsabás, de sobrenombre el Justo, y Matías.","Y oraron así: «Señor, tú que conoces los corazones de todos, muéstranos a cuál de los dos elegiste","para desempeñar el ministerio del apostolado, dejado por Judas al irse al lugar que le correspondía».","Echaron suertes, y la elección cayó sobre Matías, que fue agregado a los once Apóstoles."],["Al llegar el día de Pentecostés, estaban todos reunidos en el mismo lugar.","De pronto, vino del cielo un ruido, semejante a una fuerte ráfaga de viento, que resonó en toda la casa donde se encontraban.","Entonces vieron aparecer unas lenguas como de fuego, que descendieron por separado sobre cada uno de ellos.","Todos quedaron llenos del Espíritu Santo, y comenzaron a hablar en distintas lenguas, según el Espíritu les permitía expresarse.","Había en Jerusalén judíos piadosos, venidos de todas las naciones del mundo.","Al oírse este ruido, se congregó la multitud y se llenó de asombro, porque cada uno los oía hablar en su propia lengua.","Con gran admiración y estupor decían: «¿Acaso estos hombres que hablan no son todos galileos?","¿Cómo es que cada uno de nosotros los oye en su propia lengua?","Partos, medos y elamitas, los que habitamos en la Mesopotamia o en la misma Judea, en Capadocia, en el Ponto y en Asia Menor,","en Frigia y Panfilia, en Egipto, en la Libia Cirenaica, los peregrinos de Roma,","judíos y prosélitos, cretenses y árabes, todos los oímos proclamar en nuestras lenguas las maravillas de Dios».","Unos a otros se decían con asombro: «¿Qué significa esto?».","Algunos, burlándose, comentaban: «Han tomado demasiado vino».","Entonces, Pedro poniéndose de pie con los Once, levantó la voz y dijo: «Hombres de Judea y todos los que habitan en Jerusalén, presten atención, porque voy a explicarles lo que ha sucedido.","Estos hombres no están ebrios, como ustedes suponen, ya que no son más que las nueve de la mañana,","sino que se está cumpliendo lo que dijo el profeta Joel:","\"En los últimos días, dice el Señor, derramaré mi Espíritu sobre todos los hombres y profetizarán sus hijos y sus hijas; los jóvenes verán visiones y los ancianos tendrán sueños proféticos.","Más aún, derramaré mi Espíritu sobre mis servidores y servidoras, y ellos profetizarán.","Haré prodigios arriba, en el cielo, y signos abajo, en la tierra: verán sangre, fuego y columnas de humo.","El sol se convertirá en tinieblas y la luna en sangre, antes que llegue el Día del Señor, día grande y glorioso.","Y todo el que invoque el nombre del Señor se salvará\".","Israelitas, escuchen: A Jesús de Nazaret, el hombre que Dios acreditó ante ustedes realizando por su intermedio los milagros, prodigios y signos que todos conocen,","a ese hombre que había sido entregado conforme al plan y a la previsión de Dios, ustedes lo hicieron morir, clavándolo en la cruz por medio de los infieles.","Pero Dios lo resucitó, librándolo de las angustias de la muerte, porque no era posible que ella tuviera dominio sobre él.","En efecto, refiriéndose a él, dijo David: \"Veía sin cesar al Señor delante de mí, porque él está a mi derecha para que yo no vacile.","Por eso se alegra mi corazón y mi lengua canta llena de gozo. También mi cuerpo descansará en la esperanza,","porque tú no entregarás mi alma al Abismo, ni dejarás que tu servidor sufra la corrupción.","Tú me has hecho conocer los caminos de la vida y me llenarás de gozo en tu presencia\".","Hermanos, permítanme decirles con toda franqueza que el patriarca David murió y fue sepultado, y su tumba se conserva entre nosotros hasta el día de hoy.","Pero como él era profeta, sabía que Dios le había jurado que un descendiente suyo se sentaría en su trono.","Por eso previó y anunció la resurrección del Mesías, cuando dijo que no fue entregado al Abismo ni su cuerpo sufrió la corrupción.","A este Jesús, Dios lo resucitó, y todos nosotros somos testigos.","Exaltado por el poder de Dios, él recibió del Padre el Espíritu Santo prometido, y lo ha comunicado como ustedes ven y oyen.","Porque no es David el que subió a los cielos; al contrario, él mismo afirma: \"Dijo el Señor a mi Señor: Siéntate a mi derecha,","hasta que ponga a todos tus enemigos debajo de tus pies\".","Por eso, todo el pueblo de Israel debe reconocer que a ese Jesús que ustedes crucificaron, Dios lo ha hecho Señor y Mesías».","Al oír estas cosas, todos se conmovieron profundamente, y dijeron a Pedro y a los otros Apóstoles: «Hermanos, ¿qué debemos hacer?».","Pedro les respondió: «Conviértanse y háganse bautizar en el nombre de Jesucristo para que les sean perdonados los pecados, y así recibirán el don del Espíritu Santo.","Porque la promesa ha sido hecha a ustedes y a sus hijos, y a todos aquellos que están lejos: a cuantos el Señor, nuestro Dios, quiera llamar».","Y con muchos otros argumentos les daba testimonio y los exhortaba a que se pusieran a salvo de esta generación perversa.","Los que recibieron su palabra se hicieron bautizar; y ese día se unieron a ellos alrededor de tres mil.","Todos se reunían asiduamente para escuchar la enseñanza de los Apóstoles y participar en la vida común, en la fracción del pan y en las oraciones.","Un santo temor se apoderó de todos ellos, porque los Apóstoles realizaban muchos prodigios y signos.","Todos los creyentes se mantenían unidos y ponían lo suyo en común:","vendían sus propiedades y sus bienes, y distribuían el dinero entre ellos, según las necesidades de cada uno.","Intimamente unidos, frecuentaban a diario el Templo, partían el pan en sus casas, y comían juntos con alegría y sencillez de corazón;","ellos alababan a Dios y eran queridos por todo el pueblo. Y cada día, el Señor acrecentaba la comunidad con aquellos que debían salvarse."],["En una ocasión, Pedro y Juan subían al Templo para la oración de la tarde.","Allí encontraron a un paralítico de nacimiento, que ponían diariamente junto a la puerta del Templo llamada «la Hermosa», para pedir limosna a los que entraban.","Cuando él vio a Pedro y a Juan entrar en el Templo, les pidió una limosna.","Entonces Pedro, fijando la mirada en él, lo mismo que Juan, le dijo: «Míranos».","El hombre los miró fijamente esperando que le dieran algo.","Pedro le dijo: «No tengo plata ni oro, pero te doy lo que tengo: en el nombre de Jesucristo de Nazaret, levántate y camina».","Y tomándolo de la mano derecha, lo levantó; de inmediato, se le fortalecieron los pies y los tobillos.","Dando un salto, se puso de pie y comenzó a caminar; y entró con ellos en el Templo, caminando, saltando y glorificando a Dios.","Toda la gente lo vio caminar y alabar a Dios.","Reconocieron que era el mendigo que pedía limosna sentado a la puerta del Templo llamada «la Hermosa», y quedaron asombrados y llenos de admiración por lo que le había sucedido.","Como él no soltaba a Pedro y a Juan, todo el pueblo, lleno de asombro, corrió hacia ellos, que estaban en el pórtico de Salomón.","Al ver esto, Pedro dijo al pueblo: «Israelitas, ¿de qué se asombran? ¿Por qué nos miran así, como si fuera por nuestro poder o por nuestra santidad, que hemos hecho caminar a este hombre?","El Dios de Abraham, de Isaac y de Jacob, el Dios de nuestros padres, glorificó a su servidor Jesús, a quien ustedes entregaron, renegando de él delante de Pilato, cuando este había resuelto ponerlo en libertad.","Ustedes renegaron del Santo y del Justo, y pidiendo como una gracia la liberación de un homicida,","mataron al autor de la vida. Pero Dios lo resucitó de entre los muertos, de lo cual nosotros somos testigos.","Por haber creído en su Nombre, ese mismo Nombre ha devuelto la fuerza al que ustedes ven y conocen. Esta fe que proviene de él, es la que lo ha curado completamente, como ustedes pueden comprobar.","Ahora bien, hermanos, yo sé que ustedes obraron por ignorancia, lo mismo que sus jefes.","Pero así, Dios cumplió lo que había anunciado por medio de todos los profetas: que su Mesías debía padecer.","Por lo tanto, hagan penitencia y conviértanse, para que sus pecados sean perdonados.","Así el Señor les concederá el tiempo del consuelo y enviará a Jesús, el Mesías destinado para ustedes.","El debe permanecer en el cielo hasta el momento de la restauración universal, que Dios anunció antiguamente por medio de sus santos profetas.","Moisés, en efecto, dijo: \"El Señor Dios suscitará para ustedes, de entre sus hermanos, un profeta semejante a mí, y ustedes obedecerán a todo lo que él les diga.","El que no escuche a ese profeta será excluido del pueblo\".","Y todos los profetas que ha hablado a partir de Samuel, anunciaron también estos días.","Ustedes son los herederos de los profetas y de la Alianza que Dios hizo con sus antepasados, cuando dijo a Abraham: \"En tu descendencia serán bendecidos todos los pueblos de la tierra\".","Ante todo para ustedes Dios resucitó a su Servidor, y lo envió para bendecirlos y para que cada uno se aparte de sus iniquidades»."],["Mientras los Apóstoles hablaban al pueblo, se presentaron ante ellos los sacerdotes, el jefe de los guardias del Templo y los saduceos,","irritados de que predicaran y anunciaran al pueblo la resurrección de los muertos cumplida en la persona de Jesús.","Estos detuvieron a los Apóstoles y los encarcelaron hasta el día siguiente, porque ya era tarde.","Muchos de los que habían escuchado la Palabra abrazaron la fe, y así el número de creyentes, contando sólo los hombres, se elevó a unos cinco mil.","Al día siguiente, se reunieron en Jerusalén los jefes de los judíos, los ancianos y los escribas,","con Anás, el Sumo Sacerdote, Caifás, Juan, Alejandro y todos los miembros de las familias de los sumos sacerdotes.","Hicieron comparecer a los Apóstoles y los interrogaron: «¿Con qué poder o en nombre de quién ustedes hicieron eso?».","Pedro, lleno del Espíritu Santo, dijo: «Jefes del pueblo y ancianos,","ya que hoy se nos pide cuenta del bien que hicimos a un enfermo y de cómo fue curado,","sepan ustedes y todo el pueblo de Israel: este hombre está aquí sano delante de ustedes por el nombre de nuestro Señor Jesucristo de Nazaret, al que ustedes crucificaron y Dios resucitó de entre los muertos.","El es la piedra que ustedes, los constructores, han rechazado, y ha llegado a ser la piedra angular.","Porque no existe bajo el cielo otro Nombre dado a los hombres, por el cual podamos alcanzar la salvación».","Los miembros del Sanedrín estaban asombrados de la seguridad con que Pedro y Juan hablaban, a pesar de ser personas poco instruidas y sin cultura. Reconocieron que eran los que habían acompañado a Jesús,","pero no podrían replicarles nada, porque el hombre que había sido curado estaba de pie, al lado de ellos.","Entonces les ordenaron salir del Sanedrín y comenzaron a deliberar,","diciendo: «¿Qué haremos con estos hombres? Porque no podemos negar que han realizado un signo bien patente, que es notorio para todos los habitantes de Jerusalén.","A fin de evitar que la cosa se divulgue más entre el pueblo, debemos amenazarlos, para que de ahora en adelante no hablen de ese Nombre».","Los llamaron y les prohibieron terminantemente que dijeran una sola palabra o enseñaran en el nombre de Jesús.","Pedro y Juan les respondieron: «Juzguen si está bien a los ojos del Señor que les obedezcamos a ustedes antes que a Dios.","Nosotros no podemos callar lo que hemos visto y oído».","Después de amenazarlos nuevamente, los dejaron en libertad, ya que no sabían cómo castigarlos, por temor al pueblo que alababa a Dios al ver lo que había sucedido.","El hombre milagrosamente curado tenía más de cuarenta años.","Una vez en libertad, los Apóstoles regresaron adonde estaban sus hermanos, y les contaron todo lo que les habían dicho los sumos sacerdotes y los ancianos.","Al oírlos, todos levantaron la voz y oraron a Dios unánimemente: «Señor, tú hiciste el cielo y la tierra, el mar y todo lo que hay en ellos;","tú, por medio del Espíritu Santo, pusiste estas palabras en labios de nuestro padre David, tu servidor: \"¿Por qué se amotinan las naciones y los pueblos hacen vanos proyectos?","Los reyes de la tierra se rebelaron y los príncipes se aliaron contra el Señor y contra su Ungido\".","Porque realmente se aliaron en esta ciudad Herodes y Poncio Pilato con las naciones paganas y los pueblos de Israel, contra tu santo servidor Jesús, a quien tú has ungido.","Así ellos cumplieron todo lo que tu poder y tu sabiduría habían determinado de antemano.","Ahora, Señor, mira sus amenazas, y permite a tus servidores anunciar tu Palabra con toda libertad:","extiende tu mano para que se realicen curaciones, signos y prodigios en el nombre de tu santo servidor Jesús:.","Cuando terminaron de orar, tembló el lugar donde estaban reunidos; todos quedaron llenos del Espíritu Santo y anunciaban decididamente la Palabra de Dios.","La multitud de los creyentes tenía un solo corazón y una sola alma. Nadie consideraba sus bienes como propios, sino que todo era común entre ellos.","Los Apóstoles daban testimonio con mucho poder de la resurrección del Señor Jesús y gozaban de gran estima.","Ninguno padecía necesidad, porque todos los que poseían tierras o casas las vendían","y ponían el dinero a disposición de los Apóstoles, para que se distribuyera a cada uno según sus necesidades.","Y así José, llamado por los Apóstoles Bernabé –que quiere decir hijo del consuelo– un levita nacido en Chipre","que poseía un campo, lo vendió, y puso el dinero a disposición de los Apóstoles."],["Un hombre llamado Ananías, junto con su mujer, Safira, vendió una propiedad,","y de acuerdo con ella, se guardó parte del dinero y puso el resto a disposición de los Apóstoles.","Pedro le dijo: «Ananías, ¿por qué dejaste que Satanás se apoderara de ti hasta el punto de engañar al Espíritu Santo, guardándote una parte del dinero del campo?","¿Acaso no eras dueño de quedarte con él? Y después de venderlo, ¿no podías guardarte el dinero? ¿Cómo se te ocurrió hacer esto? No mentiste a los hombres sino a Dios».","Al oír estas palabras, Ananías cayó muerto. Un gran temor se apoderó de todos los que se enteraron de lo sucedido.","Vinieron unos jóvenes, envolvieron su cuerpo y lo llevaron a enterrar.","Unas tres horas más tarde, llegó su mujer, completamente ajena a lo ocurrido.","Pedro le preguntó: «¿Es verdad que han vendido el campo en tal suma?». Ella respondió: «Sí, en esa suma».","Pedro le dijo: «¿Por qué se han puesto de acuerdo para tentar así al Espíritu del Señor? Mira junto a la puerta las pisadas de los que acaban de enterrar a tu marido; ellos también te van a llevar a ti».","En ese mismo momento, ella cayó muerta a sus pies; los jóvenes, al entrar, la encontraron muerta, la llevaron y la enterraron junto a su marido.","Un gran temor se apoderó entonces de toda la Iglesia y de todos los que oyeron contar estas cosas.","Los Apóstoles hacían muchos signos y prodigios en el pueblo. Todos solían congregarse unidos en un mismo espíritu, bajo el pórtico de Salomón,","pero ningún otro se atrevía a unirse al grupo de los Apóstoles, aunque el pueblo hablaba muy bien de ellos.","Aumentaba cada vez más el número de los que creían en el Señor, tanto hombres como mujeres.","Y hasta sacaban a los enfermos a las calles, poniéndolos en catres y camillas, para que cuando Pedro pasara, por lo menos su sombra cubriera a alguno de ellos.","La multitud acudía también de las ciudades vecinas a Jerusalén, trayendo enfermos o poseídos por espíritus impuros, y todos quedaban curados.","Intervino entonces el Sumo Sacerdote con todos sus partidarios, los de la secta de los saduceos. Llenos de envidia,","hicieron arrestar a los Apóstoles y los enviaron a la prisión pública.","Pero durante la noche, el Angel del Señor abrió las puertas de la prisión y los hizo salir. Luego les dijo:","«Vayan al Templo y anuncien al pueblo todo lo que se refiere a esta nueva Vida».","Los Apóstoles, obedecieron la orden, entraron al Templo en las primeras horas del día, y se pusieron a enseñar. Entre tanto, llegaron el Sumo Sacerdote y sus partidarios, convocaron al Sanedrín y a todo el Senado del pueblo de Israel, y mandaron a buscarlos a la cárcel.","Cuando llegaron los guardias a la prisión, no los encontraron. Entonces volvieron y dijeron:","«Encontramos la prisión cuidadosamente cerrada y a los centinelas de guardia junto a las puertas, pero cuando las abrimos, no había nadie adentro».","Al oír esto, el jefe del Templo y los sumos sacerdotes quedaron perplejos y no podían explicarse qué había sucedido.","En ese momento llegó uno, diciendo: «Los hombres que ustedes arrestaron, están en el Templo y enseñan al pueblo».","El jefe de la guardia salió con sus hombres y trajeron a los Apóstoles, pero sin violencia, por temor a ser apedreados por el pueblo.","Los hicieron comparecer ante el Sanedrín, y el Sumo Sacerdote les dijo:","«Nosotros les habíamos prohibido expresamente predicar en ese Nombre, y ustedes han llenado Jerusalén con su doctrina. ¡Así quieren hacer recaer sobre nosotros la sangre de ese hombre!».","Pedro, junto con los Apóstoles, respondió: «Hay que obedecer a Dios antes que a los hombres.","El Dios de nuestros padres ha resucitado a Jesús, al que ustedes hicieron morir suspendiéndolo del patíbulo.","A él, Dios lo exaltó con su poder, haciéndolo Jefe y Salvador, a fin de conceder a Israel la conversión y el perdón de los pecados.","Nosotros somos testigos de estas cosas, nosotros y el Espíritu Santo que Dios ha enviado a los que le obedecen».","Al oír estas palabras, ellos se enfurecieron y querían matarlos.","Pero un fariseo, llamado Gamaliel, que era doctor de la Ley, respetado por todo el pueblo, se levantó en medio del Sanedrín. Después de hacer salir por un momento a los Apóstoles,","dijo a los del Sanedrín: «Israelitas, cuídense bien de lo que van a hacer con esos hombres.","Hace poco apareció Teudas, que pretendía ser un personaje, y lo siguieron unos cuatrocientos hombres; sin embargo, lo mataron, sus partidarios se dispersaron, y ya no queda nada.","Después de él, en la época del censo, apareció Judas de Galilea, que también arrastró mucha gente: igualmente murió, y todos sus partidarios se dispersaron.","Por eso, ahora les digo: No se metan con esos hombres y déjenlos en paz, porque si lo que ellos intentan hacer viene de los hombres, se destruirá por sí mismo,","pero si verdaderamente viene de Dios, ustedes no podrán destruirlos y correrán el riesgo de embarcarse en una lucha contra Dios». Los del Sanedrín siguieron su consejo:","llamaron a los Apóstoles, y después de hacerlos azotar, les prohibieron hablar en el nombre de Jesús y los soltaron.","Los Apóstoles, por su parte, salieron del Sanedrín, dichosos de haber sido considerados dignos de padecer por el nombre de Jesús.","Y todos los días, tanto en el Templo como en las casas, no cesaban de enseñar y de anunciar la Buena Noticia de Cristo Jesús."],["En aquellos días, como el número de discípulos aumentaba, los helenistas comenzaron a murmurar contra los hebreos porque se desatendían a sus viudas en la distribución diaria de los alimentos.","Entonces los Doce convocaron a todos los discípulos y les dijeron: «No es justo que descuidemos el ministerio de la Palabra de Dios para ocuparnos de servir las mesas.","Es preferible, hermanos, que busquen entre ustedes a siete hombres de buena fama, llenos del Espíritu Santo y de sabiduría, y nosotros les encargaremos esta tarea.","De esa manera, podremos dedicarnos a la oración y al ministerio de la Palabra».","La asamblea aprobó esta propuesta y eligieron a Esteban, hombre lleno de fe y del Espíritu Santo, a Felipe y a Prócoro, a Nicanor y a Timón, a Pármenas y a Nicolás, prosélito de Antioquía.","Los presentaron a los Apóstoles, y estos, después de orar, les impusieron las manos.","Así la Palabra de Dios se extendía cada vez más, el número de discípulos aumentaba considerablemente en Jerusalén y muchos sacerdotes abrazaban la fe.","Esteban, lleno de gracia y de poder, hacía grandes prodigios y signos en el pueblo.","Algunos miembros de la sinagoga llamada «de los Libertos», como también otros, originarios de Cirene, de Alejandría, de Cilicia y de la provincia de Asia, se presentaron para discutir con él.","Pero como no encontraban argumentos, frente a la sabiduría y al espíritu que se manifestaba en su palabra,","sobornaron a unos hombres para que dijeran que le habían oído blasfemar contra Moisés y contra Dios.","Así consiguieron excitar al pueblo, a los ancianos y a los escribas, y llegando de improviso, lo arrestaron y lo llevaron ante el Sanedrín.","Entonces presentaron falsos testigos, que declararon: «Este hombre no hace otra cosa que hablar contra el Lugar santo y contra la Ley.","Nosotros le hemos oído decir que Jesús de Nazaret destruirá este Lugar y cambiará las costumbres que nos ha transmitido Moisés».","En ese momento, los que estaban sentados en el Sanedrín tenían los ojos clavados en él y vieron que el rostro de Esteban parecía el de un ángel."],["El Sumo Sacerdote preguntó a Esteban: «¿Es verdad lo que estos dicen?».","El respondió: «Hermanos y padres, escuchen: El Dios de la gloria se apareció a nuestro padre Abraham, cuando aún estaba en la Mesopotamia, antes de establecerse en Jarán,","y le dijo: «Abandona tu tierra natal y la casa de tu padre y ve al país que yo te indicaré».","Abraham salió de Caldea para establecerse en Jarán. Después de la muerte de su padre, Dios le ordenó que se trasladara a este país, donde ustedes ahora están viviendo.","El no le dio nada en propiedad, ni siquiera un palmo de tierra, pero prometió darle en posesión este país, a él, y después de él a sus descendientes, aunque todavía no tenía hijos.","Y Dios le anunció que sus descendientes emigrarían a una tierra extranjera, y serían esclavizados y maltratados durante cuatrocientos años.","Pero yo juzgaré al pueblo que los esclavizará –dice el Señor– y después quedarán en libertad y me tributarán culto en este mismo lugar.","Le dio luego la alianza sellada con la circuncisión y así Abraham, cuando nació su hijo Isaac, lo circuncidó al octavo día; Isaac hizo lo mismo con Jacob, y Jacob con los doce patriarcas.","Los patriarcas, movidos por la envidia, vendieron a su hermano José para que fuera llevado a Egipto. Pero Dios estaba con él","y lo salvó en todas sus tribulaciones, le dio sabiduría, y lo hizo grato al Faraón, rey de Egipto, el cual lo nombró gobernador de su país y lo puso al frente de su casa real.","Luego sobrevino una época de hambre y de extrema miseria en toda la tierra de Egipto y de Canaán, y nuestros padres no tenían qué comer.","Jacob, al enterarse de que en Egipto había trigo, decidió enviar allí a nuestros padres. Esta fue la primera visita.","Cuando llegaron por segunda vez, José se dio a conocer a sus hermanos, y el mismo Faraón se enteró de origen de José.","Este mandó llamar a su padre Jacob y a toda su familia, unas setenta y cinco personas.","Jacob se radicó entonces en Egipto, y allí murió, lo mismo que nuestros padres.","Sus restos fueron trasladados a Siquem y sepultados en la tumba que Abraham Había comprado por una suma de dinero a los hijos de Emor, que habitaban en Siquem.","Al acercarse el tiempo en que debía cumplirse la promesa que Dios había hecho a Abraham, el pueblo creció y se multiplicó en Egipto,","hasta que vino un nuevo rey que no sabía nada acerca de José.","Este rey, empleando la astucia contra nuestro pueblo, maltrató a nuestros padres y los obligó a que abandonaran a sus hijos recién nacidos para que no sobrevivieran.","En ese tiempo nació Moisés, que era muy hermoso delante de Dios. Durante tres meses fue criado en la casa de su padre,","y al ser abandonado, la hija del Faraón lo recogió y lo crió como a su propio hijo.","Así Moisés fue iniciado en toda la sabiduría de los egipcios y llegó a ser poderoso en palabras y obras.","Al cumplir cuarenta años, sintió un vivo deseo de visitar a sus hermanos, los israelitas.","Y como vio que maltrataban a uno de ellos salió en su defensa, y vengó al oprimido matando al egipcio.","Moisés pensaba que sus hermanos iban a comprender que Dios, por su intermedio, les daría la salvación. Pero ellos no lo entendieron así.","Al día siguiente sorprendió a dos israelitas que se estaban peleando y trató de reconciliarlos, diciéndoles: «Ustedes son hermanos, ¿por qué se hacen daño?».","Pero el que maltrataba a su compañero rechazó a Moisés y le dijo: «¿Quién te ha nombrado jefe o árbitro nuestro?","¿Acaso piensas matarme como mataste ayer al egipcio?».","Al oír esto, Moisés huyó y fue a vivir al país de Madián, donde tuvo dos hijos.","Al cabo de cuarenta años se le apareció un ángel en el desierto del monto Sinaí, en la llama de una zarza ardiente.","Moisés quedó maravillado ante tal aparición y, al acercarse para ver mejor, oyó la voy del Señor que le decía:","«Yo soy el Dios de tus padres, el Dios de Abraham, de Isaac y de Jacob». Moisés atemorizado, no se atrevió a mirar.","Entonces el Señor le dijo: «Quítate las sandalias porque estás pisando un lugar sagrado.","Yo he visto la opresión de mi Pueblo que está en Egipto, he oído sus gritos de dolor, y por eso he venido a librarlos. Ahora prepárate, porque he decidido enviarte a Egipto».","Y a este Moisés, a quien ellos rechazaron diciendo: ¿Quién te ha nombrado jefe o árbitro nuestro?, Dios lo envió como jefe y libertador con la ayuda del ángel que se apareció en la zarza.","El los liberó, obrando milagros y signos en Egipto, en el Mar Rojo y en el desierto, durante cuarenta años.","Y este mismo Moisés dijo a los israelitas: Dios suscitará de entre ustedes un profeta semejante a mí.","Y cuando el pueblo estaba congregado en el desierto, él hizo de intermediario en el monte Sinaí, entre el ángel que le habló y nuestros padres, y recibió las palabras de vida que luego nos comunicó.","Pero nuestros padres no sólo se negaron a obedecerle, sino que lo rechazaron y, sintiendo una gran nostalgia por Egipto,","dijeron a Aarón: «Fabrícanos dioses que vayan al frente de nosotros, porque no sabemos qué le ha pasado a ese Moisés, ese hombre que nos hizo salir de Egipto».","Entonces, fabricaron un ternero de oro, ofrecieron un sacrificio al ídolo y festejaron la obra de sus manos.","Pero Dios se apartó de ellos y los entregó al culto de los astros, como está escrito en el libro de los Profetas: \"Israelitas, ¿acaso ustedes me ofrecieron víctimas y sacrificios durante los cuarenta años que estuvieron en el desierto?","Por el contrario, llevaron consigo la carpa de Moloc y la estrella del Dios Refán, esos ídolos que ustedes fabricaron para adorarlos. Por eso yo los deportaré más allá de Babilonia\".","En el desierto, nuestros padres tenían la Morada del Testimonio. Así lo había dispuesto Dios, cuando ordenó a Moisés que la hiciera conforme al modelo que había visto.","Nuestros padres recibieron como herencia esta Morada y, bajo la guía de Josué, la introdujeron en el país conquistado a los pueblos que Dios iba expulsando a su paso. Así fue hasta el tiempo de David.","David, que gozó del favor de Dios, le pidió la gracia de construir una Morada para el Dios de Jacob.","Pero fue Salomón el que le edificó una casa,","si bien es cierto que el Altísimo no habita en casas hechas por la mano del hombre. Así lo dice el Profeta:","\"El cielo es mi trono, y la tierra la tarima de mis pies. ¿Qué casa me edificarán ustedes, dice el Señor, o donde podrá estar mi lugar de reposo?","¿No fueron acaso mis manos las que hicieron todas las cosas?\"","¡Hombres rebeldes, paganos de corazón y cerrados a la verdad! Ustedes siempre resisten al Espíritu Santo y son iguales a sus padres.","¿Hubo algún profeta a quien ellos no persiguieran? Mataron a los que anunciaban la venida del Justo, el mismo que acaba de ser traicionado y asesinado por ustedes,","los que recibieron la Ley por intermedio de los ángeles y no la cumplieron».","Al oír esto, se enfurecieron y rechinaban los dientes contra él.","Esteban, lleno del Espíritu Santo y con los ojos fijos en el cielo, vio la gloria de Dios, y a Jesús, que estaba de pie a la derecha de Dios.","Entonces exclamó: «Veo el cielo abierto y al Hijo del hombre de pie a la derecha de Dios».","Ellos comenzaron a vociferar y, tapándose los oídos, se precipitaron sobre él como un solo hombre,","y arrastrándolo fuera de la ciudad, lo apedrearon. Los testigos se quitaron los mantos, confiándolos a un joven llamado Saulo.","Mientras lo apedreaban, Esteban oraba, diciendo: «Señor Jesús, recibe mi espíritu».","Después, poniéndose de rodillas, exclamó en alta voz: «Señor, no les tengas en cuenta este pecado». Y al decir esto, expiró."],["Saulo aprobó la muerte de Esteban. Ese mismo día, se desencadenó una violenta persecución contra la Iglesia de Jerusalén. Todos, excepto los Apóstoles, se dispersaron por las regiones de Judea y Samaría.","Unos hombres piadosos enterraron a Esteban y lo lloraron con gran pesar.","Saulo, por su parte, perseguía a la Iglesia; iba de casa en casa y arrastraba a hombres y mujeres, llevándolos a la cárcel.","Los que se habían dispersado iban por todas partes anunciando la Palabra.","Felipe descendió a una ciudad de Samaría y allí predicaba a Cristo.","Al oírlo y al ver los milagros que hacía, todos recibían unánimemente las palabras de Felipe.","Porque los espíritus impuros, dando grandes gritos, salían de muchos que estaban poseídos, y buen número de paralíticos y lisiados quedaron curados.","Y fue grande la alegría de aquella ciudad.","Desde hacía un tiempo, vivía en esa ciudad un hombre llamado Simón, el cual con sus artes mágicas tenía deslumbrados a los samaritanos y pretendía ser un gran personaje.","Todos, desde el más pequeño al más grande, lo seguían y decían: «Este hombre es la Fuerza de Dios, esa que es llamada Grande».","Y lo seguían, porque desde hacía tiempo los tenía seducidos con su magia.","Pero cuando creyeron a Felipe, que les anunciaba la Buena Noticia del Reino de Dios y el nombre de Jesucristo, todos, hombres y mujeres, se hicieron bautizar.","Simón también creyó y, una vez bautizado, no se separaba de Felipe. Al ver los signos y los grandes prodigios que se realizaban, él no salía de su asombro.","Cuando los Apóstoles que estaban en Jerusalén oyeron que los samaritanos habían recibido la Palabra de Dios, les enviaron a Pedro y a Juan.","Estos, al llegar, oraron por ellos para que recibieran el Espíritu Santo.","Porque todavía no había descendido sobre ninguno de ellos, sino que solamente estaban bautizados en el nombre del Señor Jesús.","Entonces les impusieron las manos y recibieron el Espíritu Santo.","Al ver que por la imposición de las manos de los Apóstoles se confería el Espíritu Santo, Simón les ofreció dinero,","diciéndoles: «Les ruego que me den ese poder a mí también, para que aquel a quien yo imponga las manos reciba el Espíritu Santo».","Pedro le contestó: «Maldito sea tu dinero y tú mismo, Porque has creído que el don de Dios se compra con dinero.","Tú no tendrás ninguna participación en ese poder, porque tu corazón no es recto a los ojos de Dios.","Arrepiéntete de tu maldad y ora al Señor: quizá él te perdone este mal deseo de tu corazón,","porque veo que estás sumido en la amargura de la hiel y envuelto en los lazos de la iniquidad».","Simón respondió: «Rueguen más bien ustedes al Señor, para que no me suceda nada de lo que acabas de decir».","Y los Apóstoles, después de haber dado testimonio y predicado la Palabra del Señor, mientras regresaban a Jerusalén, anunciaron la Buena Noticia a numerosas aldeas samaritanas.","El Angel del Señor dijo a Felipe: «Levántate y ve hacia el sur, por el camino que baja de Jerusalén a Gaza: es un camino desierto».","El se levantó y partió. Un eunuco etíope, ministro del tesoro y alto funcionario de Candace, la reina de Etiopía, había ido en peregrinación a Jerusalén","y se volvía, sentado en su carruaje, leyendo al profeta Isaías.","El Espíritu Santo dijo a Felipe: «Acércate y camina junto a su carro».","Felipe se acercó y, al oír que leía al profeta Isaías, le preguntó: «¿Comprendes lo que estás leyendo?».","El respondió: «¿Cómo lo puedo entender, si nadie me lo explica?». Entonces le pidió a Felipe que subiera y se sentara junto a él.","El pasaje de la Escritura que estaba leyendo era el siguiente: \"Como oveja fue llevado al matadero; y como cordero que no se queja ante el que lo esquila, así él no abrió la boca.","En su humillación, le fue negada la justicia. ¿Quién podrá hablar de su descendencia, ya que su vida es arrancada de la tierra?\"","El etíope preguntó a Felipe: «Dime, por favor, ¿de quién dice esto el Profeta? ¿De sí mismo o de algún otro?».","Entonces Felipe tomó la palabra y, comenzando por este texto de la Escritura, le anunció la Buena Noticia de Jesús.","Siguiendo su camino, llegaron a un lugar donde había agua, y el etíope dijo: «Aquí hay agua, ¿qué me impide ser bautizado?».","[Felipe dijo: «Si crees de todo corazón, es posible». «Creo, afirmó, que Jesucristo es el Hijo de Dios».]","Y ordenó que detuvieran el carro; ambos descendieron hasta el agua, y Felipe lo bautizó.","Cuando salieron del agua, el Espíritu del Señor, arrebató a Felipe, y el etíope no lo vio más, pero seguía gozoso su camino.","Felipe se encontró en Azoto, y en todas las ciudades por donde pasaba iba anunciando la Buena Noticia, hasta que llegó a Cesarea."],["Saulo, que todavía respiraba amenazas de muerte contra los discípulos del Señor, se presentó al Sumo Sacerdote","y le pidió cartas para las sinagogas de Damasco, a fin de traer encadenados a Jerusalén a los seguidores del Camino del Señor que encontrara, hombres o mujeres.","Y mientras iba caminando, al acercarse a Damasco, una luz que venía del cielo lo envolvió de improviso con su resplandor.","Y cayendo en tierra, oyó una voz que le decía: «Saulo, Saulo, ¿por qué me persigues?».","El preguntó: «¿Quién eres tú Señor?». «Yo soy Jesús, a quien tú persigues, le respondió la voz.","Ahora levántate, y entra en la ciudad: allí te dirán qué debes hacer».","Los que lo acompañaban quedaron sin palabra, porque oían la voz, pero no veían a nadie.","Saulo se levantó del suelo y, aunque tenía los ojos abiertos, no veía nada. Lo tomaron de la mano y lo llevaron a Damasco.","Allí estuvo tres días sin ver, y sin comer ni beber.","Vivía entonces en Damasco un discípulo llamado Ananías, a quien el Señor dijo en una visión: «¡Ananías!». El respondió: «Aquí estoy, Señor».","El Señor le dijo: «Ve a la calle llamada Recta, y busca en casa de Judas a un tal Saulo de Tarso.","El está orando y ha visto en una visión a un hombre llamado Ananías, que entraba y le imponía las manos para devolverle la vista».","Ananías respondió: «Señor, oí decir a muchos que este hombre hizo un gran daño a tus santos en Jerusalén.","Y ahora está aquí con plenos poderes de los jefes de los sacerdotes para llevar presos a todos los que invocan tu Nombre».","El Señor le respondió: «Ve a buscarlo, porque es un instrumento elegido por mí para llevar mi Nombre a todas las naciones, a los reyes y al pueblo de Israel.","Yo le haré ver cuánto tendrá que padecer por mi Nombre».","Ananías fue a la casa, le impuso las manos y le dijo: «Saulo, hermano mío, el Señor Jesús –el mismo que se te apareció en el camino– me envió a ti para que recobres la vista y quedes lleno del Espíritu Santo».","En ese momento, cayeron de sus ojos una especie de escamas y recobró la vista. Se levantó y fue bautizado.","Después comió algo y recobró sus fuerzas. Saulo permaneció algunos días con los discípulos que vivían en Damasco,","y luego comenzó a predicar en las sinagogas que Jesús es el Hijo de Dios.","Todos los que oían quedaban sorprendidos y decían: «¿No es este aquel mismo que perseguía en Jerusalén a los que invocan este Nombre, y que vino aquí para llevarlos presos ante los jefes de los sacerdotes?».","Pero Saulo, cada vez con más vigor, confundía a los judíos que vivían en Damasco, demostrándoles que Jesús es realmente el Mesías.","Al cabo de un tiempo, los judíos se pusieron de acuerdo para quitarle la vida,","pero Saulo se enteró de lo que tramaban contra él. Y como los judíos vigilaban noche y día las puertas de la ciudad, para matarlo,","sus discípulos lo tomaron durante la noche, y lo descolgaron por el muro, metido en un canasto.","Cuando llegó a Jerusalén, trato de unirse a los discípulos, pero todos le tenían desconfianza porque no creían que también él fuera un verdadero discípulo.","Entonces Bernabé, haciéndose cargo de él, lo llevó hasta donde se encontraban los Apóstoles, y les contó en qué forma Saulo había visto al Señor en el camino, cómo le había hablado, y con cuánta valentía había predicado en Damasco en el nombre de Jesús.","Desde ese momento, empezó a convivir con los discípulos en Jerusalén y predicaba decididamente en el nombre del Señor.","Hablaba también con los judíos de lengua griega y discutía con ellos, pero estos tramaban su muerte.","Sus hermanos, al enterarse, lo condujeron a Cesarea y de allí lo enviaron a Tarso.","La Iglesia, entre tanto, gozaba de paz en toda Judea, Galilea y Samaría. Se iba consolidando, vivía en el temor del Señor y crecía en número, asistida por el Espíritu Santo.","Pedro, en una gira por todas las ciudades, visitó también a los santos que vivían en Lida.","Allí encontró a un paralítico llamado Eneas, que estaba postrado en cama desde hacía ocho años.","Pedro le dijo: «Eneas, Jesucristo te devuelve la salud: levántate, y arregla tú mismo la cama». El se levantó en seguida,","y al verlo, todos los habitantes de Lida y de la llanura de Sarón se convirtieron al Señor.","Entre los discípulos de Jope había una mujer llamada Tabitá, que quiere decir «gacela». Pasaba su vida haciendo el bien y repartía abundantes limosnas.","Pero en esos días se enfermó y murió. Después de haberla lavado, la colocaron en la habitación de arriba.","Como Lida está cerca de Jope, los discípulos, enterados de que Pedro estaba allí, enviaron a dos hombres para pedirle que acudiera cuanto antes.","Pedro salió en seguida con ellos. Apenas llegó, lo llevaron a la habitación de arriba. Todas las viudas lo rodearon y, llorando, le mostraban las túnicas y los abrigos que les había hecho Tabitá cuando vivía con ellas.","Pedro hizo salir a todos afuera, se puso de rodillas y comenzó a orar. Volviéndose luego hacia el cadáver, dijo: «Tabitá, levántate». Ella abrió los ojos y, al ver a Pedro, se incorporó.","El la tomó de la mano y la hizo levantar. Llamó entonces a los hermanos y a las viudas, y se las devolvió con vida.","La noticia se extendió por toda la ciudad de Jope, y muchos creyeron en el Señor.","Pedro permaneció algún tiempo en Jope, en la casa de un curtidor llamado Simón."],["Había en Cesarea un hombre llamado Cornelio, centurión de la cohorte itálica.","Era un hombre piadoso y temeroso de Dios, lo mismo que toda su familia; hacía abundantes limosnas al pueblo y oraba a Dios sin cesar.","Este hombre tuvo una visión: un día, cerca de las tres de la tarde, vio claramente al Angel de Dios que entraba en su casa y le decía: «Cornelio».","Este lo miró lleno de temor, y le preguntó: «¿Qué quieres de mí, Señor?». El Angel le dijo: «Tus oraciones y tus limosnas han llegado hasta Dios y él se ha acordado de ti.","Envía ahora algunos hombres a Jope en busca de Simón, llamado Pedro,","que se hospeda en la casa de un tal Simón, un curtidor que vive a la orilla del mar».","En cuanto el Angel se alejó, Cornelio llamó a dos de sus servidores y a un soldado piadoso de los que estaban a sus órdenes.","Después de haberles contado lo sucedido, los envió a Jope.","Al día siguiente, mientras estos se acercaban a la ciudad, Pedro, alrededor del mediodía, subió a la terraza para orar.","Como sintió hambre, pidió de comer. Mientras le preparaban la comida, cayó en éxtasis y tuvo una visión:","vio que el cielo se abría y que bajaba a la tierra algo parecido a un gran mantel, sostenido de sus cuatro puntas.","Dentro de él había toda clase de cuadrúpedos, reptiles y aves del cielo.","Y oyó una voz que le decía: «Vamos, Pedro, mata y come».","Pero Pedro respondió: «De ninguna manera, señor, yo nunca he comido nada manchado ni impuro».","La voz le habló de nuevo, diciendo: «No consideres manchado lo que Dios purificó».","Esto se repitió tres veces, y luego, todo fue llevado otra vez al cielo.","Mientras Pedro, desconcertado, se preguntaba qué podía significar la visión que acababa de tener, llegaron los hombres enviados por Cornelio. Estos averiguaron dónde vivía Simón y se presentaron ante la puerta de la casa.","Golpearon y preguntaron si se hospedaba allí Simón, llamado Pedro.","Como Pedro seguía reflexionando sobre el significado de la visión, el Espíritu Santo le dijo: «Allí hay tres hombres que te buscan.","Baja y no dudes en irte con ellos, porque soy yo quien los he enviado».","Pedro bajó y se acercó a ellos, diciendo: «Yo soy el que ustedes buscan. ¿Para qué vinieron?».","Ellos respondieron: «El centurión Cornelio, hombre justo y temeroso de Dios, que goza de la estima de todos los judíos, recibió de un ángel de Dios la orden de conducirse a su casa para escuchar tus palabras».","Entonces Pedro los hizo pasar y les ofreció hospedaje. Al día siguiente, se puso en camino con ellos, acompañado por unos hermanos de la ciudad de Jope.","Al otro día, llegaron a Cesarea. Cornelio los esperaba, y había reunido a su familia y a sus amigos íntimos.","Cuando Pedro entró, Cornelio fue a su encuentro y se postró a sus pies.","Pero Pedro lo hizo levantar, diciéndole: «Levántate, porque yo no soy más que un hombre».","Y mientras seguía conversando con él, entró y se encontró con un grupo numeroso de personas, que estaban reunidas allí.","Dirigiéndose a ellas, les dijo: «Ustedes saben que está prohibido a un judío tratar con un extranjero o visitarlo. Pero Dios acaba de mostrarme que no hay que considerar manchado o impuro a ningún hombre.","Por eso, cuando ustedes me llamaron, vine sin dudar. Y ahora quisiera saber para qué me llamaron».","Cornelio le respondió: «Hace tres días me encontraba orando en mi casa, alrededor de las tres de la tarde, cuando se me apareció un hombre con vestiduras resplandecientes,","y me dijo: «Cornelio, tu oración ha sido escuchada y Dios se ha acordado de tus limosnas.","Manda a buscar a Simón, llamado Pedro, que está en Jope, a la orilla del mar, en la casa de Simón el curtidor».","En seguida te mandé a buscar y has hecho bien en venir. Ahora estamos reunidos delante de Dios, para escuchar lo que el Señor te ha mandado decirnos».","Entonces Pedro, tomando la palabra, dijo: «Verdaderamente, comprendo que Dios no hace acepción de personas,","y que en cualquier nación, todo el que lo teme y practica la justicia es agradable a él.","El envió su Palabra al pueblo de Israel, anunciándoles la Buena Noticia de la paz por medio de Jesucristo, que es el Señor de todos.","Ustedes ya saben qué ha ocurrido en toda Judea, comenzando por Galilea, después del bautismo que predicaba Juan:","cómo Dios ungió a Jesús de Nazaret con el Espíritu Santo, llenándolo de poder. El pasó haciendo el bien y curando a todos los que habían caído en poder del demonio, porque Dios estaba con él.","Nosotros somos testigos de todo lo que hizo en el país de los judíos y en Jerusalén. Y ellos mataron, suspendiéndolo de un patíbulo.","Pero Dios lo resucitó al tercer día y le concedió que se manifestara,","no a todo el pueblo, sino a testigos elegidos de antemano por Dios: a nosotros, que comimos y bebimos con él, después de su resurrección.","Y nos envió a predicar al pueblo, y atestiguar que él fue constituido por Dios Juez de vivos y muertos.","Todos los profetas dan testimonio de él, declarando que los que creen en él reciben el perdón de los pecados, en virtud de su Nombre».","Mientras Pedro estaba hablando, el Espíritu Santo descendió sobre todos los que escuchaban la Palabra.","Los fieles de origen judío que habían venido con Pedro quedaron maravillados al ver que el Espíritu Santo era derramado también sobre los paganos.","En efecto, los oían hablar diversas lenguas y proclamar la grandeza de Dios. Pedro dijo:","«¿Acaso se puede negar el agua del bautismo a los que recibieron el Espíritu Santo como nosotros?».","Y ordenó que fueran bautizados en el nombre del Señor Jesucristo. Entonces le rogaron que se quedara con ellos algunos días."],["Los Apóstoles y los hermanos de Judea se enteraron de que también los paganos habían recibido la Palabra de Dios.","Y cuando Pedro regresó a Jerusalén, los creyentes de origen judío lo interpelaron,","diciéndole: «¿Cómo entraste en la casa de gente no judía y comiste con ellos?».","Pedro comenzó a contarles detalladamente lo que había sucedido:","«Yo estaba orando en la ciudad de Jope, cuando caí en éxtasis y tuvo una visión. Vi que bajaba del cielo algo parecido a un gran mantel, sostenido de sus cuatro puntas, que vino hasta mí.","Lo miré atentamente y vi que había en él cuadrúpedos, animales salvajes, reptiles y aves.","Y oí una voz que me dijo: «Vamos, Pedro, mata y come».","«De ninguna manera, Señor, respondí, yo nunca he comido nada manchado ni impuro».","Por segunda voz, oí la voz del cielo que me dijo: «No consideres manchado lo que Dios purificó».","Esto se repitió tres veces, y luego, todo fue llevado otra vez al cielo.","En ese momento, se presentaron en la casa donde estábamos tres hombres que habían sido enviados desde Cesarea para buscarme.","El Espíritu Santo me ordenó: que fuera con ellos sin dudar. Me acompañaron también los seis hermanos aquí presentes y llegamos a la casa de aquel hombre.","Este nos contó en qué forma se le había aparecido un ángel, diciéndole: «Envía a alguien a Jope, a buscar a Simón, llamado Pedro.","El te anunciará un mensaje de salvación para ti y para toda tu familia».","Apenas comencé a hablar, el Espíritu Santo descendió sobre ellos, como lo hizo al principio sobre nosotros.","Me acordé entonces de la palabra del Señor: «Juan bautizó con agua, pero ustedes serán bautizados en el Espíritu Santo».","Por lo tanto, si Dios les dio a ellos la misma gracia que a nosotros, por haber creído en el Señor Jesucristo, ¿cómo podía yo oponerme a Dios?».","Después de escuchar estas palabras se tranquilizaron y alabaron a Dios, diciendo: «También a los paganos ha concedido Dios el don de la conversión que conduce a la Vida».","Mientras tanto, los que se habían dispersado durante la persecución que se desató a causa de Esteban, llegaron hasta Fenicia, Chipre y Antioquía, y anunciaban la Palabra únicamente a los judíos.","Sin embargo, había entre ellos algunos hombres originarios de Chipre y de Cirene que, al llegar a Antioquía, también anunciaron a los paganos la Buena Noticia del Señor Jesús.","La mano del Señor los acompañaba y muchos creyeron y se convirtieron.","Al enterarse de esto, la Iglesia de Jerusalén envió a Bernabé a Antioquía.","Cuando llegó y vio la gracia que Dios les había concedido, él se alegró mucho y exhortaba a todos a permanecer fieles al Señor con un corazón firme.","Bernabé era un hombre bondadoso, lleno de Espíritu Santo y de mucha fe. Y una multitud adhirió al Señor.","Entonces partió hacia Tarso en busca de Saulo,","y cuando lo encontró, lo llevó a Antioquía. Ambos vivieron todo un año en esa Iglesia y enseñaron a mucha gente. Y fue en Antioquía, donde por primera vez los discípulos recibieron el nombre de «cristianos».","En esos días, unos profetas llegaron de Jerusalén a Antioquía.","Uno de ellos, llamado Agabo, movido por el Espíritu, se levantó y anunció que el hambre asolaría toda la tierra. Esto ocurrió bajo el reinado de Claudio.","Los discípulos se decidieron a enviar una ayuda a los hermanos de Judea, cada uno según sus posibilidades.","Y así lo hicieron, remitiendo las limosnas a los presbíteros por intermedio de Bernabé y de Saulo."],["Por aquel entonces, el rey Herodes hizo arrestar a algunos miembros de la Iglesia para maltratarlos.","Mandó ejecutar a Santiago, hermano de Juan,","y al ver que esto agradaba a los judíos, también hizo arrestar a Pedro. Eran los días de «los panes Acimos».","Después de arrestarlo, lo hizo encarcelar, poniéndolo bajo la custodia de cuatro relevos de guardia, de cuatro soldados cada uno. Su intención era hacerlo comparecer ante el pueblo después de la Pascua.","Mientras Pedro estaba bajo custodia en la prisión, la Iglesia no cesaba de orar a Dios por él.","La noche anterior al día en que Herodes pensaba hacerlo comparecer, Pedro dormía entre los soldados, atado con dos cadenas, y los otros centinelas vigilaban la puerta de la prisión.","De pronto, apareció el Angel del Señor y una luz resplandeció en el calabozo. El Angel sacudió a Pedro y lo hizo levantar, diciéndole: «¡Levántate rápido!». Entonces las cadenas se le cayeron de las manos.","El Angel le dijo: «Tienes que ponerte el cinturón y las sandalias» y Pedro lo hizo. Después de dijo: «Cúbrete con el manto y sígueme».","Pedro salió y lo seguía; no se daba cuenta de que era cierto lo que estaba sucediendo por intervención del Angel, sino que creía tener una visión.","Pasaron así el primero y el segundo puesto de guardia, y llegaron a la puerta de hierro que daba a la ciudad. La puerta se abrió sola delante de ellos. Salieron y anduvieron hasta el extremo de una calle, y en seguida el Angel se alejó de él.","Pedro, volviendo en sí, dijo: «Ahora sé que realmente el Señor envió a su Angel y me libró de las manos de Herodes y de todo cuanto esperaba el pueblo judío».","Y al advertir lo que le había sucedido, se dirigió a la casa de María, la madre de Juan, llamado Marcos, donde un grupo numeroso se hallaba reunido en oración.","Cuando golpeó a la puerta de calle, acudió una sirvienta llamada Rosa;","esta, al reconocer su voz, se alegró tanto, que en lugar de abrir, entró corriendo a anunciar que Pedro estaba en la puerta.","«Estás loca», le respondieron. Pero ella insistía que era verdad. Ellos le dijeron: «Será su ángel».","Mientras tanto, Pedro seguía llamando. Cuando abrieron y vieron que era él, no salían de su asombro.","Pedro le hizo señas con la mano para que se callaran, y les relató cómo el Señor lo había sacado de la cárcel, añadiendo: «Hagan saber esto a Santiago y a los hermanos». Y saliendo de allí, se fue a otro lugar.","Cuando amaneció, se produjo un gran alboroto entre los soldados, porque no podían explicarse qué había pasado con Pedro.","Herodes lo hizo buscar, pero como no lo encontraron, después de haber interrogado a los guardias, dio orden de ejecutarlos. Luego descendió de Judea a Cesarea, y permaneció allí.","Herodes estaba en grave conflicto con los habitantes de Tiro y Sidón. Estos se pusieron de acuerdo para ir a verlo, y después de haberse conquistado a Blasto, el camarero del rey, solicitaron la reconciliación, ya que importaban sus víveres del territorio del rey.","El día fijado, Herodes se sentó en su trono con la vestidura real y les dirigió la palabra.","El pueblo comenzó a gritar: «¡Es un dios el que habla, no un hombre!».","Pero en ese mismo instante, el Angel del Señor lo hirió, por no haber dado gloria a Dios, y Herodes murió carcomido por los gusanos.","Mientras tanto, la Palabra de Dios se difundía incesantemente.","Bernabé y Saulo, una vez cumplida su misión, volvieron de Jerusalén a Antioquía, llevando consigo a Juan, llamado Marcos."],["En la Iglesia de Antioquía había profetas y doctores, entre los cuales estaban Bernabé y Simeón, llamado el Negro, Lucio de Cirene, Manahén, amigo de infancia del tetrarca Herodes, y Saulo.","Un día, mientras celebraban el culto del Señor y ayunaban, el Espíritu Santo les dijo: «Resérvenme a Saulo y a Bernabé para la obra a la cual los he llamado».","Ellos, después de haber ayunado y orado, les impusieron las manos y los despidieron.","Saulo y Bernabé, enviados por el Espíritu Santo, fueron a Seleucia y de allí se embarcaron para Chipre.","Al llegar a Salamina anunciaron la Palabra de Dios en las sinagogas de los judíos, y Juan colaboraba con ellos.","Recorrieron toda la isla y llegaron hasta Pafos, donde encontraron a un mago judío llamado Barjesús, que se hacía pasar por profeta","y estaba vinculado al procónsul Sergio Pablo, hombre de gran prudencia. Este hizo llamar a Bernabé y a Saulo, porque deseaba escuchar la Palabra de Dios.","Pero los discípulos chocaron con la oposición de Barjesús –llamado Elimas, que significa mago– el cual quería impedir que el procónsul abrazara la fe.","Saulo, llamado también Pablo, lleno del Espíritu Santo, clavó los ojos en él,","y le dijo: «Hombre falso y lleno de maldad, hijo del demonio, enemigo de la justicia, ¿cuándo dejarás de torcer los rectos caminos del Señor?","Ahora la mano del Señor va a caer sobre ti: quedarás ciego y privado por un tiempo de la luz del sol». En ese mismo momento, se vio envuelto en oscuridad y tinieblas, y andaba a tientas buscando a alguien que le tendiera la mano.","Al ver lo que había sucedido, el procónsul, profundamente impresionado por la doctrina del Señor, abrazó la fe.","Desde Pafos, donde se embarcaron, Pablo y sus compañeros llegaron a Perge de Panfilia. Juan se separó y volvió a Jerusalén,","pero ellos continuaron su viaje, y de Perge fueron a Antioquía de Pisidia. El sábado entraron en la sinagoga y se sentaron.","Después de la lectura de la Ley y de los Profetas, los jefes de la sinagoga les mandaron a decir: «Hermanos, si tienen que dirigir al pueblo alguna exhortación, pueden hablar».","Entonces Pablo se levantó y, pidiendo silencio con un gesto, dijo: «Escúchenme, israelitas y todos los que temen a Dios.","El Dios de Este Pueblo, el Dios de Israel, eligió a nuestros padres y los convirtió en un gran Pueblo, cuando todavía vivían como extranjeros en Egipto. Luego, con el poder de su brazo, los hizo salir de allí","y los cuidó durante cuarenta años en el desierto.","Después, en el país de Canaán, destruyó a siete naciones y les dio en posesión sus tierras,","al cabo de unos cuatrocientos cincuenta años. A continuación, les dio Jueces hasta el profeta Samuel.","Pero ellos pidieron un rey y Dios les dio a Saúl, hijo de Quis, de la tribu de Benjamín, por espacio de cuarenta años.","Y cuando Dios desechó a Saúl, les suscitó como rey a David, de quien dio este testimonio: He encontrado en David, el hijo de Jesé, a un hombre conforme a mi corazón que cumplirá siempre mi voluntad.","De la descendencia de David, como lo había prometido, Dios hizo surgir para Israel un Salvador, que es Jesús.","Como preparación a su venida, Juan había predicado un bautismo de penitencia a todo el pueblo de Israel.","Y al final de su carrera, Juan decía: «Yo no soy el que ustedes creen, pero sepan que después de mí viene aquel a quien yo no soy digno de desatar las sandalias».","Hermanos, este mensaje de salvación está dirigido a ustedes: los descendientes de Abraham y los que temen a Dios.","En efecto, la gente de Jerusalén y sus jefes no reconocieron a Jesús, ni entendieron las palabras de los profetas que se leen cada sábado, pero las cumplieron sin saberlo, condenado a Jesús.","Aunque no encontraron nada en él que mereciera la muerte, pidieron a Pilato que lo condenara.","Después de cumplir todo lo que estaba escrito de él, lo bajaron del patíbulo y lo pusieron en el sepulcro.","Pero Dios lo resucitó de entre los muertos","y durante un tiempo se apareció a los que habían subido con él de Galilea a Jerusalén, los mismos que ahora son sus testigos delante del pueblo.","Y nosotros les anunciamos a ustedes esta Buena Noticia: la promesa que Dios hizo a nuestros padres,","fue cumplida por él en favor de sus hijos, que somos nosotros, resucitando a Jesús, como está escrito en el Salmo segundo: Tú eres mi Hijo; yo te he engendrado hoy.","Que Dios lo ha resucitado de entre los muertos y que no habrá de someterse a la corrupción, es lo que el mismo Dios ha declarado diciendo: Cumpliré las santas promesas hechas a David, aquellas que no pueden fallar.","Por eso también dice en otro pasaje: No permitirás que tu Santo sufra la corrupción.","Sin embargo David, después de haber cumplido la voluntad de Dios en su tiempo, murió, fue a reunirse con sus padres y sufrió la corrupción.","Pero aquel a quien Dios resucitó no sufrió la corrupción.","Ustedes deben saber que la remisión de los pecados les ha sido anunciada por él. Y la justificación que ustedes no podían alcanzar por la Ley de Moisés, gracias a él,","la alcanza todo el que cree.","Tengan cuidado de que no les suceda lo que dijeron los profetas:","\"¡Ustedes, los que desprecian, llénense de estupor y ocúltense! Porque en estos días voy a realizar algo, que si alguien lo contara no lo podrían creer\"».","A la salida, les pidieron que retomaran el mismo tema el sábado siguiente.","Cuando se disolvió la asamblea, muchos judíos y prosélitos que adoraban a Dios siguieron a Pablo y a Bernabé. Estos conversaban con ellos, exhortándolos a permanecer fieles a la gracia de Dios.","Casi toda la ciudad se reunió el sábado siguiente para escuchar la Palabra de Dios.","Al ver esa multitud, los judíos se llenaron de envidia y con injurias contradecían las palabras de Pablo.","Entonces Pablo y Bernabé, con gran firmeza, dijeron: «A ustedes debíamos anunciar en primer lugar la Palabra de Dios, pero ya que la rechazan y no se consideran dignos de la Vida eterna, nos dirigimos ahora a los paganos.","Así nos ha ordenado el Señor: \"Yo te he establecido para ser la luz de las naciones, para llevar la salvación hasta los confines de la tierra\"».","Al oír esto, los paganos, llenos de alegría, alabaron la Palabra de Dios, y todos los que estaban destinados a la vida eterna abrazaron la fe.","Así la Palabra del Señor se iba extendiendo por toda la región.","Pero los judíos instigaron a unas mujeres piadosas que pertenecían a la aristocracia y a los principales de la ciudad, provocando una persecución contra Pablo y Bernabé, y los echaron de su territorio.","Estos, sacudiendo el polvo de sus pies en señal de protesta contra ellos, se dirigieron a Iconio.","Los discípulos, por su parte, quedaron llenos de alegría y del Espíritu Santo."],["En Iconio, Pablo y Bernabé entraron en la sinagoga de los judíos, como lo hacían habitualmente, y predicaron de tal manera que un gran número de judíos y paganos abrazaron la fe.","Pero los judíos que no creyeron, incitaron a los paganos y los indispusieron en contra de los hermanos.","A pesar de todo, Pablo y Bernabé prolongaron su estadía y hablaban con toda libertad, confiados en el Señor que confirmaba el mensaje de su gracia, dándoles el poder de realizar signos y prodigios.","Los habitantes de la ciudad se dividieron en dos bandos, uno en favor de los judíos y otro en favor de los Apóstoles.","Pero como los paganos y los judíos, dirigidos por sus jefes, intentaron maltratar y apedrear a los Apóstoles,","estos, al enterarse, huyeron a Listra y a Derbe, ciudades de Licaonia, y a sus alrededores;","y allí anunciaron la Buena Noticia.","Había en Listra un hombre que tenía las piernas paralizadas. Como era tullido de nacimiento, nunca había podido caminar,","y sentado, escuchaba hablar a Pablo. Este mirándolo fijamente, vio que tenía la fe necesaria para ser curado,","y le dijo en voz alta: «Levántate, y permanece erguido sobre tus pies». El se levantó de un salto y comenzó a caminar.","Al ver lo que Pablo acababa de hacer, la multitud comenzó a gritar en dialecto licaonio: «Los dioses han descendido hasta nosotros en forma humana,","y daban a Bernabé el nombre de Júpiter, y a Pablo el de Mercurio porque era el que llevaba la palabra.","El sacerdote del templo de Júpiter que estaba a la entrada de la ciudad, trajo al atrio unos toros adornados de guirnaldas y, junto con la multitud, se disponía a sacrificarlos.","Cuando Pablo y Bernabé se enteraron de esto, rasgaron sus vestiduras y se precipitaron en medio de la muchedumbre, gritando:","«Amigos, ¿qué están haciendo? Nosotros somos seres humanos como ustedes, y hemos venido a anunciarles que deben abandonar esos ídolos para convertirse al Dios viviente que hizo el cielo y la tierra, el mar y todo lo que hay en ellos.","En los tiempos pasados, él permitió que las naciones siguieran sus propios caminos.","Sin embargo, nunca dejó de dar testimonio de sí mismo, prodigando sus beneficios, enviando desde el cielo lluvias y estaciones fecundas, dando el alimento y llenando de alegría los corazones».","Pero a pesar de todo lo que dijeron, les costó mucho impedir que la multitud les ofreciera un sacrificio","Vinieron de Antioquía y de Iconio algunos judíos que lograron convencer a la multitud. Entonces apedrearon a Pablo y, creyéndolo muerto, lo arrastraron fuera de la ciudad.","Pero él se levantó y, rodeado de sus discípulos, regresó a la ciudad. Al día siguiente, partió con Bernabé rumbo a Derbe.","Después de haber evangelizado esta ciudad y haber hechos numerosos discípulos, volvieron a Listra, a Iconio y a Antioquía de Pisidia.","Confortaron a sus discípulos y los exhortaron a perseverar en la fe, recordándoles que es necesario pasar por muchas tribulaciones para entrar en el Reino de Dios.","En cada comunidad establecieron presbíteros, y con oración y ayuno, los encomendaron al Señor en el que habían creído.","Atravesaron Pisidia y llegaron a Panfilia.","Luego anunciaron la Palabra en Perge y descendieron a Atalía.","Allí se embarcaron para Antioquía, donde habían sido encomendados a la gracia de Dios para realizar la misión que acababa de cumplir.","A su llegada, convocaron a los miembros de la Iglesia y les contaron todo lo que Dios había hecho con ellos y cómo había abierto la puerta de la fe a los paganos.","Después permanecieron largo tiempo con los discípulos."],["Algunas personas venidas de Judea enseñaban a los hermanos que si no se hacían circuncidar según el rito establecido por Moisés, no podían salvarse.","A raíz de esto, se produjo una agitación: Pablo y Bernabé discutieron vivamente con ellos, y por fin, se decidió que ambos, junto con algunos otros, subieran a Jerusalén para tratar esta cuestión con los Apóstoles y los presbíteros.","Los que habían sido enviados por la Iglesia partieron y atravesaron Fenicia y Samaría, contando detalladamente la conversión de los paganos. Esto causó una gran alegría a todos los hermanos.","Cuando llegaron a Jerusalén, fueron bien recibidos por la Iglesia, por los Apóstoles y los presbíteros, y relataron todo lo que Dios había hecho con ellos.","Pero se levantaron algunos miembros de la secta de los fariseos que habían abrazado la fe, y dijeron que era necesario circuncidar a los paganos convertidos y obligarlos a observar la Ley de Moisés.","Los Apóstoles y los presbíteros se reunieron para deliberar sobre este asunto.","Al cabo de una prolongada discusión, Pedro se levantó y dijo: «Hermanos, ustedes saben que Dios, desde los primeros días, me eligió entre todos ustedes para anunciar a los paganos la Palabra del Evangelio, a fin de que ellos abracen la fe.","Y Dios, que conoce los corazones, dio testimonio en favor de ellos, enviándoles el Espíritu Santo, lo mismo que a nosotros.","El no hizo ninguna distinción entre ellos y nosotros, y los purificó por medio de la fe.","¿Por qué ahora ustedes tientan a Dios, pretendiendo imponer a los discípulos un yugo que ni nuestros padres ni nosotros pudimos soportar?","Por el contrario, creemos que tanto ellos como nosotros somos salvados por la gracia del Señor Jesús».","Después, toda la asamblea hizo silencio para oír a Bernabé y a Pablo, que comenzaron a relatar los signos y prodigios que Dios había realizado entre los paganos por intermedio de ellos.","Cuando dejaron de hablar, Santiago tomó la palabra, diciendo: «Hermano, les ruego que me escuchen:","Simón les ha expuesto cómo Dios dispuso desde el principio elegir entre las naciones paganas, un Pueblo consagrado a su Nombre.","Con esto concuerdan las palabras de los profetas que dicen:","\"Después de esto, yo volveré y levantaré la choza derruida de David; restauraré sus ruinas y la reconstruiré,","para que el resto de los hombres busque al Señor, lo mismo que todas las naciones que llevan mi Nombre. Así dice el Señor, que da","a conocer estas cosas desde la eternidad\".","Por eso considero que no se debe inquietar a los paganos que se convierten a Dios,","sino que solamente se les debe escribir, pidiéndoles que se abstengan de lo que está contaminado por los ídolos, de las uniones ilegales, de la carne de animales muertos sin desangrar y de la sangre.","Desde hace muchísimo tiempo, en efecto, Moisés tiene en cada ciudad sus predicadores que leen la Ley en la sinagoga todos los sábados».","Entonces los Apóstoles, los presbíteros y la Iglesia entera, decidieron elegir a algunos de ellos y enviarlos a Antioquía con Pablo y Bernabé. Eligieron a Judas, llamado Barsabás, y a Silas, hombres eminentes entre los hermanos","y les encomendaron llevar la siguiente carta: «Los Apóstoles y los presbíteros saludamos fraternalmente a los hermanos de origen pagano, que están en Antioquía, en Siria y en Cilicia.","Habiéndonos enterado de que algunos de los nuestros, sin mandato de nuestra parte, han sembrado entre ustedes la inquietud y provocado el desconcierto,","hemos decidido de común acuerdo elegir a unos delegados y enviárselos junto con nuestros queridos Bernabé y Pablo,","los cuales han consagrado su vida al nombre de nuestro Señor Jesucristo.","Por eso les enviamos a Judas y a Silas, quienes les transmitirán de viva voz este mismo mensaje.","El Espíritu Santo, y nosotros mismos, hemos decidido no imponerles ninguna carga más que las indispensables, a saber:","que se abstengan de la carne inmolada a los ídolos, de la sangre, de la carne de animales muertos sin desangrar y de las uniones ilegales. Harán bien en cumplir todo esto. Adiós».","Los delegados, después de ser despedidos, descendieron a Antioquía donde convocaron a la asamblea y le entregaron la carta.","Esta fue leída y todos se alegraron por el aliento que les daba.","Judas y Silas, que eran profetas, exhortaron a sus hermanos y los confirmaron, hablándoles largamente.","Al cabo de un tiempo, los hermanos los enviaron nuevamente a la comunidad que los había elegido, despidiéndolos en paz.","[Como Silas creyó que debía quedarse, Judas partió solo.]","Pablo y Bernabé permanecieron en Antioquía, enseñando y anunciando la Buena Noticia de la Palabra del Señor, junto con muchos otros.","Algún tiempo después, Pablo dijo a Bernabé: «Volvamos a visitar a los hermanos que están en las ciudades donde ya hemos anunciado la palabra del Señor, para ver cómo se encuentran».","Bernabé quería llevar consigo también a Juan, llamado Marcos.","Pero Pablo consideraba que no debía llevar a quien los había abandonado cuando estaban en Panfilia y no había trabajado con ellos.","La discusión fue tan viva que terminaron por separarse; Bernabé, llevando consigo a Marcos, se embarcó rumbo a Chipre.","Pablo, por su parte, eligió por compañero a Silas y partió, encomendado por sus hermanos a la gracia del Señor.","Así atravesó la Siria y la Cilicia, confirmando a las comunidades."],["Pablo llegó luego a Derbe y más tarde a Listra, donde había un discípulo llamado Timoteo, hijo de una judía convertida a la fe y de padre pagano.","Timoteo gozaba de buena fama entre los hermanos de Listra y de Iconio.","Pablo quería llevarlo consigo, y por eso lo hizo circuncidar en consideración a los judíos que había allí, ya que todo el mundo sabía que su padre era pagano.","Por las ciudades donde pasaban, transmitían las decisiones tomadas en Jerusalén por los Apóstoles y los presbíteros, recomendando que las observaran.","Así, las Iglesias se consolidaban en la fe, y su número crecía día tras día.","Como el Espíritu Santo les había impedido anunciar la Palabra en la provincia de Asia, atravesaron Frigia y la región de Galacia.","Cuando llegaron a los límites de Misia, trataron de entrar en Bitinia, pero el Espíritu de Jesús no se lo permitió.","Pasaron entonces por Misia y descendieron a Tróade.","Durante la noche, Pablo tuvo una visión. Vio a un macedonio de pie, que le rogaba: «Ven hasta Macedonia y ayúdanos».","Apenas tuvo esa visión, tratamos de partir para Macedonia, convencidos de que Dios nos llamaba para que la evangelizáramos.","Nos embarcamos en Tróade y fuimos derecho a Samotracia, y al día siguiente a Neápolis.","De allí fuimos a Filipos, ciudad importante de esta región de Macedonia y colonia romana. Pasamos algunos días en esta ciudad,","y el sábado nos dirigimos a las afueras de la misma, a un lugar que estaba a orillas del río, donde se acostumbraba a hacer oración. Nos sentamos y dirigimos la palabra a las mujeres que se habían reunido allí.","Había entre ellas una, llamada Lidia, negociante en púrpura, de la ciudad de Tiatira, que adoraba a Dios. El Señor le tocó el corazón para que aceptara las palabras de Pablo.","Después de bautizarse, junto con su familia, nos pidió: «Si ustedes consideran que he creído verdaderamente en el Señor, vengan a alojarse en mi casa»; y nos obligó a hacerlo.","Un día, mientras nos dirigíamos al lugar de oración, nos salió al encuentro una muchacha poseída de un espíritu de adivinación, que daba mucha ganancia a sus patrones adivinando la suerte.","Ella comenzó a seguirnos, a Pablo y a nosotros, gritando: «Esos hombres son los servidores del Dios Altísimo, que les anuncian a ustedes el camino de la salvación».","Así lo hizo durante varios días, hasta que al fin Pablo se cansó y, dándose vuelta, dijo al espíritu: «Yo te ordeno en nombre de Jesucristo que salgas de esta mujer», y en ese mismo momento el espíritu salió de ella.","Pero sus patrones, viendo desvanecerse las esperanzas y de lucro, se apoderaron de Pablo y de Silas, los arrastraron hasta la plaza pública ante las autoridades,","y llevándolos delante de los magistrados, dijeron: «Esta gente está sembrando la confusión en nuestra ciudad. Son unos judíos","que predican ciertas costumbres que nosotros, los romanos, no podemos admitir ni practicar».","La multitud se amotinó en contra de ellos, y los magistrados les hicieron arrancar la ropa y ordenaron que los azotaran.","Después de haberlos golpeado despiadadamente, los encerraron en la prisión, ordenando al carcelero que los vigilara con mucho cuidado.","Habiendo recibido esta orden, el carcelero los encerró en una celda interior y les sujetó los pies en el cepo.","Cerca de la medianoche, Pablo y Silas oraban y cantaban alabanzas de Dios, mientras los otros prisioneros los escuchaban.","De pronto, la tierra comenzó a temblar tan violentamente que se conmovieron los cimientos de la cárcel, y en un instante, todas las puertas se abrieron y las cadenas de los prisioneros se soltaron.","El carcelero se despertó sobresaltado y, al ver abiertas las puertas de la prisión, desenvainó su espada con la intención de matarse, creyendo que los prisioneros se habían escapado.","Pero Pablo le gritó: «No te hagas ningún mal, estamos todos aquí».","El carcelero pidió unas antorchas, entró precipitadamente en la celda y, temblando, se echó a los pies de Pablo y de Silas.","Luego los hizo salir y les preguntó: «Señores, ¿qué debo hacer para alcanzar la salvación?».","Ellos le respondieron: «Cree en el Señor Jesús y te salvarás, tú y toda tu familia».","En seguida le anunciaron la Palabra del Señor, a él y a todos los de su casa.","A esa misma hora de la noche, el carcelero los atendió y curó sus llagas. Inmediatamente después, fue bautizado junto con toda su familia.","Luego los hizo subir a su casa y preparó la mesa para festejar con los suyos la alegría de haber creído en Dios.","Cuando amaneció, los magistrados enviaron a los inspectores para que dijeran al carcelero: «Deja en libertad a esos hombres».","El carcelero comunicó entonces a Pablo» «Los magistrados me mandan decir que los deje en libertad; por lo tanto, salgan y vayan en paz».","Pero Pablo respondió a los inspectores: «Ellos nos hicieron azotar públicamente sin juicio previo, a nosotros que somos ciudadanos romanos, y nos pusieron en la cárcel. ¡Y ahora nos quieren hacer salir a escondidas! ¡De ninguna manera! Que vengan ellos en persona a dejarnos en libertad».","Los inspectores repitieron estas palabras a los magistrados; estos, al enterarse de que eran ciudadanos romanos, se asustaron","y fueron a tratar amigablemente con ellos. Luego los pusieron en libertad y los invitaron a alejarse de la ciudad.","Cuando salieron de la prisión, Pablo y Silas fueron a la casa de Lidia, donde volvieron a ver a los hermanos y los exhortaron. Después partieron"],["Atravesaron Anfípolis y Apolonia, y llegaron a Tesalónica, donde los judíos tenían una sinagoga.","Pablo, como de costumbre, se dirigió a ellos y discutió durante tres sábados, basándose en la Escritura.","Explicaba los textos y demostraba que el Mesías debía sufrir y resucitar de entre los muertos. «Y el Mesías, afirmaba, es este Jesús que yo les anuncio».","Algunos se convencieron y se unieron al grupo de Pablo y de Silas, lo mismo que un gran número de adoradores de Dios, de paganos y no pocas mujeres influyentes.","Llenos de envidia, los judíos reunieron un grupo de gente de la calle y promovieron un alboroto, sembrando la agitación en la ciudad. Entonces se presentaron delante de la casa de Jasón en busca de Pablo y de Silas, para conducirlos ante la asamblea del pueblo.","Como no los encontraron, arrastraron a Jasón y a algunos hermanos ante los magistrados de la ciudad, gritando: «Esos que han revolucionado todo el mundo, han venido también aquí","y Jasón los ha recibido en su casa. Toda esta gente contraviene los edictos del Emperador, pretendiendo que hay otro rey, llamado Jesús».","Estos gritos impresionaron mucho a la multitud y a los magistrados,","y solamente después de haber exigido una fianza de parte de Jasón y de los otros, los pusieron en libertad.","Esa misma noche, los hermanos hicieron partir a Pablo y a Silas hacia Berea. En cuanto llegaron, se dirigieron a la sinagoga de los judíos.","Como estos eran mejores que los de Tesalónica, acogieron la Palabra con sumo interés, y examinaban todos los días las Escrituras para verificar la exactitud de lo que oían.","Muchos de ellos abrazaron la fe, lo mismo que algunos paganos, entre los cuales había mujeres de la aristocracia y un buen número de hombres.","Pero, cuando los judíos de Tesalónica se enteraron de que Pablo había anunciado la Palabra de Dios también en Berea, fueron allí a perturbar a la multitud sembrando la agitación.","Entonces los hermanos hicieron partir inmediatamente a Pablo en dirección al mar; Silas y Timoteo, en cambio, permanecieron allí.","Los que acompañaban a Pablo lo condujeron hasta Atenas, y luego volvieron con la orden de que Silas y Timoteo se reunieran con él lo más pronto posible.","Mientras los esperaba en Atenas, Pablo sentía que la indignación se apoderaba de él, al contemplar la ciudad llena de ídolos.","Discutía en la sinagoga con los judíos y con los que adoraban a Dios, y también lo hacía diariamente en la plaza pública con los que pasaban por allí.","Incluso, algunos filósofos epicúreos y estoicos dialogaban con él. Algunos comentaban: «¿Qué estará diciendo este charlatán?», y otros: «Parece ser un predicador de divinidades extranjeras», porque Pablo anunciaba a Jesús y la resurrección.","Entonces lo llevaron con ellos al Areópago y le dijeron: «¿Podríamos saber en qué consiste la nueva doctrina que tú enseñas?","Las cosas que nos predicas nos parecen extrañas y quisiéramos saber qué significan».","Porque todos los atenienses y los extranjeros que residían allí, no tenían otro pasatiempo que el de transmitir o escuchar la última novedad.","Pablo, de pie, en medio del Aréopago, dijo: Atenienses, veo que ustedes son, desde todo punto de vista, los más religiosos de todos los hombres.","En efecto, mientras me paseaba mirando los monumentos sagrados que ustedes tienen, encontré entre otras cosas un altar con esta inscripción: «Al dios desconocido». Ahora, yo vengo a anunciarles eso que ustedes adoran sin conocer.","El Dios que ha hecho el mundo y todo lo que hay en él no habita en templos hechos por manos de hombre, porque es el Señor del cielo y de la tierra.","Tampoco puede ser servido por manos humanas como si tuviera necesidad de algo, ya que él da a todos la vida, el aliento y todas las cosas.","El hizo salir de un solo principio a todo el género humano para que habite sobre toda la tierra, y señaló de antemano a cada pueblo sus épocas y sus fronteras,","para que ellos busquen a Dios, aunque sea a tientas, y puedan encontrarlo. Porque en realidad, él no está lejos de cada uno de nosotros.","En efecto, en él vivimos, nos movemos y existimos, como muy bien lo dijeron algunos poetas de ustedes: «Nosotros somos también de su raza».","Y si nosotros somos de la raza de Dios, no debemos creer que la divinidad es semejante al oro, la plata o la piedra, trabajados por el arte y el genio del hombre.","Pero ha llegado el momento en que Dios, pasando por alto el tiempo de la ignorancia, manda a todos los hombres, en todas partes, que se arrepientan.","Porque él ha establecido un día para juzgar al universo con justicia, por medio de un Hombre que él ha destinado y acreditado delante de todos, haciéndolo resucitar de entre los muertos».","Al oír las palabras «resurrección de los muertos», unos se burlaban y otros decían: «Otro día te oiremos hablar sobre esto».","Así fue cómo Pablo se alejó de ellos.","Sin embargo, algunos lo siguieron y abrazaron la fe. Entre ellos, estaban Dionisio el Areopagita, una mujer llamada Dámaris y algunos otros."],["Después de esto, Pablo dejó Atenas y fue a Corinto.","Allí encontró a un judío llamado Aquila, originario del Ponto, que acababa de llegar de Italia con su mujer Priscila, a raíz de un edicto de Claudio que obligaba a todos los judíos a salir de Roma. Pablo fue a verlos,","y como ejercía el mismo oficio, se alojó en su casa y trabajaba con ellos haciendo tiendas de campaña.","Todos los sábados, Pablo discutía en la sinagoga y trataba de persuadir tanto a los judíos como a los paganos.","Cuando Silas y Timoteo llegaron a Macedonia, Pablo se dedicó por entero a la predicación de la Palabra, dando testimonio a los judíos de que Jesús es el Mesías.","Pero como ellos lo contradecían y lo injuriaban, sacudió su manto en señal de protesta, diciendo: «Que la sangre de ustedes caiga sobre sus cabezas. Yo soy inocente de eso; en adelante me dedicaré a los paganos».","Entonces, alejándose de allí, fue a lo de un tal Ticio Justo, uno de los que adoraban a Dios y cuya casa lindaba con la sinagoga.","Crispo, el jefe de la sinagoga, creyó en el Señor, junto con toda su familia. También muchos habitantes de Corinto, que habían escuchado a Pablo, abrazaron la fe y se hicieron bautizar.","Una noche, el Señor dijo a Pablo en una visión: «No temas. Sigue predicando y no te calles.","Yo estoy contigo. Nadir pondrá la mano sobre ti para dañarte, porque en esta ciudad hay un pueblo numeroso que me está reservado».","Pablo se radicó allí un año y medio, enseñando la Palabra de Dios.","Durante el gobierno del procónsul Galión en Acaya, los judíos se confabularon contra Pablo y lo condujeron ante el tribunal,","diciendo: «Este hombre induce a la gente a que adore a Dios de una manera contraria a la Ley».","Pablo estaba por hablar, cuando Galión dijo a los judíos: «Si se tratara de algún crimen o de algún delito grave, sería razonable que los atendiera.","Pero tratándose de discusiones sobre palabras y nombres, y sobre la Ley judía, el asunto les concierne a ustedes; yo no quiero ser juez en estas cosas».","Y los hizo salir del tribunal.","Entonces todos se apoderaron de Sóstenes, el jefe de la sinagoga, y lo golpearon ante el tribunal. Pero a Galión todo esto lo tuvo sin cuidado.","Pablo permaneció todavía un cierto tiempo en Corinto. Después se despidió de sus hermanos y se embarcó hacia Siria en compañía de Priscila y de Aquila. En Cencreas, a raíz de un voto que había hecho, se hizo cortar el cabello.","Cuando llegaron a Efeso, Pablo se separó de sus compañeros para ir a la sinagoga y dialogar con los judíos.","Estos le rogaron que se quedara más tiempo, pero Pablo no accedió,","sino que se despidió de ellos, diciéndoles: «Volveré otra vez, si Dios quiere». Y partió de Efeso.","Desembarcó en Cesarea, subió para saludar la Iglesia y luego descendió a Antioquía.","Después de haber permanecido un tiempo allí, partió de nuevo y recorrió sucesivamente la región de Galacia y la Frigia, animando a todos los discípulos.","Un judío llamado Apolo, originario de Alejandría, había llegado a Efeso. Era un hombre elocuente y versado en las Escrituras.","Había sido iniciado en el Camino del Señor y, lleno de fervor, exponía y enseñaba con precisión lo que se refiere a Jesús, aunque no conocía otro bautismo más que el de Juan.","Comenzó a hablar con decisión en la sinagoga. Después de oírlo, Priscila y Aquila lo llevaron con ellos y le explicaron más exactamente el Camino de Dios.","Como él pensaba ir a Acaya, los hermanos lo alentaron, y escribieron a los discípulos para que lo recibieran de la mejor manera posible. Desde que llegó a Corinto fue de gran ayuda, por la gracia de Dios, para aquellos que habían abrazado la fe,","porque refutaba vigorosamente a los judíos en público, demostrando por medio de las Escrituras que Jesús es el Mesías."],["Mientras Apolo permanecía en Corinto, Pablo atravesando la región interior, llegó a Efeso. Allí encontró a algunos discípulos","y les preguntó: «Cuando ustedes abrazaron la fe, ¿recibieron el Espíritu Santo?». Ellos le dijeron: «Ni siquiera hemos oído decir que hay un Espíritu Santo».","«Entonces, ¿qué bautismo recibieron?», les preguntó Pablo. «El de Juan», respondieron.","Pablo les dijo: «Juan bautizaba con el bautismo de penitencia, diciendo al pueblo que creyera en el que vendría después de él, es decir, en Jesús».","Al oír estas palabras, ellos se hicieron bautizar en el nombre del Señor Jesús.","Pablo les impuso las manos, y descendió sobre ellos el Espíritu Santo. Entonces comenzaron a hablar en distintas lenguas y a profetizar.","Eran en total unos doce hombres.","Pablo fue luego a la sinagoga y durante tres meses predicó abiertamente, hablando sobre el Reino de Dios y tratando de persuadir a los oyentes.","Pero como algunos se obstinaban y se negaban a creer, denigrando el Camino del Señor delante de la asamblea, Pablo rompió con ellos. Luego tomó aparte a sus discípulos y dialogaba diariamente en la escuela de Tirano.","Así lo hizo durante dos años, de modo que todos los habitantes de la provincia de Asia, judíos y paganos, tuvieron ocasión de escuchar la Palabra del Señor.","Por intermedio de Pablo, Dios realizaba milagros poco comunes,","hasta tal punto que el aplicarse sobre los enfermos pañuelos o lienzos que habían tocado el cuerpo de Pablo, aquellos se curaban y quedaban libres de los malos espíritus.","Algunos exorcistas ambulantes judíos, hicieron la prueba de pronunciar el nombre del Señor Jesús sobre los poseídos por los malos espíritus, diciendo: «Yo los conjuro por ese Jesús que anuncia Pablo».","Un cierto Sevas, Sumo Sacerdote judío, tenía siete hijos que practicaban estos exorcismos.","El espíritu malo les respondió: «Yo conozco a Jesús y sé quién es Pablo, pero ustedes, ¿quiénes son?».","Y el hombre poseído por el espíritu malo, abalanzándose sobre los exorcistas, los dominó a todos y los maltrató de tal manera que debieron escaparse de esa casa desnudos y cubiertos de heridas.","Todos los habitantes de Efeso, tanto judíos como paganos, se enteraron de este hecho y, llenos de temor, glorificaban el nombre del Señor Jesús.","Muchos de los que habían abrazado la fe vinieron a confesar abiertamente sus prácticas,","y un buen número de los que se habían dedicado a la magia traían sus libros y los quemaban delante de todos. Se estimó que el valor de estos libros alcanzaba a unas cincuenta mil monedas de plata.","Así, por el poder del Señor, la Palabra se difundía y se afianzaba.","Después de esto, Pablo se propuso ir a Jerusalén pasando por Macedonia y Acaya. «Primero iré allí, decía, y luego tendré que ir también a Roma».","Envió a Macedonia a dos de sus colaboradores, Timoteo y Erasto, y él permaneció en Asia un tiempo más.","Fue entonces, cuando se produjeron graves desórdenes a causa del Camino del Señor.","Un orfebre llamado Demetrio fabricaba reproducciones en plata del templo de Diana, proporcionando así abundante trabajo a los artesanos.","Demetrio los reunió, junto con los que hacían trabajos similares, y les dijo: «Ustedes saben perfectamente que nuestro bienestar depende de esta industria.","Pero ahora ustedes mismos ven y oyen que no solamente en Efeso, sino también en casi toda la provincia de Asia, ese Pablo ha conquistado y seducido a mucha gente, pretendiendo que los dioses fabricados por mano de hombre no son dioses.","De esa manera, no solamente nuestra profesión está amenazada de caer en el descrédito, sino que el templo mismo de la gran diosa Diana corre el riesgo de ser tenido por nada, y aquella a quien adoran toda el Asia y el mundo entero, terminará por quedar despojada de su prestigio.».","Al oír estas palabras, la multitud se enfureció y comenzó a gritar: «¡Viva la gran Diana de los efesios!»,","y se produjo un gran desorden en la ciudad. Todos irrumpieron en el teatro, arrastrando a los macedonios Gayo y Aristarco, compañeros de viaje de Pablo.","Pablo quería presentarse delante de la asamblea, pero sus discípulos se lo impidieron.","Hasta algunos magistrados de la ciudad, que eran amigos suyos, le rogaron que no se expusiera yendo al teatro.","Todo el mundo gritaba al mismo tiempo, ya que la confusión reinaba en la concurrencia, y la mayor parte ni siquiera sabía por qué se había reunido.","Entonces hicieron salir de entre la multitud a Alejandro, a quien los judíos empujaban hacia adelante. Este, pidiendo silencio con la mano, quería dar una explicación a la asamblea.","Pero en cuanto advirtieron que era un judío, todos se pusieron a gritar unánimemente durante dos horas: «¡Viva la gran Diana de los efesios!».","Por fin, el secretario de la ciudad consiguió calmar a la multitud, diciendo: «Efesios, ¿qué hombre de este mundo ignora que la ciudad de Efeso es la guardiana del templo de la gran diosa Diana y de su estatua venida del cielo?","Siendo esta una verdad innegable, deben quedarse tranquilos y no actuar apresuradamente.","Esos hombres que ustedes trajeron, no han cometido ningún sacrilegio ni han dicho ninguna blasfemia contra nuestra diosa.","Y si Demetrio y sus artesanos tienen una queja contra alguien, para eso están los tribunales y los procónsules ante quienes se pueden presentar las acusaciones.","Si ustedes tienen que debatir algún otro asunto, se decidirá en la asamblea legal.","Porque corremos el riesgo de ser acusados de sediciosos, a causa de lo que acaba de suceder, ya que no tenemos ningún motivo para justificar este tumulto». Y con estas palabras, disolvió la asamblea."],["Cuando cesó el tumulto, Pablo llamó a los discípulos y después de haberlos exhortado, se despidió de ellos y partió hacia Macedonia.","Atravesó toda esa región, exhortando vivamente a sus hermanos, y llegó a Grecia,","donde permaneció tres meses. Cuando iba a embarcarse para Siria, los judíos tramaron una conspiración contra él, y por eso, decidió volver por Macedonia.","Lo acompañaban Sópatro de Berea, hijo de Pirro; Aristarco y Segundo de Tesalónica; Gayo de Derbe, Timoteo, y también Tíquico y Trófimo de la provincia de Asia.","Estos se adelantaron y nos esperaron en Tróade.","Nosotros, partimos de Filipos por mar después de la fiesta de los panes Acimos, y cinco días más tarde, nos reunimos con ellos en Tróade donde pasamos una semana.","El primer día de la semana, cuando nos reunimos para partir el pan, Pablo, que debía salir al día siguiente, dirigió la palabra a la asamblea y su discurso se prolongó hasta la medianoche.","La habitación donde nos habíamos reunido estaba muy iluminada.","Un muchacho llamado Eutico, que se había sentado en el borde la ventana, tenía mucho sueño y se dormía mientras Pablo hablaba, hasta que, vencido por el sueño, se cayó desde un tercer piso. Cuando lo levantaron, estaba muerto.","Pablo bajo, se echó sobre él y, abrazándolo, dijo: «No se alarmen, porque está vivo».","Volvió a subir, partió el pan y comió. Luego siguió hablando mucho tiempo hasta el amanecer; y después salió.","En cuanto al muchacho, lo llevaron a su casa con vida, y todos se sintieron muy reconfortados.","Nosotros nos adelantamos en barco, navegando en dirección a Asos, donde debíamos recoger a Pablo. El lo había dispuesto así, porque iba a hacer el viaje por tierra.","Cuando nos juntamos en Asos, Pablo se embarcó con nosotros y nos dirigimos a Mitilene.","Partimos de allí al día siguiente y llegamos frente a Quío. Al otro día, fuimos a Samos y, después de hacer escala en Trogilio, al día siguiente llegamos a Mileto.","Pablo había decidido pasar de largo por Efeso, para no retrasarse demasiado en Asia. Estaba apurado porque, de ser posible, quería estar en Jerusalén el día de Pentecostés.","Desde Mileto, mandó llamar a los presbíteros de la Iglesia de Efeso.","Cuando estos llegaron, Pablo les dijo: «Ya saben cómo me he comportado siempre con ustedes desde el primer día que puse el pie en la provincia de Asia.","He servido al Señor con toda humildad y con muchas lágrimas, en medio de las pruebas a que fui sometido por las insidias de los judíos.","Ustedes saben que no he omitido nada que pudiera serles útil; les prediqué y les enseñé tanto en público como en privado,","instando a judíos y a paganos a convertirse a Dios y a creer en nuestro Señor Jesús.","Y ahora, como encadenado por el Espíritu, voy a Jerusalén sin saber lo que me sucederá allí.","Sólo sé que, de ciudad en ciudad, el Espíritu Santo me va advirtiendo cuántas cadenas y tribulaciones me esperan.","Pero poco me importa la vida, mientras pueda cumplir mi carrera y la misión que recibí del Señor Jesús: la de dar testimonio de la Buena Noticia de la gracia de Dios.","Y ahora sé que ustedes, entre quienes pasé predicando el Reino, no volverán a verme.","Por eso hoy declaro delante de todos que no tengo nada que reprocharme respecto de ustedes.","Porque no hemos omitido nada para anunciarles plenamente los designios de Dios.","Velen por ustedes, y por todo el rebaño sobre el cual el Espíritu Santo los ha constituido guardianes para apacentar a la Iglesia de Dios, que él adquirió al precio de su propia sangre.","Yo sé que después de mi partida se introducirán entre ustedes lobos rapaces que no perdonarán al rebaño.","Y aun de entre ustedes mismos, surgirán hombres que tratarán de arrastrar a los discípulos con doctrinas perniciosas.","Velen, entonces, y recuerden que durante tres años, de noche y de día, no he cesado de aconsejar con lágrimas a cada uno de ustedes.","Ahora los encomiendo al Señor y a la Palabra de su gracia, que tiene poder para construir el edificio y darles la parte de la herencia que les corresponde, con todos los que han sido santificados.","En cuanto a mí, no he deseado ni plata ni oro ni los bienes de nadie.","Ustedes saben que con mis propias manos he atendido a mis necesidades y a las de mis compañeros.","De todas las maneras posibles, les he mostrado que así, trabajando duramente, se debe ayudar a los débiles, y que es preciso recordar las palabras del Señor Jesús: «La felicidad está más en dar que en recibir».","Después de decirles esto, se arrodilló y oró junto a ellos.","Todos se pusieron a llorar, abrazaron a Pablo y lo besaron afectuosamente,","apenados sobre todo porque les había dicho que ya no volverían a verlo. Después lo acompañaron hasta el barco."],["Después de separarnos de ellos, nos embarcamos y fuimos derecho a Cos; al día siguiente, llegamos a Rodas y de allí pasamos a Pátara.","Como encontramos un barco que iba a Fenicia, subimos a bordo y partimos.","Avistamos la isla de Chipre y, dejándola a nuestra izquierda, seguimos navegando en dirección a Siria, hasta que por fin, atracamos en el puerto de Tiro, donde el barco debía descargar.","Allí encontramos a algunos discípulos y permanecimos una semana con ellos. Estos, iluminados por el Espíritu, aconsejaban a Pablo que no subiera a Jerusalén,","pero llegado el momento de partir, proseguimos nuestro viaje. Todos nos acompañaron hasta las afueras de la ciudad, incluso las mujeres y los niños. En la playa nos arrodillamos para orar,","y habiéndonos despedido, nosotros subimos al barco y ellos se volvieron a sus casas.","De Tiro fuimos a Tolemaida, poniendo así término a la travesía. Allí saludamos a los hermanos y nos detuvimos un día con ellos.","Al día siguiente, volvimos a partir y llegamos a Cesarea, donde fuimos a ver a Felipe, el predicador del evangelio, unos de los Siete, y nos alojamos en su casa.","El tenía cuatro hijas solteras que profetizaban.","Permanecimos allí muchos días, y durante nuestra estadía, bajó de Judea un profeta llamado Agabo.","Este vino a vernos, tomó el cinturón de Pablo, se ató con él los pies y las manos, y dijo: «El Espíritu Santo dice: Así atarán los judíos en Jerusalén al dueño de este cinturón y lo entregarán a los paganos».","Al oír estas palabras, los hermanos del lugar y nosotros mismos rogamos a Pablo que no subiera a Jerusalén.","Pablo respondió: «¿Por qué lloran así y destrozan mi corazón? Yo estoy dispuesto, no solamente a dejarme encadenar, sino también a morir en Jerusalén por el nombre del Señor Jesús».","Y como no conseguíamos persuadirlo, no insistimos más y dijimos: «Que se haga la voluntad del Señor».","Algunos días después, terminados nuestros preparativos, subimos a Jerusalén.","Iban con nosotros algunos discípulos de Cesarea, que nos hicieron alojar en casa de un tal Mnasón de Chipre, un discípulo de la primera hora.","Cuando llegamos a Jerusalén, los hermanos nos recibieron con alegría.","Al día siguiente, Pablo fue con nosotros a casa de Santiago, donde también se reunieron todos los presbíteros.","Después de saludarlos, Pablo expuso detalladamente todo lo que Dios había hecho entre los paganos a través de su ministerio.","Ellos alabaron a Dios por lo que acababan de oír, pero le advirtieron: «Tú sabes, hermano, que millares de judíos han abrazado la fe, y que todos ellos son celosos cumplidores de la Ley.","Ahora bien, ellos han oído decir que con tus enseñanzas apartas de Moisés a todos los judíos que viven entre los paganos, diciéndoles que no circunciden a sus hijos y no sigan más sus costumbres.","¿Qué haremos entonces? Pronto seguramente se van a enterar de tu llegada.","Tienes que hacer lo que te vamos a decir: Aquí tenemos a cuatro hombres que están obligados por un voto:","llévalos contigo, purifícate con ellos y paga lo que corresponde para que se hagan cortar el cabello. Así todo el mundo sabrá que no es verdad lo que han oído acerca de ti, sino que tú también eres un fiel cumplidor de la Ley.","En cuanto a los paganos que abrazaron la fe, les hemos enviado nuestras decisiones, a saber: que se abstengan de la carne inmolada a los ídolos, de la sangre, de la carne de animales muertos sin desangrar y de las uniones ilegales».","Al día siguiente, Pablo tomó consigo a esos hombres, se purificó con ellos y entró en el Templo. Allí hizo saber cuándo concluiría el plazo fijado para la purificación, es decir, cuándo debía ofrecerse la oblación por cada uno de ellos.","Casi al final de los siete días, cuando los judíos venidos de Asia vieron a Pablo en el Templo, amotinaron a la multitud y se apoderaron de él,","gritando: «¡Socorro, israelitas! Este es el hombre que predica a todos y en todas partes contra nuestro pueblo, contra la Ley y contra este Templo, y ahora ha llegado a introducir en él a los paganos, profanando este lugar santo».","Decían esto porque antes habían visto con él en la ciudad a Trófimo de Efeso, y creían que Pablo lo había introducido en el Templo.","La ciudad entera se alborotó, y de todas partes acudió el pueblo. Se apoderaron de Pablo, lo sacaron fuer del Templo y cerraron inmediatamente las puertas.","Ya iban a matarlo, cuando llegó al tribunal de la cohorte la noticia de que toda Jerusalén estaba convulsionada.","En seguida el tribuno, con unos soldados y centuriones, se precipitó sobre los manifestantes. Al ver al tribuno y a los soldados, dejaron de golpear a Pablo.","El tribuno se acercó, tomó a Pablo y mandó que lo ataran con dos cadenas; después preguntó quién era y qué había hecho.","Todos gritaban al mismo tiempo, y a causa de la confusión, no pudo sacar nada en limpio. Por eso hizo conducir a Pablo a la fortaleza.","Al llegar a la escalinata, los soldados tuvieron que alzarlo debido a la violencia de la multitud,","porque el pueblo en masa lo seguía, gritando: «¡Que lo maten!».","Cuando lo iban a introducir en la fortaleza, Pablo dijo al tribuno: «¿Puedo decirte una palabra?». «¿Tú sabes griego?», le preguntó el tribuno.","Entonces, ¿no eres el egipcio que hace unos días provocó un motín y llevó al desierto a cuatro mil terroristas?».","«Yo soy judío, dijo Pablo, originario de Tarso, ciudadano de una importante ciudad de Cilicia. Te ruego que me permitas hablar al pueblo».","El trino se lo permitió, y Pablo, de pie sobre la escalinata, hizo una señal al pueblo con la mano. Se produjo un gran silencio, y Pablo comenzó a hablarles en hebreo."],["«Hermanos y padres, les dijo, escuchen lo que hoy les voy a decir en mi defensa».","Al oír que hablaba en hebreo, el silencio se hizo aún más profundo. Pablo prosiguió:","«Yo soy judío, nacido en Tarso de Cilicia, pero me he criado en esta ciudad y he sido iniciado a los pies de Gamaliel en la estricta observancia de la Ley de nuestros padres. Estaba lleno de celo por Dios, como ustedes lo están ahora.","Perseguí a muerte a los que seguían este Camino, llevando encadenados a la prisión a hombres y mujeres;","el Sumo Sacerdote y el Consejo de los ancianos son testigos de esto. Ellos mismos me dieron cartas para los hermanos de Damasco, y yo me dirigí allá con el propósito de traer encadenados a Jerusalén a los que encontrara en esa ciudad, para que fueran castigados.","En el camino y al acercarme a Damasco, hacia el mediodía, una intensa luz que venía del cielo brilló de pronto a mi alrededor.","Caí en tierra y oí una voz que me decía: «Saulo, Saulo, ¿por qué me persigues?».","Le respondí: «¿Quién eres, Señor?», y la voz me dijo: «Yo soy Jesús de Nazaret, a quien tú persigues».","Los que me acompañaban vieron la luz, pero no oyeron la voz del que me hablaba.","Yo le pregunté: «¿Qué debo hacer, Señor?». El Señor me dijo: «Levántate y ve a Damasco donde se te dirá lo que debes hacer».","Pero como yo no podía ver, a causa del resplandor de esa luz, los que acompañaban me llevaron de la mano hasta damasco.","Un hombre llamado Ananías, fiel cumplidor de la Ley, que gozaba de gran prestigio entre los judíos del lugar,","vino a verme y, acercándose a mí, me dijo: «Hermano Saulo, recobra la vista». Y en ese mismo instante, pude verlo.","El siguió diciendo: «El Dios de nuestros padres te ha destinado para conocer su voluntad, para ver al Justo y escuchar su Palabra,","porque tú darás testimonio ante todos los hombres de lo que has visto y oído.","Y ahora, ¿qué esperas? Levántate, recibe el bautismo y purifícate de tus pecados, invocando su Nombre».","De vuelta a Jerusalén, mientras oraba en el Templo, caí en éxtasis","y vi al Señor que me decía: Aléjate rápidamente de Jerusalén, porque ellos no recibirán el testimonio que tú darás de mí».","Entonces respondí: «Ellos saben, Señor, que yo iba de una sinagoga a otra para encarcelar y azotar a los que creen en ti.","Y saben que cuando derramaban la sangre de Esteban, tu testigo, yo también estaba presente, aprobando su muerte y cuidando la ropa de los verdugos».","Pero él me dijo: «Vete, porque quiero enviarte lejos, a las naciones paganas».","Hasta aquí los judíos lo escucharon, pero al oír estas palabras comenzaron a gritar diciendo: «¡Elimina a este hombre. No merece vivir!».","Todos vociferaban, agitaban sus manos y tiraban tierra al aire.","El tribuno hizo entrar a Pablo en la fortaleza y ordenó que lo azotaran para saber por qué razón gritaban así contra él.","Cuando lo sujetaron con las correas, Pablo dijo al centurión de turno: «¿Les está permitido azotar a un ciudadano romano sin haberlo juzgado?».","Al oír estas palabras, el centurión fui a informar al tribuno: «¿Qué va a hacer?, le dijo. Este hombre es ciudadano romano».","El tribuno fue a preguntar a Pablo: «¿Tú eres ciudadano romano?». Y él le respondió: «Sí».","El tribuno prosiguió: «A mí me costó mucho dinero adquirir esa ciudadanía». «En cambio, yo la tengo de nacimiento», dijo Pablo.","Inmediatamente, se retiraron los que iban a azotarlo, y el tribunal se alarmó al enterarse de que había hecho encadenar a un ciudadano romano.","Al día siguiente, queriendo saber con exactitud de qué lo acusaban los judíos, el tribuno le hizo sacar las cadenas, y convocando a los sumos sacerdotes y a todo el Sanedrín, hizo comparecer a Pablo delante de ellos."],["Con los ojos fijos en el Sanedrín, Pablo dijo: «Hermanos, hasta hoy yo he obrado con rectitud de conciencia delante de Dios».","Pero el Sumo Sacerdote Ananías ordenó a sus asistentes que le pegaran en la boca.","Entonces Pablo replicó: «A ti te golpeará Dios, hipócrita. ¡Tú te sientas allí para juzgarme según la Ley y, violando la Ley, me haces golpear!».","Los asistentes le advirtieron: «Estás insultando al Sumo Sacerdote de Dios».","«Yo no sabía, hermanos, que era el Sumo Sacerdote, respondió Pablo, porque está escrito: No maldecirás al jefe de tu pueblo».","Pablo, sabiendo que había dos partidos, el de los saduceos y el de los fariseos, exclamó en medio del Sanedrín: «Hermanos, yo soy fariseo, hijo de fariseos, y ahora me están juzgando a causa de nuestra esperanza en la resurrección de los muertos».","Apenas pronunció estas palabras, surgió una disputa entre fariseos y saduceos, y la asamblea se dividió.","Porque los saduceos niegan la resurrección y la existencia de los ángeles y de los espíritus; los fariseos, por el contrario, admiten una y otra cosas.","Se produjo un griterío, y algunos escribas del partido de los fariseos se pusieron de pie y protestaron enérgicamente: «Nosotros no encontramos nada de malo en este hombre. ¿Y si le hubiera hablado algún espíritu o un ángel...?».","Como la disputa se hacía cada vez más violenta, el tribuno, temiendo por la integridad de Pablo, mandó descender a los soldados para que lo sacaran de allí y lo llevaran de nuevo a la fortaleza.","A la mañana siguiente, el Señor se apareció a Pablo y le dijo: «Animo, así como has dado testimonio de mí en Jerusalén, también tendrás que darlo en Roma».","Al amanecer, los judíos se confabularon y se comprometieron bajo juramente a no comer ni beber, hasta no haber matado a Pablo.","Los comprometidos en la conjuración eran más de cuarenta.","Fueron al encuentro de los sumos sacerdotes y los ancianos, y les dijeron: «Nosotros nos hemos comprometido bajo juramento a no probar nada antes de haber matado a Pablo.","Pónganse de acuerdo con el Sanedrín, y propongan al tribuno que lo haga comparecer delante de ustedes con el pretexto de examinar más exactamente su causa; nosotros, por nuestra parte, estaremos preparados para matarlo en el camino».","Pero un sobrino de Pablo, al enterarse de la emboscada, se dirigió a la fortaleza y entró para prevenir a Pablo.","Este, llamando a uno de los centuriones, le dijo: «Acompaña a este muchacho hasta donde está el tribuno, porque tiene algo que comunicarle».","El centurión lo llevó y dijo al tribuno: «El prisionero Pablo me pidió que te trajera a este muchacho, porque tiene algo que decirte».","El tribuno, tomándolo de la mano, lo llevó aparte y le preguntó: «¿Qué tienes que comunicarme?».","El muchacho le respondió: «Los judíos, bajo pretexto de examinar más a fondo la causa, se han puesto de acuerdo para pedirte que mañana presentes a Pablo ante el Sanedrín.","No lo creas. Es una emboscada que le preparan más de cuarenta de ellos, comprometidos bajo juramente a no comer ni beber hasta haberlo matado. Ya están dispuestos y sólo esperan tu consentimiento».","El tribuno despidió al muchacho, haciéndole esta recomendación: «No digas a nadie que me has contado esto».","Después llamó a dos centuriones y les dijo: «Preparen doscientos soldados, setenta jinetes y doscientos lanceros, para que salgan en dirección a Cesarea a las nueve de la noche.","Preparen también caballos para Pablo, y llévenlo sano y salvo hasta el gobernador Félix».","Y escribió una carta que decía:","«Claudio Lisias saluda al excelentísimo gobernador Félix.","Aquí te envío a un hombre que fue detenido por los judíos, y cuando ya lo iban a matar, enterándome de que era ciudadano romano, intervine con mis soldados y pude rescatarlo.","Queriendo saber exactamente de qué lo acusaban, lo hice comparecer delante del Tribunal judío,","pero comprobé que se lo acusaba por cuestiones relativas a la Ley de los judíos, y que no había ningún cargo por el que mereciera la muerte o la prisión.","Informado de que se tramaba una conspiración contra este hombre, he querido enviarlo allí en seguida, ordenando también a sus acusadores que te expongan los cargos que tengan contra él. Adiós».","De acuerdo con la orden recibida, los soldados tomaron a Pablo y lo condujeron de noche a Antipátride.","Al día siguiente, dejaron que los jinetes partieran con él, y ellos se volvieron a la fortaleza.","Llegados a Cesarea, los jinetes entregaron la carta al gobernador y le presentaron a Pablo.","El gobernador leyó la carta y preguntó de qué provincia era. Al saber que era de Cilicia,","dijo: «Te oiré cuando lleguen tus acusadores». Y lo hizo poner bajo custodia en el pretorio de Herodes."],["Cinco días después, el Sumo Sacerdote Ananías bajó con algunos ancianos y un abogado llamado Tértulo, para presentar delante del gobernador la acusación que tenían contra Pablo.","Hicieron comparecer a Pablo, y Tértulo presentó la acusación en estos términos: «Excelentísimo Félix: La profunda paz de que gozamos gracias a ti y las reformas que nuestra nación debe a tu gobierno,","constituyen para nosotros, siempre y en todas partes, un motivo de inmensa gratitud.","Como no queremos importunarte demasiado, te ruego que nos escuches un momento con tu habitual cordialidad.","Hemos comprobado que este hombre es una verdadera peste: él suscita disturbios entre todos los judíos del mundo y es uno de los dirigentes de la secta de los nazarenos.","Ha intentado incluso profanar el Templo, y por eso, nosotros lo detuvimos. Queríamos juzgarlo de acuerdo con nuestra Ley,","pero intervino el tribuno Lisias, que lo arrancó violentamente de nuestras manos","y ordenó a sus acusadores que comparecieran delante de ti. Si lo interrogas, tú mismo reconocerás que nuestros cargos contra él son bien fundados».","Los judíos ratificaron esto, asegurando que era verdad.","Cuando el gobernador hizo señas a Pablo de que hablara, este respondió: «Con entera confianza voy a defender mi causa, por sé que gobiernas esta nación desde hace varios años.","Como tú mismo puedes averiguarlo, no hace todavía doce días que subí en peregrinación a Jerusalén","y nunca se me vio ni en el Templo, ni en las sinagogas, ni en la ciudad, discutiendo con alguien o amotinando a la gente.","Ellos tampoco pueden probarte aquello de lo que me acusan ahora.","Pero sí te confieso que sirvo al Dios de mis padres, siguiendo el Camino que mis acusadores consideran una secta. Creo en todo lo que está contenido en la Ley y escrito en los Profetas,","y tengo la misma esperanza en Dios que ellos tienen: la esperanza de que habrá una resurrección de justos y pecadores.","Por eso trato de conservar siempre una conciencia irreprochable delante de Dios y de los hombres.","Después de unos cuantos años, vine a traer limosnas a mis compatriotas y a presentar ofrendas.","Así fue cómo algunos judíos de la provincia de Asia me encontraron en el Templo: yo me había purificado y no estaba provocando ninguna clase de amotinamiento ni de tumulto.","Son ellos los que hubieran debido presentarse ante ti para acusarme, si tenían alguna queja contra mí.","Por lo menos, que digan los que están aquí de qué delito me encontraron culpable cuando comparecí delante del Sanedrín.","A no ser que se trate de lo único que dije, puesto de pie en medio de ellos: «Hoy ustedes me juzgan a causa de la resurrección de los muertos».","Félix, que estaba muy bien informado de todo lo concerniente al Camino del Señor, postergó la causa, diciendo: «Cuando descienda de Jerusalén el tribuno Lisias, me expediré en este asunto».","Después ordenó al centurión que custodiara a Pablo, pero dejándole una cierta libertad y sin impedir que sus amigos lo atendieran.","Algunos días después, se presentó Félix con su mujer Drusila, que era judía. El mandó llamar a Pablo y lo oyó hablar acerca de la fe en Jesucristo.","Pero cuando Pablo se puso a tratar sobre la justicia, la continencia y el juicio futuro, Félix, lleno de temor, le respondió: «Por ahora puedes irte; te volveré a llamar en la primera ocasión».","Al mismo tiempo, él esperaba que Pablo le diera dinero, y por eso lo hacía llamar frecuentemente para conversar con él.","Al cabo de dos años, Porcio Festo sucedió a Félix; y como este quería congraciarse con los judíos, dejó a Pablo en la prisión."],["Tres días después de haberse hecho cargo de su provincia, Festo subió de Cesarea a Jerusalén.","Los sumos sacerdotes y los judíos más importantes acusaron entonces a Pablo en su presencia,","y le pidieron la gracia de que lo hiciera trasladar a Jerusalén. En realidad preparaban una emboscada para matarlo en el camino.","Pero Festo respondió que Pablo debía quedar bajo custodia en Cesarea, y que él mismo iría allí inmediatamente.","«Que los de más autoridad entre ustedes, añadió, vengan conmigo y presenten su acusación, si tienen algo contra él».","Festo permaneció en Jerusalén unos ocho o diez días, y luego bajó a Cesarea. Al día siguiente, se sentó en el tribunal e hizo comparecer a Pablo.","En cuanto llegó, los judíos venidos de Jerusalén lo rodearon, y presentaron contra él numerosas y graves acusaciones que no podían probar.","Pablo se defendía diciendo: «Yo no he cometido ninguna falta contra la Ley de los judíos, ni contra el Templo, ni contra el Emperador».","Festo, queriendo congraciarse con los judíos, se dirigió a Pablo y le dijo: «¿Quieres subir a Jerusalén para ser juzgado allí en mi presencia?».","Pablo respondió: «Estoy delante del tribunal del Emperador, y es aquí donde debo ser juzgado. Yo no hice ningún mal a los judíos, como tú lo sabes perfectamente.","Si soy culpable y he cometido algún delito que merezca la muerte, no me niego a morir, pero si las acusaciones que hacen los judíos contra mí carecen de fundamento, nadie tiene el derecho de entregarme a ellos. Apelo al Emperador».","Festo, después de haber consultado con su Consejo, respondió: «Ya que apelaste al Emperador, comparecerás ante él».","Algunos días más tarde, el rey Agripa y Berenice llegaron a Cesarea y fueron a saludar a Festo.","Como ellos permanecieron varios días, Festo expuso al rey el caso de Pablo, diciéndole: «Félix ha dejado a un prisionero,","y durante mi estadía en Jerusalén, los sumos sacerdotes y los ancianos de los judíos, presentaron quejas pidiendo su condena.","Yo les respondí que los romanos no tienen la costumbre de entregar a un hombre antes de enfrentarlo con sus acusadores y darle la oportunidad de defenderse.","Ellos vinieron aquí, y sin ninguna demora, me senté en el tribunal e hice comparecer a ese hombre al día siguiente.","Pero cuando se presentaron los acusadores, estos no alegaron contra él ninguno de los cargos que yo sospechaba.","Lo que había entre ellos eran no sé qué discusiones sobre su religión, y sobre un tal Jesús que murió y que Pablo asegura que vive.","No sabiendo bien qué partido tomar en un asunto de esta índole le pregunté a Pablo si quería ir a Jerusalén para ser juzgado allí.","Pero como este apeló al juicio de Su Majestad imperial, yo ordené que lo dejaran bajo custodia hasta que lo enviara al Emperador».","Agripa dijo entonces a Festo: «A mí también me gustaría escuchar a ese hombre». «Mañana lo escucharás», respondió Festo.","Al día siguiente, Agripa y Berenice llegaron con gran pompa y entraron en la sala de audiencias, rodeados de los tribunos y de los hombres más importantes de la ciudad. A una orden de Festo, trajeron a Pablo.","Festo tomó la palabra, diciendo: «Rey Agripa y todos los que están aquí presentes, ustedes ven a este hombre, por quien toda la comunidad judía ha venido a verme, tanto aquí como en Jerusalén, insistiendo a gritos que no había que dejarlo vivir más.","Yo no he encontrado en él nada que merezca la muerte; pero ya que él mismo ha apelado al Emperador, he decidido enviárselo.","Como no tengo nada preciso que escribir sobre él al Soberano, lo hice comparecer ante ustedes, especialmente ante ti, rey Agripa; así, después de este interrogatorio, yo tendré algo para informar.","Porque me parece absurdo enviar a un prisionero, sin indicar al mismo tiempo los cargos que se le imputan»."],["Agripa dijo a Pablo: «Estás autorizado a defenderte». Entonces Pablo, extendiendo la mano, comenzó su defensa, diciendo:","«Rey Agripa, me considero dichoso de tener que defenderme hoy, delante de ti, de las acusaciones que me hacen los judíos,","porque tú conoces todas las costumbres y controversias de los judíos. Por eso te ruego que me escuches con paciencia.","Todos los judíos saben cómo he vivido desde los primeros días de mi juventud, en medio de mi pueblo y en la misma Jerusalén.","Ellos me conocen desde hace mucho tiempo y si quieren, pueden atestiguar que he vivido como fariseo, es decir, siguiendo la secta más rígida de nuestra religión.","Y si ahora soy sometido a juicio, es por mi esperanza en la promesa hecha por Dios a nuestros padres,","la promesa que nuestras doce tribus esperan ver cumplida, sirviendo a Dios fervientemente día y noche. Acusa de esta esperanza, rey Agripa, soy acusado por los judíos.","¿Por qué les parece increíble que Dios resucite a los muertos?","Yo, por mi parte, consideraba que debía combatir por todos los medios el nombre de Jesús de Nazaret.","Así lo hice en Jerusalén: yo mismo encarcelé a un gran número de santos con la autorización de los sumos sacerdotes, y cuando se los condenaba a muerte, mi voto era favorable.","Recorría frecuentemente las sinagogas, y los castigaba para obligarlos a renegar de su fe. Lleno de rabia contra ellos, los perseguía hasta en las ciudades extranjeras.","Una vez, cuando me dirigía a Damasco con plenos poderes y con la orden de los sumos sacerdotes,","en el camino, hacia el mediodía, vi una luz más brillante que el sol, que venía del cielo y me envolvía a mí y a los que me acompañaban.","Todos caímos en tierra, y yo oí una voz que me decía en hebreo: «Saulo, Saulo, ¿por qué me persigues? Te lastimas al dar coces contra el aguijón».","Yo respondí: «¿Quién eres, Señor?». Y me dijo: «Soy Jesús, a quien tú persigues.","Levántate y permanece de pie, porque me he aparecido a ti para hacerte ministro y testigo de las cosas que has visto y de aquellas en que yo me manifestaré a ti.","Te libraré de los judíos y de las naciones paganas. A ellas te envío","para que les abras los ojos, y se conviertan de las tinieblas a la luz y del imperio de Satanás al verdadero Dios, y por la fe en mí, obtengan el perdón de los pecados y su parte en la herencia de los santos».","Desde ese momento, rey Agripa, nunca fui infiel a esa visión celestial.","Por el contrario, dirigiéndome primero a los habitantes de Damasco, luego a los de Jerusalén y de todo el país de Judea, y finalmente a los paganos, les prediqué que era necesario arrepentirse y convertirse a Dios, manifestando su conversión con obras.","Por todo esto, los judíos me detuvieron en el Templo y trataron de matarme.","Pero con la protección de Dios, he podido hasta el día de hoy seguir dando testimonio ante los pequeños y los grandes. Y nunca dije nada fuera de lo que los Profetas y Moisés anunciaron que iba a suceder,","es decir, que el Mesías debía sufrir y que, siendo el primero en resucitar de entre los muertos, anunciaría la luz a nuestro pueblo y a los paganos».","Cuando Pablo llegó a este punto de su defensa, Festo dijo en voz alta: «Estás loco, Pablo; tu excesivo estudio te ha hecho perder la cabeza».","A lo que Pablo respondió: «No estoy loco, excelentísimo Festo, sino que digo la verdad y hablo con sensatez.","El rey está al corriente de todas estas cosas, por eso me dirijo a él con toda confianza: no creo que ignore nada de esto, porque no son cosas que sucedieron en un lugar oculto.","¿Crees en los profetas, rey Agripa? Yo sé que crees en ellos».","Agripa contestó a Pablo: «¡Un poco más, y me convences que me haga cristiano!».","«No importa que se necesite poco o mucho para lograrlo, dijo Pablo. ¡Quiera Dios que no sólo tú, sino todos los que me escuchan hoy, lleguen a ser como yo..., pero sin estas cadenas!».","Entonces el rey se levantó, lo mismo que el gobernador, Berenice y los que estaban con ellos.","Al retirarse, comentaban entre sí: «Este hombre no ha hecho nada que merezca la muerte o la prisión».","Y Agripa dijo a Festo: «Podría ser dejado en libertad, si él mismo hubiera apelado al Emperador»."],["Cuando se decidió que debíamos embarcarnos para Italia, confiaron a Pablo y a otros prisioneros a un centurión de la cohorte imperial, llamado Julio.","Subimos a bordo de un barco de Adramicio que se dirigía a las costas de Asia, y zarpamos. Iba con nosotros Aristarco, un macedonio de Tesalónica.","Al día siguiente, llegamos a Sidón. Julio trató a Pablo con mucha consideración y le permitió ir a ver a sus amigos y ser atendido por ellos.","De allí, partimos y navegamos al resguardo de la isla de Chipre, porque soplaban vientos contrarios;","después, atravesando el mar de Cilicia y de Panfilia, llegamos a Mira de Licia.","Allí, el centurión encontró un barco alejandrino que iba a zarpar rumbo a Italia, y nos hizo embarcar en él.","Durante varios días, navegamos lentamente y, a duras penas, llegamos a la altura de Cnido. Como el viento era desfavorable, navegamos al resguardo de la isla de Creta hacia el cabo Salmoné,","y después de haberlo bordeado con gran dificultad, llegamos a un punto llamado Buenos Puertos, cerca de la ciudad de Lasea.","Ya había transcurrido bastante tiempo y la navegación se hacía peligrosa, porque había pasado la época del Ayuno solemne. Entonces Pablo les advirtió:","«Amigos, veo que la navegación no podrá continuar sin riesgo y sin graves pérdidas, no sólo para la carga y el barco, sino también para nuestras propias vidas».","Pero el centurión confiaba más en el capitán y en el patrón del barco que en las palabras de Pablo;","y como el puerto no se prestaba para invernar, la mayoría opinó que era mejor partir y llegar cuanto antes a Fenice, un puerto de Creta que mira hacia el suroeste y el noroeste, para pasar allí el invierno.","En ese preciso momento, se levantó una brisa del sur y creyeron que podrían realizar este proyecto. Zarparon y comenzaron a bordear la isla de Creta.","Pero muy pronto se desencadenó un huracán llamado Euraquilón, que provenía de la isla.","Como el barco no podía resistir al viento, fue arrastrado y nos dejamos llevar a la deriva.","Navegando a cubierto de una pequeña isla, llamada Cauda, a duras penas conseguimos recoger el bote salvavidas.","Después de subirlo, se utilizaron los cables de refuerzo para asegurar el casco de la nave. Luego, por temor de encallar en los bancos de Sirtes, se bajó el ancla, dejándola suelta, y así navegamos a la deriva.","Al día siguiente, como la tormenta todavía arreciaba, los marineros comenzaron a arrojar el cargamento.","Al tercer día, echaron al agua con sus propias manos los aparejos del barco.","Desde hacía varios días no se veía ni el sol ni las estrellas, y la tormenta seguía con la misma violencia, de modo que ya habíamos perdido toda esperanza de salvación.","Como ya hacía tiempo que no comíamos, Pablo, de pie en medio de todos, les dijo: «Amigos, debían haberme hecho caso: si no hubiéramos partido de Creta, nos hubiéramos ahorrado este riesgo y estas graves pérdidas.","De todas maneras, les ruego que tengan valor porque ninguno de ustedes perecerá; solamente se perderá el barco.","Esta noche, se me apareció un ángel del Dios al que yo pertenezco y al que sirvo,","y me dijo: «No temas, Pablo. Tú debes comparecer ante el Emperador y Dios te concede la vida de todos los que navegan contigo».","Por eso, amigos, tengan valor. Yo confío que Dios cumplirá lo que me ha dicho.","Pero tendremos que encallar contra una isla».","En la decimocuarta noche, todavía íbamos a la deriva por el Adriático, cuando hacia la medianoche, los marineros presintieron la cercanía de tierra firme.","Echaron la sonda al mar y comprobaron que había una profundidad de alrededor de unos treinta y seis metros. Un poco más adelante, la echaron de nuevo y vieron que había unos veintisiete metros.","Temiendo que fuéramos a chocar contra unos escollos, soltaron cuatro anclas por la popa, esperando ansiosamente que amaneciera.","Los marineros intentaron escaparse del barco, arrojando al mar el bote salvavidas, con el pretexto de soltar las anclas de proa.","Pero Pablo dijo al centurión y a los soldados: «Si esos marineros no permanecen a bordo, ustedes no podrán salvarse».","Entonces los soldados cortaron las amarras del bote y lo dejaron caer.","Mientras esperábamos que amaneciera, Pablo recomendó a todos que comieran algo, diciéndoles: «Hace catorce días que están a la expectativa, sin comer nada.","Les aconsejo que coman algo, porque están exponiendo su salud. Nadie perderá un solo cabello de su cabeza».","Después que dijo esto, tomó pan, dio gracias a Dios delante de todos, lo partió y se puso a comer.","Los demás se animaron y también comenzaron a comer.","Eramos en total doscientas setenta y seis personas a bordo.","Una vez satisfechos, comenzaron a aligerar el barco tirando el trigo al mar.","Cuando amaneció, los marineros no reconocieron la costa; sólo distinguían una bahía con una playa, e hicieron lo posible para llevar la nave en esa dirección.","Desataron las anclas y las dejaron caer al mar; al mismo tiempo, aflojaron las amarras de los timones. Después desplegaron al viento la vela artimón y enfilaron hacia la playa.","Pero chocaron contra un banco de arena y quedó inmóvil, mientras que la popa se deshacía por la violencia de las olas.","Entonces los soldados decidieron matar a los prisioneros, por temor de que alguno se escapara a nado.","Pero, el centurión, que quería salvar a Pablo, impidió que lo hicieran, y ordenó que primero se tiraran al mar los que sabían nadar para llegar a tierra.","Los demás, lo harían valiéndose de tablas o de los restos del navío. Así todos llegaron a tierra sanos y salvos."],["Cuando estuvimos a salvo, nos enteramos de que la misma se llamaba Malta. 2 Sus habitantes nos demostraron una cordialidad nada común y nos recibieron a todos alrededor de un gran fuego que habían encendido a causa de la lluvia y del frío.","","Pablo recogió unas ramas secas y las echó al fuego. El calor hizo salir una serpiente que se enroscó en su mano.","Cuando los habitantes del lugar vieron el reptil enroscado en su mano, comenzaron a decir entre sí: «Este hombre es seguramente un asesino: se ha salvado del mar, y ahora la justicia divina no le permite sobrevivir».","Pero él tiró la serpiente al fuego y no sufrió ningún mal.","Ellos esperaban que se hinchara o cayera muerto. Después de un largo rato, viendo que no le pasaba nada, cambiaron de opinión y decían: «Es un dios».","Había en los alrededores una propiedad perteneciente al principal de la isla, llamado Publio. Este nos recibió y nos brindó cordial hospitalidad durante tres días.","El padre de Publio estaba en cama con fiebre y disentería. Pablo fue a verlo, oró, le impuso las manos y lo curó.","A raíz de esto, se presentaron los otros enfermos de la isla y fueron curados.","Nos colmaron luego de toda clase de atenciones y cuando nos embarcamos, nos proveyeron de lo necesario.","Al cabo de tres meses nos embarcamos en un navío que había permanecido en la isla durante el invierno; era un barco alejandrino que tenía la insignia de Cástor y Pólux.","Hicimos escala en Siracusa, donde permanecimos tres días.","De allí, bordeando la costa llegamos a Regio. Al día siguiente, se levantó un viento del sur, y en dos días llegamos a Pozzuoli,","donde encontramos a unos hermanos que nos invitaron a permanecer una semana con ellos. Luego llegamos a Roma.","Los hermanos de esta ciudad, informamos de nuestra llegada, nos salieron al encuentro y nos alcanzaron a la altura del «Foro de Apio» y en las «Tres Tabernas». Pablo, al verlos, dio gracias a Dios y se sintió reconfortado.","Cuando llegamos a Roma, recibió autorización para alojarse en una casa particular con un soldado que lo custodiara.","Tres días después convocó a los judíos principales, y cuando se reunieron les dijo: «Hermanos, sin haber hecho nada contra el pueblo ni contra las costumbres de nuestros padres, fui arrestado en Jerusalén y puesto en manos de los romanos.","Después de interrogarme, quisieron dejarme en libertad, porque no encontraban en mí nada que mereciera la muerte;","pero ante la oposición de los judíos, me vi obligado a apelar al Emperador, sin querer por esto acusar en nada a mi pueblo.","Por eso he querido verlos y hablarles, ya que a causa de la esperanza de Israel llevo estas cadenas».","Ellos le respondieron: «Nosotros no hemos recibido de Judea ninguna carta referente a ti, y ninguno de los hermanos que vinieron nos han contado nada que te sea desfavorable.","Pero ahora quisiéramos oírte exponer lo que piensas, porque sabemos que esta secta encuentra oposición en todas partes».","Entonces fijaron un día para encontrarse con él, y fueron a verlo en mayor número al lugar donde se alojaba. Pablo les habló durante todo el día sobre el Reino de Dios, dándoles toda clase de testimonio y tratando de persuadirlos para que creyeran en Jesucristo, a partir de la Ley de Moisés y de los Profetas.","Unos se convencían con sus palabras, pero otros se resistían a creer,","y mientras ellos se retiraban sin haberse puesto de acuerdo, Pablo dijo esta sola frase: «Son muy ciertas las palabras que el Espíritu Santo dijo a los padres de ustedes, por medio del profeta Isaías:","\"Ve a decir a este pueblo: Por más que oigan no comprenderán, por más que vean, no conocerán,","Porque el corazón de este pueblo se ha endurecido, se taparon los oídos y cerraron los ojos, por temor de que sus ojos vean, que sus oídos oigan, que su corazón comprenda, que se conviertan, y que yo los cure\".","Sepan entonces que esa salvación de Dios va a ser anunciada a los paganos. Ellos sí que la escucharán».","[Al oír estas palabras los judíos se retiraron discutiendo acaloradamente.]","Pablo vivió dos años enteros por sus propios medios, recibiendo a todos los que querían verlo,","proclamando el Reino de Dios, y enseñando con toda libertad y sin encontrar ningún obstáculo, lo concerniente al Señor Jesucristo."]]};
